              <Label htmlFor="allocationName">Allocation Name</Label>
              <Input
                id="allocationName"
                value={allocation.name}
                onChange={(e: any) => updateInitialParameters('name', e.target.value)}
                className="bg-yellow-50 border-yellow-200"
              />
            </div>

            <div className="space-y-2">
              <Label htmlFor="sectorProfile">
                Linked Sector Profile
                <Info className="w-4 h-4 inline ml-1 text-gray-400" />
              </Label>
              <Select value={allocation.linkedSectorProfile} onValueChange={(value: any) => updateInitialParameters('linkedSectorProfile', value)}>
                <SelectTrigger>
                  <SelectValue />
                </SelectTrigger>
                <SelectContent>
                  <SelectItem value="Default">Default</SelectItem>
                  <SelectItem value="B2B SaaS">B2B SaaS</SelectItem>
                  <SelectItem value="B2C">B2C</SelectItem>
                  <SelectItem value="Fintech">Fintech</SelectItem>
                  <SelectItem value="Healthcare">Healthcare</SelectItem>
                </SelectContent>
              </Select>
            </div>

            <div className="space-y-2">
              <Label htmlFor="entryRound">Entry Round</Label>
              <Select value={allocation.entryRound} onValueChange={(value: any) => updateInitialParameters('entryRound', value)}>
                <SelectTrigger>
                  <SelectValue />
                </SelectTrigger>
                <SelectContent>
                  <SelectItem value="Pre-Seed">Pre-Seed</SelectItem>
                  <SelectItem value="Seed">Seed</SelectItem>
                  <SelectItem value="Series A">Series A</SelectItem>
                  <SelectItem value="Series B">Series B</SelectItem>
                </SelectContent>
              </Select>
            </div>
          </CardContent>
        </Card>

        {/* Initial Check Size Configuration */}
        <Card>
          <CardHeader>
            <CardTitle className="text-lg">
              Initial Check Size
              <Info className="w-4 h-4 inline ml-1 text-gray-400" />
            </CardTitle>
          </CardHeader>
          <CardContent className="space-y-4">
            <div className="space-y-2">
              <Label htmlFor="checkSizeType">Amount</Label>
