const CSV_TEMPLATE_HEADERS = [
  'company_name',
  'investment_date',
  'stage',
  'amount_invested',
  'valuation_pre_money',
  'valuation_post_money',
  'equity_percentage',
  'sector',
  'lead_investor',
  'status',
  'notes'
];

const SAMPLE_DATA = [
  {
    company_name: 'TechCorp Inc.',
    investment_date: '2024-01-15',
    stage: 'Series A',
    amount_invested: '2000000',
    valuation_pre_money: '8000000',
