export const BulkImportModal: React.FC<BulkImportModalProps> = ({
  onImportComplete,
  children
}) => {
  const [isOpen, setIsOpen] = useState(false);
  const [step, setStep] = useState<'upload' | 'preview' | 'processing' | 'results'>('upload');
  const [file, setFile] = useState<File | null>(null);
  const [parsedData, setParsedData] = useState<unknown[]>([]);
  const [importResult, setImportResult] = useState<ImportResult | null>(null);
  const [progress, setProgress] = useState(0);

  const generateTemplateCSV = () => {
    const csvContent = [
      CSV_TEMPLATE_HEADERS.join(','),
      ...SAMPLE_DATA.map(row =>
        CSV_TEMPLATE_HEADERS.map(header =>
          `"${(row as Record<string, unknown>)[header] || ''}"`
        ).join(',')
      )
    ].join('\n');

    const blob = new Blob([csvContent], { type: 'text/csv' });
    const url = window.URL.createObjectURL(blob);
    const a = document.createElement('a');
    a.href = url;
    a.download = 'investment_import_template.csv';
    a.click();
    window.URL.revokeObjectURL(url);
  };

  const parseCSV = (text: string): unknown[] => {
    const lines = text.split('\n').filter(line => line.trim());
    if (lines.length < 2) return [];

    const firstLine = lines[0];
    if (!firstLine) return [];
    const headers = firstLine.split(',').map(h => h.replace(/"/g, '').trim());
    const data = lines.slice(1).map((line, index) => {
      const values = line.split(',').map(v => v.replace(/"/g, '').trim());
      const row = { _rowNumber: index + 2 }; // +2 because of header and 0-indexing

      headers.forEach((header, i) => {
        row[header] = values[i] || '';
      });

      return row;
    });

    return data;
  };

  const validateData = (data: unknown[]): { valid: unknown[]; errors: Array<{ row: number; message: string; data?: unknown }> } => {
    const valid: unknown[] = [];
    const errors: Array<{ row: number; message: string; data?: unknown }> = [];

    data.forEach((row) => {
      const rowErrors: string[] = [];

      // Required fields validation
      if (!row.company_name) rowErrors.push('Company name is required');
      if (!row.investment_date) rowErrors.push('Investment date is required');
      if (!row.amount_invested) rowErrors.push('Investment amount is required');

      // Date format validation
      if (row.investment_date && isNaN(Date.parse(row.investment_date))) {
        rowErrors.push('Invalid date format (use YYYY-MM-DD)');
      }

      // Numeric validation
      if (row.amount_invested && isNaN(parseFloat(row.amount_invested))) {
        rowErrors.push('Investment amount must be a number');
      }
      if (row.valuation_pre_money && isNaN(parseFloat(row.valuation_pre_money))) {
        rowErrors.push('Pre-money valuation must be a number');
      }
      if (row.equity_percentage && (isNaN(parseFloat(row.equity_percentage)) || parseFloat(row.equity_percentage) < 0 || parseFloat(row.equity_percentage) > 100)) {
        rowErrors.push('Equity percentage must be a number between 0-100');
      }

      if (rowErrors.length > 0) {
        errors.push({
          row: row._rowNumber,
          message: rowErrors.join('; '),
          data: row
        });
      } else {
        valid.push({
          ...row,
          amount_invested: parseFloat(row.amount_invested),
          valuation_pre_money: row.valuation_pre_money ? parseFloat(row.valuation_pre_money) : undefined,
          valuation_post_money: row.valuation_post_money ? parseFloat(row.valuation_post_money) : undefined,
          equity_percentage: row.equity_percentage ? parseFloat(row.equity_percentage) : undefined,
          investment_date: new Date(row.investment_date)
        });
      }
    });

    return { valid, errors };
  };

  const handleFileUpload = useCallback((event: React.ChangeEvent<HTMLInputElement>) => {
    const selectedFile = event.target.files?.[0];
    if (!selectedFile) return;

    if (!selectedFile.name.toLowerCase().endsWith('.csv')) {
      console.error('Please select a CSV file');
      return;
    }

    setFile(selectedFile);

    const reader = new FileReader();
    reader.onload = (e) => {
      const text = e.target?.result as string;
      const parsed = parseCSV(text);
      setParsedData(parsed);
      setStep('preview');
    };
    reader.readAsText(selectedFile);
  }, []);

  const handleImport = async () => {
    if (!parsedData.length) return;

    setStep('processing');
    setProgress(0);

    const { valid, errors } = validateData(parsedData);

    try {
      // Simulate processing progress
      for (let i = 0; i <= 100; i += 10) {
        setProgress(i);
        await new Promise(resolve => setTimeout(resolve, 100));
      }

      if (valid.length > 0) {
        await onImportComplete(valid);
      }

      setImportResult({
        success: true,
        imported: valid.length,
        errors,
        warnings: []
      });

      setStep('results');
    } catch (error) {
      setImportResult({
        success: false,
        imported: 0,
        errors: [{ row: 0, message: `Import failed: ${error}` }],
        warnings: []
      });
      setStep('results');
    }
  };

  const resetModal = () => {
    setStep('upload');
    setFile(null);
    setParsedData([]);
    setImportResult(null);
    setProgress(0);
  };

  return (
    <Dialog open={isOpen} onOpenChange={(open) => {
      setIsOpen(open);
      if (!open) resetModal();
    }}>
      <DialogTrigger asChild>
        {children || (
          <Button className="gap-2">
            <Upload className="h-4 w-4" />
            Bulk Import
          </Button>
        )}
      </DialogTrigger>

      <DialogContent className="max-w-4xl max-h-[90vh] overflow-y-auto">
        <DialogHeader>
          <DialogTitle className="flex items-center gap-2">
            <FileText className="h-5 w-5" />
            Bulk Import Investments
          </DialogTitle>
        </DialogHeader>

        {step === 'upload' && (
          <div className="space-y-6">
            <div className="text-center">
              <h3 className="font-medium mb-2">Import investments from CSV</h3>
              <p className="text-gray-600 text-sm mb-6">
                Upload a CSV file with your investment data. Download our template to get started.
              </p>

              <Button
                variant="outline"
                onClick={generateTemplateCSV}
                className="gap-2 mb-6"
              >
                <Download className="h-4 w-4" />
                Download Template
              </Button>
            </div>

            <div className="border-2 border-dashed border-gray-300 rounded-lg p-8 text-center">
              <Upload className="h-12 w-12 text-gray-400 mx-auto mb-4" />
              <div className="space-y-2">
                <Label htmlFor="csv-upload" className="cursor-pointer">
                  <span className="text-lg font-medium">Choose CSV file</span>
                  <Input
                    id="csv-upload"
                    type="file"
                    accept=".csv"
                    onChange={handleFileUpload}
                    className="hidden"
                  />
                </Label>
                <p className="text-sm text-gray-500">or drag and drop your CSV file here</p>
              </div>
            </div>

            <Alert>
              <AlertDescription>
                <strong>Required columns:</strong> company_name, investment_date, amount_invested<br/>
                <strong>Optional columns:</strong> stage, valuation_pre_money, equity_percentage, sector, lead_investor, status, notes
              </AlertDescription>
            </Alert>
          </div>
        )}

        {step === 'preview' && (
          <div className="space-y-4">
            <div className="flex items-center justify-between">
              <h3 className="font-medium">Preview Import Data</h3>
              <span className="text-sm text-gray-600">{parsedData.length} rows found</span>
            </div>

            <div className="max-h-64 overflow-auto border rounded">
              <table className="w-full text-sm">
                <thead className="bg-gray-50">
                  <tr>
                    {CSV_TEMPLATE_HEADERS.slice(0, 6).map(header => (
                      <th key={header} className="px-3 py-2 text-left font-medium">
                        {header.replace(/_/g, ' ').replace(/\b\w/g, l => l.toUpperCase())}
                      </th>
                    ))}
                  </tr>
                </thead>
                <tbody>
                  {parsedData.slice(0, 10).map((row, index) => (
                    <tr key={index} className="border-t">
                      {CSV_TEMPLATE_HEADERS.slice(0, 6).map(header => (
                        <td key={header} className="px-3 py-2 truncate max-w-32">
                          {(row as any)[header] || '-'}
                        </td>
                      ))}
                    </tr>
                  ))}
                </tbody>
              </table>
            </div>

            {parsedData.length > 10 && (
              <p className="text-sm text-gray-500 text-center">
                Showing first 10 rows. {parsedData.length - 10} more rows will be imported.
              </p>
            )}

            <div className="flex gap-2 pt-4">
              <Button onClick={handleImport} className="flex-1">
                Import {parsedData.length} Investment{parsedData.length !== 1 ? 's' : ''}
              </Button>
              <Button variant="outline" onClick={resetModal}>
                Start Over
              </Button>
            </div>
          </div>
        )}

        {step === 'processing' && (
          <div className="space-y-6 text-center py-8">
            <div className="animate-spin rounded-full h-12 w-12 border-b-2 border-blue-600 mx-auto"></div>
            <div>
              <h3 className="font-medium mb-2">Processing Import...</h3>
              <p className="text-gray-600 text-sm mb-4">Validating and importing your data</p>
              <Progress value={progress} className="w-full max-w-md mx-auto" />
              <p className="text-sm text-gray-500 mt-2">{progress}% complete</p>
            </div>
          </div>
        )}

        {step === 'results' && importResult && (
          <div className="space-y-6">
            <div className="text-center">
              {importResult.success ? (
                <>
                  <CheckCircle className="h-12 w-12 text-green-500 mx-auto mb-4" />
                  <h3 className="font-medium text-green-900 mb-2">Import Completed Successfully!</h3>
                  <p className="text-gray-600">
                    {importResult.imported} investment{importResult.imported !== 1 ? 's' : ''} imported successfully
                  </p>
                </>
              ) : (
                <>
                  <AlertCircle className="h-12 w-12 text-red-500 mx-auto mb-4" />
                  <h3 className="font-medium text-red-900 mb-2">Import Failed</h3>
                  <p className="text-gray-600">Please review the errors below and try again</p>
                </>
              )}
            </div>

            {importResult.errors.length > 0 && (
              <div className="space-y-2">
                <h4 className="font-medium text-red-900">Errors ({importResult.errors.length})</h4>
                <div className="max-h-48 overflow-auto space-y-1">
                  {importResult.errors.map((error, index) => (
                    <Alert key={index} className="border-red-200">
                      <AlertDescription className="text-sm">
                        <strong>Row {error.row}:</strong> {error.message}
                      </AlertDescription>
                    </Alert>
                  ))}
                </div>
              </div>
            )}

            <div className="flex gap-2">
              <Button onClick={() => setIsOpen(false)} className="flex-1">
                Done
              </Button>
              <Button variant="outline" onClick={resetModal}>
                Import More
              </Button>
            </div>
          </div>
        )}
      </DialogContent>
    </Dialog>
  );
};

export default BulkImportModal;

/**
 * Bulk Operations Toolbar
 * Provides bulk edit, delete, and status update capabilities for investments
 */

import React, { useState } from 'react';
import { Button } from '@/components/ui/button';
import { Input } from '@/components/ui/input';
import { Select, SelectContent, SelectItem, SelectTrigger, SelectValue } from '@/components/ui/select';
import { Dialog, DialogContent, DialogHeader, DialogTitle, DialogTrigger } from '@/components/ui/dialog';
import { Label } from '@/components/ui/label';
import { Textarea } from '@/components/ui/textarea';
import {
  Edit3,
  Trash2,
  Tag,
  CheckCircle,
  X,
  AlertTriangle
} from 'lucide-react';

interface Investment {
  id: string;
  company_name: string;
  status: 'Active' | 'Exited' | 'Written Off';
  stage: string;
  sector: string;
  tags?: string[];
  [key: string]: any;
}

interface BulkOperationsToolbarProps {
  selectedInvestments: Investment[];
  onClearSelection: () => void;
  onBulkUpdate: (updates: Partial<Investment>) => Promise<void>;
  onBulkDelete: (ids: string[]) => Promise<void>;
  onBulkTag: (ids: string[], tags: string[]) => Promise<void>;
}

const INVESTMENT_STAGES = ['Pre-Seed', 'Seed', 'Series A', 'Series B', 'Series C', 'Series D+', 'Growth', 'Exit'];
const INVESTMENT_STATUSES = ['Active', 'Exited', 'Written Off', 'Under Review', 'Follow-on Required'];
const SECTORS = ['Technology', 'Healthcare', 'Financial Services', 'Consumer', 'Industrial', 'Energy', 'Real Estate', 'Other'];

export const BulkOperationsToolbar: React.FC<BulkOperationsToolbarProps> = ({
  selectedInvestments,
  onClearSelection,
  onBulkUpdate,
  onBulkDelete,
  onBulkTag
}) => {
  const [isEditModalOpen, setIsEditModalOpen] = useState(false);
  const [isDeleteModalOpen, setIsDeleteModalOpen] = useState(false);
  const [isTagModalOpen, setIsTagModalOpen] = useState(false);
  const [editForm, setEditForm] = useState<Partial<Investment>>({});
  const [newTags, setNewTags] = useState<string>('');
  const [isLoading, setIsLoading] = useState(false);

  const selectedCount = selectedInvestments.length;

  if (selectedCount === 0) {
    return null;
  }

  const handleBulkEdit = async () => {
    setIsLoading(true);
    try {
      // Remove empty/undefined values
      const cleanedUpdates = Object.fromEntries(
        Object.entries(editForm).filter(([_, value]) => value !== undefined && value !== '')
      );

      await onBulkUpdate(cleanedUpdates);
      setIsEditModalOpen(false);
      setEditForm({});
    } catch (error) {
      console.error('Bulk edit failed:', error);
    } finally {
      setIsLoading(false);
    }
  };

  const handleBulkDelete = async () => {
    setIsLoading(true);
    try {
      const ids = selectedInvestments.map(inv => inv.id);
      await onBulkDelete(ids);
      setIsDeleteModalOpen(false);
    } catch (error) {
      console.error('Bulk delete failed:', error);
    } finally {
      setIsLoading(false);
    }
  };

  const handleBulkTag = async () => {
    setIsLoading(true);
    try {
      const tags = newTags.split(',').map(tag => tag.trim()).filter(tag => tag.length > 0);
      const ids = selectedInvestments.map(inv => inv.id);
      await onBulkTag(ids, tags);
      setIsTagModalOpen(false);
      setNewTags('');
    } catch (error) {
      console.error('Bulk tagging failed:', error);
    } finally {
      setIsLoading(false);
    }
  };

  return (
    <div className="bg-blue-50 border border-blue-200 rounded-lg p-4 mb-4">
      <div className="flex items-center justify-between">
        <div className="flex items-center gap-4">
          <div className="flex items-center gap-2">
            <CheckCircle className="h-5 w-5 text-blue-600" />
            <span className="font-medium text-blue-900">
              {selectedCount} investment{selectedCount !== 1 ? 's' : ''} selected
            </span>
          </div>

          <div className="flex items-center gap-2">
            {/* Bulk Edit */}
            <Dialog open={isEditModalOpen} onOpenChange={setIsEditModalOpen}>
              <DialogTrigger asChild>
                <Button variant="outline" size="sm" className="gap-1">
                  <Edit3 className="h-4 w-4" />
                  Edit
                </Button>
              </DialogTrigger>
              <DialogContent className="max-w-md">
                <DialogHeader>
                  <DialogTitle>Bulk Edit Investments</DialogTitle>
                </DialogHeader>
                <div className="space-y-4">
                  <div>
                    <Label>Status</Label>
                    <Select
                      value={editForm.status || ''}
                      onValueChange={(value) => setEditForm(prev => ({ ...prev, status: value }))}
                    >
                      <SelectTrigger>
                        <SelectValue placeholder="Select status" />
                      </SelectTrigger>
                      <SelectContent>
                        {INVESTMENT_STATUSES.map(status => (
                          <SelectItem key={status} value={status}>{status}</SelectItem>
                        ))}
                      </SelectContent>
                    </Select>
                  </div>

                  <div>
                    <Label>Stage</Label>
                    <Select
                      value={editForm.stage || ''}
                      onValueChange={(value) => setEditForm(prev => ({ ...prev, stage: value }))}
                    >
                      <SelectTrigger>
                        <SelectValue placeholder="Select stage" />
                      </SelectTrigger>
                      <SelectContent>
                        {INVESTMENT_STAGES.map(stage => (
                          <SelectItem key={stage} value={stage}>{stage}</SelectItem>
                        ))}
                      </SelectContent>
                    </Select>
                  </div>

                  <div>
                    <Label>Sector</Label>
                    <Select
                      value={editForm.sector || ''}
                      onValueChange={(value) => setEditForm(prev => ({ ...prev, sector: value }))}
                    >
                      <SelectTrigger>
                        <SelectValue placeholder="Select sector" />
                      </SelectTrigger>
                      <SelectContent>
                        {SECTORS.map(sector => (
                          <SelectItem key={sector} value={sector}>{sector}</SelectItem>
                        ))}
                      </SelectContent>
                    </Select>
                  </div>

                  <div>
                    <Label>Notes (append to existing)</Label>
                    <Textarea
                      value={editForm['notes'] || ''}
                      onChange={(e) => setEditForm(prev => ({ ...prev, notes: e.target.value }))}
                      placeholder="Additional notes to append"
                      rows={3}
                    />
                  </div>

                  <div className="flex gap-2 pt-4">
                    <Button onClick={handleBulkEdit} disabled={isLoading} className="flex-1">
                      {isLoading ? 'Updating...' : `Update ${selectedCount} Investments`}
                    </Button>
                    <Button variant="outline" onClick={() => setIsEditModalOpen(false)}>
                      Cancel
                    </Button>
                  </div>
                </div>
              </DialogContent>
            </Dialog>

            {/* Bulk Tag */}
            <Dialog open={isTagModalOpen} onOpenChange={setIsTagModalOpen}>
              <DialogTrigger asChild>
                <Button variant="outline" size="sm" className="gap-1">
                  <Tag className="h-4 w-4" />
                  Tag
                </Button>
              </DialogTrigger>
              <DialogContent className="max-w-md">
                <DialogHeader>
                  <DialogTitle>Add Tags to Investments</DialogTitle>
                </DialogHeader>
                <div className="space-y-4">
                  <div>
                    <Label>Tags (comma-separated)</Label>
                    <Input
                      value={newTags}
                      onChange={(e) => setNewTags(e.target.value)}
                      placeholder="e.g., high-growth, ai-company, priority"
                    />
                    <p className="text-sm text-gray-600 mt-1">
                      Enter tags separated by commas. These will be added to all selected investments.
                    </p>
                  </div>

                  <div className="flex gap-2 pt-4">
                    <Button onClick={handleBulkTag} disabled={isLoading || !newTags.trim()} className="flex-1">
                      {isLoading ? 'Adding Tags...' : `Tag ${selectedCount} Investments`}
                    </Button>
                    <Button variant="outline" onClick={() => setIsTagModalOpen(false)}>
                      Cancel
                    </Button>
                  </div>
                </div>
              </DialogContent>
            </Dialog>

            {/* Quick Status Updates */}
            <div className="flex items-center gap-1 border-l pl-2 ml-2">
              <Button
                variant="outline"
                size="sm"
                className="gap-1 text-green-700 border-green-200 hover:bg-green-50"
                onClick={() => onBulkUpdate({ status: 'Active' })}
              >
                <CheckCircle className="h-4 w-4" />
                Mark Active
              </Button>
            </div>

            {/* Bulk Delete */}
            <Dialog open={isDeleteModalOpen} onOpenChange={setIsDeleteModalOpen}>
              <DialogTrigger asChild>
                <Button variant="outline" size="sm" className="gap-1 text-red-700 border-red-200 hover:bg-red-50">
                  <Trash2 className="h-4 w-4" />
                  Delete
                </Button>
              </DialogTrigger>
              <DialogContent className="max-w-md">
                <DialogHeader>
                  <DialogTitle className="flex items-center gap-2 text-red-900">
                    <AlertTriangle className="h-5 w-5" />
                    Confirm Bulk Delete
                  </DialogTitle>
                </DialogHeader>
                <div className="space-y-4">
                  <p className="text-gray-700">
                    Are you sure you want to delete {selectedCount} investment{selectedCount !== 1 ? 's' : ''}?
                    This action cannot be undone.
                  </p>

                  <div className="max-h-32 overflow-y-auto border rounded p-2 bg-gray-50">
                    {selectedInvestments.map(inv => (
                      <div key={inv.id} className="text-sm py-1">
                        • {inv.company_name}
                      </div>
                    ))}
                  </div>

                  <div className="flex gap-2 pt-4">
                    <Button
                      variant="destructive"
                      onClick={handleBulkDelete}
                      disabled={isLoading}
                      className="flex-1"
                    >
                      {isLoading ? 'Deleting...' : `Delete ${selectedCount} Investments`}
                    </Button>
                    <Button variant="outline" onClick={() => setIsDeleteModalOpen(false)}>
                      Cancel
                    </Button>
                  </div>
                </div>
              </DialogContent>
            </Dialog>
          </div>
        </div>

        <Button
          variant="ghost"
          size="sm"
          onClick={onClearSelection}
          className="gap-1 text-gray-600 hover:text-gray-900"
        >
          <X className="h-4 w-4" />
          Clear Selection
        </Button>
      </div>

      {/* Selected Investment Summary */}
      <div className="mt-3 pt-3 border-t border-blue-200">
        <div className="flex flex-wrap gap-2">
          <div className="text-sm text-blue-700">
            <strong>Companies:</strong> {selectedInvestments.slice(0, 3).map(inv => inv.company_name).join(', ')}
            {selectedCount > 3 && ` and ${selectedCount - 3} more`}
          </div>
        </div>
      </div>
    </div>
  );
};

export default BulkOperationsToolbar;

