import { useState } from 'react';
import { Card, CardContent, CardHeader, CardTitle } from '@/components/ui/card';
import { Badge } from '@/components/ui/badge';
import {
  Select,
  SelectContent,
  SelectItem,
  SelectTrigger,
  SelectValue,
} from '@/components/ui/select';
import { Input } from '@/components/ui/input';
import { 
  BarChart3, 
  LineChart, 
  PieChart, 
  TrendingUp
} from 'lucide-react';

interface ChartBuilderProps {
  onChartChange: (config: any) => void;
}

const CHART_TYPES = [
  { value: 'bar', label: 'Bar Chart', icon: BarChart3 },
  { value: 'line', label: 'Line Chart', icon: LineChart },
  { value: 'pie', label: 'Pie Chart', icon: PieChart },
  { value: 'area', label: 'Area Chart', icon: TrendingUp },
];

const METRICS = [
  { value: 'revenue', label: 'Revenue' },
  { value: 'grossMargin', label: 'Gross Margin' },
  { value: 'burnRate', label: 'Burn Rate' },
  { value: 'cashInBank', label: 'Cash in Bank' },
  { value: 'currentValuation', label: 'Current Valuation' },
  { value: 'totalInvested', label: 'Total Invested' },
  { value: 'employees', label: 'Employee Count' },
  { value: 'arrGrowth', label: 'ARR Growth' },
  { value: 'mrr', label: 'Monthly Recurring Revenue' },
];

const DIMENSIONS = [
  { value: 'name', label: 'Company Name' },
  { value: 'sector', label: 'Sector' },
  { value: 'stage', label: 'Stage' },
  { value: 'quarter', label: 'Time Quarter' },
];

export default function SimpleChartBuilder({ onChartChange }: ChartBuilderProps) {
  const [chartType, setChartType] = useState('bar');
  const [xAxis, setXAxis] = useState('name');
  const [yAxis, setYAxis] = useState('revenue');
  const [title, setTitle] = useState('Revenue by Company');

  const updateChart = (updates: any) => {
    const config = {
      type: chartType,
      xAxis,
      yAxis,
      title,
      ...updates,
    };

    onChartChange(config);
  };

  const handleChartTypeChange = (value: string) => {
    setChartType(value);
    updateChart({ type: value });
  };

  const handleXAxisChange = (value: string) => {
    setXAxis(value);
    updateChart({ xAxis: value });
  };

  const handleYAxisChange = (value: string) => {
    setYAxis(value);
    updateChart({ yAxis: value });
  };

  const handleTitleChange = (value: string) => {
    setTitle(value);
    updateChart({ title: value });
  };

  return (
    <div className="space-y-6">
      {/* Chart Configuration */}
      <Card>
        <CardHeader>
          <CardTitle>Chart Configuration</CardTitle>
        </CardHeader>
        <CardContent>
          <div className="grid grid-cols-2 md:grid-cols-4 gap-4">
            <div>
              <label className="block text-sm font-medium mb-2">Chart Type</label>
              <Select value={chartType} onValueChange={handleChartTypeChange}>
                <SelectTrigger>
                  <SelectValue />
                </SelectTrigger>
                <SelectContent>
                  {CHART_TYPES.map((type: any) => {
                    const Icon = type.icon;
                    return (
                      <SelectItem key={type.value} value={type.value}>
                        <div className="flex items-center">
                          <Icon className="h-4 w-4 mr-2" />
                          {type.label}
                        </div>
                      </SelectItem>
                    );
                  })}
                </SelectContent>
              </Select>
            </div>

            <div>
              <label className="block text-sm font-medium mb-2">X-Axis</label>
              <Select value={xAxis} onValueChange={handleXAxisChange}>
                <SelectTrigger>
                  <SelectValue />
                </SelectTrigger>
                <SelectContent>
                  {DIMENSIONS.map((dim: any) => (
                    <SelectItem key={dim.value} value={dim.value}>
                      {dim.label}
                    </SelectItem>
                  ))}
                </SelectContent>
              </Select>
            </div>

            <div>
              <label className="block text-sm font-medium mb-2">Y-Axis</label>
              <Select value={yAxis} onValueChange={handleYAxisChange}>
                <SelectTrigger>
                  <SelectValue />
                </SelectTrigger>
                <SelectContent>
                  {METRICS.map((metric: any) => (
                    <SelectItem key={metric.value} value={metric.value}>
                      {metric.label}
                    </SelectItem>
                  ))}
                </SelectContent>
              </Select>
            </div>

            <div>
              <label className="block text-sm font-medium mb-2">Title</label>
              <Input
                value={title}
                onChange={(e: any) => handleTitleChange(e.target.value)}
                placeholder="Chart title"
              />
            </div>
          </div>
        </CardContent>
      </Card>

      {/* Current Configuration Summary */}
      <Card>
        <CardHeader>
          <CardTitle>Current Configuration</CardTitle>
        </CardHeader>
        <CardContent>
          <div className="flex flex-wrap gap-2">
            <Badge variant="outline">
              Chart: {CHART_TYPES.find(t => t.value === chartType)?.label}
            </Badge>
            <Badge variant="outline">
              X-Axis: {DIMENSIONS.find(d => d.value === xAxis)?.label}
            </Badge>
            <Badge variant="outline">
              Y-Axis: {METRICS.find(m => m.value === yAxis)?.label}
            </Badge>
            <Badge variant="outline">
              Title: {title}
            </Badge>
          </div>
        </CardContent>
      </Card>
    </div>
  );
}

/**
 * Allocations Tab Component
 * Displays allocation state for all companies in a fund
 */
import { useState, useMemo, useCallback } from 'react';
import {
  Table,
  TableBody,
  TableCell,
  TableHead,
  TableHeader,
  TableRow,
} from '@/components/ui/table';
import { Button } from '@/components/ui/button';
import { Input } from '@/components/ui/input';
import { Badge } from '@/components/ui/badge';
import { Alert, AlertDescription } from '@/components/ui/alert';
import { Skeleton } from '@/components/ui/skeleton';
import { Card, CardContent, CardHeader, CardTitle } from '@/components/ui/card';
import { Search, AlertCircle, RefreshCw } from 'lucide-react';
import { useLatestAllocations } from './hooks/useLatestAllocations';
import { EditAllocationDialog } from './EditAllocationDialog';
import { createAllocationsColumns } from './allocations-table-columns';
import { formatCents } from '@/lib/units';
import type { AllocationCompany } from './types';

export function AllocationsTab() {
  const { data, isLoading, error, refetch } = useLatestAllocations();
  const [selectedCompany, setSelectedCompany] = useState<AllocationCompany | null>(null);
  const [isEditDialogOpen, setIsEditDialogOpen] = useState(false);
  const [searchQuery, setSearchQuery] = useState('');
  const [sectorFilter, setSectorFilter] = useState<string>('all');
  const [statusFilter, setStatusFilter] = useState<string>('all');
  const [sortConfig, setSortConfig] = useState<{
    key: keyof AllocationCompany;
    direction: 'asc' | 'desc';
  } | null>(null);

  const handleEdit = useCallback((company: AllocationCompany) => {
    setSelectedCompany(company);
    setIsEditDialogOpen(true);
  }, []);

  const columns = useMemo(() => createAllocationsColumns(handleEdit), [handleEdit]);

  const companies = data?.companies;

  // Extract unique sectors and statuses for filters
  const sectors = useMemo(() => {
    if (!companies) return [];
    return Array.from(new Set(companies.map((c) => c.sector))).sort();
  }, [companies]);

  const statuses = useMemo(() => {
    if (!companies) return [];
    return Array.from(new Set(companies.map((c) => c.status))).sort();
  }, [companies]);

  // Filter and sort data
  const filteredAndSortedCompanies = useMemo(() => {
    if (!companies) return [];

    let filtered = companies.filter((company) => {
      const matchesSearch = company.company_name
        .toLowerCase()
        .includes(searchQuery.toLowerCase());
      const matchesSector = sectorFilter === 'all' || company.sector === sectorFilter;
      const matchesStatus = statusFilter === 'all' || company.status === statusFilter;

      return matchesSearch && matchesSector && matchesStatus;
    });

    if (sortConfig) {
      filtered = [...filtered].sort((a, b) => {
        const aValue = a[sortConfig.key];
        const bValue = b[sortConfig.key];

        if (aValue === null) return 1;
        if (bValue === null) return -1;

        if (typeof aValue === 'string' && typeof bValue === 'string') {
          return sortConfig.direction === 'asc'
            ? aValue.localeCompare(bValue)
            : bValue.localeCompare(aValue);
        }

        if (typeof aValue === 'number' && typeof bValue === 'number') {
          return sortConfig.direction === 'asc' ? aValue - bValue : bValue - aValue;
        }

        return 0;
      });
    }

    return filtered;
  }, [companies, searchQuery, sectorFilter, statusFilter, sortConfig]);

  const handleSort = (key: keyof AllocationCompany) => {
    setSortConfig((current) => {
      if (!current || current.key !== key) {
        return { key, direction: 'asc' };
      }
      if (current.direction === 'asc') {
        return { key, direction: 'desc' };
      }
      return null;
    });
  };

  // Create column objects with sorting handlers
  const enrichedColumns = columns.map((col) => ({
    ...col,
    column: {
      toggleSorting: (desc?: boolean) => {
        if (col.accessorKey) {
          handleSort(col.accessorKey);
        }
      },
    },
  }));

  // Loading state
  if (isLoading) {
    return (
      <div className="space-y-4">
        <Skeleton className="h-12 w-full" />
        <Skeleton className="h-64 w-full" />
      </div>
    );
  }

  // Error state
  if (error) {
    return (
      <Alert variant="destructive">
        <AlertCircle className="h-4 w-4" />
        <AlertDescription>
          {error instanceof Error ? error.message : 'Failed to load allocations'}
        </AlertDescription>
        <Button variant="outline" size="sm" onClick={() => refetch()} className="mt-2">
          <RefreshCw className="h-4 w-4 mr-2" />
          Retry
        </Button>
      </Alert>
    );
  }

  // Empty state
  if (!companies || companies.length === 0) {
    return (
      <Card>
        <CardHeader>
          <CardTitle>Company Allocations</CardTitle>
        </CardHeader>
        <CardContent>
          <div className="text-center py-12 text-gray-500">
            <p className="text-lg font-medium mb-2">No companies found</p>
            <p className="text-sm">
              There are no companies with allocation data for this fund.
            </p>
          </div>
        </CardContent>
      </Card>
    );
  }

  return (
    <div className="space-y-4">
      {/* Header */}
      <div className="flex items-center justify-between">
        <div>
          <h2 className="text-2xl font-bold text-gray-900">Company Allocations</h2>
          <p className="text-sm text-gray-500 mt-1">
