                      ? column.header({ column: column.column })
                      : column.header}
                  </TableHead>
                ))}
              </TableRow>
            </TableHeader>
            <TableBody>
              {filteredAndSortedCompanies.length === 0 ? (
                <TableRow>
                  <TableCell
                    colSpan={enrichedColumns.length}
                    className="text-center py-8 text-gray-500"
                  >
