  const getMetricLabel = () => {
    switch (selectedMetric) {
      case 'invested': return 'Invested to Date';
      case 'moic': return 'MOIC';
      case 'irr': return 'IRR (%)';
      case 'count': return 'Number of Companies';
      default: return 'Invested to Date';
