// Main SwipeableMetricCards component
export function SwipeableMetricCards({
  metrics,
  activeIndex = 0,
  onIndexChange,
  onCardSelect,
  className,
  cardClassName,
  showNavigation = true,
  showIndicators = true,
  autoScroll = false,
  autoScrollInterval = 5000,
  compactMode = false,
  cardsPerView = 1,
  enableSwipeNavigation = true
}: SwipeableMetricCardsProps) {
  const scrollRef = useRef<HTMLDivElement>(null);
  const [isDragging, setIsDragging] = useState(false);
  const [dragStart, setDragStart] = useState({ x: 0, scrollLeft: 0, time: 0 });
  const [currentIndex, setCurrentIndex] = useState(activeIndex);
  const autoScrollTimeoutRef = useRef<ReturnType<typeof setTimeout>>();

  // Handle index changes
  const handleIndexChange = useCallback((newIndex: number) => {
    const clampedIndex = Math.max(0, Math.min(metrics.length - 1, newIndex));
    setCurrentIndex(clampedIndex);
    onIndexChange?.(clampedIndex);

    // Scroll to the correct position
    if (scrollRef.current) {
      const scrollContainer = scrollRef.current;
      const cardWidth = scrollContainer.clientWidth / cardsPerView;
      const targetScrollLeft = clampedIndex * cardWidth;

      scrollContainer.scrollTo({
        left: targetScrollLeft,
        behavior: 'smooth'
      });
    }
  }, [metrics.length, onIndexChange, cardsPerView]);

  // Auto-scroll functionality
  useEffect(() => {
    if (autoScroll && metrics.length > 1) {
      autoScrollTimeoutRef.current = setTimeout(() => {
        const nextIndex = (currentIndex + 1) % metrics.length;
        handleIndexChange(nextIndex);
      }, autoScrollInterval);

      return () => {
        if (autoScrollTimeoutRef.current) {
          clearTimeout(autoScrollTimeoutRef.current);
        }
      };
    }
  }, [autoScroll, currentIndex, metrics.length, autoScrollInterval, handleIndexChange]);

  // Touch/Mouse event handlers
  const handlePointerDown = (clientX: number) => {
    if (!scrollRef.current) return;

    setIsDragging(true);
    setDragStart({
      x: clientX,
      scrollLeft: scrollRef.current.scrollLeft,
      time: Date.now()
    });

    // Stop auto-scroll when user interacts
    if (autoScrollTimeoutRef.current) {
      clearTimeout(autoScrollTimeoutRef.current);
    }
  };

  const handlePointerMove = (clientX: number) => {
    if (!isDragging || !scrollRef.current) return;

    const deltaX = clientX - dragStart.x;
    const newScrollLeft = dragStart.scrollLeft - deltaX;
    scrollRef.current.scrollLeft = newScrollLeft;
  };

  const handlePointerUp = (clientX: number) => {
    if (!isDragging || !scrollRef.current) return;

    setIsDragging(false);

    const deltaX = clientX - dragStart.x;
    const deltaTime = Date.now() - dragStart.time;
    const velocity = Math.abs(deltaX) / deltaTime;

    // Determine if it's a swipe or click
    const isSwipe = Math.abs(deltaX) > 50 || velocity > 0.5;

    if (isSwipe) {
      // Swipe navigation
      const direction = deltaX > 0 ? -1 : 1;
      const newIndex = currentIndex + direction;
      handleIndexChange(newIndex);
    } else {
      // Snap to nearest card
      const cardWidth = scrollRef.current.clientWidth / cardsPerView;
      const newIndex = Math.round(scrollRef.current.scrollLeft / cardWidth);
      handleIndexChange(newIndex);
    }
  };

  // Touch events
  const handleTouchStart = (e: React.TouchEvent) => {
    e.preventDefault();
    handlePointerDown(e.touches[0]!.clientX);
  };

  const handleTouchMove = (e: React.TouchEvent) => {
    handlePointerMove(e.touches[0]!.clientX);
  };

  const handleTouchEnd = (e: React.TouchEvent) => {
    handlePointerUp(e.changedTouches[0]!.clientX);
  };

  // Mouse events for desktop
  const handleMouseDown = (e: React.MouseEvent) => {
    e.preventDefault();
    handlePointerDown(e.clientX);
  };

  const handleMouseMove = (e: React.MouseEvent) => {
    handlePointerMove(e.clientX);
  };

  const handleMouseUp = (e: React.MouseEvent) => {
    handlePointerUp(e.clientX);
  };

  // Navigation functions
  const goToPrevious = () => {
    handleIndexChange(currentIndex - 1);
  };

  const goToNext = () => {
    handleIndexChange(currentIndex + 1);
  };

  const handleCardClick = (metric: MetricCardData, index: number) => {
    if (Math.abs(Date.now() - dragStart.time) < 200) {
      // Quick tap - treat as selection
      onCardSelect?.(metric, index);
    }
    handleIndexChange(index);
  };

  // Responsive cards per view
  const getCardsPerView = () => {
    if (typeof window === 'undefined') return cardsPerView;

    const width = window.innerWidth;
    if (width >= 1024) return Math.min(4, metrics.length); // Desktop
    if (width >= 640) return Math.min(2, metrics.length);  // Tablet
    return 1; // Mobile
  };

  const responsiveCardsPerView = getCardsPerView();

  return (
    <div className={cn("space-y-4", className)}>
      {/* Header with title and navigation */}
      {showNavigation && (
        <div className="flex items-center justify-between">
          <h3 className="font-inter font-semibold text-lg text-slate-900">
            Key Metrics
          </h3>
          <div className="flex items-center gap-2">
            <Button
              variant="ghost"
              size="sm"
              onClick={goToPrevious}
              disabled={currentIndex === 0}
              className="h-8 w-8 p-0"
              aria-label="Previous metric"
            >
              <ChevronLeft className="h-4 w-4" />
            </Button>

            {showIndicators && (
              <div className="flex items-center gap-1 px-2">
                {metrics.map((_, index) => (
                  <button
                    key={index}
                    className={cn(
                      "w-2 h-2 rounded-full transition-all duration-300",
                      index === currentIndex
                        ? "bg-blue-600 w-4"
                        : "bg-slate-300 hover:bg-slate-400"
                    )}
                    onClick={() => handleIndexChange(index)}
                    aria-label={`Go to metric ${index + 1}`}
                  />
                ))}
              </div>
            )}

            <Button
              variant="ghost"
              size="sm"
              onClick={goToNext}
              disabled={currentIndex === metrics.length - 1}
              className="h-8 w-8 p-0"
              aria-label="Next metric"
            >
              <ChevronRight className="h-4 w-4" />
            </Button>
          </div>
        </div>
      )}

      {/* Swipeable container */}
      <div
        ref={scrollRef}
        className={cn(
          "flex gap-4 overflow-x-auto scrollbar-hide snap-x snap-mandatory",
          "touch-pan-x select-none",
          isDragging ? "cursor-grabbing" : "cursor-grab"
        )}
        onTouchStart={handleTouchStart}
        onTouchMove={handleTouchMove}
        onTouchEnd={handleTouchEnd}
        onMouseDown={handleMouseDown}
        onMouseMove={isDragging ? handleMouseMove : undefined}
        onMouseUp={isDragging ? handleMouseUp : undefined}
        onMouseLeave={isDragging ? handleMouseUp : undefined}
        onKeyDown={(e) => {
          if (e.key === 'ArrowLeft') {
            e.preventDefault();
            goToPrevious();
          } else if (e.key === 'ArrowRight') {
            e.preventDefault();
            goToNext();
          }
        }}
        tabIndex={0}
        style={{
          scrollbarWidth: 'none',
          msOverflowStyle: 'none',
          WebkitOverflowScrolling: 'touch'
        }}
      >
        {metrics.map((metric, index) => (
          <div
            key={metric.id}
            className={cn(
              "flex-shrink-0 snap-start",
              responsiveCardsPerView === 1 && "w-full",
              responsiveCardsPerView === 2 && "w-[calc(50%-0.5rem)]",
              responsiveCardsPerView >= 4 && "w-[calc(25%-0.75rem)]"
            )}
          >
            <MetricCard
              metric={metric}
              isActive={index === currentIndex}
              onClick={() => handleCardClick(metric, index)}
              compactMode={compactMode}
              {...spreadIfDefined('className', cardClassName)}
            />
          </div>
        ))}
      </div>

      {/* Accessibility info */}
      <div className="sr-only" aria-live="polite">
        Showing metric {currentIndex + 1} of {metrics.length}: {metrics[currentIndex]?.title}
      </div>
    </div>
  );
}

export default SwipeableMetricCards;

/**
 * AIInsightCard Component
 *
 * Transforms Monte Carlo simulation results into natural language insights
 * with confidence levels and actionable recommendations for VC decisions.
 */

import React from 'react';
import { Card, CardContent, CardHeader } from '@/components/ui/card';
import { Badge } from '@/components/ui/badge';
import { cn } from '@/lib/utils';
import {
  Lightbulb,
  TrendingUp,
  AlertTriangle,
  Target,
  Brain,
  BarChart3
} from 'lucide-react';

// Types based on power law distribution data structures
export interface MonteCarloResult {
  multiple: number;
  irr: number;
  category: 'failure' | 'modest' | 'good' | 'homeRun' | 'unicorn';
  stage: string;
  exitTiming: number;
}

export interface PortfolioInsight {
  title: string;
  insight: string;
  recommendation: string;
  confidence: number;
  severity: 'low' | 'medium' | 'high' | 'critical';
  category: 'risk' | 'opportunity' | 'strategy' | 'allocation';
  metrics?: {
    label: string;
    value: string | number;
    trend?: 'up' | 'down' | 'stable';
  }[];
}

interface AIInsightCardProps {
  results?: MonteCarloResult[];
  portfolioSize?: number;
  fundSize?: number;
  timeHorizon?: number;
  insights?: PortfolioInsight[];
  className?: string;
  variant?: 'default' | 'compact' | 'detailed';
}

// AI insight generation based on Monte Carlo results
function generateInsights(
  results: MonteCarloResult[],
  portfolioSize: number,
  fundSize: number,
  timeHorizon: number
): PortfolioInsight[] {
  const insights: PortfolioInsight[] = [];

  if (!results || results.length === 0) return insights;

  // Calculate key metrics
  const totalInvestments = results.length;
  const avgMultiple = results.reduce((sum, r) => sum + r.multiple, 0) / totalInvestments;
  const failureRate = results.filter(r => r.category === 'failure').length / totalInvestments;
  const unicornRate = results.filter(r => r.category === 'unicorn').length / totalInvestments;
  const homeRunRate = results.filter(r => r.category === 'homeRun').length / totalInvestments;

  // Series A Chasm Analysis
  if (failureRate > 0.65) {
    insights.push({
      title: "Series A Chasm Detected",
      insight: `Your ${Math.round(failureRate * 100)}% failure rate reflects the harsh reality of the Series A Chasm, where most startups fail to secure subsequent funding rounds.`,
      recommendation: `Consider increasing reserve allocation to ${Math.round(28 + failureRate * 10)}% to support portfolio companies through this critical transition.`,
      confidence: 85,
      severity: 'high',
      category: 'risk',
      metrics: [
        { label: 'Failure Rate', value: `${Math.round(failureRate * 100)}%`, trend: 'down' },
        { label: 'Recommended Reserves', value: `${Math.round(28 + failureRate * 10)}%`, trend: 'up' }
      ]
    });
  }

  // Power Law Distribution Analysis
  if (unicornRate > 0.005 && homeRunRate > 0.03) {
    insights.push({
      title: "Power Law Distribution Active",
      insight: `Your portfolio shows healthy power law dynamics with ${Math.round(unicornRate * 100 * 100) / 100}% unicorns driving ${Math.round((avgMultiple - 1) * 100)}% of returns.`,
      recommendation: `Focus on identifying and doubling down on potential 10x+ outcomes. Consider concentrating follow-on investments in top quartile performers.`,
      confidence: 92,
      severity: 'medium',
      category: 'opportunity',
      metrics: [
        { label: 'Unicorn Rate', value: `${Math.round(unicornRate * 1000) / 10}%`, trend: 'up' },
        { label: 'Home Run Rate', value: `${Math.round(homeRunRate * 100)}%`, trend: 'up' }
      ]
    });
  }

  // Portfolio Concentration Risk
  const top10Percent = Math.ceil(results.length * 0.1);
  const topPerformers = results.sort((a, b) => b.multiple - a.multiple).slice(0, top10Percent);
  const topPerformerContribution = topPerformers.reduce((sum, r) => sum + r.multiple, 0) /
                                   results.reduce((sum, r) => sum + r.multiple, 0);

  if (topPerformerContribution > 0.8) {
    insights.push({
      title: "High Concentration Risk",
      insight: `Top ${Math.round(100/results.length * top10Percent)}% of investments drive ${Math.round(topPerformerContribution * 100)}% of total returns.`,
      recommendation: `Diversify portfolio construction and consider increasing check sizes for high-conviction opportunities to reduce concentration risk.`,
      confidence: 78,
      severity: 'medium',
      category: 'risk',
      metrics: [
        { label: 'Top Performer Impact', value: `${Math.round(topPerformerContribution * 100)}%`, trend: 'up' },
        { label: 'Portfolio Concentration', value: 'High', trend: 'stable' }
      ]
    });
  }

  // IRR Analysis
  const avgIRR = results.reduce((sum, r) => sum + r.irr, 0) / totalInvestments;
  if (avgIRR > 0.25) {
    insights.push({
      title: "Strong IRR Performance",
      insight: `Portfolio IRR of ${Math.round(avgIRR * 100)}% exceeds venture benchmarks, indicating strong investment selection and timing.`,
      recommendation: `Maintain current investment thesis and consider raising fund size to capitalize on deal flow quality.`,
      confidence: 88,
      severity: 'low',
      category: 'opportunity',
      metrics: [
        { label: 'Portfolio IRR', value: `${Math.round(avgIRR * 100)}%`, trend: 'up' },
        { label: 'Benchmark', value: '20-25%', trend: 'stable' }
      ]
    });
  }

  return insights;
}

