      // Default C to Exit - not in original FundDataForReserves
      cToExit: { graduate: 65, fail: 15, remain: 20 },
    },
  };

  // Only add seed for stochastic mode
  if (!expectationMode) {
    config.seed = seed;
  }

  return config;
}

