/**
 * Fund Domain Types
 *
 * Type-safe domain models for VC fund KPI calculations.
 * All types are designed for immutability and pure function compatibility.
 *
 * @module fund-domain
 */

/**
 * Core fund information
 */
export interface Fund {
  id: number;
  name: string;
  size: number; // Total committed capital
  managementFee: number; // Annual management fee rate (decimal, e.g., 0.025 for 2.5%)
  carryPercentage: number; // Carried interest percentage (decimal, e.g., 0.20 for 20%)
  vintageYear: number;
  establishmentDate?: string; // ISO date string
  deployedCapital: number; // Total capital deployed to date
  status: string;
  createdAt: string;
  updatedAt: string;
  termYears?: number; // Fund term in years
}

/**
 * Portfolio company investment
 */
export interface Investment {
  id: number;
  fundId: number;
  companyName: string;
  investmentDate: string; // ISO date string
  initialAmount: number; // Initial investment amount
  totalInvested: number; // Total invested including follow-ons
  stage: string; // e.g., 'seed', 'series_a', 'series_b'
  sector: string;
  ownership: number; // Ownership percentage (decimal, e.g., 0.15 for 15%)
  isActive: boolean;
  exitDate?: string; // ISO date string if exited
  exitAmount?: number; // Exit proceeds if realized
  createdAt: string;
  updatedAt: string;
}

/**
 * Portfolio company valuation (fair value)
 */
export interface Valuation {
  id: number;
  investmentId: number;
  valuationDate: string; // ISO date string
  fairValue: number; // Fair market value of the position
  valuer: string; // Who provided the valuation (e.g., 'GP', 'third_party')
  methodology: string; // Valuation methodology (e.g., 'last_round', 'dcf', 'comparable')
  notes?: string;
  isLatest: boolean; // Whether this is the most recent valuation
  createdAt: string;
  updatedAt: string;
}

/**
 * Capital call to LPs
 */
export interface CapitalCall {
  id: number;
  fundId: number;
  callNumber: number; // Sequential capital call number
  amount: number; // Total amount called
  callDate: string; // ISO date string when call was issued
  dueDate: string; // ISO date string when payment is due
  receivedDate?: string; // ISO date string when fully received
  status: 'planned' | 'issued' | 'partial' | 'received' | 'overdue';
  purpose: string; // Reason for the capital call
  createdAt: string;
  updatedAt: string;
}

/**
 * Distribution to LPs
 */
export interface Distribution {
  id: number;
  fundId: number;
  distributionDate: string; // ISO date string
  amount: number; // Total distribution amount
  type: 'recallable' | 'non_recallable' | 'return_of_capital' | 'profit';
  source?: string; // Source of distribution (e.g., company exit, dividend)
  investmentId?: number; // Related investment if distribution is from exit
  status: 'planned' | 'approved' | 'executed';
  createdAt: string;
  updatedAt: string;
}

/**
 * Fund operating expenses and fees
 */
export interface FeeExpense {
  id: number;
  fundId: number;
  expenseDate: string; // ISO date string
  amount: number; // Expense amount (positive number)
  category: 'management_fee' | 'legal' | 'audit' | 'admin' | 'consulting' | 'other';
  description: string;
  isPaid: boolean;
  createdAt: string;
  updatedAt: string;
}

/**
 * Cash flow event for XIRR/IRR calculations
 * Negative amounts = outflows (investments, fees)
 * Positive amounts = inflows (distributions, exits)
 */
export interface CashFlowEvent {
  date: string; // ISO date string
  amount: number; // Positive for inflows, negative for outflows
  type: 'capital_call' | 'distribution' | 'fee' | 'other';
}

/**
 * Complete fund data structure for KPI calculations
 * This is the primary input to selector functions
 */
export interface FundData {
  fund: Fund;
  investments: Investment[];
  valuations: Valuation[];
  capitalCalls: CapitalCall[];
  distributions: Distribution[];
  feeExpenses: FeeExpense[];
}

/**
 * Historical snapshot options for "as of" date queries
 */
export interface AsOfOptions {
  asOf?: string; // ISO date string - if not provided, uses current date
}

/**
 * KPI calculation result with metadata
 */
export interface KPIResult<T> {
  value: T;
  calculatedAt: string; // ISO date string
  asOf?: string; // ISO date string if historical
  metadata?: Record<string, unknown>;
}

/**
 * Complete KPI snapshot
 */
export interface FundKPIs {
  committed: number; // Total committed capital
  called: number; // Total capital called from LPs
  uncalled: number; // Remaining callable capital (committed - called)
  invested: number; // Total capital invested in portfolio companies
  nav: number; // Net Asset Value (current portfolio value - liabilities)
  dpi: number; // Distributions to Paid-In (distributions / called)
  tvpi: number; // Total Value to Paid-In ((distributions + nav) / called)
  irr: number; // Internal Rate of Return (annualized)
  calculatedAt: string; // ISO date string
  asOf?: string; // ISO date string if historical
}

/**
 * Type guards for runtime validation
 */
export function isFund(obj: unknown): obj is Fund {
  return (
    typeof obj === 'object' &&
    obj !== null &&
    'id' in obj &&
    'name' in obj &&
    'size' in obj &&
    typeof (obj as Fund).size === 'number'
  );
}

export function isFundData(obj: unknown): obj is FundData {
  return (
    typeof obj === 'object' &&
    obj !== null &&
    'fund' in obj &&
    'investments' in obj &&
    'valuations' in obj &&
    'capitalCalls' in obj &&
    'distributions' in obj &&
    'feeExpenses' in obj &&
    isFund((obj as FundData).fund) &&
    Array.isArray((obj as FundData).investments) &&
    Array.isArray((obj as FundData).valuations) &&
    Array.isArray((obj as FundData).capitalCalls) &&
    Array.isArray((obj as FundData).distributions) &&
    Array.isArray((obj as FundData).feeExpenses)
  );
}

/**
 * Helper type for filtering by date
 */
export type DateFilterable = {
  [K in keyof any]: string;
} & Record<string, unknown>;

/**
 * Utility type for making all properties optional except specified keys
 */
export type PartialExcept<T, K extends keyof T> = Partial<T> & Pick<T, K>;

export function installFetchTap() {
  if (import.meta.env['VITE_WIZARD_DEBUG'] !== '1') return;
  if ((window as any).__fetch_tap_installed) return;
  (window as any).__fetch_tap_installed = true;

  const orig = window.fetch;
  window.fetch = async (input: RequestInfo | URL, init?: RequestInit) => {
    const url = typeof input === 'string' ? input : (input as Request).url;
    const t0 = performance.now();
    try {
      const res = await orig(input, init);
      console.log(`[FETCH] ${init?.method ?? 'GET'} ${url} → ${res.status} in ${(performance.now()-t0).toFixed(1)}ms`);
      return res;
    } catch (e) {
      console.warn(`[FETCH] ${init?.method ?? 'GET'} ${url} → NETWORK ERROR`, e);
      throw e;
    }
  };
}

export function traceWizard(
  event: string,
  detail?: unknown,
  opts?: { component?: string }
) {
  if (import.meta.env['VITE_WIZARD_DEBUG'] !== '1') return;
  const entry = {
    ts: new Date().toISOString(),
    t: Math.round(performance.now()), // ms since navigationStart
    event,
    component: opts?.component,
    detail: sanitize(detail),
  };
  // Log a single JSON object for easy copy/paste/parse
  // Use `WIZARD` marker so it's easy to filter in Console
  console.log('WIZARD', entry);
}

function sanitize(v: unknown) {
  try {
    const s = JSON.stringify(v);
    return s && s.length > 140 ? JSON.parse(`${s.slice(0, 140)  }"…]"`) : v;
  } catch {
    return String(v);
  }
}

/**
 * Engine selector with shadow comparison capability
 * Intelligently chooses between TypeScript and WASM implementations
 * Supports A/B testing and gradual migration
 */

import { isEnabled } from '@/lib/feature-flags';
import { calculateReservesSafe } from '@/lib/reserves-v11';
import { metrics } from '@/metrics/reserves-metrics';
import type { 
  ReservesInput, 
  ReservesConfig, 
  ReservesResult,
  Company 
} from '@shared/types/reserves-v11';

// Mock WASM implementation (replace with actual when available)
async function calculateReservesWASM(
  input: ReservesInput,
  config: ReservesConfig
): Promise<ReservesResult> {
  // Simulate WASM call delay
  await new Promise(resolve => setTimeout(resolve, 10));

  // For now, return TS implementation
  // In production, this would call the actual WASM module
  return calculateReservesSafe(input, config);
}

// TypeScript implementation wrapper
async function calculateReservesTS(
  input: ReservesInput,
  config: ReservesConfig
): Promise<ReservesResult> {
  return calculateReservesSafe(input, config);
}

// Check if results are different (for shadow comparison)
function isDifferent(
  tsResult: ReservesResult,
  wasmResult: ReservesResult,
  epsilonCents: number = 1
): boolean {
  if (!tsResult.ok || !wasmResult.ok) {
    return tsResult.ok !== wasmResult.ok;
  }

  const tsData = tsResult.data!;
  const wasmData = wasmResult.data!;

  // Check remaining difference
  if (Math.abs(tsData.remaining_cents - wasmData.remaining_cents) > epsilonCents) {
    return true;
  }

  // Check allocation count
  if (tsData.allocations.length !== wasmData.allocations.length) {
    return true;
  }

  // Check each allocation
  const tsMap = new Map(tsData.allocations.map(a => [a.company_id, a.planned_cents]));
  const wasmMap = new Map(wasmData.allocations.map(a => [a.company_id, a.planned_cents]));

  for (const [id, tsCents] of tsMap) {
    const wasmCents = wasmMap['get'](id);
    if (wasmCents === undefined || Math.abs(tsCents - wasmCents) > epsilonCents) {
      return true;
    }
  }

  return false;
}

// Engine selection function
export type ReservesCalculator = (
  input: ReservesInput,
  config: ReservesConfig
) => Promise<ReservesResult>;

/**
 * Get the appropriate reserves calculator based on feature flags and user
 */
export async function getReservesCalculator(userId?: string): Promise<ReservesCalculator> {
  const shadow = isEnabled('shadow_compare', userId);
  const tsOn = isEnabled('ts_reserves', userId);
  const wasmOn = isEnabled('wasm_reserves', userId);

  // Shadow comparison mode - run both and compare
  if (shadow && tsOn && wasmOn) {
    return async (input: ReservesInput, config: ReservesConfig) => {
      const timer = metrics.startTimer('reserves.shadow_compare');

      try {
        // Run both implementations in parallel
        const [tsResult, wasmResult] = await Promise.all([
          calculateReservesTS(input, config),
          calculateReservesWASM(input, config).catch(error => {
            // If WASM fails, log and continue with TS
            metrics.recordError(`WASM error: ${error}`);
            return null;
          })
        ]);

        // Compare results if both succeeded
        if (wasmResult && isDifferent(tsResult, wasmResult)) {
          metrics.recordDivergence(tsResult, wasmResult);
          console.warn('Reserves calculation divergence detected', {
            ts: tsResult.data,
            wasm: wasmResult.data
          });
        }

        // Always return TS result during shadow mode
        return tsResult;

      } finally {
        timer.end();
      }
    };
  }

  // WASM only mode
  if (wasmOn && !tsOn) {
    return async (input: ReservesInput, config: ReservesConfig) => {
      const timer = metrics.startTimer('reserves.wasm');
      try {
        return await calculateReservesWASM(input, config);
      } catch (error) {
        // Fallback to TS if WASM fails
        metrics.recordError(`WASM fallback: ${error}`);
        return await calculateReservesTS(input, config);
      } finally {
        timer.end();
      }
    };
  }

  // TypeScript mode (default)
  return async (input: ReservesInput, config: ReservesConfig) => {
    const timer = metrics.startTimer('reserves.typescript');
    try {
      return await calculateReservesTS(input, config);
    } finally {
      timer.end();
    }
  };
}

/**
