// HELPER TYPES
// =============================================================================

export interface LiquidityAlert {
  id: string;
  type: 'info' | 'warning' | 'error';
  title: string;
  message: string;
  severity: 'low' | 'medium' | 'high';
  timestamp: Date;
}

// =============================================================================
