// =============================================================================

function formatCurrency(amount: number): string {
  return new Intl.NumberFormat('en-US', {
    style: 'currency',
    currency: 'USD',
    minimumFractionDigits: 0,
    maximumFractionDigits: 0,
  }).format(amount);
}

/**
 * useModelingWizard Hook
 *
 * React hook that integrates the XState modeling wizard machine with React components.
 * Provides a clean API for:
 * - State management
 * - Navigation
 * - Validation
 * - Persistence
 * - Submission
 */

import { useMachine } from '@xstate/react';
import { useCallback, useEffect, useMemo } from 'react';
import {
  modelingWizardMachine,
  type WizardStep,
  type ModelingWizardContext,
  STEP_ORDER,
  getNextStep,
  getPreviousStep
} from '@/machines/modeling-wizard.machine';

// ============================================================================
// TYPES
// ============================================================================

export interface UseModelingWizardOptions {
  /**
   * Skip optional steps (e.g., Exit Recycling)
   */
  skipOptionalSteps?: boolean;

  /**
   * Auto-save interval in milliseconds
   * Default: 30000 (30 seconds)
   */
  autoSaveInterval?: number;

  /**
   * Load saved progress on mount
   * Default: true
   */
  loadSavedProgress?: boolean;

  /**
   * Callback when wizard is completed
   */
  onComplete?: (data: ModelingWizardContext) => void;

  /**
   * Callback when submission fails
   */
  onError?: (error: Error) => void;
}

export interface UseModelingWizardReturn {
  // State
  state: any;
  context: ModelingWizardContext;
  currentStep: WizardStep;
  currentStepIndex: number;
  isSubmitting: boolean;
  isDirty: boolean;

  // Navigation
  canGoNext: boolean;
  canGoBack: boolean;
  goNext: () => void;
  goBack: () => void;
  goToStep: (step: WizardStep) => void;

  // Data management
  saveStep: (step: WizardStep, data: any) => void;
  getStepData: <T = any>(step: WizardStep) => T | undefined;

  // Validation
  isStepValid: (step: WizardStep) => boolean;
  getStepErrors: (step: WizardStep) => string[];

  // Submission
  submit: () => void;
  retrySubmit: () => void;
  cancelSubmission: () => void;

  // Progress
  completedSteps: Set<WizardStep>;
  visitedSteps: Set<WizardStep>;
  progressPercentage: number;

  // Configuration
  toggleSkipOptional: (skip: boolean) => void;

  // Reset
  reset: () => void;
}

// ============================================================================
// HOOK
// ============================================================================

export function useModelingWizard(options: UseModelingWizardOptions = {}): UseModelingWizardReturn {
  const {
    skipOptionalSteps = false,
    autoSaveInterval = 30000,
    loadSavedProgress = true,
    onComplete,
    onError
  } = options;

  // Initialize XState machine
  const [state, send] = useMachine(modelingWizardMachine, {
    input: {
      skipOptionalSteps,
      autoSaveInterval
    }
  });

  const context = state.context;

  // Load saved progress on mount
  useEffect(() => {
    if (loadSavedProgress) {
      send({ type: 'LOAD_FROM_STORAGE' });
    }
  }, [loadSavedProgress, send]);

  // Handle completion
  useEffect(() => {
    if (state.matches('completed')) {
      onComplete?.(context);
    }
  }, [state, context, onComplete]);

  // Handle errors
  useEffect(() => {
    if (context.submissionError && onError) {
      onError(new Error(context.submissionError));
    }
  }, [context.submissionError, onError]);

  // ============================================================================
  // NAVIGATION
  // ============================================================================

  const currentStep = context.currentStep;
  const currentStepIndex = context.currentStepIndex;

  const canGoNext = useMemo(() => {
    // Check if current step is valid
    const isValid = context.isStepValid[currentStep] ?? false;

    // Check if there is a next step
    const hasNext = getNextStep(currentStep, context.skipOptionalSteps) !== null;

    return isValid && hasNext;
  }, [currentStep, context.isStepValid, context.skipOptionalSteps]);

  const canGoBack = useMemo(() => {
    return getPreviousStep(currentStep, context.skipOptionalSteps) !== null;
  }, [currentStep, context.skipOptionalSteps]);

  const goNext = useCallback(() => {
    if (canGoNext) {
      send({ type: 'NEXT' });
    }
  }, [canGoNext, send]);

  const goBack = useCallback(() => {
    if (canGoBack) {
      send({ type: 'BACK' });
    }
  }, [canGoBack, send]);

  const goToStep = useCallback((step: WizardStep) => {
    send({ type: 'GOTO', step });
  }, [send]);

  // ============================================================================
  // DATA MANAGEMENT
  // ============================================================================

  const saveStep = useCallback((step: WizardStep, data: any) => {
    send({ type: 'SAVE_STEP', step, data });
  }, [send]);

  const getStepData = useCallback(<T = any>(step: WizardStep): T | undefined => {
    return context.steps[step] as T | undefined;
  }, [context.steps]);

  // ============================================================================
  // VALIDATION
  // ============================================================================

  const isStepValid = useCallback((step: WizardStep): boolean => {
    return context.isStepValid[step] ?? false;
  }, [context.isStepValid]);

  const getStepErrors = useCallback((step: WizardStep): string[] => {
    return context.validationErrors[step] || [];
  }, [context.validationErrors]);

  // ============================================================================
  // SUBMISSION
  // ============================================================================

  const submit = useCallback(() => {
    send({ type: 'SUBMIT' });
  }, [send]);

  const retrySubmit = useCallback(() => {
    send({ type: 'RETRY_SUBMIT' });
  }, [send]);

  const cancelSubmission = useCallback(() => {
    send({ type: 'CANCEL_SUBMISSION' });
  }, [send]);

  // ============================================================================
  // PROGRESS
  // ============================================================================

  const progressPercentage = useMemo(() => {
    return ((currentStepIndex + 1) / context.totalSteps) * 100;
  }, [currentStepIndex, context.totalSteps]);

  // ============================================================================
  // CONFIGURATION
  // ============================================================================

  const toggleSkipOptional = useCallback((skip: boolean) => {
    send({ type: 'TOGGLE_SKIP_OPTIONAL', skip });
  }, [send]);

  // ============================================================================
  // RESET
  // ============================================================================

  const reset = useCallback(() => {
    send({ type: 'RESET' });
  }, [send]);

  // ============================================================================
  // RETURN
  // ============================================================================

  return {
    // State
    state,
    context,
    currentStep,
    currentStepIndex,
    isSubmitting: state.matches({ active: 'submitting' }),
    isDirty: context.isDirty,

    // Navigation
    canGoNext,
    canGoBack,
    goNext,
    goBack,
    goToStep,

    // Data management
    saveStep,
    getStepData,

    // Validation
    isStepValid,
    getStepErrors,

    // Submission
    submit,
    retrySubmit,
    cancelSubmission,

    // Progress
    completedSteps: context.completedSteps,
    visitedSteps: context.visitedSteps,
    progressPercentage,

    // Configuration
    toggleSkipOptional,

    // Reset
    reset
  };
}

// ============================================================================
// EXAMPLE USAGE COMPONENT
// ============================================================================

/**
 * Example usage of the useModelingWizard hook
 *
 * @example
 * ```tsx
 * function ModelingWizardExample() {
 *   const wizard = useModelingWizard({
 *     skipOptionalSteps: false,
 *     autoSaveInterval: 30000,
 *     onComplete: (data) => {
 *       console.log('Wizard completed!', data);
 *     },
 *     onError: (error) => {
 *       console.error('Wizard error:', error);
 *     }
 *   });
 *
 *   return (
 *     <div>
 *       <h1>Modeling Wizard</h1>
 *       <p>Current Step: {wizard.currentStep}</p>
 *       <p>Progress: {wizard.progressPercentage.toFixed(0)}%</p>
 *       <p>Is Dirty: {wizard.isDirty ? 'Yes' : 'No'}</p>
 *
 *       <div>
 *         <button onClick={wizard.goBack} disabled={!wizard.canGoBack}>
 *           Back
 *         </button>
 *         <button onClick={wizard.goNext} disabled={!wizard.canGoNext}>
 *           Next
 *         </button>
 *       </div>
 *
 *       {wizard.isSubmitting && <p>Submitting...</p>}
 *
 *       {wizard.currentStep === 'generalInfo' && (
 *         <div>
 *           <h2>General Info Step</h2>
 *         </div>
 *       )}
 *     </div>
 *   );
 * }
 * ```
 */

// ============================================================================
// UTILITY HOOKS
// ============================================================================

/**
 * Hook to get the current step component based on wizard state
 */
export function useCurrentStepComponent(wizard: UseModelingWizardReturn) {
  return useMemo(() => {
    const stepComponents = {
      generalInfo: 'GeneralInfoStep',
      sectorProfiles: 'SectorProfilesStep',
      capitalAllocation: 'CapitalAllocationStep',
      feesExpenses: 'FeesExpensesStep',
      exitRecycling: 'ExitRecyclingStep',
      waterfall: 'WaterfallStep',
      scenarios: 'ScenariosStep'
    };

    return stepComponents[wizard.currentStep];
  }, [wizard.currentStep]);
}

/**
 * Hook to check if wizard is ready to submit
 */
export function useIsWizardComplete(wizard: UseModelingWizardReturn): boolean {
  return useMemo(() => {
    // Check if all required steps are completed
    const requiredSteps = STEP_ORDER.filter(
      step => !wizard.context.skipOptionalSteps || step !== 'exitRecycling'
    );

    return requiredSteps.every(step => wizard.isStepValid(step));
  }, [wizard]);
}

/**
 * Hook to format wizard data for API submission
 */
export function useFormattedWizardData(wizard: UseModelingWizardReturn) {
  return useMemo(() => {
    return {
      generalInfo: wizard.getStepData('generalInfo'),
      sectorProfiles: wizard.getStepData('sectorProfiles'),
      capitalAllocation: wizard.getStepData('capitalAllocation'),
      feesExpenses: wizard.getStepData('feesExpenses'),
      exitRecycling: wizard.getStepData('exitRecycling'),
      waterfall: wizard.getStepData('waterfall'),
      scenarios: wizard.getStepData('scenarios')
    };
  }, [wizard]);
}

/**
 * usePerformanceDashboard Hook
 *
 * Data fetching hook for the Portfolio Performance Dashboard.
 * Provides access to timeseries, breakdown, and comparison data.
 *
 * @module client/hooks/usePerformanceDashboard
 */

import { useQuery, useQueryClient } from '@tanstack/react-query';
import { useFundContext } from '@/contexts/FundContext';
import type {
  TimeseriesResponse,
  BreakdownResponse,
  ComparisonResponse,
  Granularity,
  GroupByDimension,
} from '@shared/types/performance-api';

// ============================================================================
// TIMESERIES HOOK
// ============================================================================

interface UsePerformanceTimeseriesOptions {
  startDate: string;
  endDate: string;
  granularity: Granularity;
  metrics?: string[];
  enabled?: boolean;
}

/**
 * Hook for fetching performance timeseries data
 *
 * @example
 * ```tsx
 * const { data, isLoading } = usePerformanceTimeseries({
 *   startDate: '2024-01-01',
 *   endDate: '2024-12-31',
 *   granularity: 'monthly',
 * });
 * ```
 */
export function usePerformanceTimeseries(options: UsePerformanceTimeseriesOptions) {
  const { fundId } = useFundContext();
  const { startDate, endDate, granularity, metrics, enabled = true } = options;

  return useQuery<TimeseriesResponse, Error>({
    queryKey: ['performance-timeseries', fundId, startDate, endDate, granularity, metrics],
    queryFn: async () => {
      if (!fundId) {
        throw new Error('No fund ID available');
      }

      const params = new URLSearchParams({
        startDate,
        endDate,
        granularity,
      });

      if (metrics && metrics.length > 0) {
        params.append('metrics', metrics.join(','));
      }

      const response = await fetch(
        `/api/funds/${fundId}/performance/timeseries?${params.toString()}`
      );

      if (!response.ok) {
        const errorData = await response.json().catch(() => ({}));
        throw new Error(errorData.message || `HTTP ${response.status}: Failed to fetch timeseries`);
      }

      return response.json();
    },
    enabled: enabled && !!fundId && !!startDate && !!endDate,
    staleTime: 60_000, // 1 minute
    gcTime: 300_000, // 5 minutes
    refetchOnWindowFocus: false,
    retry: 2,
  });
}

// ============================================================================
// BREAKDOWN HOOK
// ============================================================================

interface UsePerformanceBreakdownOptions {
  groupBy: GroupByDimension;
  asOfDate?: string;
  includeExited?: boolean;
  enabled?: boolean;
}

/**
 * Hook for fetching performance breakdown by sector/stage/company
 *
 * @example
 * ```tsx
 * const { data, isLoading } = usePerformanceBreakdown({
 *   groupBy: 'sector',
 *   includeExited: false,
 * });
 * ```
 */
export function usePerformanceBreakdown(options: UsePerformanceBreakdownOptions) {
  const { fundId } = useFundContext();
  const { groupBy, asOfDate, includeExited = false, enabled = true } = options;

  return useQuery<BreakdownResponse, Error>({
    queryKey: ['performance-breakdown', fundId, groupBy, asOfDate, includeExited],
    queryFn: async () => {
      if (!fundId) {
        throw new Error('No fund ID available');
      }

      const params = new URLSearchParams({ groupBy });

      if (asOfDate) {
        params.append('asOfDate', asOfDate);
      }

      if (includeExited) {
        params.append('includeExited', 'true');
      }

      const response = await fetch(
        `/api/funds/${fundId}/performance/breakdown?${params.toString()}`
      );

      if (!response.ok) {
        const errorData = await response.json().catch(() => ({}));
        throw new Error(errorData.message || `HTTP ${response.status}: Failed to fetch breakdown`);
      }

      return response.json();
    },
    enabled: enabled && !!fundId,
    staleTime: 60_000,
    gcTime: 300_000,
    refetchOnWindowFocus: false,
    retry: 2,
  });
}

// ============================================================================
// COMPARISON HOOK
// ============================================================================

interface UsePerformanceComparisonOptions {
  dates: string[];
  metrics?: string[];
  enabled?: boolean;
}

/**
 * Hook for comparing fund metrics across multiple dates
 *
 * @example
 * ```tsx
 * const { data, isLoading } = usePerformanceComparison({
 *   dates: ['2024-03-31', '2024-06-30', '2024-09-30', '2024-12-31'],
 * });
 * ```
 */
export function usePerformanceComparison(options: UsePerformanceComparisonOptions) {
  const { fundId } = useFundContext();
  const { dates, metrics, enabled = true } = options;

  return useQuery<ComparisonResponse, Error>({
    queryKey: ['performance-comparison', fundId, dates, metrics],
    queryFn: async () => {
      if (!fundId) {
        throw new Error('No fund ID available');
      }

      if (!dates || dates.length === 0) {
        throw new Error('At least one date is required for comparison');
      }

      const params = new URLSearchParams({
        dates: dates.join(','),
      });

      if (metrics && metrics.length > 0) {
        params.append('metrics', metrics.join(','));
      }

      const response = await fetch(
        `/api/funds/${fundId}/performance/comparison?${params.toString()}`
      );

      if (!response.ok) {
        const errorData = await response.json().catch(() => ({}));
        throw new Error(errorData.message || `HTTP ${response.status}: Failed to fetch comparison`);
      }

      return response.json();
    },
    enabled: enabled && !!fundId && dates.length > 0,
    staleTime: 60_000,
    gcTime: 300_000,
    refetchOnWindowFocus: false,
    retry: 2,
  });
}

// ============================================================================
// COMBINED DASHBOARD HOOK
// ============================================================================

interface UsePerformanceDashboardOptions {
  dateRange: {
    startDate: string;
    endDate: string;
  };
  granularity?: Granularity;
  groupBy?: GroupByDimension;
  enabled?: boolean;
}

/**
 * Combined hook for fetching all performance dashboard data
 *
 * Fetches timeseries and breakdown data in parallel.
 *
 * @example
 * ```tsx
 * const { timeseries, breakdown, isLoading } = usePerformanceDashboard({
 *   dateRange: { startDate: '2024-01-01', endDate: '2024-12-31' },
 *   granularity: 'monthly',
 *   groupBy: 'sector',
 * });
 * ```
 */
export function usePerformanceDashboard(options: UsePerformanceDashboardOptions) {
  const {
    dateRange,
    granularity = 'monthly',
    groupBy = 'sector',
    enabled = true,
  } = options;

  const timeseriesQuery = usePerformanceTimeseries({
    startDate: dateRange.startDate,
    endDate: dateRange.endDate,
    granularity,
    enabled,
  });

  const breakdownQuery = usePerformanceBreakdown({
    groupBy,
    enabled,
  });

  return {
    timeseries: timeseriesQuery.data,
    breakdown: breakdownQuery.data,
    isLoading: timeseriesQuery.isLoading || breakdownQuery.isLoading,
    isError: timeseriesQuery.isError || breakdownQuery.isError,
    error: timeseriesQuery.error || breakdownQuery.error,
    refetch: async () => {
      await Promise.all([timeseriesQuery.refetch(), breakdownQuery.refetch()]);
    },
  };
}

// ============================================================================
// CACHE INVALIDATION
// ============================================================================

/**
 * Hook for invalidating performance dashboard cache
 */
export function useInvalidatePerformanceCache() {
  const { fundId } = useFundContext();
  const queryClient = useQueryClient();

  const invalidate = async () => {
    if (!fundId) return;

    await queryClient.invalidateQueries({
      predicate: (query) => {
        const key = query.queryKey[0] as string;
        return (
          key.startsWith('performance-') &&
          query.queryKey[1] === fundId
        );
      },
    });
  };

  return { invalidate };
}

