                    onChange={(e) => setCashflowConfig(prev => ({ ...prev, forecastHorizonMonths: parseInt(e.target.value) || 12 }))}
                    className="border-[#E0D8D1] focus:border-[#292929] focus:ring-[#292929] font-poppins"
                  />
