            <div className="text-2xl font-bold">{forecastingData.monthlyInvestmentRate}</div>
            <p className="text-xs text-muted-foreground">
              Deals per month
            </p>
          </CardContent>
        </Card>
      </div>

      {/* Main Forecasting Interface */}
      <Tabs defaultValue="capital" className="space-y-6">
