// client/src/services/funds.ts
// Idempotent + cancellable fund creation with timeout and telemetry
// Single source of truth lives in the store; this is a belt-and-suspenders final check.

import { clampPct, clampInt } from '../lib/coerce';
import * as Telemetry from '../lib/telemetry';
import { startInFlight, isInFlight, cancelInFlight } from '../lib/inflight';

type Json = Record<string, unknown> | unknown[] | string | number | boolean | null | undefined;

interface StageData {
  name?: string;
  graduate?: number;
  exit?: number;
  months?: number;
}

interface FundPayload {
  stages?: StageData[];
  modelVersion?: string;
  basics?: {
    modelVersion?: string;
  };
}

export interface CreateFundOptions {
  endpoint?: string;            // default: '/api/funds'
  method?: 'POST' | 'PUT';      // default: 'POST'
  timeoutMs?: number;           // default: 10_000
  signal?: AbortSignal;         // optional external signal
  dedupe?: boolean;             // default: true
  telemetry?: boolean;          // default: true
  reuseExisting?: boolean;      // default: false - reuse existing fund if found
}

export interface CreateFundResult {
  res: Response;
  hash: string;
  aborted: boolean;
  durationMs: number;
}

const DEFAULT_ENDPOINT = '/api/funds';
const DEFAULT_TIMEOUT = 10_000;

// ---------- Stable stringify + FNV-1a hash (deterministic) ----------
function stableStringify(value: unknown): string {
  const seen = new WeakSet();
  const walk = (v: unknown): unknown => {
    if (v === null || typeof v !== 'object') return v;
    if (seen.has(v as object)) return '[Circular]';
    seen.add(v as object);

    if (Array.isArray(v)) return v.map(walk);

    const obj = v as Record<string, unknown>;
    const out: Record<string, unknown> = {};
    for (const k of Object.keys(obj).sort()) out[k] = walk(obj[k]);
    return out;
  };
  return JSON.stringify(walk(value));
}

function fnv1a(input: string): string {
  let hash = 0x811c9dc5;
  for (let i = 0; i < input.length; i++) {
    hash ^= input.charCodeAt(i);
    hash += (hash << 1) + (hash << 4) + (hash << 7) + (hash << 8) + (hash << 24);
  }
  // unsigned >>> 0, represent as hex
  return (hash >>> 0).toString(16);
}

export function computeCreateFundHash(payload: Json): string {
  // Add environment namespace to avoid cross-env collisions
  const namespace = `${import.meta.env.MODE || 'unknown-env'  }|fund-create|`;
  return fnv1a(namespace + stableStringify(payload));
}

// ---------- Compose timeout + external AbortSignal ----------
function _composeSignal(timeoutMs: number, external?: AbortSignal) {
  const ctrl = new AbortController();
  const timer = setTimeout(() => ctrl.abort(new DOMException('Timeout', 'AbortError')), timeoutMs);

  const onAbort = () => ctrl.abort(external?.reason ?? new DOMException('Aborted', 'AbortError'));
  if (external) {
    if (external.aborted) onAbort();
    else external.addEventListener('abort', onAbort, { once: true });
  }

  const cleanup = () => {
    clearTimeout(timer);
    if (external) external.removeEventListener('abort', onAbort);
  };

  return { signal: ctrl.signal, controller: ctrl, cleanup };
}

// ---------- In-flight de-duplication registry (in-flight only, no cache) ----------
// Purpose: Prevent duplicate requests while in-flight. Server handles post-completion idempotency.
const IDEMPOTENCY_MAX = Number(import.meta.env.VITE_IDEMPOTENCY_MAX || 200);

type InflightEntry = {
  promise: Promise<CreateFundResult>;
  controllers: AbortController[];
  startedAt: number;
};

const inflight = new Map<string, InflightEntry>();

// Ensure we don't exceed capacity (throw if at limit)
function _assertInflightCapacity() {
  if (inflight.size >= IDEMPOTENCY_MAX) {
    const err = new Error('Too many concurrent requests; please retry shortly.') as Error & { code?: string };
    err.code = 'CAPACITY_EXCEEDED';
    throw err;
  }
}

export function isCreateFundInFlight(hash: string) {
  return isInFlight(hash);
}

export function cancelCreateFund(hash: string) {
  return cancelInFlight(hash);
}

// ---------- Final clamp before wire (defense-in-depth) ----------
function finalizePayload(payload: Json): FundPayload {
  try {
    const p = { ...(payload as FundPayload) };

    // If stages exist, ensure values are sane
    if (Array.isArray(p.stages)) {
      p.stages = p.stages.map(s => ({
        ...s,
        name: typeof s.name === 'string' ? s.name.trim() : s.name,
        graduate: clampPct(Number(s.graduate)),
        exit: clampPct(Number(s.exit)),
        months: clampInt(Number(s.months) || 12, 1, 120),
      }));
    }

    // Version tag enables non-breaking evolution
    if (!p.modelVersion) p.modelVersion = 'reserves-ev1';

    return p;
  } catch {
    return payload; // never block on "safety"; better to ship the payload than throw here
  }
}

// ---------- Main entry ----------
export async function startCreateFund(
  payload: Json,
  opts: CreateFundOptions = {}
): Promise<CreateFundResult> {
  const endpoint = opts.endpoint ?? DEFAULT_ENDPOINT;
  const method = opts.method ?? 'POST';
  const timeoutMs = opts.timeoutMs ?? DEFAULT_TIMEOUT;
  const dedupe = opts.dedupe ?? true;
  const useTelemetry = opts.telemetry ?? true;

  const finalized = finalizePayload(payload);
  const hash = computeCreateFundHash(finalized);

  // Optional: 1 ms hold only in test to avoid flicker; keep 0 in prod if you prefer.
  const holdForMs = import.meta.env?.MODE === 'test' ? 1 : 0;

  if (!dedupe) {
    // Skip deduplication - create unique key with timestamp
    const uniqueHash = `${hash}-${Date.now()}-${Math.random()}`;
    return startInFlight(uniqueHash, async ({ signal }) => {
      return await executeCreateFund(finalized, endpoint, method, timeoutMs, signal, useTelemetry, hash);
    }, { holdForMs });
  }

  return startInFlight(hash, async ({ signal }) => {
    return await executeCreateFund(finalized, endpoint, method, timeoutMs, signal, useTelemetry, hash);
  }, { holdForMs });
}

// Helper function to execute the actual fund creation
async function executeCreateFund(
  finalized: FundPayload,
  endpoint: string,
  method: string,
  timeoutMs: number,
  signal: AbortSignal,
  useTelemetry: boolean,
  hash: string
): Promise<CreateFundResult> {
  const startedAt = performance.now();

  // Track attempt
  if (useTelemetry) {
    try {
      const track = (Telemetry as { track?: (event: string, data: Record<string, unknown>) => void }).track;
      track?.('fund_create_attempt', {
        hash,
        model_version: finalized.basics?.modelVersion,
        env: import.meta.env.MODE,
      });
    } catch {
      // Ignore telemetry errors
    }
  }

  try {
    const res = await fetch(endpoint, {
      method,
      signal,
      headers: { 
        'Content-Type': 'application/json',
        'Idempotency-Key': hash  // Server-side deduplication
      },
      body: JSON.stringify(finalized),
    });

    const durationMs = Math.round(performance.now() - startedAt);
    if (useTelemetry) {
      try {
        const eventName = res.ok ? 'fund_create_success' : 'fund_create_failure';
        const idempotencyStatus = res.headers.get('Idempotency-Status') || 'created';
        const track = (Telemetry as { track?: (event: string, data: Record<string, unknown>) => void }).track;
        track?.(eventName, {
          status: res.status,
          durationMs,
          hash,
          idempotency_status: idempotencyStatus,
          model_version: finalized.basics?.modelVersion,
          env: import.meta.env.MODE,
        });
      } catch {
        // Ignore telemetry errors
      }
    }
    return { res, hash, aborted: false, durationMs };
  } catch (err) {
    const error = err as Error & { name?: string; message?: string };
    const aborted = error?.name === 'AbortError';
    const durationMs = Math.round(performance.now() - startedAt);
    if (useTelemetry) {
      try {
        const track = (Telemetry as { track?: (event: string, data: Record<string, unknown>) => void }).track;
        track?.('fund_create_failure', {
          aborted,
          message: String(error?.message ?? err),
          durationMs,
          hash,
          idempotency_status: 'error',
          model_version: finalized.basics?.modelVersion,
          env: import.meta.env.MODE,
        });
      } catch {
        // Ignore telemetry errors
      }
    }
    // surface same shape; callers can inspect aborted if needed
    const fundError = err instanceof Error ? err : new Error('Create fund failed');
    throw Object.assign(fundError, { aborted, hash, durationMs });
  }
}

// ---------- Toast throttling for capacity hits ----------
let lastCapacityToast = 0;
const TOAST_THROTTLE_MS = 10_000; // One toast every 10 seconds max

function maybeToastCapacity() {
  const now = Date.now();
  if (now - lastCapacityToast > TOAST_THROTTLE_MS) {
    lastCapacityToast = now;
    return true;
  }
  return false;
}

// ---------- Convenience wrappers for backward compatibility ----------
export async function createFund(payload: Json, options?: CreateFundOptions): Promise<unknown> {
  const result = await startCreateFund(payload, options);
  if (!result.res.ok) {
    throw new Error(`Fund creation failed: ${result.res.status}`);
  }
  return result.res.json();
}

export async function createFundWithToast(payload: Json, options?: CreateFundOptions) {
  const { toast } = await import('../lib/toast');

  try {
    const result = await startCreateFund(payload, options);
    if (!result.res.ok) {
      const text = await result.res.text().catch(() => '');
      toast(`❌ Failed to save fund: ${text || result.res.statusText}`, 'error');
      return null;
    }
    const data = await result.res.json();
    toast('✅ Fund saved successfully!', 'success');
    return data;
  } catch (err) {
    const error = err as { aborted?: boolean; code?: string };
    if (error?.aborted) {
      toast('⚠️ Save cancelled', 'info');
    } else if (error?.code === 'CAPACITY_EXCEEDED') {
      // Throttled user-friendly capacity hit message
      const showToast = maybeToastCapacity();
      if (showToast) {
        toast('⚠️ You have too many concurrent operations. Please wait a moment and try again.', 'info');
      }
      // Always track capacity hit for observability
      try {
        const { inFlightSize } = await import('../lib/inflight');
        const track = (Telemetry as { track?: (event: string, data: Record<string, unknown>) => void }).track;
        track?.('client_capacity_hit', {
          route: '/api/funds',
          concurrent: inFlightSize(),
          env: import.meta.env.MODE,
          throttled: !showToast
        });
      } catch {
        // Ignore telemetry errors
      }
    } else {
      toast('❌ Network error saving fund', 'error');
    }
    throw err;
  }
}

/**
 * Client-side feature flag accessor with runtime overrides
 *
 * Extends the central flag system from shared/feature-flags/flag-definitions.ts
 * with client-specific runtime controls.
 *
 * Priority (highest to lowest):
 * 1. Query params: ?ff_enable_new_ia=1
 * 2. LocalStorage: localStorage.setItem('ff_enable_new_ia', '1')
 * 3. Environment: VITE_ENABLE_NEW_IA=true
 * 4. Definition default: ALL_FLAGS[key].enabled
 *
 * Usage:
 *   const flags = useFlags();
 *   if (flags.enable_new_ia) { ... }
 *
 *   // Or single flag:
 *   const isNewIA = useFlag('enable_new_ia');
 */

import { useMemo, useSyncExternalStore } from 'react';
import { ALL_FLAGS, type FlagKey } from '@shared/feature-flags/flag-definitions';

/**
 * Get runtime override from query params or localStorage
 * Matches pattern from client/src/config/features.ts
 */
const getRuntimeFlag = (flagKey: string): boolean | undefined => {
  try {
    // Check query params first: ?ff_enable_new_ia=1
    const qp = new URLSearchParams(window.location.search).get(`ff_${flagKey}`);
    if (qp === '0' || qp === '1') return qp === '1';

    // Check localStorage fallback: localStorage.setItem('ff_enable_new_ia', '1')
    const ls = localStorage.getItem(`ff_${flagKey}`);
    if (ls === '0' || ls === '1') return ls === '1';
  } catch (e) {
    console.warn(`[useFlags] Runtime check failed for ${flagKey}:`, e);
  }
  return undefined;
};

/**
 * Get environment variable flag value
 */
const getEnvFlag = (flagKey: string): boolean | undefined => {
  try {
    const meta = import.meta as ImportMeta & { env?: Record<string, string> };
    const envVal = meta.env?.[`VITE_${flagKey.toUpperCase()}`];
    if (envVal === 'true' || envVal === '1') return true;
    if (envVal === 'false' || envVal === '0') return false;
  } catch (_e) {
    // Ignore - might be SSR or no import.meta
  }
  return undefined;
};

/**
 * Subscribe to localStorage changes for live flag updates
 */
const subscribe = (callback: () => void) => {
  window.addEventListener('storage', callback);
  // Also listen to popstate for query param changes
  window.addEventListener('popstate', callback);
  return () => {
    window.removeEventListener('storage', callback);
    window.removeEventListener('popstate', callback);
  };
};

/**
 * Hook to access all feature flags with runtime overrides
 * Re-renders when flags change via localStorage or query params
 */
export function useFlags(): Record<FlagKey, boolean> {
  // Re-render on storage/navigation changes
  useSyncExternalStore(
    subscribe,
    () => window.location.search + Date.now() // Snapshot includes query params
  );

  return useMemo(() => {
    const flags: Record<string, boolean> = {};

    Object.keys(ALL_FLAGS).forEach((key) => {
      const flagKey = key as FlagKey;
      // Priority: runtime > env > definition default
      flags[key] =
        getRuntimeFlag(key) ??
        getEnvFlag(key) ??
        ALL_FLAGS[flagKey]?.enabled ?? false;
    });

    return flags as Record<FlagKey, boolean>;
  }, []); // Dependencies handled by useSyncExternalStore
}

/**
 * Hook to access a single feature flag
 * Convenience wrapper with TypeScript autocomplete
 */
export function useFlag(key: FlagKey): boolean {
  const flags = useFlags();
  return flags[key] ?? false;
}

/**
 * Development helper - log current flag states
 */
export function debugFlags(): void {
  const flags = {} as Record<FlagKey, boolean>;
  Object.keys(ALL_FLAGS).forEach((key) => {
    const flagKey = key as FlagKey;
    flags[flagKey] =
      getRuntimeFlag(key) ??
      getEnvFlag(key) ??
      ALL_FLAGS[flagKey]?.enabled ?? false;
  });

  console.group('🚩 Feature Flags');
  console.table(
    Object.entries(flags).map(([key, value]) => ({
      flag: key,
      enabled: value,
      runtime: getRuntimeFlag(key) ?? 'not set',
      env: getEnvFlag(key) ?? 'not set',
      default: ALL_FLAGS[key as FlagKey]?.enabled ?? false,
    }))
  );
  console.groupEnd();
}

// Expose to window in development
if (import.meta.env?.DEV) {
  (window as unknown as { __debugFlags?: typeof debugFlags }).__debugFlags = debugFlags;
}

import { shallow } from 'zustand/shallow';
import type { StoreApi, UseBoundStore } from 'zustand';
import { useFundStore } from './useFundStore';

// Infer the store state and re-cast the bound store so TS knows
// it accepts a selector + optional equality function.
type FundState = ReturnType<typeof useFundStore.getState>;
const bound = useFundStore as unknown as UseBoundStore<StoreApi<FundState>>;

/**
 * Safe wrapper over useFundStore that defaults to shallow equality for
 * object/array selectors to prevent getSnapshot churn.
 *
 * Prefer tuple/object selectors here:
 * const [hydrated, stages] = useFundSelector(s => [s.hydrated, s.stages]);
 */
export function useFundSelector<T>(
  selector: (s: FundState) => T,
  equality?: (a: T, b: T) => boolean
): T {
  // Use type assertion to bypass TS argument checking
  return (bound as any)(selector, equality ?? shallow);
}

import { useStoreWithEqualityFn } from 'zustand/traditional';
import { shallow } from 'zustand/shallow';
import { fundStore } from './fundStore';
import type { FundState } from './fundStore';

/**
 * Core implementation of the fund selector.
 * Internal function - use `useFundSelector` export instead.
 */
function useFundSelectorImpl<T>(
  selector: (s: FundState) => T,
  equality?: (a: T, b: T) => boolean
): T {
  return useStoreWithEqualityFn(fundStore, selector, equality);
}

/**
 * Safe selector hook using Zustand's built-in primitives.
 * Prevents the "getSnapshot must be cached" warning and infinite re-renders.
 *
 * In development mode, wraps selectors with performance monitoring to detect
 * slow selectors (>4ms execution time).
 *
 * @param selector - Function to select a slice of state
 * @param equality - Optional equality function (defaults to Object.is)
 * @returns The selected state slice
 *
 * @example
 * // Single value
 * const hydrated = useFundSelector(s => s.hydrated);
 *
 * // Multiple values with tuple (preferred)
 * const [stages, allocations] = useFundTuple(s => [s.stages, s.allocations]);
 *
 * // Actions (usually stable by reference)
 * const addStage = useFundSelector(s => s.addStage);
 */
export function useFundSelector<T>(
  selector: (s: FundState) => T,
  equality?: (a: T, b: T) => boolean
): T {
  // Wrap selector with performance monitoring in dev mode
  const wrappedSelector = import.meta.env.DEV
    ? (state: FundState): T => {
        const start = performance.now();
        const result = selector(state);
        const duration = performance.now() - start;

        // Only warn for selectors taking more than 4ms
        if (duration > 4) {
          console.warn(`[Slow selector] ${duration.toFixed(2)}ms`, {
            selector: selector.toString().slice(0, 100)
          });
        }

        return result;
      }
    : selector;

  // Call the hook unconditionally (same call path every render)
  return useFundSelectorImpl(wrappedSelector, equality);
}

/**
 * Tuple selector with shallow equality check.
 * Use this when selecting multiple values to prevent unnecessary re-renders.
 * 
 * @example
 * const [hydrated, stages, sectorProfiles] = useFundTuple(s => [
 *   s.hydrated,
 *   s.stages,
 *   s.sectorProfiles
 * ]);
 */
export const useFundTuple = <T extends any[]>(
  selector: (s: FundState) => T
) => useFundSelector(selector, shallow);

/**
 * Action selector helper.
 * Actions are typically stable by reference, so no equality check needed.
 * 
 * @example
 * const fromInvestmentStrategy = useFundAction(s => s.fromInvestmentStrategy);
 */
export const useFundAction = <T>(
  selector: (s: FundState) => T
) => useFundSelector(selector);

/**
 * Batch action selector with shallow equality.
 * Use when you need multiple actions at once.
 * 
 * @example
 * const actions = useFundActions(s => ({
 *   addStage: s.addStage,
 *   removeStage: s.removeStage,
 *   updateStageName: s.updateStageName
 * }));
 */
export const useFundActions = <T extends Record<string, any>>(
  selector: (s: FundState) => T
) => useFundSelector(selector, shallow);

import { create } from 'zustand';
import { persist } from 'zustand/middleware';
import { allocate100 } from '../core/utils/allocate100';
import { clampPct, clampInt } from '../lib/coerce';
import { sortById, normalizeNumber, eq } from '../utils/state-utils';
import type { SectorProfile, Allocation, InvestmentStrategy } from '@shared/types';

export type StrategyStage = {
  id: string;
  name: string;
  graduate: number; // %
  exit: number;     // %
  months: number;   // int >= 1
};

type StrategySlice = {
  // Hydration flag
  hydrated: boolean;
  setHydrated: (_v: boolean) => void;

  stages: StrategyStage[];
  sectorProfiles: SectorProfile[];
  allocations: Allocation[];
  followOnChecks: { A: number; B: number; C: number };

  // Stage management
  addStage: () => void;
  removeStage: (_idx: number) => void;
  updateStageName: (_idx: number, _name: string) => void;
  updateStageRate: (_idx: number, _patch: Partial<Pick<StrategyStage, 'graduate'|'exit'|'months'>>) => void;

  // Selector-like helper
  stageValidation: () => { allValid: boolean; errorsByRow: (string | null)[] };

  // Conversion utilities
  toInvestmentStrategy: () => InvestmentStrategy;
  fromInvestmentStrategy: (_strategy: InvestmentStrategy) => void;
};

// helper functions
const enforceLast = (rows: StrategyStage[]) =>
  rows.map((r, i) => (i === rows.length - 1 ? { ...r, graduate: 0 } : r));

const generateStableId = (): string => {
  if (typeof crypto !== 'undefined' && 'randomUUID' in crypto) {
    return crypto.randomUUID();
  }
  return `stage-${Date.now()}-${Math.random().toString(36).substr(2, 9)}`;
};

/**
 * Business rules (canonical):
 * - Percentages are clamped to [0, 100].
 * - Last stage `graduate` is always 0.
 * - Remain is derived: remain = 100 - (graduate + exit). Never persisted.
 * - Months are integers ≥ 1.
 * - graduate + exit must be ≤ 100 for each stage.
 * 
 * Any consumer should rely on these invariants.
 */
export const useFundStore = create<StrategySlice>()(
  persist(
    (set, get): StrategySlice => {
      // Cache for stageValidation to prevent object recreation
      let cachedStagesState: StrategyStage[] | null = null;
      let cachedValidationResult: { allValid: boolean; errorsByRow: (string | null)[] } | null = null;

      return {
        hydrated: false,
        setHydrated: (v: boolean) => set({ hydrated: v }),

        stages: [
        { id: generateStableId(), name: 'Seed', graduate: 30, exit: 20, months: 18 },
        { id: generateStableId(), name: 'Series A', graduate: 40, exit: 25, months: 24 },
        { id: generateStableId(), name: 'Series B+', graduate: 0, exit: 35, months: 30 }
        ],
        sectorProfiles: [
        { id: 'sector-1', name: 'FinTech', targetPercentage: 40, description: 'Financial technology companies' },
        { id: 'sector-2', name: 'HealthTech', targetPercentage: 30, description: 'Healthcare technology companies' },
        { id: 'sector-3', name: 'Enterprise SaaS', targetPercentage: 30, description: 'B2B software solutions' }
        ],
        allocations: [
        { id: 'alloc-1', category: 'New Investments', percentage: 75, description: 'Fresh capital for new portfolio companies' },
        { id: 'alloc-2', category: 'Reserves', percentage: 20, description: 'Follow-on investments for existing portfolio' },
        { id: 'alloc-3', category: 'Operating Expenses', percentage: 5, description: 'Fund management and operations' }
        ],
        followOnChecks: { A: 800_000, B: 1_500_000, C: 2_500_000 },

        addStage: () => set((s) => {
        // Invalidate cache when stages change
        cachedStagesState = null;
        cachedValidationResult = null;

        const id = generateStableId();
        const next = [...s.stages, { id, name: '', graduate: 0, exit: 0, months: 12 }];
        return { stages: enforceLast(next) };
        }),

        removeStage: (idx: number) => set((s) => {
        // Invalidate cache when stages change
        cachedStagesState = null;
        cachedValidationResult = null;

        const next = s.stages.filter((_, i) => i !== idx);
        return { stages: enforceLast(next) };
        }),

        updateStageName: (idx: number, name: string) => set((s) => {
        // Invalidate cache when stages change
        cachedStagesState = null;
        cachedValidationResult = null;

        const stages = [...s.stages];
        if (stages[idx]) {
          stages[idx] = { ...stages[idx], name };
        }
        return { stages };
        }),

        updateStageRate: (idx: number, patch: Partial<Pick<StrategyStage, 'graduate'|'exit'|'months'>>) => set((s) => {
        // Invalidate cache when stages change
        cachedStagesState = null;
        cachedValidationResult = null;

        const stages: StrategyStage[] = [...s.stages];
        const r = stages[idx];
        if (!r) return s;

        const isLast = idx === stages.length - 1;
        const gradRaw = isLast ? 0 : clampPct(patch.graduate ?? r.graduate);
        const exitRaw = clampPct(patch.exit ?? r.exit);
        const months = clampInt(patch.months ?? r.months, 1, 120);

        const [graduate, exit] = allocate100(gradRaw, exitRaw);
        stages[idx] = { ...r, graduate, exit, months };

        // Re-enforce last rule in case stages changed earlier
        const lastIdx = stages.length - 1;
        if (lastIdx >= 0 && stages[lastIdx]?.graduate !== 0) {
          stages[lastIdx] = { ...stages[lastIdx]!, graduate: 0 };
        }

          return { stages };
        }),

        stageValidation: (): { allValid: boolean; errorsByRow: (string | null)[] } => {
          const { stages } = get();

          // Return cached result if stages haven't changed
          if (cachedStagesState === stages && cachedValidationResult) {
            return cachedValidationResult;
          }

          // Compute new validation result
          const errors = stages.map((r, i) => {
            if (!r.name?.trim()) return 'Stage name required';
            if (r.graduate + r.exit > 100) return 'Graduate + Exit must be ≤ 100%';
            if (i === stages.length - 1 && r.graduate !== 0) return 'Last stage must have 0% graduation';
            return null;
          });

          const result = { allValid: errors.every((e) => !e), errorsByRow: errors };

          // Cache the result
          cachedStagesState = stages;
          cachedValidationResult = result;

          return result;
        },

        // Conversion utilities to work with existing InvestmentStrategy type
        toInvestmentStrategy: (): InvestmentStrategy => {
        const { stages, sectorProfiles, allocations } = get();
        return {
          stages: stages.map((s: StrategyStage) => ({
            id: s.id,
            name: s.name,
            graduationRate: s.graduate,
            exitRate: s.exit
          })),
          sectorProfiles,
          allocations
        };
      },

        fromInvestmentStrategy: (strategy: InvestmentStrategy) => {
        const current = get();

        // 1) Normalize & default only when absent (use ?? not ||)
        const mappedStages = strategy.stages.map(s => ({
          id: s.id,
          name: s.name,
          graduate: normalizeNumber(s.graduationRate),
          exit: normalizeNumber(s.exitRate),
          months: (s as {months?: number}).months ?? 12 // Only default when undefined/null (months not in base type)
        }));

        // 2) Sort before compare & write (order-agnostic)
        const newStages = enforceLast(mappedStages).sort(sortById);
        const prevStages = current.stages.slice().sort(sortById);

        // 3) Deep equality check for stages (using NaN-safe equality)
        const stagesEqual =
          prevStages.length === newStages.length &&
          prevStages.every((a, i) =>
            a.id === newStages[i].id &&
            a.name === newStages[i].name &&
            eq(a.graduate, newStages[i].graduate) &&
            eq(a.exit, newStages[i].exit) &&
            eq(a.months, newStages[i].months)
          );

        // Sort and compare profiles (with normalized percentages)
        const nextProfiles = strategy.sectorProfiles.slice().sort(sortById);
        const prevProfiles = current.sectorProfiles.slice().sort(sortById);
        const profilesEqual =
          prevProfiles.length === nextProfiles.length &&
          prevProfiles.every((a, i) =>
            a.id === nextProfiles[i]?.id &&
            a.name === nextProfiles[i]?.name &&
            eq(a.targetPercentage, normalizeNumber(nextProfiles[i]?.targetPercentage)) &&
            a.description === nextProfiles[i]?.description
          );

        // Sort and compare allocations (with normalized percentages)
        const nextAllocs = strategy.allocations.slice().sort(sortById);
        const prevAllocs = current.allocations.slice().sort(sortById);
        const allocsEqual =
          prevAllocs.length === nextAllocs.length &&
          prevAllocs.every((a, i) =>
            a.id === nextAllocs[i]?.id &&
            a.category === nextAllocs[i]?.category &&
            eq(a.percentage, normalizeNumber(nextAllocs[i]?.percentage)) &&
            a.description === nextAllocs[i]?.description
          );

        // 4) True no-op: don't call set() if nothing changed
        if (stagesEqual && profilesEqual && allocsEqual) {
          return; // Early return - no state update
        }

        // 5) Invalidate cache and publish update
        cachedStagesState = null;
        cachedValidationResult = null;

        set({
          stages: newStages,
          sectorProfiles: nextProfiles,
          allocations: nextAllocs
        });
        }
      };
  },
  {
      name: 'investment-strategy',
      version: 2, // Bump version for new structure
      partialize: (s) => ({
        // Only persist primitive inputs (no derived remain)
        stages: s.stages.map((r: StrategyStage) => ({
          id: r.id, name: r.name, graduate: r.graduate, exit: r.exit, months: r.months
        })),
        sectorProfiles: s.sectorProfiles,
        allocations: s.allocations,
        followOnChecks: s.followOnChecks,
        modelVersion: 'reserves-ev1',
      }),
      migrate: (state, from: number) => {
        if (from < 2) {
          state.stages = (state.stages ?? []).map((r: {months?: number}) => ({ months: 12, ...r }));
        }
        return state;
      },
      onRehydrateStorage: () => (_state, err) => {
        if (err) console.error('[fund-store] rehydrate error', err);
        // Flip on next microtask so subscribers see the final rehydrated values
        Promise.resolve().then(() => useFundStore.getState().setHydrated(true));
      }
    }
  )
);

// Dev-only store tracer for debugging state updates
if (import.meta.env.DEV && import.meta.env['VITE_WIZARD_DEBUG'] === '1' && typeof window !== 'undefined' && !(window as Window & {__fundStoreTracer?: boolean}).__fundStoreTracer) {
  (window as Window & {__fundStoreTracer?: boolean; __unsubFundStoreTracer?: () => void}).__fundStoreTracer = true;
  const unsub = useFundStore.subscribe((state, prev) => {
    const changed: string[] = [];
    if (state.hydrated !== prev.hydrated) changed.push('hydrated');
    if (state.stages !== prev.stages) changed.push('stages');
    if (state.sectorProfiles !== prev.sectorProfiles) changed.push('sectorProfiles');
    if (state.allocations !== prev.allocations) changed.push('allocations');
    if (state.followOnChecks !== prev.followOnChecks) changed.push('followOnChecks');
    if (changed.length) {
      console.debug('[fund-store publish]', changed.join(','), { 
        changed,
        timestamp: new Date().toISOString(),
        perf: Math.round(performance.now())
      });
    }
  });
  // Store unsubscribe function for cleanup if needed
  (window as Window & {__unsubFundStoreTracer?: () => void}).__unsubFundStoreTracer = unsub;
}

