// client/src/utils/array-safety-enhanced.ts
// --------------------------------------------------
// Comprehensive array safety utilities for null/undefined handling
// Enhanced version with additional features for server-side use

/**
 * Type guards for array validation
 */
export function isArray<T>(value: unknown): value is T[] {
  return Array.isArray(value);
}

export function isSafeArray<T>(value: T[] | null | undefined): value is T[] {
  return Array.isArray(value) && value !== null;
}

/**
 * Safe forEach implementation with comprehensive null/undefined handling
 */
export function forEach<T>(
  array: T[] | null | undefined,
  callback: (_item: T, _index: number, _array: T[]) => void,
  thisArg?: any
): void {
  if (!isSafeArray(array)) {
    if (process.env['NODE_ENV'] === 'development') {
      console.debug('forEach called on null/undefined array');
    }
    return;
  }

  array.forEach(callback, thisArg);
}

/**
 * Safe map implementation
 */
export function map<T, R>(
  array: T[] | null | undefined,
  callback: (_item: T, _index: number, _array: T[]) => R,
  thisArg?: any
): R[] {
  if (!isSafeArray(array)) return [];
  return array.map(callback, thisArg);
}

/**
 * Safe filter implementation
 */
export function filter<T>(
  array: T[] | null | undefined,
  predicate: (_item: T, _index: number, _array: T[]) => boolean,
  thisArg?: any
): T[] {
  if (!isSafeArray(array)) return [];
  return array.filter(predicate, thisArg);
}

/**
 * Safe reduce implementation
 */
export function reduce<T, R>(
  array: T[] | null | undefined,
  callback: (_acc: R, _item: T, _index: number, _array: T[]) => R,
  initialValue: R
): R {
  if (!isSafeArray(array)) return initialValue;
  return array.reduce(callback, initialValue);
}

/**
 * Safe find implementation
 */
export function find<T>(
  array: T[] | null | undefined,
  predicate: (_item: T, _index: number, _array: T[]) => boolean,
  thisArg?: any
): T | undefined {
  if (!isSafeArray(array)) return undefined;
  return array.find(predicate, thisArg);
}

/**
 * Safe some implementation
 */
export function some<T>(
  array: T[] | null | undefined,
  predicate: (_item: T, _index: number, _array: T[]) => boolean,
  thisArg?: any
): boolean {
  if (!isSafeArray(array)) return false;
  return array.some(predicate, thisArg);
}

/**
 * Safe every implementation
 */
export function every<T>(
  array: T[] | null | undefined,
  predicate: (_item: T, _index: number, _array: T[]) => boolean,
  thisArg?: any
): boolean {
  if (!isSafeArray(array)) return true; // Empty array behavior
  return array.every(predicate, thisArg);
}

/**
 * Safe array access with default fallback
 */
export function safeArray<T>(
  array: T[] | null | undefined,
  defaultValue: T[] = []
): T[] {
  return isSafeArray(array) ? array : defaultValue;
}

/**
 * Get array length safely
 */
export function length(array: any[] | null | undefined): number {
  return isSafeArray(array) ? array.length : 0;
}

/**
 * Get item at index safely
 */
export function at<T>(
  array: T[] | null | undefined,
  index: number
): T | undefined {
  if (!isSafeArray(array)) return undefined;
  return array.at(index);
}

/**
 * Chainable SafeArray class for fluent operations
 */
export class SafeArray<T> {
  constructor(private array: T[] | null | undefined) {}

  forEach(callback: (_item: T, _index: number) => void): SafeArray<T> {
    forEach(this.array, callback);
    return this;
  }

  map<R>(callback: (_item: T, _index: number) => R): SafeArray<R> {
    return new SafeArray(map(this.array, callback));
  }

  filter(predicate: (_item: T, _index: number) => boolean): SafeArray<T> {
    return new SafeArray(filter(this.array, predicate));
  }

  reduce<R>(callback: (_acc: R, _item: T) => R, initial: R): R {
    return reduce(this.array, callback, initial);
  }

  find(predicate: (_item: T, _index: number) => boolean): T | undefined {
    return find(this.array, predicate);
  }

  some(predicate: (_item: T, _index: number) => boolean): boolean {
    return some(this.array, predicate);
  }

  every(predicate: (_item: T, _index: number) => boolean): boolean {
    return every(this.array, predicate);
  }

  toArray(): T[] {
    return safeArray(this.array);
  }

  get length(): number {
    return length(this.array);
  }

  isEmpty(): boolean {
    return this.length === 0;
  }

  isNotEmpty(): boolean {
    return this.length > 0;
  }
}

/**
 * Factory function for chainable operations
 */
export function safe<T>(array: T[] | null | undefined): SafeArray<T> {
  return new SafeArray(array);
}

/**
 * Helper for nested array operations
 */
export function forEachNested<T, U>(
  array: T[] | null | undefined,
  nestedGetter: (_item: T) => U[] | null | undefined,
  callback: (_parent: T, _child: U, _parentIndex: number, _childIndex: number) => void
): void {
  forEach(array, (parent: any, parentIndex: any) => {
    forEach(nestedGetter(parent), (child: any, childIndex: any) => {
      callback(parent, child, parentIndex, childIndex);
    });
  });
}

/**
 * Performance monitoring wrapper for debugging
 */
export function forEachWithMetrics<T>(
  array: T[] | null | undefined,
  callback: (_item: T, _index: number) => void,
  metricName?: string
): void {
  const start = performance.now();
  forEach(array, callback);

  if (metricName && process.env['NODE_ENV'] === 'development') {
    const duration = performance.now() - start;
    console.debug(`forEach[${metricName}]: ${duration.toFixed(2)}ms for ${length(array)} items`);
  }
}

/**
 * Async-safe forEach for promise-based operations
 */
export async function forEachAsync<T>(
  array: T[] | null | undefined,
  callback: (_item: T, _index: number) => Promise<void>
): Promise<void> {
  if (!isSafeArray(array)) return;

  for (let i = 0; i < array.length; i++) {
    const item = array[i];
    if (item !== undefined) {
      await callback(item, i);
    }
  }
}

/**
 * Parallel processing for async operations
 */
export async function forEachParallel<T>(
  array: T[] | null | undefined,
  callback: (_item: T, _index: number) => Promise<void>,
  concurrency: number = 10
): Promise<void> {
  if (!isSafeArray(array)) return;

  const chunks: T[][] = [];
  for (let i = 0; i < array.length; i += concurrency) {
    chunks.push(array.slice(i, i + concurrency));
  }

  for (const chunk of chunks) {
    await Promise.all(
      chunk.map((item: any, localIndex: any) => {
        const globalIndex = chunks.indexOf(chunk) * concurrency + localIndex;
        return callback(item, globalIndex);
      })
    );
  }
}

/**
 * Legacy compatibility - matches the existing utility pattern
 */
export const safeForEach = forEach;
export const safeMap = map;
export const safeFilter = filter;
export const safeReduce = reduce;

/* eslint-disable @typescript-eslint/no-explicit-any */




/**
 * Async iteration utilities to replace problematic forEach patterns
 */

import { logger } from '../lib/logger';

// Compile-time flag for metrics collection - dead-stripped in production builds
const withMetrics: boolean = import.meta.env?.['MODE'] !== 'production';

export interface ProcessingOptions {
  parallel?: boolean;
  batchSize?: number;
  continueOnError?: boolean;
  delayBetweenBatches?: number;
}

/**
 * Process an array of items with proper async handling
 * @param items Array of items to process
 * @param processor Function to process each item
 * @param options Processing options
 */
export async function processAsync<T>(
  items: T[],
  processor: (_item: T, _index: number) => Promise<void>,
  options: ProcessingOptions = {}
): Promise<void> {
  const { 
    parallel = false, 
    batchSize = 10, 
    continueOnError = false,
    delayBetweenBatches = 0
  } = options;

  if (!Array.isArray(items) || items.length === 0) {
    return;
  }

  if (parallel) {
    if (batchSize >= items.length) {
      // Process all items in parallel
      if (continueOnError) {
        const results = await Promise.allSettled(items.map((item: any, index: any) => processor(item, index)));
        // Handle errors from Promise.allSettled
        for (let i = 0; i < results.length; i++) {
          const result = results[i];
          if (result && result['status'] === 'rejected') {
            logger.error(`Failed to process item ${i}:`, result['reason']);
          }
        }
      } else {
        await Promise.all(items.map((item: any, index: any) => processor(item, index)));
      }
    } else {
      // Process in batches
      await processBatches(items, processor, batchSize, delayBetweenBatches, continueOnError);
    }
  } else {
    // Sequential processing
    for (let i = 0; i < items.length; i++) {
      try {
        const item = items[i];
        if (item !== undefined) {
          await processor(item, i);
        }
      } catch (error) {
        if (!continueOnError) throw error;
        logger.error(`Processing error at index ${i}:`, error as Error);
      }
    }
  }
}

/**
 * Process items in batches with optional delays
 */
async function processBatches<T>(
  items: T[],
  processor: (_item: T, _index: number) => Promise<void>,
  batchSize: number,
  delay: number,
  continueOnError: boolean
): Promise<void> {
  for (let i = 0; i < items.length; i += batchSize) {
    const batch = items.slice(i, i + batchSize);
    const batchStart = i;

    try {
      if (continueOnError) {
        const results = await Promise.allSettled(
          batch.map((item: any, batchIndex: any) => processor(item, batchStart + batchIndex))
        );

        for (let i = 0; i < results.length; i++) {
          const result = results[i];
          if (result && result['status'] === 'rejected') {
            logger.error(`Failed to process item ${batchStart + i}:`, result['reason']);
          }
        }
      } else {
        await Promise.all(
          batch.map((item: any, batchIndex: any) => processor(item, batchStart + batchIndex))
        );
      }
    } catch (error) {
      if (!continueOnError) throw error;
      logger.error(`Batch processing error starting at index ${batchStart}:`, error as Error);
    }

    // Add delay between batches if specified
    if (delay > 0 && i + batchSize < items.length) {
      await new Promise(resolve => setTimeout(resolve, delay));
    }
  }
}

/**
 * Sequential async forEach replacement
 * @param items Array to iterate over
 * @param callback Async callback function
 */
export async function forEachAsync<T>(
  items: T[],
  callback: (_item: T, _index: number, _array: T[]) => Promise<void>
): Promise<void> {
  if (!Array.isArray(items)) return;

  const start = withMetrics ? performance.now() : 0;

  for (let i = 0; i < items.length; i++) {
    const item = items[i];
    if (item !== undefined) {
      await callback(item, i, items);
    }
  }

  if (withMetrics && items.length > 100) {
    console.info(`[async-metrics] forEachAsync: ${items.length} items in ${(performance.now() - start).toFixed(1)}ms`);
  }
}

/**
 * Parallel async map with proper error handling
 * @param items Array to map over
 * @param callback Async mapping function
 * @param options Processing options
 */
export async function mapAsync<T, R>(
  items: T[],
  callback: (_item: T, _index: number, _array: T[]) => Promise<R>,
  options: Omit<ProcessingOptions, 'continueOnError'> = {}
): Promise<R[]> {
  const { parallel = true, batchSize = 10, delayBetweenBatches = 0 } = options;

  if (!Array.isArray(items)) return [];

  const start = withMetrics ? performance.now() : 0;
  let results: R[];

  if (parallel && batchSize >= items.length) {
    // Process all items in parallel
    results = await Promise.all(items.map(callback));
  } else if (parallel) {
    // Process in batches
    results = [];

    for (let i = 0; i < items.length; i += batchSize) {
      const batch = items.slice(i, i + batchSize);
      const batchResults = await Promise.all(
        batch.map((item: any, batchIndex: any) => callback(item, i + batchIndex, items))
      );
      results.push(...batchResults);

      // Add delay between batches if specified
      if (delayBetweenBatches > 0 && i + batchSize < items.length) {
        await new Promise(resolve => setTimeout(resolve, delayBetweenBatches));
      }
    }
  } else {
    // Sequential processing
    results = [];
    for (let i = 0; i < items.length; i++) {
      const item = items[i];
      if (item !== undefined) {
        const result = await callback(item, i, items);
        results.push(result);
      }
    }
  }

  if (withMetrics && items.length > 100) {
    const mode = parallel ? 'parallel' : 'sequential';
    console.info(`[async-metrics] mapAsync (${mode}): ${items.length} items in ${(performance.now() - start).toFixed(1)}ms`);
  }

  return results;
}


/**
 * Filter with async predicate
 */
export async function filterAsync<T>(
  items: T[],
  predicate: (_item: T, _index: number, _array: T[]) => Promise<boolean>
): Promise<T[]> {
  if (!Array.isArray(items)) return [];

  const results = await mapAsync(items, predicate);
  return items.filter((_: any, index: any) => results[index] === true);
}

/**
 * Find with async predicate
 */
export async function findAsync<T>(
  items: T[],
  predicate: (_item: T, _index: number, _array: T[]) => Promise<boolean>
): Promise<T | undefined> {
  if (!Array.isArray(items)) return undefined;

  for (let i = 0; i < items.length; i++) {
    const item = items[i];
    if (item !== undefined && await predicate(item, i, items)) {
      return item;
    }
  }
  return undefined;
}

/**
 * Reduce with async reducer
 */
export async function reduceAsync<T, R>(
  items: T[],
  reducer: (_accumulator: R, _currentValue: T, _currentIndex: number, _array: T[]) => Promise<R>,
  initialValue: R
): Promise<R> {
  if (!Array.isArray(items)) return initialValue;

  let accumulator = initialValue;
  for (let i = 0; i < items.length; i++) {
    const item = items[i];
    if (item !== undefined) {
      accumulator = await reducer(accumulator, item, i, items);
    }
  }
  return accumulator;
}

/**
 * Some with async predicate
 */
export async function someAsync<T>(
  items: T[],
  predicate: (_item: T, _index: number, _array: T[]) => Promise<boolean>
): Promise<boolean> {
  if (!Array.isArray(items)) return false;

  for (let i = 0; i < items.length; i++) {
    const item = items[i];
    if (item !== undefined && await predicate(item, i, items)) {
      return true;
    }
  }
  return false;
}

/**
 * Every with async predicate
 */
export async function everyAsync<T>(
  items: T[],
  predicate: (_item: T, _index: number, _array: T[]) => Promise<boolean>
): Promise<boolean> {
  if (!Array.isArray(items)) return true;

  for (let i = 0; i < items.length; i++) {
    const item = items[i];
    if (item === undefined || !(await predicate(item, i, items))) {
      return false;
    }
  }
  return true;
}

// Example usage patterns
export const examples = {
  // Sequential processing (safest)
  sequential: async <T>(items: T[], processor: (_item: T) => Promise<void>) => {
    await forEachAsync(items, processor);
  },

  // Parallel processing (fastest)
  parallel: async <T>(items: T[], processor: (_item: T) => Promise<void>) => {
    await processAsync(items, processor, { parallel: true });
  },

  // Batched processing (balanced)
  batched: async <T>(items: T[], processor: (_item: T) => Promise<void>) => {
    await processAsync(items, processor, { 
      parallel: true, 
      batchSize: 5, 
      delayBetweenBatches: 100 
    });
  },

  // Error-resilient processing
  resilient: async <T>(items: T[], processor: (_item: T) => Promise<void>) => {
    await processAsync(items, processor, { 
      parallel: true, 
      continueOnError: true 
    });
  }
};

