/**
 * pLimit – minimal concurrency limiter
 * ------------------------------------
 * Usage:
 *   const limit = pLimit(4);                          // max 4 in flight
 *   await Promise.all(items.map(item => limit(() => doAsync(item))));
 */
export type AsyncTask<T> = () => Promise<T>;

export default function pLimit(concurrency: number) {
  if (concurrency < 1) throw new Error('Concurrency must be ≥ 1');
  let active = 0;
  const queue: (() => void)[] = [];

  const next = () => {
    active--;
    if (queue.length) queue.shift()!();    // run next task
  };

  const run = <T>(task: AsyncTask<T>): Promise<T> =>
    new Promise((res: any, rej: any) => {
      const execute = () => {
        active++;
        task().then(res, rej).finally(next);
      };
      if (active < concurrency) {
        execute();
      } else {
        queue.push(execute);
      }
    });

  return run;
}

/**
 * Performance baseline collection utilities for tracking render counts
 * and detecting performance regressions during the state management migration.
 */

import React from 'react';

interface RenderMetrics {
  componentName: string;
  renderCount: number;
  averageRenderTime: number;
  maxRenderTime: number;
  minRenderTime: number;
  timestamp: string;
}

class PerformanceBaseline {
  private metrics: Map<string, RenderMetrics> = new Map();
  private renderTimes: Map<string, number[]> = new Map();

  /**
   * Track a component render
   */
  trackRender(componentName: string, renderTime: number) {
    // Get or initialize render times array
    const times = this.renderTimes['get'](componentName) || [];
    times.push(renderTime);
    this.renderTimes['set'](componentName, times);

    // Update metrics
    const existing = this.metrics['get'](componentName);
    const renderCount = (existing?.renderCount || 0) + 1;

    this.metrics['set'](componentName, {
      componentName,
      renderCount,
      averageRenderTime: times.reduce((a: any, b: any) => a + b, 0) / times.length,
      maxRenderTime: Math.max(...times),
      minRenderTime: Math.min(...times),
      timestamp: new Date().toISOString()
    });
  }

  /**
   * Get metrics for a specific component
   */
  getMetrics(componentName: string): RenderMetrics | undefined {
    return this.metrics['get'](componentName);
  }

  /**
   * Get all collected metrics
   */
  getAllMetrics(): RenderMetrics[] {
    return Array.from(this.metrics.values());
  }

  /**
   * Export metrics as JSON
   */
  exportMetrics(): string {
    return JSON.stringify(this.getAllMetrics(), null, 2);
  }

  /**
   * Reset all metrics
   */
  reset() {
    this.metrics.clear();
    this.renderTimes.clear();
  }

  /**
   * Compare current metrics with a baseline
   */
  compareWithBaseline(baseline: RenderMetrics[]): {
    regressions: string[];
    improvements: string[];
  } {
    const regressions: string[] = [];
    const improvements: string[] = [];

    for (const baselineMetric of baseline) {
      const current = this.metrics['get'](baselineMetric.componentName);
      if (!current) continue;

      // Check for render count regression (>10% increase)
      if (current.renderCount > baselineMetric.renderCount * 1.1) {
        regressions.push(
          `${baselineMetric.componentName}: render count increased from ${baselineMetric.renderCount} to ${current.renderCount}`
        );
      } else if (current.renderCount < baselineMetric.renderCount * 0.9) {
        improvements.push(
          `${baselineMetric.componentName}: render count decreased from ${baselineMetric.renderCount} to ${current.renderCount}`
        );
      }

      // Check for render time regression (>20% increase)
      if (current.averageRenderTime > baselineMetric.averageRenderTime * 1.2) {
        regressions.push(
          `${baselineMetric.componentName}: average render time increased from ${baselineMetric.averageRenderTime.toFixed(2)}ms to ${current.averageRenderTime.toFixed(2)}ms`
        );
      } else if (current.averageRenderTime < baselineMetric.averageRenderTime * 0.8) {
        improvements.push(
          `${baselineMetric.componentName}: average render time decreased from ${baselineMetric.averageRenderTime.toFixed(2)}ms to ${current.averageRenderTime.toFixed(2)}ms`
        );
      }
    }

    return { regressions, improvements };
  }
}

// Global singleton instance
export const performanceBaseline = new PerformanceBaseline();

/**
 * React hook to track component render performance
 */
export function useRenderTracking(componentName: string) {
  const startTime = performance.now();

  // Track after render completes
  React.useEffect(() => {
    // Only track in development environment
    if (!import.meta.env.DEV) return;

    const renderTime = performance.now() - startTime;
    performanceBaseline.trackRender(componentName, renderTime);
  });
}

/**
 * Development-only render counter hook
 */
export function useRenderCounter(componentName: string) {
  const renderCount = React.useRef(0);

  React.useEffect(() => {
    if (!import.meta.env.DEV) return;

    renderCount.current += 1;

    // Log every 10 renders to avoid spam
    if (renderCount.current % 10 === 0) {
      console.debug(`[Render Count] ${componentName}: ${renderCount.current} renders`);
    }
  });

  return renderCount.current;
}

// Export for use in tests
export type { RenderMetrics };

// Helper for running baseline collection
if (import.meta.env.DEV && typeof window !== 'undefined') {
  (window as any).__performanceBaseline = performanceBaseline;

  // Log metrics on page unload
  window.addEventListener('beforeunload', () => {
    const metrics = performanceBaseline.getAllMetrics();
    if (metrics.length > 0) {
      console.log('[Performance Baseline]', metrics);
    }
  });
}

// State utility functions for consistent normalization and comparison

// Sort comparator for id-bearing records
export const sortById = <T extends { id?: string | number }>(a: T, b: T) => {
  const aId = a.id ?? '';
  const bId = b.id ?? '';
  if (aId === bId) return 0;
  return aId > bId ? 1 : -1;
};

// Normalize to number; return NaN for non-finite
export function normalizeNumber(v: unknown): number {
  if (v === '' || v === null || v === undefined) return NaN;
  const n = typeof v === 'number' ? v : Number(v);
  return Number.isFinite(n) ? n : NaN;
}

// Circular-safe, stable key order serialization
export function stableSerialize(value: unknown): string {
  const seen = new WeakSet<object>();
  return JSON.stringify(value, function (_k, v) {
    if (v && typeof v === 'object') {
      if (seen.has(v as object)) return '[Circular]';
      seen.add(v as object);
      if (!Array.isArray(v)) {
        const o: Record<string, unknown> = {};
        for (const k of Object.keys(v as any).sort()) o[k] = (v as any)[k];
        return o;
      }
    }
    return v;
  });
}

// Fast FNV-1a 32-bit hash for small/medium strings
export function fnv1a32(str: string): string {
  let h = 0x811c9dc5;
  for (let i = 0; i < str.length; i++) {
    h ^= str.charCodeAt(i);
    h += (h << 1) + (h << 4) + (h << 7) + (h << 8) + (h << 24);
  }
  return (h >>> 0).toString(16).padStart(8, '0');
}

// Robust stable hash with circular reference handling
export function stableHash(value: unknown): string {
  try {
    return fnv1a32(stableSerialize(value));
  } catch {
    return fnv1a32(String(value));
  }
}

// NaN-safe equality using Object.is
// Object.is(NaN, NaN) === true, while NaN === NaN === false
export const eq = Object.is;

import type { Metric } from 'web-vitals';
import { onLCP, onINP, onCLS, onFCP, onTTFB } from 'web-vitals';
import { Sentry } from '@/monitoring';

interface VitalMetric extends Omit<Metric, 'navigationType'> {
  navigationType?: string;
  delta: number;
}

/**
 * Check if telemetry is allowed based on privacy settings
 */
function isTelemetryAllowed(): boolean {
  // Check DNT header respect
  if (navigator.doNotTrack === '1') {
    return false;
  }

  // Check user opt-out preference
  const privacySettings = localStorage.getItem('privacy-settings');
  if (privacySettings) {
    try {
      const settings = JSON.parse(privacySettings) as Record<string, unknown>;
      if (settings.telemetryOptOut === true) {
        return false;
      }
    } catch (e: unknown) {
      // Invalid settings, allow by default
    }
  }

  // Check if RUM v2 is enabled and should validate
  if (import.meta.env.VITE_ENABLE_RUM_V2 === '1') {
    // Additional v2 checks can go here
    return true;
  }

  return true;
}

/**
 * Send Core Web Vitals to monitoring backends
 */
function sendToAnalytics(metric: VitalMetric) {
  // Privacy check - short circuit if telemetry disabled
  if (!isTelemetryAllowed()) {
    if (import.meta.env.DEV) {
      console.log('[Web Vital] Telemetry disabled by privacy settings');
    }
    return;
  }

  // Get or create correlation ID
  const cid = sessionStorage.getItem('cid') || crypto.randomUUID();
  if (!sessionStorage.getItem('cid')) {
    sessionStorage.setItem('cid', cid);
  }

  const body = {
    name: metric.name,
    value: metric.value,
    rating: metric.rating,
    delta: metric.delta,
    id: metric.id,
    navigationType: metric.navigationType,
    pathname: window.location.pathname,
    timestamp: Date.now(), // Use numeric timestamp for v2 validation
    release: import.meta.env.VITE_GIT_SHA || 'unknown',
    env: import.meta.env.MODE,
    cid,
  };

  // Send to Sentry as custom measurement (if privacy allows)
  if ((window as Record<string, unknown>).Sentry && isTelemetryAllowed()) {
    // Use span API for measurements in v10+
    Sentry.withScope((scope) => {
      scope.setMeasurement(`webvital.${metric.name.toLowerCase()}`, metric.value);

      // Also send as breadcrumb for observability
      Sentry.addBreadcrumb({
        message: `Web Vital: ${metric.name.toLowerCase()}`,
        level: 'info',
        data: {
          value: metric.value,
          rating: metric.rating
        }
      });
    });
  }

  // Send to backend RUM endpoint
  if (navigator.sendBeacon) {
    const url = '/metrics/rum';
    const blob = new Blob([JSON.stringify(body)], { type: 'application/json' });
    navigator.sendBeacon(url, blob);
  } else {
    // Fallback for older browsers
    fetch('/metrics/rum', {
      method: 'POST',
      headers: { 'Content-Type': 'application/json' },
      body: JSON.stringify(body),
      keepalive: true,
    }).catch(console.error);
  }

  // Log to console in development
  if (import.meta.env.DEV) {
    console.log(`[Web Vital] ${metric.name}:`, metric.value, metric.rating);
  }
}

/**
 * Initialize Web Vitals collection
 */
export function startVitals() {
  // Core Web Vitals
  onLCP(sendToAnalytics);  // Largest Contentful Paint
  onINP(sendToAnalytics);  // Interaction to Next Paint (replaces FID)
  onCLS(sendToAnalytics);  // Cumulative Layout Shift

  // Additional metrics
  onFCP(sendToAnalytics);  // First Contentful Paint
  onTTFB(sendToAnalytics); // Time to First Byte

  // Custom performance marks
  if (window.performance && window.performance.mark) {
    // Mark when React app is interactive
    window.addEventListener('load', () => {
      window.performance.mark('app-interactive');

      // Measure time to interactive
      window.performance.measure('time-to-interactive', 'navigationStart', 'app-interactive');
      const measure = window.performance.getEntriesByName('time-to-interactive')[0];

      if (measure) {
        sendToAnalytics({
          name: 'TTI',
          value: measure.duration,
          rating: measure.duration < 3800 ? 'good' : measure.duration < 7300 ? 'needs-improvement' : 'poor',
          id: `tti-${Date.now()}`,
          entries: [],
          navigationType: 'navigate',
        } as unknown as VitalMetric);
      }
    });
  }

  // Monitor long tasks
  if ('PerformanceObserver' in window) {
    try {
      const observer = new PerformanceObserver((list) => {
        for (const entry of list.getEntries()) {
          // Report tasks longer than 50ms as potential issues
          if (entry.duration > 50) {
            Sentry.addBreadcrumb({
              category: 'performance',
              message: `Long task detected: ${entry.duration}ms`,
              level: entry.duration > 100 ? 'warning' : 'info',
              data: {
                duration: entry.duration,
                startTime: entry.startTime,
                name: entry.name,
              },
            });
          }
        }
      });

      observer.observe({ entryTypes: ['longtask'] });
    } catch (e: unknown) {
      console.warn('Long task observer not supported:', e);
    }
  }

  console.log('Web Vitals monitoring initialized');
}

/**
 * Get current Web Vitals snapshot (for debugging)
 */
export function getVitalsSnapshot() {
  const vitals: Record<string, number | null> = {
    lcp: null,
    inp: null,
    cls: null,
    fcp: null,
    ttfb: null,
  };

  // Collect current values (note: these are cumulative)
  onLCP((metric) => { vitals['lcp'] = metric.value; }, { reportAllChanges: false });
  onINP((metric) => { vitals['inp'] = metric.value; }, { reportAllChanges: false });
  onCLS((metric) => { vitals['cls'] = metric.value; }, { reportAllChanges: false });
  onFCP((metric) => { vitals['fcp'] = metric.value; }, { reportAllChanges: false });
  onTTFB((metric) => { vitals['ttfb'] = metric.value; }, { reportAllChanges: false });

  return vitals;
}

// Expose for debugging in console
if (import.meta.env.DEV) {
  (window as Record<string, unknown>).getVitalsSnapshot = getVitalsSnapshot;
}

