/**
 * ESLint rule: no-async-array-methods
 * 
 * Prevents usage of native array methods like forEach, map, filter with async callbacks
 * and suggests using the async-safe utilities instead.
 * 
 * This rule provides autofix capabilities to replace problematic patterns with
 * safe async alternatives.
 */

const asyncArrayMethods = [
  'forEach',
  'map',
  'filter',
  'reduce',
  'find',
  'some',
  'every'
];

const asyncUtilityMap = {
  'forEach': 'forEachAsync',
  'map': 'mapAsync', 
  'filter': 'filterAsync',
  'reduce': 'reduceAsync',
  'find': 'findAsync',
  'some': 'someAsync',
  'every': 'everyAsync'
};

function isAsyncFunction(node) {
  // Check if the function is async
  if (node.async) return true;

  // Check if it's an arrow function with async
  if (node.type === 'ArrowFunctionExpression' && node.async) return true;

  // Check if the function body contains await
  if (hasAwait(node)) return true;

  return false;
}

function hasAwait(node) {
  if (!node) return false;

  if (node.type === 'AwaitExpression') return true;

  // Recursively check child nodes
  for (const key in node) {
    if (key === 'parent') continue; // Avoid circular references

    const value = node[key];
    if (Array.isArray(value)) {
      for (const item of value) {
        if (item && typeof item === 'object' && hasAwait(item)) {
          return true;
        }
      }
    } else if (value && typeof value === 'object' && hasAwait(value)) {
      return true;
    }
  }

  return false;
}

function getAsyncIterationImport(context) {
  const program = context.getSourceCode().ast;

  for (const node of program.body) {
    if (node.type === 'ImportDeclaration' && 
        (node.source.value.includes('async-iteration') || 
         node.source.value.includes('utils/async-iteration'))) {
      return node;
    }
  }
  return null;
}

export default {
  meta: {
    type: 'problem',
    docs: {
      description: 'Prevent async array method usage and suggest async-safe alternatives',
      category: 'Possible Errors',
      recommended: true,
    },
    fixable: 'code',
    schema: [],
    messages: {
      asyncArrayMethod: 'Avoid using {{method}} with async callbacks. Use {{asyncMethod}} instead for proper async handling.',
      missingImport: 'Import async utilities to use {{asyncMethod}}. Add: import { {{asyncMethod}} } from "../../utils/async-iteration"',
    },
  },

  create(context) {
    return {
      CallExpression(node) {
        // Check if this is a call to an array method
        if (node.callee.type !== 'MemberExpression') return;

        const methodName = node.callee.property?.name;
        if (!asyncArrayMethods.includes(methodName)) return;

        // Check if the callback is async or contains await
        const callback = node.arguments[0];
        if (!callback || !isAsyncFunction(callback)) return;

        const asyncMethodName = asyncUtilityMap[methodName];
        const existingImport = getAsyncIterationImport(context);

        context.report({
          node,
          messageId: 'asyncArrayMethod',
          data: {
            method: methodName,
            asyncMethod: asyncMethodName,
          },
          fix(fixer) {
            const sourceCode = context.getSourceCode();
            const fixes = [];

            // Replace the method call
            const objectText = sourceCode.getText(node.callee.object);
            const argsText = node.arguments.map(arg => sourceCode.getText(arg)).join(', ');
            const replacement = `await ${asyncMethodName}(${objectText}, ${argsText})`;

            fixes.push(fixer.replaceText(node, replacement));

            // Add import if needed
            if (!existingImport) {
              const program = context.getSourceCode().ast;
              const firstImport = program.body.find(node => node.type === 'ImportDeclaration');

              let importPath = '../../utils/async-iteration';
              // Try to determine the correct relative path based on file location
              const filename = context.getFilename();
              if (filename.includes('client/src/pages/')) {
                importPath = '../../utils/async-iteration';
              } else if (filename.includes('client/src/components/')) {
                importPath = '../../utils/async-iteration';
              } else if (filename.includes('workers/')) {
                importPath = '../client/src/utils/async-iteration';
              }

              const importStatement = `import { ${asyncMethodName} } from "${importPath}";\n`;

              if (firstImport) {
                fixes.push(fixer.insertTextBefore(firstImport, importStatement));
              } else {
                fixes.push(fixer.insertTextBefore(program.body[0], importStatement));
              }
            } else {
              // Check if the specific method is already imported
              const importedMethods = existingImport.specifiers
                .filter(spec => spec.type === 'ImportSpecifier')
                .map(spec => spec.imported.name);

              if (!importedMethods.includes(asyncMethodName)) {
                // Add to existing import
                const lastSpecifier = existingImport.specifiers[existingImport.specifiers.length - 1];
                fixes.push(fixer.insertTextAfter(lastSpecifier, `, ${asyncMethodName}`));
              }
            }

            return fixes;
          },
        });
      },
    };
  },
};

import { Rule } from 'eslint';
import * as ESTree from 'estree';

const rule: Rule.RuleModule = {
  meta: {
    type: 'suggestion',
    docs: {
      description: 'Disallow async callbacks in array methods that don\'t handle promises',
      url: 'https://github.com/nikhillinit/Updog_restore/blob/main/docs/dev/async-iteration.md'
    },
    fixable: 'code',
    schema: [],
    messages: {
      useForEachAsync: 'Use forEachAsync for async callbacks instead of forEach',
      useAsyncUtility: 'Use async-safe array utility for {{method}} with async callbacks'
    }
  },

  create(context) {
    const sourceCode = context.getSourceCode();

    // Check if forEachAsync is already imported
    function hasForEachAsyncImport(): boolean {
      const program = sourceCode.ast;
      for (const node of program.body) {
        if (
          node.type === 'ImportDeclaration' &&
          node.source.value &&
          (node.source.value as string).includes('async-iteration')
        ) {
          for (const specifier of node.specifiers) {
            if (
              specifier.type === 'ImportSpecifier' &&
              specifier.imported.type === 'Identifier' &&
              specifier.imported.name === 'forEachAsync'
            ) {
              return true;
            }
          }
        }
      }
      return false;
    }

    // Find the best position to insert import
    function getImportInsertPosition(): number {
      const program = sourceCode.ast;
      let lastImportIndex = -1;
      
      for (let i = 0; i < program.body.length; i++) {
        if (program.body[i].type === 'ImportDeclaration') {
          lastImportIndex = i;
        }
      }

      if (lastImportIndex >= 0) {
        const lastImport = program.body[lastImportIndex];
        return lastImport.range![1];
      }

      // No imports found, insert at the beginning
      return 0;
    }

    // Add import for forEachAsync
    function* addForEachAsyncImport(fixer: Rule.RuleFixer): IterableIterator<Rule.Fix> {
      const program = sourceCode.ast;
      
      // Check if there's already an import from utils/async-iteration
      for (const node of program.body) {
        if (
          node.type === 'ImportDeclaration' &&
          node.source.value === 'utils/async-iteration'
        ) {
          // Add forEachAsync to existing import
          const lastSpecifier = node.specifiers[node.specifiers.length - 1];
          if (lastSpecifier) {
            yield fixer.insertTextAfter(lastSpecifier, ', forEachAsync');
            return;
          }
        }
      }

      // No existing import from utils/async-iteration, add new import
      const insertPosition = getImportInsertPosition();
      const importStatement = `import { forEachAsync } from 'utils/async-iteration';\n`;
      
      if (insertPosition === 0) {
        yield fixer.insertTextBeforeRange([0, 0], importStatement);
      } else {
        yield fixer.insertTextAfterRange([insertPosition, insertPosition], '\n' + importStatement);
      }
    }

    return {
      CallExpression(node: ESTree.CallExpression) {
        // Check if this is a method call on an array
        if (
          node.callee.type !== 'MemberExpression' ||
          node.callee.property.type !== 'Identifier'
        ) {
          return;
        }

        const methodName = node.callee.property.name;
        const arrayMethods = ['forEach', 'map', 'filter', 'reduce'];

        if (!arrayMethods.includes(methodName)) {
          return;
        }

        // Check if the first argument is an async function
        const firstArg = node.arguments[0];
        if (!firstArg) {
          return;
        }

        let isAsync = false;
        if (
          (firstArg.type === 'ArrowFunctionExpression' && firstArg.async) ||
          (firstArg.type === 'FunctionExpression' && firstArg.async)
        ) {
          isAsync = true;
        }

        if (!isAsync) {
          return;
        }

        // For now, only auto-fix forEach
        // TODO: Expand fixer to handle mapAsync, filterAsync, reduceAsync
        if (methodName === 'forEach') {
          context.report({
            node,
            messageId: 'useForEachAsync',
            *fix(fixer) {
              // Add import if needed
              if (!hasForEachAsyncImport()) {
                yield* addForEachAsyncImport(fixer);
              }

              // Replace forEach with forEachAsync
              const memberExpression = node.callee as ESTree.MemberExpression;
              const object = memberExpression.object;
              const callback = node.arguments[0];
              
              // Check if the parent is already an await expression
              const parent = sourceCode.getNodeByRangeIndex(node.range![0] - 1);
              const needsAwait = parent?.type !== 'AwaitExpression';

              const objectText = sourceCode.getText(object);
              const callbackText = sourceCode.getText(callback);
              const additionalArgs = node.arguments.slice(1).map(arg => sourceCode.getText(arg)).join(', ');
              
              let replacement = `forEachAsync(${objectText}, ${callbackText}`;
              if (additionalArgs) {
                replacement += `, ${additionalArgs}`;
              }
              replacement += ')';

              if (needsAwait) {
                replacement = `await ${replacement}`;
              }

              yield fixer.replaceText(node, replacement);
            }
          });
        } else {
          // For other methods, just report without fix
          context.report({
            node,
            messageId: 'useAsyncUtility',
            data: { method: methodName }
          });
        }
      }
    };
  }
};

export default rule;

/**
 * ESLint Rule: no-hardcoded-fund-metrics
 *
 * Prevents hardcoding of fund metrics in UI components.
 * This rule ensures all metrics are fetched from the Unified Metrics API
 * via the useFundMetrics() hook, maintaining a single source of truth.
 *
 * ❌ Bad:
 * ```js
 * const fundMetrics = { irr: 28.5, tvpi: 2.82, totalInvested: 85000000 };
 * ```
 *
 * ✅ Good:
 * ```js
 * const { data: metrics } = useFundMetrics();
 * const irr = metrics?.actual.irr;
 * ```
 *
 * @module eslint-rules/no-hardcoded-fund-metrics
 */

// Metric-related property names to detect
const METRIC_PROPERTIES = [
  'irr',
  'tvpi',
  'dpi',
  'rvpi',
  'moic',
  'totalInvested',
  'totalDeployed',
  'totalValue',
  'totalCommitted',
  'totalCalled',
  'currentNAV',
  'totalDistributions',
  'deploymentRate',
  'activeCompanies',
  'exitedCompanies',
  'fundMetrics',
  'portfolioMetrics',
  'actualMetrics',
  'projectedMetrics',
];

// Allowlisted file patterns (tests, mocks, types)
const ALLOWLIST_PATTERNS = [
  /__tests__\//,
  /\.test\./,
  /\.spec\./,
  /\.mock\./,
  /\.stories\./,
  /\/test\//,
  /\/tests\//,
  /\/mocks\//,
  /\/fixtures\//,
  /types\.ts$/,
  /\.d\.ts$/,
  /shared\/types\/metrics\.ts$/, // The type definitions themselves
];

/**
 * Check if a file is allowlisted
 */
function isAllowlistedFile(filename) {
  return ALLOWLIST_PATTERNS.some((pattern) => pattern.test(filename));
}

/**
 * Check if an object has suspicious metric properties
 */
function hasSuspiciousProperties(properties) {
  return properties.some((prop) => {
    if (prop.type !== 'Property') return false;
    if (prop.key.type === 'Identifier') {
      return METRIC_PROPERTIES.includes(prop.key.name);
    }
    if (prop.key.type === 'Literal') {
      return METRIC_PROPERTIES.includes(prop.key.value);
    }
    return false;
  });
}

/**
 * Check if a value looks like a financial metric (large number or percentage)
 */
function looksLikeFinancialValue(value) {
  if (value.type === 'Literal' && typeof value.value === 'number') {
    // Large numbers (> 1M) likely represent dollar amounts
    // Small decimals (0.0 - 10.0) likely represent multiples or rates
    const num = value.value;
    return (
      Math.abs(num) > 1_000_000 ||
      (num >= 0 && num <= 10 && num % 1 !== 0)
    );
  }
  return false;
}

/**
 * ESLint rule definition
 */
module.exports = {
  meta: {
    type: 'problem',
    docs: {
      description: 'Disallow hardcoded fund metrics in UI components',
      category: 'Best Practices',
      recommended: true,
    },
    messages: {
      hardcodedMetrics:
        'Do not hardcode fund metrics. Use the useFundMetrics() hook to fetch metrics from the Unified Metrics API. See client/src/hooks/useFundMetrics.ts for usage.',
      hardcodedFinancialValue:
        'This looks like a hardcoded financial metric ({{ value }}). Use useFundMetrics() to fetch actual data.',
    },
    schema: [], // No options
  },

  create(context) {
    const filename = context.getFilename();

    // Skip allowlisted files
    if (isAllowlistedFile(filename)) {
      return {};
    }

    return {
      /**
       * Detect object literals with metric properties
       *
       * const fundMetrics = { irr: 0.285, tvpi: 2.82, ... }
       */
      VariableDeclarator(node) {
        // Check if variable name contains "metrics"
        const isMetricsVariable =
          node.id.type === 'Identifier' &&
          (node.id.name.toLowerCase().includes('metrics') ||
            node.id.name.toLowerCase().includes('performance'));

        // Check if initializer is an object with suspicious properties
        if (
          node.init &&
          node.init.type === 'ObjectExpression' &&
          (isMetricsVariable || hasSuspiciousProperties(node.init.properties))
        ) {
          context.report({
            node: node.init,
            messageId: 'hardcodedMetrics',
          });
        }
      },

      /**
       * Detect object literals assigned to properties
       *
       * this.fundMetrics = { irr: 0.285, ... }
       */
      AssignmentExpression(node) {
        if (
          node.right.type === 'ObjectExpression' &&
          hasSuspiciousProperties(node.right.properties)
        ) {
          // Check if left side is a metrics-related property
          if (
            (node.left.type === 'MemberExpression' &&
              node.left.property.type === 'Identifier' &&
              (node.left.property.name.toLowerCase().includes('metrics') ||
                METRIC_PROPERTIES.includes(node.left.property.name))) ||
            (node.left.type === 'Identifier' &&
              node.left.name.toLowerCase().includes('metrics'))
          ) {
            context.report({
              node: node.right,
              messageId: 'hardcodedMetrics',
            });
          }
        }
      },

      /**
       * Detect suspicious numeric literals that look like financial data
       *
       * const totalInvested = 85000000;
       * const irr = 0.285;
       */
      VariableDeclarator(node) {
        if (
          node.id.type === 'Identifier' &&
          METRIC_PROPERTIES.includes(node.id.name) &&
          node.init &&
          looksLikeFinancialValue(node.init)
        ) {
          context.report({
            node: node.init,
            messageId: 'hardcodedFinancialValue',
            data: {
              value: node.init.value,
            },
          });
        }
      },
    };
  },
};

/**
 * Example: Integrating circuit breaker into existing cache layer
 * 
 * This shows how to replace your current cache implementation with
 * a circuit breaker-protected version that automatically falls back
 * to memory cache when Redis fails.
 */

import { CacheBreakerService } from '../server/infra/circuit-breaker/cache-breaker';
import { breakerRegistry } from '../server/infra/circuit-breaker/breaker-registry';
import { buildCache } from '../server/cache/index';

// Example: Enhanced cache service with circuit breaker protection
export async function createProtectedCacheService(): Promise<CacheBreakerService> {
  // Build your existing cache (Redis with memory fallback)
  const primaryCache = await buildCache();
  
  // Wrap it with circuit breaker protection
  const protectedCache = new CacheBreakerService(primaryCache);
  
  // Register for monitoring and admin access
  breakerRegistry.register('cache-primary', protectedCache);
  
  return protectedCache;
}

// Example: Portfolio service using protected cache
export class PortfolioService {
  constructor(private cache: CacheBreakerService) {}

  async getPortfolio(id: string) {
    const key = `portfolio:${id}`;
    
    // Try to get from cache first (with circuit breaker protection)
    const cached = await this.cache.get(key);
    if (cached) {
      return JSON.parse(cached);
    }

    // Simulate database/computation fallback
    const portfolio = await this.computePortfolio(id);
    
    // Cache the result (with circuit breaker protection)
    await this.cache.set(key, JSON.stringify(portfolio), 300); // 5 min TTL
    
    return portfolio;
  }

