export interface AgentExecutionContext {
  runId: string;
  timestamp: string;
  agent: string;
  operation: string;
  metadata?: Record<string, unknown>;
  continuationId?: string;
  conversationHistory?: string;
}

export interface AgentResult<T = unknown> {
  success: boolean;
