/**
 * Pattern Learning Engine
 *
 * Enables cross-conversation pattern learning by recording successful/failed
 * approaches and applying learned insights to future tasks.
 *
 * Features:
 * - Pattern extraction from agent execution results
 * - Confidence scoring based on occurrence frequency
 * - Relevance ranking for context matching
 * - Prompt augmentation with learned patterns
 *
 * @example
 * ```typescript
 * const engine = new PatternLearningEngine(storage, 'user:project');
 *
 * // Record a pattern after execution
 * await engine.recordPattern(result, context);
 *
 * // Retrieve relevant patterns for new task
 * const patterns = await engine.getRelevantPatterns({
 *   operation: 'test-repair',
 *   fileTypes: ['.ts', '.tsx'],
 * });
 *
 * // Build context for prompt
 * const context = await engine.buildPatternContext('test-repair', ['.ts']);
 * ```
 */

import { v4 as uuidv4 } from 'uuid';
import type { ConversationStorage } from './ConversationMemory.js';
import { CacheKeySchema } from './cache/KeySchema.js';
import type { MemoryEventBus} from './MemoryEventBus.js';
import { getEventBus } from './MemoryEventBus.js';
import { logger } from './Logger.js';
import type { AgentResult, AgentExecutionContext } from './BaseAgent.js';

/**
 * Pattern types
 */
export type PatternType = 'success' | 'failure' | 'optimization' | 'user_preference';

/**
 * Conversation pattern
 */
export interface ConversationPattern {
  /** Unique pattern ID */
  id: string;

  /** Tenant ID for isolation */
  tenantId: string;

  /** Pattern type */
  patternType: PatternType;

  /** Context in which pattern was observed */
  context: {
    /** Operation type (e.g., 'test-repair', 'code-review') */
    operation: string;

    /** Hash of input pattern */
    inputSignature: string;

    /** File types involved */
    fileTypes: string[];

    /** Tags for searchability */
    tags?: string[];
  };

  /** Observation details */
  observation: {
    /** Approach that was tried */
    approach: string;

    /** Result of the approach */
    result: 'success' | 'failure';

    /** Performance metrics */
    metrics?: {
      duration: number;
      retries: number;
      cost?: number;
    };
  };

  /** Natural language lesson learned */
  learnedInsight: string;

  /** Confidence score (0-1) based on occurrences */
  confidence: number;

  /** Number of times pattern observed */
  occurrences: number;

  /** First observed timestamp */
  firstSeen: string;

  /** Last observed timestamp */
  lastSeen: string;

  /** Searchable tags */
  tags: string[];
}

/**
 * Pattern retrieval context
 */
export interface PatternContext {
  /** Operation type */
  operation: string;

  /** File types */
  fileTypes: string[];

  /** Optional tags */
  tags?: string[];

  /** Maximum patterns to retrieve */
  limit?: number;
}

/**
 * Pattern Learning Engine
 */
export class PatternLearningEngine {
  private readonly storage: ConversationStorage;
  private readonly tenantId: string;
  private readonly eventBus: MemoryEventBus;

  constructor(storage: ConversationStorage, tenantId: string, eventBus?: MemoryEventBus) {
    this.storage = storage;
    this.tenantId = tenantId;
    this.eventBus = eventBus ?? getEventBus();
  }

  /**
   * Record a pattern from agent execution
   *
   * @param result - Agent execution result
   * @param context - Execution context
   */
  async recordPattern(
    result: AgentResult<unknown>,
    context: AgentExecutionContext
  ): Promise<void> {
    try {
      const pattern = this.extractPattern(result, context);

      // Check if similar pattern exists
      const existingPattern = await this.findSimilarPattern(pattern);

      if (existingPattern) {
        // Update existing pattern (increment occurrences, update confidence)
        await this.updatePattern(existingPattern, pattern);
      } else {
        // Create new pattern
        await this.createPattern(pattern);
      }

      // Emit event
      await this.eventBus.emit({
        type: 'pattern_learned',
        patternId: pattern.id,
        tenantId: this.tenantId,
        operation: pattern.context.operation,
        confidence: pattern.confidence,
      });

      logger.info('Pattern recorded', {patternId: pattern.id,
        operation: pattern.context.operation,
        patternType: pattern.patternType,
        confidence: pattern.confidence,
      });
    } catch (error: unknown) {
      logger.error('Failed to record pattern', {error: error instanceof Error ? error.message : String(error),
        tenantId: this.tenantId,
      });
    }
  }

  /**
   * Retrieve relevant patterns for current context
   *
   * @param context - Pattern retrieval context
   * @returns Array of relevant patterns, sorted by relevance
   */
  async getRelevantPatterns(context: PatternContext): Promise<ConversationPattern[]> {
    try {
      // Get all patterns for tenant + operation
      const patterns = await this.getAllPatterns(context.operation);

      // Filter by file types and tags
      const filtered = patterns.filter(pattern =>
        this.matchesContext(pattern, context)
      );

      // Sort by relevance (confidence * recency)
      const sorted = this.sortByRelevance(filtered);

      // Limit results
      const limit = context.limit ?? 5;
      return sorted.slice(0, limit);
    } catch (error: unknown) {
      logger.error('Failed to retrieve patterns', {error: error instanceof Error ? error.message : String(error),
        operation: context.operation,
      });
      return [];
    }
  }

  /**
   * Build prompt augmentation from learned patterns
   *
   * @param operation - Operation type
   * @param fileTypes - File types involved
   * @returns Formatted pattern context for prompt
   */
  async buildPatternContext(
    operation: string,
    fileTypes: string[]
  ): Promise<string> {
    const patterns = await this.getRelevantPatterns({
      operation,
      fileTypes,
      limit: 3, // Top 3 patterns
    });

    if (patterns.length === 0) {
      return '';
    }

    const formatted = patterns
      .map((p, i) => {
        const resultEmoji = p.observation.result === 'success' ? '✅' : '❌';
        return `
${i + 1}. ${resultEmoji} **${p.observation.approach}** → ${p.observation.result}
   **Insight**: ${p.learnedInsight}
   **Confidence**: ${(p.confidence * 100).toFixed(0)}% (observed ${p.occurrences} time${p.occurrences > 1 ? 's' : ''})
   **Performance**: ${p.observation.metrics?.duration ?? 'N/A'}ms${p.observation.metrics?.retries ? `, ${p.observation.metrics.retries} retries` : ''}
`.trim();
      })
      .join('\n\n');

    return `
<learned_patterns>
Based on previous similar ${operation} tasks, here are relevant insights:

${formatted}

Consider these patterns when approaching this task. Apply successful patterns and avoid approaches that previously failed.
</learned_patterns>
`.trim();
  }

  /**
   * Extract pattern from agent result and context
   */
  private extractPattern(
    result: AgentResult<unknown>,
    context: AgentExecutionContext
  ): ConversationPattern {
    const patternType: PatternType = result.success ? 'success' : 'failure';
    const fileTypes = this.extractFileTypes(context);
    const inputSignature = this.hashInput(context.input);

    // Extract learned insight from result
    const learnedInsight = this.extractInsight(result, context);

    // Extract approach description
    const approach = this.extractApproach(result, context);

    return {
      id: uuidv4(),
      tenantId: this.tenantId,
      patternType,
      context: {
        operation: context.operation ?? 'unknown',
        inputSignature,
        fileTypes,
        tags: context.tags ?? [],
      },
      observation: {
        approach,
        result: result.success ? 'success' : 'failure',
        metrics: {
          duration: result.duration ?? 0,
          retries: result.retries ?? 0,
          cost: context.cost,
        },
      },
      learnedInsight,
      confidence: 0.5, // Initial confidence (will be adjusted based on occurrences)
      occurrences: 1,
      firstSeen: new Date().toISOString(),
      lastSeen: new Date().toISOString(),
      tags: [...(context.tags ?? []), ...fileTypes, context.operation ?? 'unknown'],
    };
  }

  /**
   * Find similar existing pattern
   */
  private async findSimilarPattern(
    pattern: ConversationPattern
  ): Promise<ConversationPattern | null> {
    // Get all patterns for same operation
    const patterns = await this.getAllPatterns(pattern.context.operation);

    // Find pattern with matching signature and approach
    return patterns.find(
      p =>
        p.context.inputSignature === pattern.context.inputSignature &&
        p.observation.approach === pattern.observation.approach
    ) ?? null;
  }

  /**
   * Update existing pattern with new observation
   */
  private async updatePattern(
    existing: ConversationPattern,
    newObservation: ConversationPattern
  ): Promise<void> {
    const updated: ConversationPattern = {
      ...existing,
      occurrences: existing.occurrences + 1,
      lastSeen: new Date().toISOString(),
      // Increase confidence based on occurrences (max 0.95)
      confidence: Math.min(0.95, 0.5 + (existing.occurrences * 0.05)),
      // Update metrics (running average)
      observation: {
        ...existing.observation,
        metrics: existing.observation.metrics ? {
          duration: Math.round(
            (existing.observation.metrics.duration * existing.occurrences +
              (newObservation.observation.metrics?.duration ?? 0)) /
            (existing.occurrences + 1)
          ),
          retries: Math.round(
            (existing.observation.metrics.retries * existing.occurrences +
              (newObservation.observation.metrics?.retries ?? 0)) /
            (existing.occurrences + 1)
          ),
        } : newObservation.observation.metrics,
      },
    };

    const { key } = CacheKeySchema.pattern(
      updated.id,
      this.tenantId,
      updated.context.operation
    );

    await this.storage.set(key, JSON.stringify(updated));

    logger.debug('Pattern updated', {patternId: updated.id,
      occurrences: updated.occurrences,
      confidence: updated.confidence,
    });
  }

  /**
   * Create new pattern
   */
  private async createPattern(pattern: ConversationPattern): Promise<void> {
    const { key } = CacheKeySchema.pattern(
      pattern.id,
      this.tenantId,
      pattern.context.operation
    );

    await this.storage.set(key, JSON.stringify(pattern));

    logger.debug('Pattern created', {patternId: pattern.id,
      operation: pattern.context.operation,
    });
  }

  /**
   * Get all patterns for operation (placeholder - needs Redis SCAN)
   */
  private async getAllPatterns(operation: string): Promise<ConversationPattern[]> {
    // TODO: Implement with Redis SCAN or dedicated index
    // For now, return empty array
    // Full implementation would scan keys matching:
    // app:prod:pattern:{operation}:{tenantId}:*:v1

    logger.debug('getAllPatterns not fully implemented', {operation,
      note: 'Requires Redis SCAN implementation',
    });

    return [];
  }

  /**
   * Check if pattern matches context
   */
  private matchesContext(
    pattern: ConversationPattern,
    context: PatternContext
  ): boolean {
    // Match operation
    if (pattern.context.operation !== context.operation) {
      return false;
    }

    // Match file types (at least one overlap)
    const hasFileTypeOverlap = context.fileTypes.some(ft =>
      pattern.context.fileTypes.includes(ft)
    );

    if (!hasFileTypeOverlap && context.fileTypes.length > 0) {
      return false;
    }

    // Match tags (optional)
    if (context.tags && context.tags.length > 0) {
      const hasTagOverlap = context.tags.some(tag =>
        pattern.tags.includes(tag)
      );

      if (!hasTagOverlap) {
        return false;
      }
    }

    return true;
  }

  /**
   * Sort patterns by relevance
   *
   * Relevance = confidence * recency_weight
   * Recency weight decays over time (more recent = higher weight)
   */
  private sortByRelevance(patterns: ConversationPattern[]): ConversationPattern[] {
    const now = Date.now();

    return patterns.sort((a, b) => {
      const aRecency = this.calculateRecencyWeight(a.lastSeen, now);
      const bRecency = this.calculateRecencyWeight(b.lastSeen, now);

      const aRelevance = a.confidence * aRecency;
      const bRelevance = b.confidence * bRecency;

      return bRelevance - aRelevance; // Descending order
    });
  }

  /**
   * Calculate recency weight (exponential decay)
   *
   * Weight = e^(-days_old / 30)
   * - Recent (< 7 days): ~0.8-1.0
   * - Medium (7-30 days): ~0.4-0.8
   * - Old (> 30 days): < 0.4
   */
  private calculateRecencyWeight(lastSeen: string, now: number): number {
    const lastSeenMs = new Date(lastSeen).getTime();
    const ageMs = now - lastSeenMs;
    const ageDays = ageMs / (1000 * 60 * 60 * 24);

    return Math.exp(-ageDays / 30);
  }

  /**
   * Extract file types from context
   */
  private extractFileTypes(context: AgentExecutionContext): string[] {
    // Try to extract from input if it's a string or has file paths
    const input = context.input;

    if (typeof input === 'string') {
      // Extract file extensions from paths
      const matches = input.match(/\.\w+/g);
      return matches ? [...new Set(matches)] : [];
    }

    if (typeof input === 'object' && input !== null) {
      // Look for common file-related properties
      const fileProps = ['files', 'filePaths', 'path', 'file'];
      for (const prop of fileProps) {
        if (prop in input) {
          const value = (input as Record<string, unknown>)[prop];
          if (typeof value === 'string') {
            const ext = value.match(/\.(\w+)$/)?.[0];
            return ext ? [ext] : [];
          }
        }
      }
    }

    return [];
  }

  /**
   * Hash input for signature matching
   */
  private hashInput(input: unknown): string {
    const str = typeof input === 'string' ? input : JSON.stringify(input);
    // Simple hash (for demo - use crypto.createHash in production)
    return str.slice(0, 100); // First 100 chars
  }

  /**
   * Extract learned insight from result
   */
  private extractInsight(result: AgentResult<unknown>, context: AgentExecutionContext): string {
    if (result.success) {
      return `Successful approach for ${context.operation ?? 'operation'} with ${result.retries ?? 0} retries`;
    } else {
      return `Failed approach for ${context.operation ?? 'operation'}: ${result.error ?? 'unknown error'}`;
    }
  }

  /**
   * Extract approach description from result
   */
  private extractApproach(result: AgentResult<unknown>, context: AgentExecutionContext): string {
    // Try to extract from result output
    if (result.output && typeof result.output === 'string') {
      // Take first sentence as approach
      const firstSentence = result.output.split('.')[0];
      return firstSentence.slice(0, 200); // Truncate to 200 chars
    }

    return `${context.operation ?? 'operation'} execution`;
  }
}

/**
 * Asynchronous serialization helper to prevent event loop blocking
 *
 * Large objects (>10KB) can block the event loop for 100-500ms when serialized.
 * This helper uses worker threads via Piscina to offload serialization work.
 *
 * Phase 2 Fix (Issue #1): Actually offloads work to worker threads instead of
 * wrapping synchronous JSON.stringify in async function.
 */

import Piscina from 'piscina';
import path from 'path';
import { fileURLToPath } from 'url';
import os from 'os';
import type { SerializationTask, SerializationWorkerResult } from './workers/serialization-worker';

// ESM-compatible __dirname replacement
const __filename = fileURLToPath(import.meta.url);
const __dirname = path.dirname(__filename);

export interface SerializationOptions {
  maxSize?: number;
  pretty?: boolean;
  truncate?: boolean;
}

export interface SerializationResult {
  serialized: string;
  truncated: boolean;
  originalSize?: number;
}

// Singleton worker pool - shared across all serialization operations
let workerPool: Piscina | null = null;

/**
 * Initialize the worker thread pool
 * Called lazily on first use
 */
function getWorkerPool(): Piscina {
  if (!workerPool) {
    const workerPath = path.join(__dirname, 'workers', 'serialization-worker.js');

    workerPool = new Piscina({
      filename: workerPath,
      maxThreads: Math.max(2, Math.floor(os.cpus().length / 2)), // Use half CPU cores, min 2
      minThreads: 1,
      idleTimeout: 30000, // Keep workers alive for 30s
    });
  }
  return workerPool;
}

/**
 * Cleanup worker pool on process exit
 */
export async function shutdownSerializationPool(): Promise<void> {
  const pool = workerPool;
  if (pool) {
    await pool.destroy();
    // eslint-disable-next-line require-atomic-updates -- Safe: pool reference prevents race condition
    workerPool = null;
  }
}

/**
 * Safely serialize objects without blocking the event loop
 *
 * Small objects (< 1KB): Uses synchronous JSON.stringify for speed
 * Large objects (>= 1KB): Offloads to worker thread to prevent event loop blocking
 *
 * Phase 2 Fix: Now actually offloads work to worker threads instead of fake async
 *
 * @param obj - Object to serialize
 * @param options - Serialization options
 * @returns Promise resolving to serialized string and metadata
 */
export async function serializeAsync(
  obj: unknown,
  options: SerializationOptions = {}
): Promise<SerializationResult> {
  const {
    maxSize = 50000,
    pretty = false,
    truncate = true
  } = options;

  try {
    // Fast path for simple values (primitives)
    if (obj === null || obj === undefined || typeof obj !== 'object') {
      const serialized = JSON.stringify(obj);
      return { serialized, truncated: false };
    }

    // Quick size estimate using char count heuristic (fast, synchronous)
    const estimatedSize = estimateSize(obj);

    // Small objects: use fast synchronous path (< 1KB threshold)
    if (estimatedSize < 1024) {
      const serialized = pretty ? JSON.stringify(obj, null, 2) : JSON.stringify(obj);
      return { serialized, truncated: false };
    }

    // Large objects: offload to worker thread (ACTUAL async, not fake)
    const pool = getWorkerPool();
    const task: SerializationTask = { obj, pretty, maxSize, truncate };

    const result: SerializationWorkerResult = await pool.run(task);

    // Handle worker errors
    if (result.error) {
      // Worker handled the error, but log it
      console.warn('[SerializationHelper] Worker serialization error:', result.error);
    }

    return {
      serialized: result.serialized,
      truncated: result.truncated,
      originalSize: result.originalSize
    };

  } catch (error: unknown) {
    // Fallback if worker pool fails - use synchronous serialization
    console.error('[SerializationHelper] Worker pool failure, falling back to sync:', error);

    try {
      const serialized = pretty ? JSON.stringify(obj, null, 2) : JSON.stringify(obj);
      return { serialized, truncated: false };
    } catch (syncError) {
      // Final fallback
      const errorMessage = syncError instanceof Error ? syncError.message : String(syncError);
      const fallback = JSON.stringify({
        _serializationError: true,
        error: errorMessage,
        type: typeof obj,
        preview: String(obj).substring(0, 200)
      });

      return { serialized: fallback, truncated: true };
    }
  }
}

/**
 * Estimate serialized size without actually serializing
 * Uses heuristic: avg 4 chars per primitive, recursively count fields
 */
function estimateSize(obj: unknown): number {
  if (obj === null || obj === undefined) return 4;
  if (typeof obj === 'string') return obj.length + 2; // quotes
  if (typeof obj === 'number' || typeof obj === 'boolean') return 8;

  if (Array.isArray(obj)) {
    // Estimate array size
    return obj.reduce((sum, item) => sum + estimateSize(item), 10);
  }

  if (typeof obj === 'object') {
    // Estimate object size
    const keys = Object.keys(obj);
    return keys.reduce((sum, key) => {
      return sum + key.length + estimateSize((obj as Record<string, unknown>)[key]);
    }, 20);
  }

  return 4;
}

/**
 * Synchronously serialize with safety checks
 * Useful when async is not needed but safety is still required
 */
export function serializeSafely(obj: unknown, maxSize = 50000): string {
  try {
    const serialized = JSON.stringify(obj, null, 2);

    if (serialized.length > maxSize) {
      return JSON.stringify({
        _truncated: true,
        _size: serialized.length,
        preview: serialized.substring(0, maxSize - 200),
        summary: generateSummary(obj)
      }, null, 2);
    }

    return serialized;
  } catch (error: unknown) {
    return JSON.stringify({
      _serializationError: true,
      error: error instanceof Error ? error.message : String(error),
      type: typeof obj
    });
  }
}

/**
 * Generate a summary of an object structure
 */
function generateSummary(obj: unknown): Record<string, unknown> {
  if (obj === null || obj === undefined) {
    return { type: String(obj) };
  }

  if (Array.isArray(obj)) {
    return {
      type: 'Array',
      length: obj.length,
      sample: obj.slice(0, 3)
    };
  }

  if (typeof obj === 'object') {
    const keys = Object.keys(obj);
    return {
      type: 'Object',
      keys: keys.length,
      keyNames: keys.slice(0, 10),
      ...(keys.length > 10 && { truncatedKeys: keys.length - 10 })
    };
  }

  return {
    type: typeof obj,
    value: String(obj).substring(0, 100)
  };
}

/**
 * Batch serialize multiple objects efficiently
 * Useful for logging or metrics collection
 */
export async function serializeBatch(
  objects: unknown[],
  options: SerializationOptions = {}
): Promise<SerializationResult[]> {
  // Process in parallel but limit concurrency to avoid memory spikes
  const BATCH_SIZE = 5;
  const results: SerializationResult[] = [];

  for (let i = 0; i < objects.length; i += BATCH_SIZE) {
    const batch = objects.slice(i, i + BATCH_SIZE);
    const batchResults = await Promise.all(
      batch.map(obj => serializeAsync(obj, options))
    );
    results.push(...batchResults);
  }

  return results;
}

/**
 * Upstash HTTP Redis Adapter
 *
 * HTTP-based Redis client optimized for serverless environments.
 *
 * Features:
 * - HTTP-based (no socket connection issues on Vercel)
 * - MessagePack serialization (30-50% smaller than JSON)
 * - gzip compression for objects > 2KB
 * - Circuit breaker for fault tolerance
 * - Time-budgeted operations (25ms timeout)
 * - Lazy connection
 * - Automatic retry with exponential backoff
 *
 * Phase 2 - Issue #2: Redis L2 Cache
 */

import { Redis } from '@upstash/redis';
import { encode, decode } from '@msgpack/msgpack';
import * as pako from 'pako';
import type {
  CacheAdapter,
  CacheAdapterConfig,
  CacheEntry} from './CacheAdapter';
import {
  withTimeout
} from './CacheAdapter';
import { CircuitBreaker } from './CircuitBreaker';

/**
 * Compression threshold (2KB)
 * Objects larger than this will be gzipped
 */
const COMPRESSION_THRESHOLD = 2048;

/**
 * Maximum payload size (128KB)
 * Reject objects larger than this to prevent memory issues
 */
const MAX_PAYLOAD_SIZE = 128 * 1024;

/**
 * Default operation timeout (25ms)
 */
const DEFAULT_TIMEOUT_MS = 25;

/**
 * Upstash adapter implementation
 *
 * Usage:
 * ```typescript
 * const adapter = new UpstashAdapter({
 *   url: process.env.UPSTASH_REDIS_REST_URL!,
 *   token: process.env.UPSTASH_REDIS_REST_TOKEN!,
 *   timeoutMs: 25,
 *   enableCircuitBreaker: true
 * });
 *
 * const value = await adapter.get<CachedConversation>('key');
 * await adapter.set('key', value, 3600);
 * ```
 */
export class UpstashAdapter implements CacheAdapter {
  private client: Redis | null = null;
  private circuitBreaker: CircuitBreaker | null = null;
  private readonly config: CacheAdapterConfig;
  private isInitialized = false;

  // Metrics (simple counters)
  private stats = {
    gets: 0,
    sets: 0,
    dels: 0,
    hits: 0,
    misses: 0,
    errors: 0,
    timeouts: 0,
    compressions: 0,
    decompressions: 0,
    payloadRejections: 0,
  };

  constructor(config: CacheAdapterConfig) {
    this.config = {
      timeoutMs: DEFAULT_TIMEOUT_MS,
      maxRetries: 3,
      enableCircuitBreaker: true,
      circuitBreakerThreshold: 5,
      ...config,
    };

    // Initialize circuit breaker if enabled
    if (this.config.enableCircuitBreaker) {
      this.circuitBreaker = new CircuitBreaker({
        threshold: this.config.circuitBreakerThreshold || 5,
        timeout: 60000,      // 60s failure window
        resetTimeout: 120000  // 2min recovery
      });
    }

    // Lazy initialization - client created on first use
  }

  /**
   * Initialize Redis client (lazy)
   */
  private init(): void {
    if (this.isInitialized) return;

    try {
      // Validate config
      if (!this.config.url) {
        throw new Error('Upstash URL is required');
      }

      if (!this.config.token) {
        throw new Error('Upstash token is required');
      }

      this.client = new Redis({
        url: this.config.url,
        token: this.config.token,
        automaticDeserialization: false, // We handle serialization
      });

      this.isInitialized = true;

    } catch (error: unknown) {
      console.error('[UpstashAdapter] Initialization failed:', error);
      this.stats.errors++;
      // Don't throw - graceful degradation
    }
  }

  /**
   * Get value by key
   */
  async get<T>(key: string): Promise<T | null> {
    this.stats.gets++;

    // Circuit breaker check
    if (this.circuitBreaker?.isOpen()) {
      return null;
    }

    // Lazy init
    if (!this.isInitialized) {
      this.init();
    }

    if (!this.client) {
      return null;
    }

    try {
      const start = Date.now();

      // Time-budgeted get
      const result = await withTimeout(
        this.client.get(key),
        this.config.timeoutMs!,
        null
      );

      const latency = Date.now() - start;

      // Timeout detection
      if (latency >= this.config.timeoutMs!) {
        this.stats.timeouts++;
        this.circuitBreaker?.recordFailure();
        return null;
      }

      if (!result) {
        this.stats.misses++;
        return null;
      }

      // Deserialize
      const deserialized = this.deserialize<T>(result as string);

      if (deserialized === null) {
        this.stats.errors++;
        this.circuitBreaker?.recordFailure();
        return null;
      }

      this.stats.hits++;
      this.circuitBreaker?.recordSuccess();
      return deserialized;

    } catch (error: unknown) {
      this.stats.errors++;
      this.circuitBreaker?.recordFailure();
      console.error('[UpstashAdapter] Get error:', {
        key,
        error: error instanceof Error ? error.message : String(error)
      });
      return null;
    }
  }

  /**
   * Get multiple values (batch operation)
   */
  async mget<T>(keys: string[]): Promise<(T | null)[]> {
    if (keys.length === 0) return [];

    // Circuit breaker check
    if (this.circuitBreaker?.isOpen()) {
      return keys.map(() => null);
    }

    if (!this.isInitialized) {
      this.init();
    }

    if (!this.client) {
      return keys.map(() => null);
    }

    try {
      // Longer timeout for batch operations
      const batchTimeout = this.config.timeoutMs! * 2;

      const results = await withTimeout(
        this.client.mget(...keys),
        batchTimeout,
        keys.map(() => null)
      );

      return (results as (string | null)[]).map(r => {
        if (!r) return null;
        return this.deserialize<T>(r);
      });

    } catch (error: unknown) {
      this.stats.errors++;
      console.error('[UpstashAdapter] Mget error:', error);
      return keys.map(() => null);
    }
  }

  /**
   * Set value with TTL
   */
  async set<T>(key: string, value: T, ttlSec: number): Promise<void> {
    this.stats.sets++;

    // Circuit breaker check
    if (this.circuitBreaker?.isOpen()) {
      return;
    }

    if (!this.isInitialized) {
      this.init();
    }

    if (!this.client) {
      return;
    }

    try {
      // Serialize
      const serialized = this.serialize(value);

      if (serialized === null) {
        this.stats.errors++;
        this.circuitBreaker?.recordFailure();
        return;
      }

      // Time-budgeted set
      await withTimeout(
        this.client.setex(key, ttlSec, serialized),
        this.config.timeoutMs!,
        undefined
      );

      this.circuitBreaker?.recordSuccess();

    } catch (error: unknown) {
      this.stats.errors++;
      this.circuitBreaker?.recordFailure();
      console.error('[UpstashAdapter] Set error:', {
        key,
        error: error instanceof Error ? error.message : String(error)
      });
    }
  }

  /**
   * Set multiple values (batch operation)
   */
  async mset<T>(entries: CacheEntry<T>[]): Promise<void> {
    if (entries.length === 0) return;

    if (this.circuitBreaker?.isOpen()) {
      return;
    }

    if (!this.isInitialized) {
      this.init();
    }

    if (!this.client) {
      return;
    }

    try {
      // Execute in parallel (with concurrency limit)
      const promises = entries.map(({ key, value, ttlSec }) =>
        this.set(key, value, ttlSec)
      );

      await Promise.all(promises);

    } catch (error: unknown) {
      this.stats.errors++;
      console.error('[UpstashAdapter] Mset error:', error);
    }
  }

  /**
   * Delete one or more keys
   */
  async del(keys: string | string[]): Promise<number> {
    this.stats.dels++;

    if (this.circuitBreaker?.isOpen()) {
      return 0;
    }

    if (!this.isInitialized) {
      this.init();
    }

    if (!this.client) {
      return 0;
    }

    try {
      const keysArray = Array.isArray(keys) ? keys : [keys];

      const result = await withTimeout(
        this.client.del(...keysArray),
        this.config.timeoutMs!,
        0
      );

      this.circuitBreaker?.recordSuccess();
      return result as number;

    } catch (error: unknown) {
      this.stats.errors++;
      this.circuitBreaker?.recordFailure();
      console.error('[UpstashAdapter] Del error:', error);
      return 0;
    }
  }

  /**
   * Get remaining TTL
   */
  async ttl(key: string): Promise<number | null> {
    if (this.circuitBreaker?.isOpen()) {
      return null;
    }

    if (!this.isInitialized) {
      this.init();
    }

    if (!this.client) {
      return null;
    }

    try {
      const result = await withTimeout(
        this.client.ttl(key),
        this.config.timeoutMs!,
        -1
      );

      return result as number;

    } catch (error: unknown) {
      console.error('[UpstashAdapter] TTL error:', error);
      return null;
    }
  }

  /**
   * Add member to set (for tag indexing)
   */
  async sadd(setKey: string, member: string): Promise<void> {
    if (this.circuitBreaker?.isOpen()) {
      return;
    }

    if (!this.isInitialized) {
      this.init();
    }

    if (!this.client) {
      return;
    }

    try {
      await withTimeout(
        this.client.sadd(setKey, member),
        this.config.timeoutMs!,
        undefined
      );

    } catch (error: unknown) {
      console.error('[UpstashAdapter] Sadd error:', error);
    }
  }

  /**
   * Get all members of set
   */
  async smembers(setKey: string): Promise<string[]> {
    if (this.circuitBreaker?.isOpen()) {
      return [];
    }

    if (!this.isInitialized) {
      this.init();
    }

    if (!this.client) {
      return [];
    }

    try {
      const result = await withTimeout(
        this.client.smembers(setKey),
        this.config.timeoutMs! * 2, // Longer timeout for potentially large sets
        []
      );

      return result as string[];

    } catch (error: unknown) {
      console.error('[UpstashAdapter] Smembers error:', error);
      return [];
    }
  }

  /**
   * Health check
   */
  async ping(): Promise<boolean> {
    if (!this.isInitialized) {
      this.init();
    }

    if (!this.client) {
      return false;
    }

    try {
      const result = await withTimeout(
        this.client.ping(),
        1000, // 1s timeout for ping
        'TIMEOUT'
      );

      return result === 'PONG';

    } catch (_error: unknown) {
      return false;
    }
  }

  /**
   * Disconnect (no-op for HTTP client)
   */
  async disconnect(): Promise<void> {
    // HTTP client doesn't maintain persistent connections
    this.isInitialized = false;
    this.client = null;
  }

  /**
   * Get adapter name
   */
  getName(): string {
    return 'UpstashAdapter';
  }

  /**
   * Check if circuit breaker is open
   */
  isCircuitOpen(): boolean {
    return this.circuitBreaker?.isOpen() ?? false;
  }

  /**
   * Get adapter stats (for debugging)
   */
  getStats() {
    return {
      ...this.stats,
      circuitState: this.circuitBreaker?.getState() ?? 'unknown',
      isInitialized: this.isInitialized,
    };
  }

  /**
   * Serialize value with MessagePack + optional compression
   */
  private serialize<T>(value: T): string | null {
    try {
      // MessagePack encode
      const encoded = encode(value);
      const buffer = Buffer.from(encoded);

      // Check size limit
      if (buffer.length > MAX_PAYLOAD_SIZE) {
        console.error('[UpstashAdapter] Payload too large:', {
          size: buffer.length,
          limit: MAX_PAYLOAD_SIZE
        });
        this.stats.payloadRejections++;
        return null;
      }

      // Compress if over threshold
      const final = buffer.length > COMPRESSION_THRESHOLD
        ? pako.gzip(buffer)
        : buffer;

      if (buffer.length > COMPRESSION_THRESHOLD) {
        this.stats.compressions++;
      }

      // Base64 encode for string transport
      return final.toString('base64');

    } catch (error: unknown) {
      console.error('[UpstashAdapter] Serialization error:', error);
      return null;
    }
  }

  /**
   * Deserialize value with MessagePack + optional decompression
   */
  private deserialize<T>(value: string): T | null {
    try {
      // Base64 decode
      const buffer = Buffer.from(value, 'base64');

      // Try decompression (detect gzip magic number)
      const isCompressed = buffer[0] === 0x1f && buffer[1] === 0x8b;

      const decompressed = isCompressed
        ? pako.ungzip(buffer)
        : buffer;

      if (isCompressed) {
        this.stats.decompressions++;
      }

      // MessagePack decode
      const decoded = decode(decompressed) as T;

      return decoded;

    } catch (error: unknown) {
      console.error('[UpstashAdapter] Deserialization error:', {
        error: error instanceof Error ? error.message : String(error)
      });

      // Delete corrupted key (best effort)
      // Don't await to avoid blocking
      // void this.del(key);

      return null;
    }
  }
}

import type { AgentExecutionContext } from '../../agent-core/src/BaseAgent';
import { BaseAgent } from '../../agent-core/src/BaseAgent';
import { withThinking } from '../../agent-core/src/ThinkingMixin';
import * as fs from 'fs';
import * as path from 'path';
import { exec } from 'child_process';
import { promisify } from 'util';
import * as zlib from 'zlib';

const execAsync = promisify(exec);
const gzip = promisify(zlib.gzip);

export interface BundleOptimizationInput {
  targetSizeKB: number;
  preserveFunctionality: boolean;
  strategy?: 'aggressive' | 'safe' | 'balanced';
  excludePatterns?: string[];
  rollbackOnFailure?: boolean;
}

export interface BundleAnalysis {
  currentSizeKB: number;
  targetSizeKB: number;
  chunks: ChunkInfo[];
  recommendations: OptimizationRecommendation[];
  estimatedSavingsKB: number;
}

interface ChunkInfo {
  name: string;
  sizeKB: number;
  gzippedKB: number;
  modules: string[];
  isVendor: boolean;
  canBeLazyLoaded: boolean;
}

interface OptimizationRecommendation {
  type: 'lazy-load' | 'remove-dep' | 'replace-dep' | 'tree-shake' | 'code-split';
  description: string;
  estimatedSavingsKB: number;
  risk: 'low' | 'medium' | 'high';
  implementation: string;
}

export class BundleOptimizationAgent extends withThinking(BaseAgent)<BundleOptimizationInput, BundleAnalysis> {
  constructor() {
    super({
      name: 'BundleOptimizationAgent',
      maxRetries: 2,
      retryDelay: 2000,
      timeout: 120000,
      logLevel: 'info',

      // Enable native memory integration
      enableNativeMemory: true,
      enablePatternLearning: true,
      tenantId: 'agent:bundle-optimization',
      memoryScope: 'project', // Learn optimization patterns across builds
    });
  }

  protected async performOperation(
    input: BundleOptimizationInput,
    context: AgentExecutionContext
  ): Promise<BundleAnalysis> {
    this.logger.info('Starting bundle optimization analysis', { input });

    // Build the project first to get accurate bundle sizes
    await this.buildProject();

    // Analyze current bundle
    const currentAnalysis = await this.analyzeBundle();

    // Generate optimization recommendations
    const recommendations = await this.generateRecommendations(
      currentAnalysis,
      input
    );

    // Calculate estimated savings
    const estimatedSavingsKB = recommendations.reduce(
      (sum, rec) => sum + rec.estimatedSavingsKB,
      0
    );

    const analysis: BundleAnalysis = {
      currentSizeKB: currentAnalysis.totalSizeKB,
      targetSizeKB: input.targetSizeKB,
      chunks: currentAnalysis.chunks,
      recommendations,
      estimatedSavingsKB,
    };

    // If aggressive mode, attempt to apply optimizations
    if (input.strategy === 'aggressive' && input.preserveFunctionality) {
      await this.applyOptimizations(recommendations, input);
    }

    return analysis;
  }

  private async buildProject(): Promise<void> {
    this.logger.info('Building project for analysis');
    try {
      await execAsync('npm run build');
    } catch (error: unknown) {
      this.logger.warn('Build failed, continuing with existing bundle', { error });
    }
  }

  private async analyzeBundle(): Promise<{ totalSizeKB: number; chunks: ChunkInfo[] }> {
    const distPath = path.resolve('dist/public/assets');
    let totalSize = 0;
    const chunks: ChunkInfo[] = [];

    if (!fs.existsSync(distPath)) {
      throw new Error('Build directory not found. Please build the project first.');
    }

    const files = fs.readdirSync(distPath);

    for (const file of files) {
      if (!file.endsWith('.js') && !file.endsWith('.css')) continue;

      const filePath = path.join(distPath, file);
      const stats = fs.statSync(filePath);
      const content = fs.readFileSync(filePath);
      const gzipped = await gzip(content);

      const chunkInfo: ChunkInfo = {
        name: file,
        sizeKB: Math.round(stats.size / 1024),
        gzippedKB: Math.round(gzipped.length / 1024),
        modules: this.extractModules(content.toString()),
        isVendor: file.includes('vendor'),
        canBeLazyLoaded: this.canBeLazyLoaded(file, content.toString()),
      };

      chunks.push(chunkInfo);
      totalSize += chunkInfo.gzippedKB;
    }

    return { totalSizeKB: totalSize, chunks };
  }

  private extractModules(content: string): string[] {
    const modules: string[] = [];
    const modulePattern = /from\s+["']([^"']+)["']/g;
    const matches = content.matchAll(modulePattern);

    for (const match of matches) {
      if (match[1] && !modules.includes(match[1])) {
        modules.push(match[1]);
      }
    }

    return modules.slice(0, 10); // Return top 10 modules
  }

  private canBeLazyLoaded(filename: string, content: string): boolean {
    // Don't lazy load main entry or critical vendor chunks
    if (filename.includes('index') || filename.includes('vendor-react')) {
      return false;
    }

    // Check if it's a route-based chunk
    if (filename.includes('planning') || filename.includes('analytics')) {
      return true;
    }

    // Check for chart libraries (good candidates for lazy loading)
    if (content.includes('recharts') || content.includes('nivo')) {
      return true;
    }

    return false;
  }

  private async generateRecommendations(
    analysis: { totalSizeKB: number; chunks: ChunkInfo[] },
    input: BundleOptimizationInput
  ): Promise<OptimizationRecommendation[]> {
    const recommendations: OptimizationRecommendation[] = [];
    const sizeDelta = analysis.totalSizeKB - input.targetSizeKB;

    if (sizeDelta <= 0) {
      this.logger.info('Bundle already meets target size');
      return recommendations;
    }

    try {
      // Use extended thinking for complex optimization strategy
      const strategy = await this.think(
        `Analyze bundle and suggest optimizations:

Current size: ${analysis.totalSizeKB}KB
Target size: ${input.targetSizeKB}KB
Delta: ${sizeDelta}KB
Chunks: ${analysis.chunks.length}

Largest chunks:
${analysis.chunks.slice(0, 5).map(c => `- ${c.name}: ${c.gzippedKB}KB`).join('\n')}

Suggest specific, actionable optimization strategies.`,
        {
          depth: sizeDelta > 100 ? 'deep' : 'quick',
          context: 'Vite build system, React SPA, modern browser targets'
        }
      );

      // Parse AI recommendations and merge with heuristic-based ones
      this.logger.info('Extended thinking provided optimization strategy', {
        thinking_blocks: strategy.thinking.length,
        cost: strategy.cost?.total_cost_usd
      });
    } catch (error: unknown) {
      this.logger.warn('Extended thinking failed, using heuristic analysis', { error });
    }

    // Analyze for heavy dependencies
    const vendorChunks = analysis.chunks.filter(c => c.isVendor);
    for (const chunk of vendorChunks) {
      if (chunk.gzippedKB > 50) {
        recommendations.push({
          type: 'code-split',
          description: `Split ${chunk.name} into smaller chunks`,
          estimatedSavingsKB: Math.round(chunk.gzippedKB * 0.2),
          risk: 'low',
          implementation: `Add to vite.config.ts manualChunks`,
        });
      }
    }

    // Check for lazy loading opportunities
    const lazyLoadCandidates = analysis.chunks.filter(c => c.canBeLazyLoaded);
    for (const chunk of lazyLoadCandidates) {
      recommendations.push({
        type: 'lazy-load',
        description: `Lazy load ${chunk.name}`,
        estimatedSavingsKB: chunk.gzippedKB,
        risk: 'low',
        implementation: `Use React.lazy() for this route/component`,
      });
    }

    // Check for large libraries that can be replaced
    if (analysis.chunks.some(c => c.modules.some(m => m.includes('moment')))) {
      recommendations.push({
        type: 'replace-dep',
        description: 'Replace moment.js with date-fns',
        estimatedSavingsKB: 30,
        risk: 'medium',
        implementation: 'npm remove moment && npm install date-fns',
      });
    }

    if (analysis.chunks.some(c => c.modules.some(m => m.includes('lodash')))) {
      recommendations.push({
        type: 'replace-dep',
        description: 'Replace lodash with lodash-es',
        estimatedSavingsKB: 20,
        risk: 'low',
        implementation: 'npm remove lodash && npm install lodash-es',
      });
    }

    // Sort by impact and risk
    recommendations.sort((a, b) => {
      if (a.risk === b.risk) {
        return b.estimatedSavingsKB - a.estimatedSavingsKB;
      }
      const riskOrder = { low: 0, medium: 1, high: 2 };
      return riskOrder[a.risk] - riskOrder[b.risk];
    });

    return recommendations;
  }

  private async applyOptimizations(
    recommendations: OptimizationRecommendation[],
    input: BundleOptimizationInput
  ): Promise<void> {
    if (!input.preserveFunctionality) {
      this.logger.warn('Skipping auto-application without preserve functionality flag');
      return;
    }

    // Only apply low-risk optimizations automatically
    const safeOptimizations = recommendations.filter(r => r.risk === 'low');

    for (const optimization of safeOptimizations) {
      try {
        this.logger.info('Applying optimization', { optimization });

        if (optimization.type === 'replace-dep' && optimization.implementation.includes('npm')) {
          await execAsync(optimization.implementation);
        }

        // Run tests after each change
        if (input.preserveFunctionality) {
          const testResult = await execAsync('npm test').catch(e => e);
          if (testResult instanceof Error) {
            this.logger.warn('Tests failed after optimization, rolling back', { optimization });
            if (input.rollbackOnFailure) {
              await execAsync('git checkout .');
            }
          }
        }
      } catch (error: unknown) {
        this.logger.error('Failed to apply optimization', { optimization, error });
      }
    }
  }

  protected getExecutionMetadata(input: BundleOptimizationInput): Record<string, unknown> {
    return {
      targetSizeKB: input.targetSizeKB,
      strategy: input.strategy || 'balanced',
      preserveFunctionality: input.preserveFunctionality,
    };
  }
}

/**
 * BMAD Multi-Agent Fleet & Intelligent Routing
 * Coordinates specialized repair agents for different failure types
 */

import { TestRepairAgent } from '@povc/test-repair-agent';
import type { BaseAgent } from '@povc/agent-core';

export interface TestFailure {
  file: string;
  test: string;
  error: string;
  stack: string;
  type?: string;
  confidence?: number;
}

export interface RepairPlan {
  syntax: TestFailure[];
  assertion: TestFailure[];
  integration: TestFailure[];
  e2e: TestFailure[];
  manual: TestFailure[];
}

/**
 * Specialized agent configurations
 */
export const agentConfigs = {
  syntax: {
    specialty: 'syntax',
    maxConcurrency: 3,
    patterns: [
      /SyntaxError/,
      /Unexpected token/,
      /Missing semicolon/,
      /Unterminated/,
    ],
  },
  assertion: {
    specialty: 'assertion',
    maxConcurrency: 2,
    patterns: [
      /Expected .* to be/,
      /toBe|toEqual|toMatch/,
      /AssertionError/,
      /received.*expected/,
    ],
  },
  integration: {
    specialty: 'integration',
    maxConcurrency: 1,
    patterns: [
      /database|Database/,
      /redis|Redis/,
      /connection|Connection/,
      /timeout.*query/i,
    ],
  },
  e2e: {
    specialty: 'e2e',
    maxConcurrency: 2,
    patterns: [
      /\.e2e\.|\.spec\./,
      /playwright|Playwright/,
      /selector|locator/,
      /Element not found/,
    ],
  },
};

/**
 * Failure classifier using pattern matching and confidence scoring
 */
export class FailureClassifier {
  classify(failures: TestFailure[]): TestFailure[] {
    return failures.map(failure => {
      let type = 'unknown';
      let confidence = 0;

      // Check each agent's patterns
      for (const [agentType, config] of Object.entries(agentConfigs)) {
        const matchCount = config.patterns.filter(pattern => 
          pattern.test(failure.error) || pattern.test(failure.stack)
        ).length;

        const currentConfidence = matchCount / config.patterns.length;

        if (currentConfidence > confidence) {
          type = agentType;
          confidence = currentConfidence;
        }
      }

      // File-based classification overrides
      if (failure.file.includes('.e2e.')) {
        type = 'e2e';
        confidence = 0.9;
      } else if (failure.file.includes('integration')) {
        type = 'integration';
        confidence = 0.8;
      }

      return { ...failure, type, confidence };
    });
  }
}

/**
 * Intelligent repair router
 * Routes failures to appropriate specialized agents
 */
export class RepairRouter {
  private classifier = new FailureClassifier();

  async route(failures: TestFailure[]): Promise<RepairPlan> {
    const classified = this.classifier.classify(failures);

    return {
      syntax: classified.filter(f => 
        f.type === 'syntax' && (f.confidence ?? 0) > 0.7
      ),
      assertion: classified.filter(f => 
        f.type === 'assertion' && (f.confidence ?? 0) > 0.6
      ),
      integration: classified.filter(f => 
        f.type === 'integration' || 
        (/database|redis/i.test(f.stack) && (f.confidence ?? 0) > 0.5)
      ),
      e2e: classified.filter(f => 
        f.type === 'e2e' || 
        /\.e2e\./.test(f.file)
      ),
      manual: classified.filter(f => 
        f.type === 'unknown' || (f.confidence ?? 0) < 0.5
      ),
    };
  }
}

/**
 * Multi-agent fleet coordinator
 * Manages parallel execution of specialized repair agents
 */
export class MultiAgentFleet {
  private agents: Map<string, BaseAgent<unknown, unknown>> = new Map();
  private router = new RepairRouter();

  constructor() {
    this.initializeAgents();
  }

  private initializeAgents() {
    // Create specialized agents
    for (const [type, config] of Object.entries(agentConfigs)) {
      this.agents.set(type, new TestRepairAgent({
        name: `repair-agent-${type}`,
        maxRetries: 2,
        timeout: 60000,
        ...config,
      }));
    }
  }

  /**
   * Execute repairs using the multi-agent fleet
   */
  async executeRepairs(failures: TestFailure[]): Promise<{
    successful: number;
    failed: number;
    manual: number;
    repairs: unknown[];
  }> {
    // Route failures to appropriate agents
    const plan = await this.router.route(failures);

    // Execute repairs in parallel
    const repairPromises: Promise<{ type: string; result?: unknown; error?: unknown }>[] = [];

    for (const [type, agentFailures] of Object.entries(plan)) {
      if (type === 'manual' || agentFailures.length === 0) continue;

      const agent = this.agents.get(type);
      if (agent) {
        repairPromises.push(
          agent.execute({ failures: agentFailures })
            .then(result => ({ type, result }))
            .catch(error => ({ type, error }))
        );
      }
    }

    // Wait for all repairs to complete
    const results = await Promise.allSettled(repairPromises);

    // Aggregate results
    let successful = 0;
    let failed = 0;
    const repairs: unknown[] = [];

    for (const result of results) {
      if (result.status === 'fulfilled') {
        const { type, result: agentResult, error } = result.value;

        if (error) {
          failed += plan[type as keyof RepairPlan]?.length || 0;
          console.error(`Agent ${type} failed:`, error);
        } else if (agentResult?.success) {
          successful += agentResult.data?.repairs?.length || 0;
          repairs.push(...(agentResult.data?.repairs || []));
        } else {
          failed += plan[type as keyof RepairPlan]?.length || 0;
        }
      } else {
        failed++;
        console.error('Repair promise rejected:', result.reason);
      }
    }

    return {
      successful,
      failed,
      manual: plan.manual.length,
      repairs,
    };
  }

  /**
   * Get agent statistics
   */
  getStats() {
    const stats: Record<string, { name: string }> = {};

    for (const [type, agent] of this.agents) {
      stats[type] = {
        name: agent.name,
        // Add more stats as needed
      };
    }

    return stats;
  }
}

