export function makeAdminRouter(registry: Record<string, CircuitBreaker<any>>) {
  const r = Router();

  // AUTHZ REQUIRED INTEGRATION: ensure only admins can access
  r.get('/api/admin/circuit', (_req, res) => {
    const snapshot = Object.fromEntries(Object.entries(registry).map(([k, b]) => [k, b.getMetrics()]));
    res.json(snapshot);
  });

  r.post('/api/admin/circuit/:name/force', (req, res) => {
    const { name } = req.params;
    const breaker = registry[name];
    if (!breaker) return res.status(404).json({ error: 'not found' });
    const { state } = req.body as { state: CircuitState };
    // In a real system we would expose a method on CircuitBreaker to force state; omitted for safety.
    return res.status(501).json({ error: 'force state not implemented in demo – wire a safe hook if needed' });
  });

  return r;
}

import { Request, Response, NextFunction } from 'express';

export function degradedHeader(req: Request, res: Response, next: NextFunction) {
  const originalJson = res.json.bind(res);
  res.locals.degraded = false;
  res.setHeader('Server-Timing', 'cb;desc="circuit-breaker"');
  res.json = (body: any) => {
    if (res.locals.degraded) {
      res.setHeader('X-Circuit-State', 'DEGRADED');
    }
    return originalJson(body);
  };
  next();
}

export function isSystemError(error: unknown): boolean {
  if (!(error instanceof Error)) return false;
  const code = (error as any).code || '';
  const patterns = [/timeout/i, /ETIMEDOUT/, /ECONNRESET/, /ECONNREFUSED/, /EHOSTUNREACH/, /EPIPE/, /network/i];
  return patterns.some((p) => p.test(error.message) || p.test(code));
}

export function classifyError(err: unknown): 'system'|'logical' {
  return isSystemError(err) ? 'system' : 'logical';
}

export async function hedged<T>(
  primary: () => Promise<T>,
  secondary: () => Promise<T>,
  hedgeDelayMs: number
): Promise<T> {
  let timer: any;
  let secondaryStarted = false;
  const p1 = primary();
  const p2 = new Promise<T>((resolve, reject) => {
    timer = setTimeout(() => {
      secondaryStarted = true;
      secondary().then(resolve, reject);
    }, hedgeDelayMs);
  });
  try {
    return await Promise.race([p1, p2]);
  } finally {
    clearTimeout(timer);
    // Best-effort: let the slower request be GC'd; upstream clients should use abortable fetch to cancel.
  }
}

import type { CircuitBreakerOptions } from './types';
import { CircuitBreaker } from './CircuitBreaker';

export type Preset = 'cache' | 'http' | 'db';

export function createBreaker<T>(
  preset: Preset,
  deps: { operation: () => Promise<T>; fallback: () => Promise<T> },
  overrides: Partial<CircuitBreakerOptions> = {}
) {
  const base: Record<Preset, CircuitBreakerOptions> = {
    cache: {
      failureThreshold: 5, resetTimeout: 10_000, operationTimeout: 350,
      successesToClose: 2, maxHalfOpenRequests: 3, halfOpenRateLimit: { capacity: 5, refillPerSecond: 1 },
      adaptiveThreshold: { enabled: false, min: 3, max: 10, rate: 0.1 }
    },
    http: {
      failureThreshold: 3, resetTimeout: 5_000, operationTimeout: 500,
      successesToClose: 2, maxHalfOpenRequests: 2, halfOpenRateLimit: { capacity: 3, refillPerSecond: 0.5 },
      adaptiveThreshold: { enabled: false, min: 2, max: 8, rate: 0.1 }
    },
    db: {
      failureThreshold: 4, resetTimeout: 8_000, operationTimeout: 400,
      successesToClose: 2, maxHalfOpenRequests: 2, halfOpenRateLimit: { capacity: 3, refillPerSecond: 1 },
      adaptiveThreshold: { enabled: false, min: 3, max: 10, rate: 0.1 }
    }
  };
  const opts = { ...base[preset], ...overrides };
  return new CircuitBreaker(opts, deps.operation, deps.fallback);
}

