export function readinessHandler(breakers: Record<string, CircuitBreaker<any>>, maxOpenMs = 5 * 60 * 1000) {
  return (_req: Request, res: Response) => {
    const now = Date.now();
    const unhealthy = Object.entries(breakers).some(([_, b]) => {
      const m = b.getMetrics();
      if (m.state === 'OPEN' && m.currentBackoffMs > maxOpenMs) return true;
      return false;
    });
    if (unhealthy) return res.status(503).json({ status: 'unready' });
    return res.status(200).json({ status: 'ready' });
  };
}

export class Ring {
  private arr: number[];
  private idx = 0;
  private filled = false;
  constructor(private size: number) {
    this.arr = new Array(size).fill(0);
  }
  push(v: number) {
    this.arr[this.idx] = v;
    this.idx = (this.idx + 1) % this.size;
    if (this.idx === 0) this.filled = true;
  }
  values(): number[] {
    return this.filled ? [...this.arr] : this.arr.slice(0, this.idx);
  }
}

type Inflight<T> = { promise: Promise<T>; count: number };

export class Singleflight {
  private map = new Map<string, Inflight<any>>();
  async do<T>(key: string, fn: () => Promise<T>): Promise<T> {
    const existing = this.map.get(key);
    if (existing) {
      existing.count += 1;
      try { return await existing.promise; } finally { existing.count -= 1; if (existing.count === 0) this.map.delete(key); }
    }
    const entry: Inflight<T> = { promise: fn(), count: 1 };
    this.map.set(key, entry);
    try { return await entry.promise; } finally { entry.count -= 1; if (entry.count === 0) this.map.delete(key); }
  }
}

export class TokenBucket {
  private tokens: number;
  private lastRefill: number;
  constructor(private capacity: number, private refillRate: number) {
    this.tokens = capacity;
    this.lastRefill = Date.now();
  }
  tryConsume(): boolean {
    this.refill();
    if (this.tokens >= 1) {
      this.tokens -= 1;
      return true;
    }
    return false;
  }
  reset() {
    this.tokens = this.capacity;
    this.lastRefill = Date.now();
  }
  private refill() {
    const now = Date.now();
    const elapsed = (now - this.lastRefill) / 1000;
    this.tokens = Math.min(this.capacity, this.tokens + elapsed * this.refillRate);
    this.lastRefill = now;
  }
}

