/**
 * Resilient Cache System with Graceful Redis Fallback
 * Eliminates Redis connection failures in development
 */

export interface Cache {
  get(_key: string): Promise<string | null>;
  set(_key: string, value: string, ttlSeconds?: number): Promise<void>;
  del(_key: string): Promise<void>;
  close(): Promise<void>;
}

// Use the bounded memory cache implementation
import { BoundedMemoryCache } from './memory.js';

class RedisCache implements Cache {
  constructor(private redis: any) {}

  async get(key: string): Promise<string | null> {
    return (await this.redis['get'](key)) ?? null;
  }

  async set(key: string, value: string, ttlSeconds?: number): Promise<void> {
    if (ttlSeconds) {
      await this.redis.setex(key, ttlSeconds, value);
    } else {
      await this.redis['set'](key, value);
    }
  }

  async del(key: string): Promise<void> {
    await this.redis['del'](key);
  }

  async close(): Promise<void> {
    await this.redis['quit']();
  }
}

let lastRedisWarning = 0;
const REDIS_WARNING_THROTTLE = 60000; // 1 minute

function throttledWarn(message: string) {
  const now = Date.now();
  if (now - lastRedisWarning > REDIS_WARNING_THROTTLE) {
    console.warn(`[cache] ${message}`);
    lastRedisWarning = now;
  }
}

export async function buildCache(): Promise<Cache> {
  const url = process.env['REDIS_URL'];

  // Explicit memory cache mode
  if (!url || url.startsWith('memory://')) {
    console.log('[cache] Using bounded in-memory cache (development mode)');
    return new BoundedMemoryCache();
  }

  try {
    const { default: IORedis } = await import('ioredis');
    const redis = new IORedis(url, { 
      lazyConnect: true, 
      maxRetriesPerRequest: 1,
      retryDelayOnFailover: 100,
      connectTimeout: 800
    });

    // Test Redis availability with timeout
    await Promise.race([
      redis.connect(),
      new Promise((_: any, reject: any) => 
        setTimeout(() => reject(new Error('Redis connection timeout')), 800)
      )
    ]);

    // Verify with ping
    await Promise.race([
      redis['ping'](),
      new Promise((_: any, reject: any) => 
        setTimeout(() => reject(new Error('Redis ping timeout')), 500)
      )
    ]);

    console.log('[cache] Connected to Redis successfully');

    // Handle Redis errors gracefully in production
    redis['on']('error', (err: Error) => {
      throttledWarn(`Redis error: ${err.message}`);
    });

    redis['on']('reconnecting', () => {
      throttledWarn('Redis reconnecting...');
    });

    return new RedisCache(redis);

  } catch (error) {
    throttledWarn(`Redis unavailable, falling back to bounded memory cache: ${(error as Error).message}`);
    return new BoundedMemoryCache();
  }
}

// Global cache instance
let cacheInstance: Cache | null = null;

export async function getCache(): Promise<Cache> {
  if (!cacheInstance) {
    cacheInstance = await buildCache();
  }
  return cacheInstance;
}

export async function closeCache(): Promise<void> {
  if (cacheInstance) {
    await cacheInstance.close();
    cacheInstance = null;
  }
}






/**
 * Bounded Memory Cache with LRU Eviction and TTL Enforcement
 * Prevents memory exhaustion and provides observability
 */

import type { Cache } from './index.js';

interface CacheEntry {
  value: string;
  expires: number;
}

interface CacheMetrics {
  hits: number;
  misses: number;
  sets: number;
  deletes: number;
  evictions: number;
  size: number;
  maxSize: number;
}

export class BoundedMemoryCache implements Cache {
  private data = new Map<string, CacheEntry>();
  private readonly maxSize: number;
  private readonly defaultTTL: number;
  private cleanupInterval: NodeJS.Timeout;
  private metrics: CacheMetrics;

  constructor(options: { maxSize?: number; defaultTTL?: number; cleanupInterval?: number } = {}) {
    this.maxSize = options.maxSize ?? Number(process.env['CACHE_MAX_KEYS'] ?? 5000);
    this.defaultTTL = options.defaultTTL ?? 300; // 5 minutes default

    this.metrics = {
      hits: 0,
      misses: 0,
      sets: 0,
      deletes: 0,
      evictions: 0,
      size: 0,
      maxSize: this.maxSize
    };

    // Clean up expired entries periodically
    const interval = options.cleanupInterval ?? 60000; // 1 minute
    this.cleanupInterval = setInterval(() => this.cleanup(), interval);

    console.log(`[cache] Bounded memory cache initialized (max: ${this.maxSize} keys, TTL: ${this.defaultTTL}s)`);
  }

  async get(key: string): Promise<string | null> {
    const entry = this.data['get'](key);

    if (!entry) {
      this.metrics.misses++;
      return null;
    }

    // Check expiration
    if (entry.expires && Date.now() > entry.expires) {
      this.data.delete(key);
      this.metrics.misses++;
      this.updateSize();
      return null;
    }

    // LRU: Move to end (most recently used)
    this.data.delete(key);
    this.data['set'](key, entry);

    this.metrics.hits++;
    return entry.value;
  }

  async set(key: string, value: string, ttlSeconds: number = this.defaultTTL): Promise<void> {
    const expires = Date.now() + (ttlSeconds * 1000);

    // Evict LRU entry if at capacity
    if (this.data.size >= this.maxSize && !this.data.has(key)) {
      const firstKey = this.data.keys().next().value;
      if (firstKey) {
        this.data.delete(firstKey);
        this.metrics.evictions++;
      }
    }

    this.data['set'](key, { value, expires });
    this.metrics.sets++;
    this.updateSize();
  }

  async del(key: string): Promise<void> {
    const deleted = this.data.delete(key);
    if (deleted) {
      this.metrics.deletes++;
      this.updateSize();
    }
  }

  async close(): Promise<void> {
    clearInterval(this.cleanupInterval);
    this.data.clear();
    this.updateSize();
    console.log('[cache] Memory cache closed');
  }

  // Observability
  getMetrics(): CacheMetrics {
    return { ...this.metrics };
  }

  getHitRate(): number {
    const total = this.metrics.hits + this.metrics.misses;
    return total > 0 ? this.metrics.hits / total : 0;
  }

  // Cleanup expired entries
  private cleanup(): void {
    const before = this.data.size;
    const now = Date.now();

    for (const [key, entry] of this.data.entries()) {
      if (entry.expires && now > entry.expires) {
        this.data.delete(key);
      }
    }

    const cleaned = before - this.data.size;
    if (cleaned > 0) {
      this.updateSize();
      console.log(`[cache] Cleaned ${cleaned} expired entries (${this.data.size}/${this.maxSize} remaining)`);
    }
  }

  private updateSize(): void {
    this.metrics.size = this.data.size;
  }

  // Health check for monitoring
  isHealthy(): boolean {
    return this.data.size < this.maxSize * 0.9; // Warn at 90% capacity
  }

  // Emit metrics for Prometheus (if available)
  emitMetrics(): void {
    try {
      // This could be wired to prom-client if available
      console.log(`[cache] Metrics - Hits: ${this.metrics.hits}, Misses: ${this.metrics.misses}, Hit Rate: ${(this.getHitRate() * 100).toFixed(1)}%, Size: ${this.metrics.size}/${this.maxSize}`);
    } catch (error) {
      // Silently ignore if metrics collection fails
    }
  }
}

