}

export class FeatureFlaggedReserveEngine implements ReserveEnginePort {
  private metrics: EngineMetrics = {
    totalRequests: 0,
    mlRequests: 0,
    rulesRequests: 0,
    hybridRequests: 0,
    fallbackCount: 0,
    avgLatencyMs: 0,
    errorRate: 0,
  };

  constructor(
    private deterministicEngine: DeterministicReserveEngine,
    private constrainedEngine: ConstrainedReserveEngine,
    private mlClient: MlClient,
    private config: FeatureFlagConfig
  ) {}

  async compute(
    company: PortfolioCompany, 
    market: MarketConditions, 
    opts: ReserveEngineOptions = {}
  ): Promise<ReserveDecision> {
    const startTime = Date.now();
    const requestId = opts.requestId ?? nanoid();

    this.metrics.totalRequests++;

    // Determine engine mode based on feature flags and A/B testing
    const engineMode = this.determineEngineMode(company, opts);

    let decision: ReserveDecision;
    let fallbackUsed = false;

    try {
      switch (engineMode) {
        case 'ml':
          decision = await this.runMlEngine(company, market, opts);
          this.metrics.mlRequests++;
          break;

        case 'hybrid':
          decision = await this.runHybridEngine(company, market, opts);
          this.metrics.hybridRequests++;
          break;

        case 'rules':
        default:
          decision = await this.runRulesEngine(company, market, opts);
          this.metrics.rulesRequests++;
          break;
      }
    } catch (error) {
      logger.warn({
        companyId: company.id,
        engineMode,
        error: error instanceof Error ? error.message : String(error),
      }, 'Primary engine failed, falling back to rules');

      if (this.config.fallbackOnError) {
        decision = await this.runRulesEngine(company, market, opts);
        fallbackUsed = true;
        this.metrics.fallbackCount++;
      } else {
        throw error;
      }
    }

    // Update decision metadata
    decision.latencyMs = Date.now() - startTime;
    decision.metadata = {
      ...decision.metadata,
      requestId,
      engineMode,
      fallbackUsed,
      abTestBucket: this.getABTestBucket(company.id),
    };

    // Log decision to database if enabled
    if (this.config.logAllDecisions) {
      await this.logDecision(company, market, decision, opts).catch(error => {
        logger.error({ 
          companyId: company.id, 
          error: error instanceof Error ? error.message : String(error) 
        }, 'Failed to log reserve decision');
      });
    }

    // Update performance metrics
    this.updateMetrics(decision.latencyMs!, fallbackUsed ? 1 : 0);

    // Record performance monitoring
    // TODO: Wire up performance monitoring when instrumentation is configured
    // if (performanceMonitor) {
    //   performanceMonitor.recordCalculationPerformance(
    //     decision.latencyMs!,
    //     1, // company count
    //     !fallbackUsed
    //   );
    // }

    return decision;
  }

  private determineEngineMode(company: PortfolioCompany, opts: ReserveEngineOptions): 'ml' | 'rules' | 'hybrid' {
    // Check if ML is disabled globally
    if (!this.config.useMl) return 'rules';

    // Check explicit mode override in options
    if (opts.flags?.['engineMode']) {
      return opts.flags['engineMode'] as 'ml' | 'rules' | 'hybrid';
    }

    // A/B testing logic
    if (this.config.enableABTest) {
      const bucket = this.getABTestBucket(company.id);
      if (bucket > this.config.abTestPercentage) {
        return 'rules';
      }
    }

    return this.config.mode;
  }

  private getABTestBucket(companyId: string): number {
    // Simple hash-based bucketing for consistent A/B assignment
    let hash = 0;
    for (let i = 0; i < companyId.length; i++) {
      const char = companyId.charCodeAt(i);
      hash = ((hash << 5) - hash) + char;
      hash = hash & hash; // Convert to 32-bit integer
    }
    return Math.abs(hash) % 100;
  }

  private async runMlEngine(
    company: PortfolioCompany, 
    market: MarketConditions, 
    opts: ReserveEngineOptions
  ): Promise<ReserveDecision> {
    const decision = await this.mlClient.predict(company, market, opts);

    // Enhance decision with additional context
    decision.prediction.notes = [
      ...(decision.prediction.notes || []),
      `ML prediction based on ${decision.engineVersion}`,
      `Market score: ${market.marketScore?.toFixed(3) || 'N/A'}`,
    ];

    return decision;
  }

  private async runRulesEngine(
    company: PortfolioCompany, 
    market: MarketConditions, 
    opts: ReserveEngineOptions
  ): Promise<ReserveDecision> {
    // Convert to format expected by existing engines
    const reserveInput = this.convertToReserveInput(company, market);

    // Use DeterministicReserveEngine for sophisticated calculations
    const result = await this.deterministicEngine.calculateOptimalReserveAllocation(reserveInput);

    // Convert back to our standardized format
    const decision: ReserveDecision = {
      prediction: {
        recommendedReserve: result.inputSummary.totalAllocated,
        notes: [
          'Rules-based allocation using deterministic engine',
          `Allocation efficiency: ${(result.inputSummary?.allocationEfficiency || 0).toFixed(1)}%`,
        ],
        confidence: {
          low: result.inputSummary.totalAllocated * 0.9,
          high: result.inputSummary.totalAllocated * 1.1,
          level: 0.9,
        },
      },
      explanation: {
        method: 'rules',
        details: {
          allocationLogic: 'Deterministic allocation based on company metrics',
          riskFactors: result.riskAnalysis?.keyRiskFactors || [],
          stagePolicies: 'Stage-based allocation policies applied',
        },
        rulesFired: result.riskAnalysis?.riskMitigationActions || [],
      },
      engineType: 'rules',
      engineVersion: 'deterministic-1.0',
    };

    return decision;
  }

  private async runHybridEngine(
    company: PortfolioCompany, 
    market: MarketConditions, 
    opts: ReserveEngineOptions
  ): Promise<ReserveDecision> {
    // Run both engines in parallel
    const [rulesDecision, mlDecision] = await Promise.allSettled([
      this.runRulesEngine(company, market, opts),
      this.runMlEngine(company, market, opts),
    ]);

    // Handle engine results
    const rules = rulesDecision.status === 'fulfilled' ? rulesDecision.value : null;
    const ml = mlDecision.status === 'fulfilled' ? mlDecision.value : null;

    if (!rules && !ml) {
      throw new Error('Both rules and ML engines failed');
    }

    if (!ml) {
      return { ...rules!, engineType: 'hybrid', engineVersion: 'hybrid-rules-fallback-v1' };
    }

    if (!rules) {
      return { ...ml, engineType: 'hybrid', engineVersion: 'hybrid-ml-only-v1' };
    }

    // Combine predictions using weighted average
    const mlWeight = this.config.mlWeight;
    const rulesWeight = 1 - mlWeight;

    const combinedReserve = 
      (ml.prediction.recommendedReserve * mlWeight) + 
      (rules.prediction.recommendedReserve * rulesWeight);

    const combinedExplanation: PredictionExplanation = {
      method: 'hybrid',
      details: {
        mlPrediction: ml.prediction.recommendedReserve,
        rulesPrediction: rules.prediction.recommendedReserve,
        mlWeight,
        rulesWeight,
        combinedLogic: 'Weighted average of ML and rules predictions',
        mlExplanation: ml.explanation?.details,
        rulesExplanation: rules.explanation?.details,
      },
      topFactors: [
        ...(ml.explanation?.topFactors || []).map(f => ({ ...f, source: 'ml' as const })),
        ...(rules.explanation?.topFactors || []).map(f => ({ ...f, source: 'rules' as const })),
      ].slice(0, 8),
    };

    const combinedPerRound = ml.prediction.perRound ?? rules.prediction.perRound;
    const hybridDecision: ReserveDecision = {
      prediction: {
        recommendedReserve: Math.max(0, combinedReserve),
        ...(combinedPerRound !== undefined ? { perRound: combinedPerRound } : {}),
        confidence: {
          low: Math.min(
            ml.prediction.confidence?.low || combinedReserve,
            rules.prediction.confidence?.low || combinedReserve
          ),
          high: Math.max(
            ml.prediction.confidence?.high || combinedReserve,
            rules.prediction.confidence?.high || combinedReserve
          ),
          level: 0.8,
        },
        notes: [
          `Hybrid prediction: ${(mlWeight * 100).toFixed(0)}% ML, ${(rulesWeight * 100).toFixed(0)}% Rules`,
          `ML: ${ml.prediction.recommendedReserve.toLocaleString()}`,
          `Rules: ${rules.prediction.recommendedReserve.toLocaleString()}`,
          ...ml.prediction.notes || [],
          ...rules.prediction.notes || [],
        ],
      },
      explanation: combinedExplanation,
      engineType: 'hybrid',
      engineVersion: `hybrid-v1-ml${mlWeight}-rules${rulesWeight}`,
    };

    return hybridDecision;
  }

  private convertToReserveInput(company: PortfolioCompany, market: MarketConditions): any {
    // Convert our standardized format to what DeterministicReserveEngine expects
    return {
      portfolio: [company],
      availableReserves: company.invested * 2, // Example: 2x initial investment
      totalFundSize: company.invested * 10, // Example: company is 10% of fund
      marketConditions: market,
      scenarioType: 'base' as const,
      constraints: {
        maxPerCompany: company.invested * 3,
        maxPerStage: company.invested * 5,
        minCheck: 50000,
      },
    };
  }

  private async logDecision(
    company: PortfolioCompany,
    market: MarketConditions,
    decision: ReserveDecision,
    opts: ReserveEngineOptions
  ): Promise<void> {
    // Convert to date strings for the date columns
    const periodStartDate = opts.periodStart 
      ? new Date(opts.periodStart) 
      : new Date(market.asOfDate);
    const periodEndDate = opts.periodEnd 
      ? new Date(opts.periodEnd) 
      : new Date(market.asOfDate);

    const insertData = {
      fundId: company.fundId,
      companyId: company.id,
      decisionTs: new Date(),
      periodStart: periodStartDate.toISOString().split('T')[0]!, // date type expects YYYY-MM-DD
      periodEnd: periodEndDate.toISOString().split('T')[0]!, // date type expects YYYY-MM-DD
      engineType: decision.engineType,
      engineVersion: decision.engineVersion,
      requestId: opts.requestId || null,
      featureFlags: {
        ...opts.flags,
        useMl: this.config.useMl,
        mode: this.config.mode,
        mlWeight: this.config.mlWeight,
      },
      inputs: { company, market, opts },
      prediction: decision.prediction,
      explanation: decision.explanation || null,
      latencyMs: decision.latencyMs || null,
      userId: opts.userId || null,
    };

    await db.insert(reserveDecisions).values(insertData);
  }

  private updateMetrics(latencyMs: number, _errors: number): void {
    // Update rolling average latency
    const totalLatency = this.metrics.avgLatencyMs * (this.metrics.totalRequests - 1) + latencyMs;
    this.metrics.avgLatencyMs = totalLatency / this.metrics.totalRequests;

    // Update error rate (simplified)
    this.metrics.errorRate = (this.metrics.fallbackCount / this.metrics.totalRequests) * 100;
  }

  public getMetrics(): EngineMetrics {
    return { ...this.metrics };
  }

  public resetMetrics(): void {
    this.metrics = {
      totalRequests: 0,
      mlRequests: 0,
      rulesRequests: 0,
      hybridRequests: 0,
      fallbackCount: 0,
      avgLatencyMs: 0,
      errorRate: 0,
    };
  }
}

/**
 * ML Reserve Service Client
 * HTTP client for machine learning reserve prediction service
 */

import fetch, { AbortError } from 'node-fetch';
import type { PortfolioCompany, MarketConditions, ReserveDecision, ReserveEngineOptions, ReservePrediction } from './ports.js';
import { logger } from '../../lib/logger.js';

export interface MLServiceConfig {
  baseUrl: string;
  timeoutMs: number;
  retries: number;
  backoffMs: number;
}

export interface MLTrainingRow {
  company: PortfolioCompany;
  market: MarketConditions;
  realizedReserveUsed: number;
  actualOutcome?: 'success' | 'failure' | 'partial';
}

export interface MLTrainingRequest {
  rows: MLTrainingRow[];
  modelVersion?: string;
  hyperparameters?: Record<string, unknown>;
}

export interface MLPredictRequest {
  company: PortfolioCompany;
  market: MarketConditions;
  explain: boolean;
  confidenceLevel?: number;
}

export class MlClient {
  private config: MLServiceConfig;

  constructor(config: Partial<MLServiceConfig> = {}) {
    this.config = {
      baseUrl: process.env['ML_RESERVE_URL'] || 'http://localhost:8088',
      timeoutMs: parseInt(process.env['ML_TIMEOUT_MS'] || '1200'),
      retries: 2,
      backoffMs: 100,
      ...config,
    };
  }

  async healthCheck(): Promise<{ status: string; modelLoaded: boolean }> {
    try {
      const res = await this.fetchWithTimeout('/health', { method: 'GET' });
      if (!res.ok) throw new Error(`Health check failed: ${res.status}`);
      return await res["json"]() as { status: string; modelLoaded: boolean };
    } catch (error) {
      logger.error({ error: error instanceof Error ? error.message : String(error) }, 'ML service health check failed');
      throw error;
    }
  }

  async trainModel(request: MLTrainingRequest): Promise<{ modelVersion: string; rows: number }> {
    const startTime = Date.now();

    try {
      const res = await this.fetchWithTimeout('/train', {
        method: 'POST',
        headers: { 'content-type': 'application/json' },
        body: JSON.stringify(request),
      });

      if (!res.ok) {
        throw new Error(`Training failed: ${res.status} ${res.statusText}`);
      }

      const result = await res["json"]() as { modelVersion: string; rows: number };

      logger.info({
        modelVersion: result.modelVersion,
        trainingRows: result.rows,
        durationMs: Date.now() - startTime,
      }, 'ML model training completed');

      return result;
    } catch (error) {
      logger.error({
        error: error instanceof Error ? error.message : String(error),
        durationMs: Date.now() - startTime,
        trainingRows: request.rows.length,
      }, 'ML model training failed');
      throw error;
    }
  }

  async predict(
    company: PortfolioCompany, 
    market: MarketConditions, 
    opts: ReserveEngineOptions = {}
  ): Promise<ReserveDecision> {
    const startTime = Date.now();
    const request: MLPredictRequest = {
      company,
      market,
      explain: opts.explainPrediction ?? true,
      confidenceLevel: opts.confidenceLevel ?? 0.8,
    };

    try {
      const res = await this.fetchWithRetry('/predict', {
        method: 'POST',
        headers: { 
          'content-type': 'application/json',
          'x-request-id': opts.requestId || '',
        },
        body: JSON.stringify(request),
      });

      if (!res.ok) {
        throw new Error(`ML prediction failed: ${res.status} ${res.statusText}`);
      }

      const body = await res["json"]() as {
        modelVersion: string;
        prediction: {
          recommendedReserve: number;
          perRound?: Record<string, number>;
          confidence?: { low: number; high: number };
          notes?: string[];
        };
        explanation?: {
          method: string;
          details: Record<string, unknown>;
        };
        latencyMs?: number;
      };

      // Build prediction with conditional optional properties
      const prediction: ReservePrediction = {
        recommendedReserve: Math.max(0, body.prediction.recommendedReserve),
        notes: body.prediction.notes || [],
      };
      if (body.prediction.perRound !== undefined) {
        prediction.perRound = body.prediction.perRound;
      }
      if (body.prediction.confidence !== undefined) {
        prediction.confidence = body.prediction.confidence;
      }

      // Build decision with conditional explanation
      const decision: ReserveDecision = {
        prediction,
        engineType: 'ml',
        engineVersion: body.modelVersion,
        latencyMs: body.latencyMs ?? (Date.now() - startTime),
      };
      if (body.explanation !== undefined) {
        decision.explanation = {
          method: body.explanation.method as 'rules' | 'shap' | 'permutation' | 'feature_importance' | 'hybrid',
          details: body.explanation.details,
          topFactors: this.extractTopFactors(body.explanation.details),
        };
      }

      logger.debug({
        companyId: company.id,
        recommendedReserve: decision.prediction.recommendedReserve,
        latencyMs: decision.latencyMs,
        modelVersion: decision.engineVersion,
      }, 'ML prediction completed');

      return decision;
    } catch (error) {
      logger.error({
        companyId: company.id,
        error: error instanceof Error ? error.message : String(error),
        latencyMs: Date.now() - startTime,
      }, 'ML prediction failed');
      throw error;
    }
  }

  private async fetchWithTimeout(path: string, options: any): Promise<any> {
    const controller = new AbortController();
    const timeout = setTimeout(() => controller.abort(), this.config.timeoutMs);

    try {
      const res = await fetch(`${this.config.baseUrl}${path}`, {
        ...options,
        signal: controller.signal,
      });
      return res;
    } catch (error) {
      if (error instanceof AbortError) {
        throw new Error(`ML service timeout after ${this.config.timeoutMs}ms`);
      }
      throw error;
    } finally {
      clearTimeout(timeout);
    }
  }

  private async fetchWithRetry(path: string, options: any): Promise<Response> {
    let lastError: Error | null = null;

    for (let attempt = 0; attempt <= this.config.retries; attempt++) {
      try {
        return await this.fetchWithTimeout(path, options);
      } catch (error) {
        lastError = error instanceof Error ? error : new Error(String(error));

        if (attempt < this.config.retries) {
          const delay = this.config.backoffMs * Math.pow(2, attempt);
          await new Promise(resolve => setTimeout(resolve, delay));
          logger.warn({ 
            attempt: attempt + 1, 
            maxRetries: this.config.retries,
            delayMs: delay,
            error: lastError.message 
          }, 'Retrying ML service request');
        }
      }
    }

    throw lastError;
  }

  private extractTopFactors(details: Record<string, unknown>): Array<{ factor: string; importance: number; direction: 'positive' | 'negative' }> {
    return Object.entries(details)
      .filter(([_, value]) => typeof value === 'number')
      .map(([factor, importance]) => ({
        factor,
        importance: Math.abs(importance as number),
        direction: ((importance as number) >= 0 ? 'positive' : 'negative') as 'positive' | 'negative',
      }))
      .sort((a: any, b: any) => b.importance - a.importance)
      .slice(0, 5); // Top 5 factors
  }
}

