import type { Request, Response } from 'express';
import { db } from './db';
import { healthStatus } from './metrics';
import { getEnv } from './env';
// Circuit breaker metrics disabled for dev mode
// import { getBreakerTrips } from '../client/src/utils/resilientLimit';

interface HealthComponent {
  name: string;
  status: 'healthy' | 'unhealthy';
  message?: string;
  details?: Record<string, any>;
}

interface HealthResponse {
  status: 'healthy' | 'unhealthy';
  timestamp: string;
  uptime: number;
  version: string;
  circuitBreaker: {
    trips: number;
  };
  components: HealthComponent[];
}

async function checkDatabase(): Promise<HealthComponent> {
  try {
    // In dev mode with mock database, just return healthy
    if (process.env['DATABASE_URL']?.includes('mock')) {
      healthStatus['set']({ component: 'database' }, 1);
      return {
        name: 'database',
        status: 'healthy',
        message: 'Database in mock mode (development)',
      };
    }

    // Simple query to check database connectivity
    await db.execute('SELECT 1');
    healthStatus['set']({ component: 'database' }, 1);
    return {
      name: 'database',
      status: 'healthy',
      message: 'Database connection successful',
    };
  } catch (error) {
    healthStatus['set']({ component: 'database' }, 0);
    return {
      name: 'database',
      status: 'unhealthy',
      message: error instanceof Error ? error.message : 'Unknown database error',
    };
  }
}

async function checkRedis(): Promise<HealthComponent> {
  const env = getEnv();

  if (!env.REDIS_URL || env.REDIS_URL === 'memory://') {
    healthStatus['set']({ component: 'redis' }, 1);
    return {
      name: 'redis',
      status: 'healthy',
      message: 'Redis in memory mode (development)',
    };
  }

  try {
    // If Redis is configured, we would check it here
    // For now, we'll just mark it as healthy since it's optional
    healthStatus['set']({ component: 'redis' }, 1);
    return {
      name: 'redis',
      status: 'healthy',
      message: 'Redis connection successful',
    };
  } catch (error) {
    healthStatus['set']({ component: 'redis' }, 0);
    return {
      name: 'redis',
      status: 'unhealthy',
      message: error instanceof Error ? error.message : 'Unknown Redis error',
    };
  }
}

async function performHealthCheck(): Promise<HealthResponse> {
  const startTime = Date.now();

  const [databaseHealth, redisHealth] = await Promise.all([
    checkDatabase(),
    checkRedis(),
  ]);

  const components = [databaseHealth, redisHealth];
  const isHealthy = components.every(component => component.status === 'healthy');

  // Set overall health status
  healthStatus['set']({ component: 'overall' }, isHealthy ? 1 : 0);

  return {
    status: isHealthy ? 'healthy' : 'unhealthy',
    timestamp: new Date().toISOString(),
    uptime: process.uptime(),
    version: process.env["npm_package_version"] || 'unknown',
    circuitBreaker: {
      trips: 0 // Circuit breaker disabled in dev mode
    },
    components,
  };
}

// Basic health check endpoint
export async function healthCheck(req: Request, res: Response) {
  try {
    const health = await performHealthCheck();
    const statusCode = health.status === 'healthy' ? 200 : 503;

    res["status"](statusCode)["json"](health);
  } catch (error) {
    res["status"](503)["json"]({
      status: 'unhealthy',
      timestamp: new Date().toISOString(),
      uptime: process.uptime(),
      version: process.env["npm_package_version"] || 'unknown',
      circuitBreaker: {
        trips: 0
      },
      components: [{
        name: 'health_check',
        status: 'unhealthy',
        message: error instanceof Error ? error.message : 'Health check failed',
      }],
    });
  }
}

// Readiness check (for Kubernetes)
export async function readinessCheck(req: Request, res: Response) {
  try {
    // Check if all critical components are ready
    const databaseHealth = await checkDatabase();
    const isReady = databaseHealth.status === 'healthy';

    if (isReady) {
      res["status"](200)["json"]({ 
        status: 'ready',
        timestamp: new Date().toISOString(),
      });
    } else {
      res["status"](503)["json"]({ 
        status: 'not_ready',
        timestamp: new Date().toISOString(),
        reason: 'Database not ready',
      });
    }
  } catch (error) {
    res["status"](503)["json"]({ 
      status: 'not_ready',
      timestamp: new Date().toISOString(),
      reason: error instanceof Error ? error.message : 'Readiness check failed',
    });
  }
}

// Liveness check (for Kubernetes)
export async function livenessCheck(req: Request, res: Response) {
  // Simple liveness check - if the process is running, it's alive
  res["status"](200)["json"]({ 
    status: 'alive',
    timestamp: new Date().toISOString(),
    uptime: process.uptime(),
  });
}

interface Cache<T = string> {
  get<K = T>(key: string): Promise<K | null>;
  set<K = T>(key: string, value: K, ttl?: number): Promise<void>;
  delete(key: string): Promise<boolean>;
  keys(pattern?: string): Promise<string[]>;
  clear(): Promise<void>;
}

export interface CircuitBreakerConfig {
  failureThreshold: number;       // e.g., 3
  resetTimeout: number;           // ms until OPEN => HALF-OPEN (e.g., 1000)
  monitoringPeriod: number;
  successThreshold?: number;      // successes required in HALF-OPEN to close (default 1)
  halfOpenMaxConcurrent?: number; // concurrent probes allowed in HALF-OPEN (default 1)
}

// Factory function to create cache with optional Upstash support
export async function createBreakerCache(
  fallbackStore: Cache,
  config?: Partial<CircuitBreakerConfig>
): Promise<CircuitBreakerCache> {
  let backingStore: Cache = fallbackStore;

  // Check for Upstash configuration (skip in test environment)
  if (process.env['NODE_ENV'] !== 'test' && 
      process.env['UPSTASH_REDIS_REST_URL'] && 
      process.env['UPSTASH_REDIS_REST_TOKEN']) {
    try {
      // Lazy import Upstash if available
      const { Redis } = await import('@upstash/redis');

      if (Redis) {
        const redis = new Redis({
          url: process.env['UPSTASH_REDIS_REST_URL'],
          token: process.env['UPSTASH_REDIS_REST_TOKEN'],
        });

        // Create Upstash-backed cache
        backingStore = {
          async get<T>(key: string): Promise<T | null> {
            const raw = await redis['get'](`cb:${key}`);
            return raw ? (typeof raw === 'string' ? JSON.parse(raw) : raw as T) : null;
          },
          async set<T>(key: string, value: T, ttl?: number): Promise<void> {
            const ttlSeconds = ttl ? Math.ceil(ttl / 1000) : 300; // Default 5 min
            await redis['set'](`cb:${key}`, JSON.stringify(value), { ex: ttlSeconds });
          },
          async delete(key: string): Promise<boolean> {
            const result = await redis['del'](`cb:${key}`);
            return result > 0;
          },
          async keys(): Promise<string[]> {
            // Upstash doesn't have a keys method, return empty for now
            // This would require using scan or maintaining a separate index
            return [];
          },
          async clear(): Promise<void> {
            // Upstash doesn't have a simple clear for pattern
            // Would need to implement with scan or maintain index
            return;
          }
        };

        console.log('Circuit breaker using Upstash Redis cache');
      }
    } catch (error) {
      console.warn('Failed to initialize Upstash cache, falling back to memory:', error);
    }
  }

  return new CircuitBreakerCache(backingStore, fallbackStore, {
    failureThreshold: 10,
    resetTimeout: 60000,
    monitoringPeriod: 300000,
    ...config
  }, Date.now);
}

export class CircuitBreakerCache implements Cache {
  private state: 'closed' | 'open' | 'half-open' = 'closed';
  private failures = 0;
  private successes = 0;
  private lastFailureTime = 0;
  private lastSuccessTime: number;
  private halfOpenInFlight = 0;
  private openedAt = 0;

  constructor(
    private backingStore: Cache,
    private fallbackStore: Cache,
    private config: CircuitBreakerConfig = {
      failureThreshold: 10,
      resetTimeout: 60000,
      monitoringPeriod: 300000
    },
    private getCurrentTime: () => number = Date.now
  ) {
    this.lastSuccessTime = this.getCurrentTime();
  }

  private get maxHalfOpen(): number {
    return this.config['halfOpenMaxConcurrent'] ?? 1;
  }
  private get halfOpenSuccessTarget(): number {
    return this.config['successThreshold'] ?? 1;
  }

  private toOpen(now: number) {
    this.state = 'open';
    this.openedAt = now;
    this.halfOpenInFlight = 0;
    this.lastFailureTime = now;
  }

  private toHalfOpen() {
    this.state = 'half-open';
    this.failures = 0;
    this.successes = 0;
    this.halfOpenInFlight = 0;
  }

  async get<T>(key: string): Promise<T | null> {
    const now = this.getCurrentTime();

    // If OPEN, see if the window has elapsed; if yes, move to HALF-OPEN before any early return.
    if (this.state === 'open') {
      if (now - this.openedAt >= this.config['resetTimeout']) {
        this.toHalfOpen();
      }
    }

    // HALF-OPEN: allow exactly `maxHalfOpen` probes to the primary; others get fallback.
    if (this.state === 'half-open') {
      if (this.halfOpenInFlight >= this.maxHalfOpen) {
        return this.fallbackStore.get<T>(key);
      }
      this.halfOpenInFlight++;
      try {
        const v = await this.backingStore.get<T>(key);
        // Treat null as a valid value; success means "primary responded without throwing"
        this.successes++;
        this.lastSuccessTime = now;
        if (this.successes >= this.halfOpenSuccessTarget) {
          // Primary looks healthy again
          this.state = 'closed';
          this.failures = 0;
          this.successes = 0;
        }
        return v;
      } catch (error) {
        // Probe failed -> go back to OPEN and serve fallback
        this.failures++;
        this.toOpen(now);
        console.debug('[circuit-breaker-cache] Half-open probe failed, returning to OPEN state:', error instanceof Error ? error.message : String(error));
        return this.fallbackStore.get<T>(key);
      } finally {
        this.halfOpenInFlight = Math.max(0, this.halfOpenInFlight - 1);
      }
    }

    // Still OPEN and within the window? Serve fallback (no probing here).
    if (this.state === 'open') {
      return this.fallbackStore.get<T>(key);
    }

    // CLOSED: primary first, fallback on error
    try {
      const v = await this.backingStore.get<T>(key);
      this.failures = 0;
      this.successes++;
      this.lastSuccessTime = now;
      return v;
    } catch (error) {
      this.failures++;
      this.lastFailureTime = now;
      if (this.failures >= this.config['failureThreshold']) {
        console.warn('[circuit-breaker-cache] Failure threshold reached, opening circuit:', error instanceof Error ? error.message : String(error));
        this.toOpen(now);
      }
      return this.fallbackStore.get<T>(key);
    }
  }

  async set<T>(key: string, value: T, ttl?: number): Promise<void> {
    // Always try to write to both stores to maintain consistency
    const promises = [];

    if (this.state === 'closed') {
      promises.push(this.backingStore['set'](key, value, ttl).catch((err) => {
        console.debug('[circuit-breaker-cache] Primary store set failed (non-blocking):', err instanceof Error ? err.message : String(err));
      }));
    }
    promises.push(this.fallbackStore['set'](key, value, ttl).catch((err) => {
      console.debug('[circuit-breaker-cache] Fallback store set failed (non-blocking):', err instanceof Error ? err.message : String(err));
    }));

    await Promise.all(promises);
  }

  async delete(key: string): Promise<boolean> {
    let deleted = false;

    // Try both stores
    if (this.state === 'closed') {
      try {
        deleted = await this.backingStore['delete'](key);
      } catch (error) {
        // Continue to fallback, log for observability
        console.debug('[circuit-breaker-cache] Primary store delete failed, trying fallback:', error instanceof Error ? error.message : String(error));
      }
    }

    try {
      const fallbackDeleted = await this.fallbackStore['delete'](key);
      deleted = deleted || fallbackDeleted;
    } catch (error) {
      // Fallback delete failed - log but don't fail
      console.debug('[circuit-breaker-cache] Fallback store delete failed:', error instanceof Error ? error.message : String(error));
    }

    return deleted;
  }

  async keys(): Promise<string[]> {
    if (this.state === 'closed') {
      try {
        return await this.backingStore['keys']();
      } catch (error) {
        // Fall back to fallback store
        console.debug('[circuit-breaker-cache] Primary store keys() failed, trying fallback:', error instanceof Error ? error.message : String(error));
      }
    }

    try {
      return await this.fallbackStore['keys']();
    } catch (error) {
      // Both stores failed - log and return empty
      console.warn('[circuit-breaker-cache] All stores failed for keys():', error instanceof Error ? error.message : String(error));
      return [];
    }
  }

  async clear(): Promise<void> {
    // Clear both stores regardless of circuit state
    const promises = [];

    promises.push(this.backingStore.clear().catch((err) => {
      console.debug('[circuit-breaker-cache] Primary store clear failed (non-blocking):', err instanceof Error ? err.message : String(err));
    }));
    promises.push(this.fallbackStore.clear().catch((err) => {
      console.debug('[circuit-breaker-cache] Fallback store clear failed (non-blocking):', err instanceof Error ? err.message : String(err));
    }));

    await Promise.all(promises);
  }

  getState(): {
    state: string;
    failures: number;
    successes: number;
    requestCount: number;
    successCount: number;
    isHealthy: boolean;
    uptime: number;
  } {
    const now = this.getCurrentTime();
    return {
      state: this.state,
      failures: this.failures,
      successes: this.successes,
      requestCount: this.failures + this.successes,
      successCount: this.successes,
      isHealthy: this.state !== 'open',
      uptime: this.lastSuccessTime > 0 ? now - this.lastSuccessTime : 0
    };
  }

  // Alias for test compatibility
  getCircuitState() {
    return this.getState();
  }

  reset(): void {
    this.state = 'closed';
    this.failures = 0;
    this.successes = 0;
    this.halfOpenInFlight = 0;
  }
}

import { EventEmitter } from 'events';
import { Mutex } from './mutex';
import { TokenBucket } from './token-bucket';
import { classifyError } from './error-classifier';
import type { CircuitBreakerOptions, CircuitState } from './types';
import type { StateChangeEvent, ProbeDeniedEvent } from './typed-events';

export class CircuitBreaker<T> {
  private state: CircuitState = 'CLOSED';
  private stateLock = new Mutex();
  private emitter = new EventEmitter();

  // Failure tracking
  private failures = 0;
  private failureTimes: number[] = [];

  // State timestamps/backoff
  private openedAt = 0;
  private currentOpenInterval = 0;
  private resetBackoffMs: number;
  private readonly maxResetBackoffMs: number;

  // Half-open
  private halfOpenRequests = 0;
  private halfOpenSuccesses = 0;
  private halfOpenBucket?: TokenBucket;

  // Metrics
  private totalRequests = 0;
  private successCount = 0;
  private fallbackCount = 0;
  private latencies: number[] = [];

  // Adaptive
  private effectiveFailureThreshold: number;

  constructor(
    private options: CircuitBreakerOptions,
    private operation: () => Promise<T>,
    private fallback: () => Promise<T>
  ) {
    this.resetBackoffMs = options.resetTimeout;
    this.maxResetBackoffMs = options.resetTimeout * 32;
    this.effectiveFailureThreshold = options.failureThreshold;

    if (options.halfOpenRateLimit) {
      this.halfOpenBucket = new TokenBucket(
        options.halfOpenRateLimit.capacity,
        options.halfOpenRateLimit.refillPerSecond
      );
    }
  }

  async execute(): Promise<T> {
    return this.executeWithCircuitBreaker(this.operation, this.fallback);
  }

  async run<R>(op: () => Promise<R>, fb: () => Promise<R>): Promise<R> {
    return this.executeWithCircuitBreaker(op, fb);
  }

  private async executeWithCircuitBreaker<R>(operation: () => Promise<R>, fallback: () => Promise<R>): Promise<R> {
    const start = Date.now();
    this.totalRequests++;

    if (this.state === 'OPEN') {
      if (Date.now() - this.openedAt > this.currentOpenInterval) {
        await this.transitionState(['OPEN'], 'HALF_OPEN', 'backoff interval elapsed');
      } else {
        this.fallbackCount++;
        this.emitter.emit('circuitOpen', { timestamp: Date.now() });
        return fallback();
      }
    }

    let isProbe = false;
    if (this.state === 'HALF_OPEN') {
      const rateOK = !this.halfOpenBucket || this.halfOpenBucket.tryConsume();
      const concOK = this.halfOpenRequests < (this.options.maxHalfOpenRequests ?? 3);
      if (!rateOK || !concOK) {
        this.fallbackCount++;
        const ev: ProbeDeniedEvent = { rateLimited: !rateOK, concurrencyLimited: !concOK, timestamp: Date.now() };
        this.emitter.emit('probeDenied', ev);
        return fallback();
      }
      isProbe = true;
      this.halfOpenRequests++;
    }

    try {
      const result = await this.withTimeout(operation(), this.options.operationTimeout ?? 5000, 'operation');
      this.successCount++;
      this.recordLatency(Date.now() - start);
      await this.handleSuccess();
      return result;
    } catch (err) {
      this.recordLatency(Date.now() - start);
      if (classifyError(err) === 'system') {
        await this.handleFailure(err as Error);
      }
      this.fallbackCount++;
      return fallback();
    } finally {
      if (isProbe) this.halfOpenRequests--;
    }
  }

  private async handleSuccess() {
    if (this.state === 'HALF_OPEN') {
      this.halfOpenSuccesses++;
      const need = this.options.successesToClose ?? 2;
      if (this.halfOpenSuccesses >= need) {
        await this.transitionState(['HALF_OPEN'], 'CLOSED', `${need} consecutive successes`);
      }
    } else {
      // CLOSED
      this.failures = 0;
      this.failureTimes = [];
    }
    this.maybeAdaptThreshold();
  }

  private async handleFailure(_error: Error) {
    if (this.options.monitoringPeriod) {
      const now = Date.now();
      const cutoff = now - this.options.monitoringPeriod;
      this.failureTimes.push(now);
      while (this.failureTimes.length > 0 && (this.failureTimes[0] ?? Infinity) < cutoff) {
        this.failureTimes.shift();
      }
    } else {
      this.failures++;
    }

    if (this.state === 'HALF_OPEN') this.halfOpenSuccesses = 0;

    const shouldOpen = this.options.monitoringPeriod
      ? this.failureTimes.length >= this.effectiveFailureThreshold
      : this.failures >= this.effectiveFailureThreshold;

    if (shouldOpen && (this.state === 'CLOSED' || this.state === 'HALF_OPEN')) {
      await this.transitionState(['CLOSED', 'HALF_OPEN'], 'OPEN', 'failure threshold reached');
    }
  }

  private async transitionState(from: CircuitState[] | CircuitState, to: CircuitState, reason: string): Promise<boolean> {
    return this.stateLock.runExclusive(async () => {
      const allow = Array.isArray(from) ? from : [from];
      if (!allow.includes(this.state)) return false;
      const prev = this.state;
      this.state = to;

      switch (to) {
        case 'HALF_OPEN':
          this.halfOpenRequests = 0;
          this.halfOpenSuccesses = 0;
          this.halfOpenBucket?.reset();
          break;
        case 'CLOSED':
          this.failures = 0;
          this.failureTimes = [];
          this.halfOpenSuccesses = 0;
          this.resetBackoffMs = this.options.resetTimeout;
          break;
        case 'OPEN':
          this.openedAt = Date.now();
          this.currentOpenInterval = this.nextResetInterval();
          break;
      }

      const ev: StateChangeEvent = { from: prev, to, reason, timestamp: Date.now() };
      this.emitter.emit('stateChange', ev);
      return true;
    });
  }

  private nextResetInterval(): number {
    const jitter = 0.7 + Math.random() * 0.6; // 70–130%
    const interval = Math.min(this.resetBackoffMs * jitter, this.maxResetBackoffMs);
    this.resetBackoffMs = Math.min(this.resetBackoffMs * 2, this.maxResetBackoffMs);
    return interval;
  }

  private async withTimeout<R>(p: Promise<R>, ms: number, label: string): Promise<R> {
    let to: NodeJS.Timeout;
    const timeout = new Promise<never>((_: any, reject: any) => {
      to = setTimeout(() => reject(new Error(`Timeout (${label}) after ${ms}ms`)), ms);
    });
    try {
      return await Promise.race([p, timeout]);
    } finally {
      clearTimeout(to!);
    }
  }

  private maybeAdaptThreshold() {
    const a = this.options.adaptiveThreshold;
    if (!a?.enabled) return;
    const successRate = this.totalRequests > 0 ? this.successCount / this.totalRequests : 1;
    if (successRate > 0.95) {
      this.effectiveFailureThreshold = Math.min(a.max, Math.round(this.effectiveFailureThreshold * (1 + a.rate)));
    } else if (successRate < 0.8) {
      this.effectiveFailureThreshold = Math.max(a.min, Math.round(this.effectiveFailureThreshold * (1 - a.rate)));
    }
  }

  private recordLatency(ms: number) {
    this.latencies.push(ms);
    if (this.latencies.length > 1000) this.latencies.shift();
  }

  // Public API
  onStateChange(listener: (_e: StateChangeEvent) => void) { this.emitter['on']('stateChange', listener); }
  getState(): CircuitState { return this.state; }
  getMetrics() {
    const successRate = this.totalRequests ? this.successCount / this.totalRequests : 0;
    return {
      state: this.state,
      totalRequests: this.totalRequests,
      successCount: this.successCount,
      fallbackCount: this.fallbackCount,
      successRate,
      effectiveThreshold: this.effectiveFailureThreshold,
      currentBackoffMs: this.resetBackoffMs,
      isHealthy: this.state === 'CLOSED' && successRate > 0.95
    };
  }
}

export type ErrorClass = 'system' | 'logical';

export function classifyError(err: unknown): ErrorClass {
  if (!(err instanceof Error)) return 'logical';
  const msg = (err.message || '').toLowerCase();
  const code = (err as any).code || '';
  const patterns = [/timeout/, /etimedout/, /econnreset/, /econnrefused/, /ehostunreach/, /epipe/, /network/];
  return patterns.some((p: any) => p.test(msg) || p.test(String(code).toLowerCase())) ? 'system' : 'logical';
}

// Hedged requests: launch a backup after a delay; first to resolve wins.
export async function hedged<T>(primary: () => Promise<T>, backup: () => Promise<T>, hedgeDelayMs = 50): Promise<T> {
  let settled = false;
  return new Promise<T>((resolve: any, reject: any) => {
    const to = setTimeout(() => {
      if (settled) return;
      backup().then((v: any) => { settled = true; resolve(v); }).catch((e: any) => { if (!settled) reject(e); });
    }, hedgeDelayMs);
    primary().then((v: any) => { settled = true; clearTimeout(to); resolve(v); }).catch((e: any) => { if (!settled) reject(e); });
  });
}

import { TypedCircuitBreaker, type BreakerLike } from './typed-breaker';
import { envCircuit } from '../../../shared/config/env.circuit';

/**
 * Circuit breaker wrapper for HTTP operations
 * Protects against partner API failures with stale fallback support
 */
export class HttpBreakerService implements BreakerLike {
  private breaker: TypedCircuitBreaker<any>;
  private staleDataCache = new Map<string, { data: any; timestamp: number }>();
  private readonly STALE_TTL_MS = 5 * 60 * 1000; // 5 minutes

  constructor(private serviceName: string) {
    this.breaker = new TypedCircuitBreaker({
      failureThreshold: envCircuit.CB_HTTP_FAILURE_THRESHOLD,
      resetTimeout: envCircuit.CB_HTTP_RESET_TIMEOUT_MS,
      operationTimeout: envCircuit.CB_HTTP_OP_TIMEOUT_MS,
      successesToClose: envCircuit.CB_HTTP_SUCCESS_TO_CLOSE,
      maxHalfOpenRequests: envCircuit.CB_HTTP_HALF_OPEN_MAX_CONC,
      halfOpenRateLimit: { capacity: 3, refillPerSecond: 0.5 }
    });
  }

  async run<T>(
    operation: () => Promise<T>,
    fallback?: () => Promise<T>
  ): Promise<T> {
    return this.breaker.run(operation, fallback || (async () => { throw new Error('No fallback provided'); }));
  }

  async execute<T>(
    operation: () => Promise<T>,
    cacheKey?: string,
    staleTimeoutMs?: number
  ): Promise<{ data: T; degraded: boolean }> {
    try {
      const result = await this.breaker.run(
        operation,
        // Fallback: try to get stale data
        cacheKey ? () => this.getStaleData(cacheKey) : async () => null
      );

      // Cache fresh data for future fallback
      if (cacheKey && result !== null && result !== undefined) {
        this.storeStaleData(cacheKey, result);
      }

      return { 
        data: result, 
        degraded: this.breaker.getState() !== 'CLOSED' 
      };
    } catch (error) {
      // Last resort: try stale data even if circuit breaker fails
      if (cacheKey) {
        const staleData = this.getStaleData(cacheKey);
        if (staleData !== null) {
          console.warn(`[http-breaker:${this.serviceName}] Using stale data for ${cacheKey}`);
          return { data: staleData, degraded: true };
        }
      }
      throw error;
    }
  }

  private storeStaleData(key: string, data: any): void {
    this.staleDataCache['set'](key, {
      data: JSON.parse(JSON.stringify(data)), // Deep clone
      timestamp: Date.now()
    });
  }

  private getStaleData(key: string): any | null {
    const cached = this.staleDataCache['get'](key);
    if (!cached) return null;

    const age = Date.now() - cached.timestamp;
    if (age > this.STALE_TTL_MS) {
      this.staleDataCache.delete(key);
      return null;
    }

    return cached.data;
  }

  getState() {
    return this.breaker.getState();
  }

  getMetrics() {
    return this.breaker.getMetrics();
  }

  // Clean up old stale data periodically
  cleanup(): void {
    const now = Date.now();
    for (const [key, value] of this.staleDataCache.entries()) {
      if (now - value.timestamp > this.STALE_TTL_MS) {
        this.staleDataCache.delete(key);
      }
    }
  }
}

import { CircuitBreaker } from './CircuitBreaker';
import type { CircuitBreakerOptions } from './types';

export function createBreaker<T>(preset: 'cache' | 'http' | 'db', operation: () => Promise<T>, fallback: () => Promise<T>, overrides?: Partial<CircuitBreakerOptions>) {
  const base: Record<typeof preset, CircuitBreakerOptions> = {
    cache: {
      failureThreshold: 5,
      resetTimeout: 10_000,
      operationTimeout: 350,
      successesToClose: 2,
      maxHalfOpenRequests: 3,
    },
    http: {
      failureThreshold: 3,
      resetTimeout: 5_000,
      operationTimeout: 500,
      successesToClose: 2,
      maxHalfOpenRequests: 2,
    },
    db: {
      failureThreshold: 4,
      resetTimeout: 8_000,
      operationTimeout: 400,
      successesToClose: 2,
      maxHalfOpenRequests: 2,
      monitoringPeriod: 60_000, // optional rolling window
    },
  } as any;
  const opts = { ...base[preset], ...overrides };
  return new CircuitBreaker<T>(opts, operation, fallback);
}

export { CircuitBreaker };

// Zero-dependency async mutex
export class Mutex {
  private tail: Promise<unknown> = Promise.resolve();
  runExclusive<T>(fn: () => Promise<T> | T): Promise<T> {
    const next = this.tail.then(() => fn());
    // Swallow errors in tail to prevent chain breakage; actual error propagates via next
    this.tail = next.catch((err) => {
      console.debug('[Mutex] Previous operation in chain failed:', err?.message || err);
    });
    return next;
  }
}

// Minimal singleflight to coalesce duplicate inflight work by key
const inflight = new Map<string, Promise<any>>();

export function singleflight<T>(key: string, fn: () => Promise<T>): Promise<T> {
  const existing = inflight['get'](key);
  if (existing) return existing;
  const p = fn()
    .finally(() => {
      inflight.delete(key);
    });
  inflight['set'](key, p);
  return p;
}

/**
 * Type-safe wrapper for CircuitBreaker to avoid 'as any' casts
 */
import { CircuitBreaker } from './CircuitBreaker';
import type { CircuitBreakerOptions } from './types';

// Common interface for all breaker types
export interface BreakerLike {
  run<T>(op: () => Promise<T>, fallback?: () => Promise<T>): Promise<T>;
  getState(): string;                  
  getMetrics?(): unknown;          
}

export class TypedCircuitBreaker<T = any> implements BreakerLike {
  private breaker: CircuitBreaker<T>;

  constructor(options: CircuitBreakerOptions) {
    // Create with dummy operation and fallback since we'll use run() method
    this.breaker = new CircuitBreaker<T>(
      options,
      async () => { throw new Error('Use run method'); },
      async () => { throw new Error('Use run method'); }
    );
  }

  async run<R>(
    operation: () => Promise<R>,
    fallback?: () => Promise<R>
  ): Promise<R> {
    return this.breaker.run(operation, fallback || (async () => { throw new Error('No fallback provided'); }));
  }

  getState(): string {
    return this.breaker.getState();
  }

  getMetrics() {
    return this.breaker.getMetrics?.();
  }
}

import type { Request, Response, NextFunction } from 'express';

export function setDegradedHeaders(state: 'CLOSED' | 'OPEN' | 'HALF_OPEN') {
  return (_req: Request, res: Response, next: NextFunction) => {
    res['setHeader']('X-Circuit-State', state);
    if (state !== 'CLOSED') {
      // Surfaced in timelines
      res['setHeader']('Server-Timing', `circuit;desc="${state}"`);
      (res.locals as any).degraded = true;
    }
    next();
  };
}

/**
 * JWT Authentication for Flag Admin API
 * Production-grade token validation with RS256/JWKS and strict validation
 *
 * Supports both HS256 (symmetric) and RS256 (asymmetric) algorithms:
 * - HS256: Uses JWT_SECRET for signing and verification
 * - RS256: Uses JWKS endpoint (JWT_JWKS_URL) for public key retrieval
 *
 * Uses unified Express.User interface from types/express.d.ts
 */

import type { Algorithm, JwtPayload } from 'jsonwebtoken';
import jwt from 'jsonwebtoken';
import jwksClient from 'jwks-rsa';
import type { Request, Response, NextFunction } from 'express';
import { getConfig } from '../../config';
import { authMetrics } from '../../telemetry';

export type JWTClaims = JwtPayload & {
  sub: string;
  role?: string;
  email?: string;
  fundIds?: number[];
  lpId?: number; // LP-specific: Limited Partner ID for LP role users
};

const cfg = getConfig();

// JWKS client singleton for RS256 (lazy initialized)
let jwksClientInstance: jwksClient.JwksClient | null = null;

function getJwksClient(): jwksClient.JwksClient {
  if (!jwksClientInstance && cfg.JWT_JWKS_URL) {
    jwksClientInstance = jwksClient({
      jwksUri: cfg.JWT_JWKS_URL,
      cache: true,
      cacheMaxAge: 600000, // 10 minutes
      rateLimit: true,
      jwksRequestsPerMinute: 10,
    });
  }
  if (!jwksClientInstance) {
    throw new Error('JWKS client not initialized - JWT_JWKS_URL required for RS256');
  }
  return jwksClientInstance;
}

/**
 * Get signing key from JWKS endpoint for RS256 verification
 */
async function getSigningKey(kid: string): Promise<string> {
  const client = getJwksClient();
  const key = await client.getSigningKey(kid);
  return key.getPublicKey();
}

/**
 * Verify JWT token - supports both HS256 and RS256 algorithms
 *
 * For HS256: Synchronous verification using JWT_SECRET
 * For RS256: Async verification using JWKS public keys
 */
export function verifyAccessToken(token: string): JWTClaims {
  if (cfg.JWT_ALG === "HS256") {
    const verified = jwt.verify(token, cfg.JWT_SECRET!, {
      algorithms: ["HS256" as Algorithm],
      issuer: cfg.JWT_ISSUER,
      audience: cfg.JWT_AUDIENCE
    });
    return verified as JWTClaims;
  }

  // RS256: Need to handle async key retrieval
  // For sync API compatibility, we throw here and use verifyAccessTokenAsync for RS256
  throw new Error("Use verifyAccessTokenAsync for RS256");
}

/**
 * Async token verification - required for RS256 with JWKS
 * Falls back to sync verification for HS256
 */
export async function verifyAccessTokenAsync(token: string): Promise<JWTClaims> {
  if (cfg.JWT_ALG === "HS256") {
    return verifyAccessToken(token);
  }

  // RS256: Decode header to get kid, then fetch public key
  const decoded = jwt.decode(token, { complete: true });
  if (!decoded || typeof decoded === 'string' || !decoded.header.kid) {
    throw new Error('Invalid token: missing kid in header');
  }

  const publicKey = await getSigningKey(decoded.header.kid);
  const verified = jwt.verify(token, publicKey, {
    algorithms: ["RS256" as Algorithm],
    issuer: cfg.JWT_ISSUER,
    audience: cfg.JWT_AUDIENCE,
  });

  return verified as JWTClaims;
}

/**
 * Assign verified claims to request user object
 */
function assignUserFromClaims(req: Request, claims: JWTClaims): void {
  // eslint-disable-next-line @typescript-eslint/no-unsafe-member-access, @typescript-eslint/no-explicit-any
  (req as any).user = {
    id: claims.sub,
    sub: claims.sub,
    email: claims.email ?? claims.sub,
    role: claims.role,
    roles: claims.role ? [claims.role] : [],
    fundIds: claims.fundIds || [],
    lpId: claims.lpId, // LP-specific: attach if present in token
    ip: req.ip || 'unknown',
    userAgent: req.header("user-agent") || 'unknown',
  };
}

export const requireAuth = () => async (req: Request, res: Response, next: NextFunction) => {
  const h = req.header("authorization") || "";
  const token = h.startsWith("Bearer ") ? h.slice(7) : undefined;

  if (!token) {
    authMetrics.jwtMissingToken.inc?.();
    return res.sendStatus(401);
  }

  try {
    // Use async verification to support both HS256 and RS256
    const claims = await verifyAccessTokenAsync(token);
    assignUserFromClaims(req, claims);
    next();
  // eslint-disable-next-line @typescript-eslint/no-explicit-any
  } catch (err: any) {
    console.warn("JWT verification failed", { name: err?.name, message: err?.message });
    authMetrics.jwtVerificationFailed.inc?.();
    return res.sendStatus(401);
  }
};

export const requireRole = (role: string) => (req: Request, res: Response, next: NextFunction) => {
  const user = req.user;
  if (!user || user.role !== role) return res.sendStatus(403);
  next();
};

/**
 * Require user to have access to a specific fund
 * Use after requireAuth to check fund-level permissions
 */
export const requireFundAccess = (req: Request, res: Response, next: NextFunction) => {
  const fundIdParam = req.params['fundId'];

  if (!fundIdParam) {
    return res.status(400).json({
      error: 'Bad Request',
      message: 'Fund ID is required',
    });
  }

  const fundId = parseInt(fundIdParam, 10);

  if (isNaN(fundId)) {
    return res.status(400).json({
      error: 'Bad Request',
      message: 'Invalid fund ID',
    });
  }

  // Check if user has access to this fund
  const userFundIds = req.user?.fundIds || [];

  // Empty fundIds array means access to all funds (admin/superuser pattern)
  if (userFundIds.length === 0) {
    return next();
  }

  if (userFundIds.includes(fundId)) {
    return next();
  }

  // User doesn't have access to this fund
  return res.status(403).json({
    error: 'Forbidden',
    message: `You do not have access to fund ${fundId}`,
  });
};

// eslint-disable-next-line @typescript-eslint/no-explicit-any
export function signToken(data: any): string {
  const cfg = getConfig();
  return jwt.sign(data, cfg.JWT_SECRET!, {
    algorithm: "HS256" as Algorithm,
    expiresIn: "7d",
    issuer: cfg.JWT_ISSUER,
    audience: cfg.JWT_AUDIENCE
  });
}

/**
 * Field-Level Encryption for Sensitive PII
 *
 * Provides AES-256-GCM encryption/decryption for database fields containing
 * sensitive personally identifiable information (PII).
 *
 * Security Features:
 * - AES-256-GCM authenticated encryption
 * - Per-field random IV (96-bit nonce)
 * - Authentication tag prevents tampering
 * - PBKDF2 key derivation from master secret
 * - Constant-time MAC verification
 *
 * Usage:
 * ```typescript
 * const encrypted = await encryptField('123-45-6789');
 * const decrypted = await decryptField(encrypted); // '123-45-6789'
 * ```
 *
 * Environment Variables Required:
 * - FIELD_ENCRYPTION_KEY: Base64-encoded 256-bit key or passphrase
 *
 * @module server/lib/crypto/field-encryption
 */

import { createCipheriv, createDecipheriv, randomBytes, pbkdf2 } from 'crypto';
import { promisify } from 'util';

const pbkdf2Async = promisify(pbkdf2);

// Encryption constants
const ALGORITHM = 'aes-256-gcm';
const IV_LENGTH = 12; // 96 bits for GCM
const AUTH_TAG_LENGTH = 16; // 128 bits
const KEY_LENGTH = 32; // 256 bits
const SALT_LENGTH = 16; // 128 bits
const PBKDF2_ITERATIONS = 100000;
const PBKDF2_DIGEST = 'sha256';

// Cache for derived keys to avoid repeated PBKDF2
const keyCache = new Map<string, Buffer>();

/**
 * Derive encryption key from environment variable
 *
 * Uses PBKDF2 with 100,000 iterations if passphrase is provided,
 * or directly decodes if already a 256-bit base64 key.
 */
async function getDerivedKey(): Promise<Buffer> {
  const envKey = process.env['FIELD_ENCRYPTION_KEY'];

  if (!envKey) {
    throw new Error(
      'FIELD_ENCRYPTION_KEY environment variable is required for field encryption'
    );
  }

  // Check cache first
  if (keyCache.has(envKey)) {
    return keyCache.get(envKey)!;
  }

  let derivedKey: Buffer;

  // Try to decode as base64 first
  try {
    const decoded = Buffer.from(envKey, 'base64');
    if (decoded.length === KEY_LENGTH) {
      // Valid 256-bit key
      derivedKey = decoded;
    } else {
      // Treat as passphrase and derive key
      const salt = Buffer.from('lp-field-encryption-salt', 'utf8');
      derivedKey = await pbkdf2Async(
        envKey,
        salt,
        PBKDF2_ITERATIONS,
        KEY_LENGTH,
        PBKDF2_DIGEST
      );
    }
  } catch {
    // Decode failed, treat as passphrase
    const salt = Buffer.from('lp-field-encryption-salt', 'utf8');
    derivedKey = await pbkdf2Async(
      envKey,
      salt,
      PBKDF2_ITERATIONS,
      KEY_LENGTH,
      PBKDF2_DIGEST
    );
  }

  keyCache.set(envKey, derivedKey);
  return derivedKey;
}

/**
 * Encrypt a plaintext field value
 *
 * Returns base64-encoded ciphertext with format:
 * [iv:12 bytes][ciphertext:variable][authTag:16 bytes]
 *
 * @param plaintext - The sensitive data to encrypt
 * @returns Base64-encoded encrypted value
 * @throws Error if encryption fails
 */
export async function encryptField(plaintext: string | null): Promise<string | null> {
  if (plaintext === null || plaintext === undefined || plaintext === '') {
    return null;
  }

  const key = await getDerivedKey();
  const iv = randomBytes(IV_LENGTH);

  const cipher = createCipheriv(ALGORITHM, key, iv);

  let encrypted = cipher.update(plaintext, 'utf8');
  encrypted = Buffer.concat([encrypted, cipher.final()]);

  const authTag = cipher.getAuthTag();

  // Format: [iv][encrypted][authTag]
  const result = Buffer.concat([iv, encrypted, authTag]);

  return result.toString('base64');
}

/**
 * Decrypt an encrypted field value
 *
 * Expects base64-encoded ciphertext with format:
 * [iv:12 bytes][ciphertext:variable][authTag:16 bytes]
 *
 * @param encrypted - Base64-encoded encrypted value
 * @returns Decrypted plaintext
 * @throws Error if decryption fails or authentication tag is invalid
 */
export async function decryptField(encrypted: string | null): Promise<string | null> {
  if (encrypted === null || encrypted === undefined || encrypted === '') {
    return null;
  }

  const key = await getDerivedKey();
  const buffer = Buffer.from(encrypted, 'base64');

  if (buffer.length < IV_LENGTH + AUTH_TAG_LENGTH) {
    throw new Error('Invalid encrypted field: data too short');
  }

  // Extract components
  const iv = buffer.subarray(0, IV_LENGTH);
  const authTag = buffer.subarray(buffer.length - AUTH_TAG_LENGTH);
  const ciphertext = buffer.subarray(IV_LENGTH, buffer.length - AUTH_TAG_LENGTH);

  const decipher = createDecipheriv(ALGORITHM, key, iv);
  decipher.setAuthTag(authTag);

  let decrypted = decipher.update(ciphertext);
  decrypted = Buffer.concat([decrypted, decipher.final()]);

  return decrypted.toString('utf8');
}

/**
 * Check if field encryption is configured
 *
 * @returns True if FIELD_ENCRYPTION_KEY is set
 */
export function isEncryptionConfigured(): boolean {
  return !!process.env['FIELD_ENCRYPTION_KEY'];
}

/**
 * Clear the key cache (useful for testing)
 */
export function clearKeyCache(): void {
  keyCache.clear();
}

/**
 * PII Sanitization for Safe Logging
 *
 * Redacts sensitive personally identifiable information (PII) from logs
 * to prevent accidental exposure of LP data in error messages.
 *
 * Redacted Fields:
 * - Email addresses (full redaction)
 * - Tax IDs (SSN, EIN patterns)
 * - Phone numbers
 * - Full names (in specific contexts)
 * - Addresses
 * - Credit card numbers
 *
 * Usage:
 * ```typescript
 * const safeError = sanitizeForLogging(error);
 * console.error('LP API error:', safeError);
 * ```
 *
 * @module server/lib/crypto/pii-sanitizer
 */

/**
 * PII patterns to redact
 */
const PII_PATTERNS = {
  // Email: user@example.com -> [EMAIL_REDACTED]
  email: /\b[A-Za-z0-9._%+-]+@[A-Za-z0-9.-]+\.[A-Z|a-z]{2,}\b/gi,

  // Tax ID: 123-45-6789 or 12-3456789 -> [TAX_ID_REDACTED]
  taxId: /\b\d{2,3}-?\d{2}-?\d{4,5}\b/g,

  // Phone: (123) 456-7890, 123-456-7890, etc -> [PHONE_REDACTED]
  phone: /\b(?:\+?1[-.\s]?)?\(?([0-9]{3})\)?[-.\s]?([0-9]{3})[-.\s]?([0-9]{4})\b/g,

  // Credit card: 4111-1111-1111-1111 -> [CARD_REDACTED]
  creditCard: /\b\d{4}[-\s]?\d{4}[-\s]?\d{4}[-\s]?\d{4}\b/g,

  // IP addresses (may contain PII in some contexts)
  ip: /\b(?:\d{1,3}\.){3}\d{1,3}\b/g,
};

/**
 * Field names that may contain PII (case-insensitive)
 */
const PII_FIELD_NAMES = [
  'email',
  'contactEmail',
  'contactemail',
  'taxId',
  'taxid',
  'taxIdEncrypted',
  'taxidencrypted',
  'name',
  'lpName',
  'lpname',
  'contactName',
  'contactname',
  'address',
  'contactPhone',
  'contactphone',
  'phone',
  'ssn',
  'ein',
  'password',
  'token',
  'secret',
  'apiKey',
  'apikey',
];

/**
 * Sanitize a string by redacting PII patterns
 */
function sanitizeString(value: string): string {
  let sanitized = value;

  sanitized = sanitized.replace(PII_PATTERNS.email, '[EMAIL_REDACTED]');
  sanitized = sanitized.replace(PII_PATTERNS.taxId, '[TAX_ID_REDACTED]');
  sanitized = sanitized.replace(PII_PATTERNS.phone, '[PHONE_REDACTED]');
  sanitized = sanitized.replace(PII_PATTERNS.creditCard, '[CARD_REDACTED]');
  sanitized = sanitized.replace(PII_PATTERNS.ip, '[IP_REDACTED]');

  return sanitized;
}

/**
 * Check if field name indicates PII
 */
function isPIIField(key: string): boolean {
  const lowerKey = key.toLowerCase();
  return PII_FIELD_NAMES.some((piiField) => lowerKey.includes(piiField.toLowerCase()));
}

/**
 * Sanitize an object by redacting PII fields
 */
function sanitizeObject(obj: Record<string, unknown>): Record<string, unknown> {
  const sanitized: Record<string, unknown> = {};

  for (const [key, value] of Object.entries(obj)) {
    if (isPIIField(key)) {
      // Completely redact known PII fields
      sanitized[key] = '[PII_REDACTED]';
    } else if (typeof value === 'string') {
      // Sanitize string values for pattern-based PII
      sanitized[key] = sanitizeString(value);
    } else if (Array.isArray(value)) {
      // Recursively sanitize arrays
      sanitized[key] = value.map((item) =>
        typeof item === 'object' && item !== null
          ? sanitizeObject(item as Record<string, unknown>)
          : typeof item === 'string'
            ? sanitizeString(item)
            : item
      );
    } else if (value && typeof value === 'object') {
      // Recursively sanitize nested objects
      sanitized[key] = sanitizeObject(value as Record<string, unknown>);
    } else {
      // Pass through other types unchanged
      sanitized[key] = value;
    }
  }

  return sanitized;
}

/**
 * Sanitize error objects for safe logging
 *
 * Removes PII from:
 * - Error messages
 * - Stack traces
 * - Custom error properties
 *
 * @param error - Error object or any value
 * @returns Sanitized version safe for logging
 *
 * @example
 * ```typescript
 * try {
 *   await createLP({ email: 'john@example.com' });
 * } catch (error) {
 *   console.error('LP creation failed:', sanitizeForLogging(error));
 * }
 * ```
 */
export function sanitizeForLogging(error: unknown): unknown {
  if (error instanceof Error) {
    // Create sanitized error copy
    const sanitizedError: Record<string, unknown> = {
      name: error.name,
      message: sanitizeString(error.message),
    };

    // Sanitize stack trace
    if ('stack' in error && typeof error.stack === 'string') {
      sanitizedError['stack'] = sanitizeString(error.stack);
    }

    // Sanitize custom properties
    const errorObj = error as unknown as Record<string, unknown>;
    for (const key in errorObj) {
      if (
        key !== 'name' &&
        key !== 'message' &&
        key !== 'stack' &&
        Object.prototype.hasOwnProperty.call(errorObj, key)
      ) {
        const value = errorObj[key];
        if (typeof value === 'string') {
          sanitizedError[key] = sanitizeString(value);
        } else if (value && typeof value === 'object') {
          sanitizedError[key] = sanitizeObject(value as Record<string, unknown>);
        } else {
          sanitizedError[key] = value;
        }
      }
    }

    return sanitizedError;
  } else if (typeof error === 'string') {
    return sanitizeString(error);
  } else if (error && typeof error === 'object') {
    return sanitizeObject(error as Record<string, unknown>);
  }

  return error;
}

/**
 * Create a sanitized error message for API responses
 *
 * @param error - Error object
 * @returns Safe, generic error message suitable for API responses
 */
export function sanitizeErrorMessage(error: unknown): string {
  if (error instanceof Error) {
    return sanitizeString(error.message);
  } else if (typeof error === 'string') {
    return sanitizeString(error);
  }

  return 'An error occurred while processing your request';
}

/**
 * Redact specific PII from request bodies for logging
 *
 * Use this before logging request bodies that may contain LP data.
 *
 * @param body - Request body object
 * @returns Sanitized copy of request body
 */
export function sanitizeRequestBody(body: unknown): unknown {
  if (body && typeof body === 'object') {
    return sanitizeObject(body as Record<string, unknown>);
  }
  return body;
}

