const FLAG_ENV = process.env['FLAG_ENV'] || process.env['NODE_ENV'] || 'development';
const CACHE_KEY = `flags:v1:${FLAG_ENV}`;
const INVALIDATION_KEY = 'flags:changed';

// Global state with versioning and LKG
