import type { IdempotencyStore } from './idempotency';

export async function getOrStart<T>(
  store: IdempotencyStore,
  key: string,
  worker: (_signal: AbortSignal) => Promise<T>,
  ttlMs = 60_000
): Promise<{ status: 'joined' | 'created'; promise: Promise<T> }> {
  const existing = await store.get<T>(key);
  if (existing?.status === 'succeeded') {
    return { status: 'joined', promise: Promise.resolve(existing.result as T) };
  }
  if (existing?.status === 'in-progress') {
    // In a Redis-backed impl, you would return a shared promise via pub/sub or an operation endpoint.
    return { status: 'joined', promise: Promise.reject(new Error('in-progress')) };
  }

  const controller = new AbortController();
  await store['set'](key, { status: 'in-progress', updatedAt: Date.now(), ttlMs });

  const p = (async () => {
    try {
      const out = await worker(controller.signal);
      await store['set'](key, { status: 'succeeded', result: out, updatedAt: Date.now(), ttlMs });
      return out;
    } catch (e: any) {
      await store['set'](key, { status: 'failed', error: String(e?.message ?? e), updatedAt: Date.now(), ttlMs });
      throw e;
    }
  })();

  return { status: 'created', promise: p };
}

/**
 * Redis-backed rate limiter for distributed systems
 * Provides consistent rate limiting across multiple server instances
 */

import type { RedisClientType } from 'redis';
import { createClient } from 'redis';

export interface RateLimitResult {
  allowed: boolean;
  remaining: number;
  resetAt: number;
  retryAfter?: number;
}

export interface RateLimiterConfig {
  maxRequests: number;
  windowMs: number;
  keyPrefix?: string;
  redisUrl?: string;
}

/**
 * Redis-backed approval rate limiter
 * Uses atomic Lua scripts for race-condition-free rate limiting
 */
export class RedisApprovalRateLimiter {
  private tokenBucketScript: string;
  private slidingWindowScript: string;
  private redis: RedisClientType | null;
  private connected = false;
  private readonly useMemory: boolean;
  private readonly memoryBuckets = new Map<string, number[]>();

  constructor(
    private config: RateLimiterConfig = {
      maxRequests: 3,
      windowMs: 60000, // 1 minute default
      keyPrefix: 'rl' // Namespace keys properly
    }
  ) {
    const resolvedRedisUrl = config.redisUrl ?? process.env['REDIS_URL'];
    this.useMemory = !resolvedRedisUrl || resolvedRedisUrl === 'memory://';

    this.redis = this.useMemory
      ? null
      : createClient({
          url: resolvedRedisUrl as string,
          socket: {
            connectTimeout: 5000
          },
        });

    // Atomic token bucket Lua script
    this.tokenBucketScript = `
      local key = KEYS[1]
      local now = tonumber(ARGV[1])
      local window = tonumber(ARGV[2])
      local limit = tonumber(ARGV[3])
      local ttl = tonumber(ARGV[4])

      local bucket = redis.call('HMGET', key, 'count', 'reset_time')
      local count = tonumber(bucket[1]) or 0
      local reset_time = tonumber(bucket[2]) or now

      -- Reset bucket if window expired
      if now >= reset_time then
        count = 0
        reset_time = now + window
      end

      if count >= limit then
        -- Rate limited
        return {0, 0, reset_time}
      else
        -- Allow request
        count = count + 1
        redis.call('HMSET', key, 'count', count, 'reset_time', reset_time)
        redis.call('EXPIRE', key, ttl)
        return {1, limit - count, reset_time}
      end
    `;

    // Sliding window Lua script (more accurate)
    this.slidingWindowScript = `
      local key = KEYS[1]
      local now = tonumber(ARGV[1])
      local window = tonumber(ARGV[2])
      local limit = tonumber(ARGV[3])
      local identifier = ARGV[4]

      local window_start = now - window

      -- Remove expired entries
      redis.call('ZREMRANGEBYSCORE', key, '-inf', window_start)

      -- Count current entries
      local current = redis.call('ZCARD', key)

      if current >= limit then
        -- Find reset time (oldest entry + window)
        local oldest = redis.call('ZRANGE', key, 0, 0, 'WITHSCORES')
        local reset_at = oldest[2] and (tonumber(oldest[2]) + window) or (now + window)
        return {0, 0, reset_at}
      else
        -- Add current request
        redis.call('ZADD', key, now, identifier)
        redis.call('EXPIRE', key, math.ceil(window / 1000))
        return {1, limit - current - 1, now + window}
      end
    `;

    if (this.redis) {
      this.redis['on']('error', (err: any) => {
        console.error('Redis rate limiter error:', err);
        this.connected = false;
      });

      this.redis['on']('connect', () => {
        console.log('Redis rate limiter connected');
        this.connected = true;
      });
    } else {
      this.connected = true;
    }
  }

  async connect(): Promise<void> {
    if (this.useMemory) {
      this.connected = true;
      return;
    }
    if (!this.connected && this.redis) {
      await this.redis.connect();
      this.connected = true;
    }
  }

  async disconnect(): Promise<void> {
    if (this.useMemory) {
      this.connected = false;
      this.memoryBuckets.clear();
      return;
    }
    if (this.connected && this.redis) {
      await this.redis['quit']();
      this.connected = false;
    }
  }

  /**
   * Check if approval creation is allowed
   * Uses atomic Lua scripts to prevent race conditions
   */
  async canCreateApproval(
    strategyId: string, 
    inputsHash: string
  ): Promise<RateLimitResult> {
    if (this.useMemory) {
      const key = `${this.config.keyPrefix}:approval:${strategyId}:${inputsHash}`;
      const now = Date.now();
      const windowStart = now - this.config.windowMs;
      const timestamps = (this.memoryBuckets.get(key) || []).filter(ts => ts > windowStart);
      if (timestamps.length >= this.config.maxRequests) {
        const resetAt = timestamps[0]! + this.config.windowMs;
        this.memoryBuckets.set(key, timestamps);
        return {
          allowed: false,
          remaining: 0,
          resetAt,
          retryAfter: Math.ceil((resetAt - now) / 1000)
        };
      }
      timestamps.push(now);
      this.memoryBuckets.set(key, timestamps);
      return {
        allowed: true,
        remaining: this.config.maxRequests - timestamps.length,
        resetAt: now + this.config.windowMs
      };
    }

    if (!this.connected) {
      try {
        await this.connect();
      } catch (error) {
        console.error('Redis connection failed, allowing request:', error);
        return {
          allowed: true,
          remaining: this.config.maxRequests - 1,
          resetAt: Date.now() + this.config.windowMs
        };
      }
    }

    const key = `${this.config.keyPrefix}:approval:${strategyId}:${inputsHash}`;
    const now = Date.now();
    const ttl = Math.ceil(this.config.windowMs / 1000);
    const identifier = `${now}-${Math.random().toString(36).substr(2, 9)}`;

    try {
      const result = await this.redis!.eval(
        this.slidingWindowScript,
        {
          keys: [key],
          arguments: [
            now.toString(),
            this.config.windowMs.toString(),
            this.config.maxRequests.toString(),
            identifier
          ]
        }
      ) as [number, number, number];

      const [allowed, remaining, resetAt] = result;

      const retryAfter = allowed === 0 ? Math.ceil((resetAt - now) / 1000) : undefined;
      return {
        allowed: allowed === 1,
        remaining,
        resetAt,
        ...(retryAfter !== undefined && { retryAfter })
      };

    } catch (error) {
      console.error('Redis rate limit check failed:', error);

      return {
        allowed: false,
        remaining: 0,
        resetAt: now + this.config.windowMs,
        retryAfter: Math.ceil(this.config.windowMs / 1000)
      };
    }
  }

  /**
   * Clear rate limit for a specific key
   * Useful for testing or manual intervention
   */
  async clearLimit(strategyId: string, inputsHash: string): Promise<void> {
    if (this.useMemory) {
      const key = `${this.config.keyPrefix}:approval:${strategyId}:${inputsHash}`;
      this.memoryBuckets.delete(key);
      return;
    }

    if (!this.connected) {
      await this.connect();
    }

    const key = `${this.config.keyPrefix}:approval:${strategyId}:${inputsHash}`;
    await this.redis!['del'](key);
  }

  /**
   * Get current usage for monitoring
   */
  async getCurrentUsage(
    strategyId: string,
    inputsHash: string
  ): Promise<{ count: number; oldestRequest: number | null }> {
    if (this.useMemory) {
      const key = `${this.config.keyPrefix}:approval:${strategyId}:${inputsHash}`;
      const now = Date.now();
      const windowStart = now - this.config.windowMs;
      const timestamps = (this.memoryBuckets.get(key) || []).filter(ts => ts > windowStart);
      this.memoryBuckets.set(key, timestamps);
      return {
        count: timestamps.length,
        oldestRequest: timestamps.length > 0 ? timestamps[0]! : null,
      };
    }

    if (!this.connected) {
      await this.connect();
    }

    const key = `${this.config.keyPrefix}:approval:${strategyId}:${inputsHash}`;
    const now = Date.now();
    const windowStart = now - this.config.windowMs;

    await this.redis!.zRemRangeByScore(key, '-inf', windowStart.toString());

    const count = await this.redis!.zCard(key);
    const oldest = await this.redis!.zRange(key, 0, 0);

    return {
      count,
      oldestRequest: oldest.length > 0 && oldest[0]
        ? parseInt(oldest[0].split('-')[0]!)
        : null
    };
  }
}

/**
 * Fallback in-memory rate limiter for development/testing
 * Only use when Redis is not available
 */
export class InMemoryRateLimiter {
  private storage = new Map<string, { timestamps: number[]; lastCleanup: number }>();
  private readonly maxStorageSize = 1000;
  private readonly cleanupInterval = 60000; // 1 minute

  constructor(
    private maxRequests: number = 3,
    private windowMs: number = 60000
  ) {}

  canCreateApproval(
    strategyId: string, 
    inputsHash: string
  ): RateLimitResult {
    const key = `rl:approval:${strategyId}:${inputsHash}`;
    const now = Date.now();
    const windowStart = now - this.windowMs;

    // Get existing data
    const data = this.storage['get'](key) || { timestamps: [], lastCleanup: now };

    // Filter out expired timestamps
    data.timestamps = data.timestamps.filter(t => t > windowStart);

    if (data.timestamps.length >= this.maxRequests) {
      const oldestTimestamp = Math.min(...data.timestamps);
      const resetAt = oldestTimestamp + this.windowMs;

      return {
        allowed: false,
        remaining: 0,
        resetAt,
        retryAfter: Math.ceil((resetAt - now) / 1000)
      };
    }

    // Add current timestamp
    data.timestamps.push(now);
    data.lastCleanup = now;
    this.storage['set'](key, data);

    // Periodic cleanup
    if (this.storage.size > this.maxStorageSize || 
        now - data.lastCleanup > this.cleanupInterval) {
      this.cleanup(now);
    }

    return {
      allowed: true,
      remaining: this.maxRequests - data.timestamps.length,
      resetAt: now + this.windowMs
    };
  }

  private cleanup(now: number = Date.now()): void {
    for (const [key, data] of this.storage.entries()) {
      const validTimestamps = data.timestamps.filter(t => t > now - this.windowMs);
      if (validTimestamps.length === 0) {
        this.storage.delete(key);
      } else {
        data.timestamps = validTimestamps;
        data.lastCleanup = now;
      }
    }
  }

  clear(): void {
    this.storage.clear();
  }
}

/**
 * Factory function to create appropriate rate limiter
 * Uses Redis in production, in-memory for development
 */
export async function createRateLimiter(
  config?: RateLimiterConfig
): Promise<RedisApprovalRateLimiter | InMemoryRateLimiter> {
  const isProduction = process.env['NODE_ENV'] === 'production';
  const redisUrl = config?.redisUrl ?? process.env['REDIS_URL'];
  const shouldUseRedis = !!redisUrl && redisUrl !== 'memory://';

  if (isProduction && shouldUseRedis) {
    try {
      const limiterConfig: RateLimiterConfig = {
        maxRequests: config?.maxRequests ?? 3,
        windowMs: config?.windowMs ?? 60000,
        redisUrl
      };
      if (config?.keyPrefix !== undefined) {
        limiterConfig.keyPrefix = config.keyPrefix;
      }
      const redisLimiter = new RedisApprovalRateLimiter(limiterConfig);
      await redisLimiter.connect();
      console.log('Using Redis-backed rate limiter');
      return redisLimiter;
    } catch (error) {
      console.warn('Failed to connect to Redis, falling back to in-memory rate limiter:', error);
    }
  }

  console.log('Using in-memory rate limiter (development mode)');
  return new InMemoryRateLimiter(
    config?.maxRequests,
    config?.windowMs
  );
}

/**
 * Redis connection helper (single/cluster aware)
 */
import { parseRedisConfig } from '../../config/redis';
import * as fs from 'fs';

export interface RedisConn {
  conn: any; // RedisClientType or RedisClusterType
  mode: 'single' | 'cluster';
  describe(): string;
  close(): Promise<void>;
}

export async function connectRedis(): Promise<RedisConn | undefined> {
  const cfg = parseRedisConfig();
  if (cfg.mode === 'memory') return undefined;

  const { createClient, createCluster } = await import('redis');

  if (cfg.mode === 'cluster') {
    if (!cfg.nodes?.length) {
      throw new Error('Redis cluster mode requires nodes');
    }

    const tlsEnabled = cfg.tls || false;
    const socketOptions: any = {
      reconnectStrategy: (retries: number) => Math.min(1000 * retries, 5000),
      connectTimeout: 5000
    };

    // Add TLS configuration if enabled
    if (tlsEnabled) {
      socketOptions.tls = true;
      if (process.env['REDIS_CA_PATH']) {
        socketOptions.ca = fs.readFileSync(process.env['REDIS_CA_PATH']);
      }
      if (process.env['REDIS_CERT_PATH']) {
        socketOptions.cert = fs.readFileSync(process.env['REDIS_CERT_PATH']);
      }
      if (process.env['REDIS_KEY_PATH']) {
        socketOptions.key = fs.readFileSync(process.env['REDIS_KEY_PATH']);
      }
      if (process.env['REDIS_SERVERNAME']) {
        socketOptions.servername = process.env['REDIS_SERVERNAME'];
      }
    }

    const cluster = createCluster({
      rootNodes: cfg.nodes.map(node => ({ 
        url: `redis${tlsEnabled ? 's' : ''}://${node}` 
      })),
      defaults: { socket: socketOptions }
    });

    cluster['on']('error', (err: any) => {

      console.error('[redis-cluster] error:', err?.message);
    });

    await cluster.connect();

    return {
      conn: cluster,
      mode: 'cluster',
      describe: () => `cluster(${cfg.nodes!.join(',')})`,
      close: async () => { await cluster['quit'](); }
    };
  }

  // Single node
  const socketOptions: any = {
    reconnectStrategy: (retries: number) => Math.min(1000 * retries, 5000),
    connectTimeout: 5000,
    keepAlive: 1
  };

  // Add TLS if URL starts with rediss://
  if (cfg.url?.startsWith('rediss://')) {
    socketOptions.tls = true;
    if (process.env['REDIS_CA_PATH']) {
      socketOptions.ca = fs.readFileSync(process.env['REDIS_CA_PATH']);
    }
    if (process.env['REDIS_CERT_PATH']) {
      socketOptions.cert = fs.readFileSync(process.env['REDIS_CERT_PATH']);
    }
    if (process.env['REDIS_KEY_PATH']) {
      socketOptions.key = fs.readFileSync(process.env['REDIS_KEY_PATH']);
    }
    if (process.env['REDIS_SERVERNAME']) {
      socketOptions.servername = process.env['REDIS_SERVERNAME'];
    }
  }

  const client = createClient({
    ...(cfg.url !== undefined ? { url: cfg.url } : {}),
    socket: socketOptions
  });

  client['on']('error', (err: any) => {

    console.error('[redis] error:', err?.message);
  });

  await client.connect();

  return {
    conn: client,
    mode: 'single',
    describe: () => `single(${cfg.url})`,
    close: async () => { await client['quit'](); }
  };
}

export async function pingRedis(conn: any): Promise<{ ok: boolean; latencyMs?: number; error?: string }> {
  try {
    const start = Date.now();
    await conn['ping']();
    return { ok: true, latencyMs: Date.now() - start };
  } catch (err) {
    return { ok: false, error: (err as Error)?.message };
  }
}

/**
 * Startup Environment Validation for Stage Normalization v3.4
 *
 * Validates critical environment variables and configuration
 * before the server starts. Fails fast with structured warnings
 * if configuration is invalid.
 */

import { createClient } from 'redis';
import { sql } from '../db-serverless';

/**
 * Validate STAGE_VALIDATION_MODE environment variable
 *
 * @returns true if valid, false with warning if invalid
 */
export function validateStageValidationMode(): boolean {
  const mode = process.env['STAGE_VALIDATION_MODE'];
  const validModes = ['off', 'warn', 'enforce'];

  if (!mode) {
    console.warn(
      JSON.stringify({
        level: 'warn',
        event: 'startup_validation',
        component: 'stage_validation_mode',
        message: 'STAGE_VALIDATION_MODE not set, will default to "warn"',
        timestamp: new Date().toISOString(),
      })
    );
    return true; // Not an error - will use default
  }

  if (!validModes.includes(mode)) {
    console.error(
      JSON.stringify({
        level: 'error',
        event: 'startup_validation_failed',
        component: 'stage_validation_mode',
        message: `Invalid STAGE_VALIDATION_MODE="${mode}", must be one of: ${validModes.join(', ')}`,
        provided: mode,
        valid_values: validModes,
        timestamp: new Date().toISOString(),
      })
    );
    return false;
  }

  console.log(
    JSON.stringify({
      level: 'info',
      event: 'startup_validation',
      component: 'stage_validation_mode',
      message: `STAGE_VALIDATION_MODE="${mode}" is valid`,
      timestamp: new Date().toISOString(),
    })
  );
  return true;
}

/**
 * Validate ALERTMANAGER_WEBHOOK_SECRET length
 *
 * Must be at least 32 characters for security
 *
 * @returns true if valid, false with error if invalid
 */
export function validateWebhookSecret(): boolean {
  const secret = process.env['ALERTMANAGER_WEBHOOK_SECRET'];
  const MIN_LENGTH = 32;

  if (!secret) {
    console.error(
      JSON.stringify({
        level: 'error',
        event: 'startup_validation_failed',
        component: 'webhook_secret',
        message: 'ALERTMANAGER_WEBHOOK_SECRET is required but not set',
        required_min_length: MIN_LENGTH,
        timestamp: new Date().toISOString(),
      })
    );
    return false;
  }

  if (secret.length < MIN_LENGTH) {
    console.error(
      JSON.stringify({
        level: 'error',
        event: 'startup_validation_failed',
        component: 'webhook_secret',
        message: `ALERTMANAGER_WEBHOOK_SECRET too short (${secret.length} chars), must be ≥${MIN_LENGTH} chars`,
        provided_length: secret.length,
        required_min_length: MIN_LENGTH,
        timestamp: new Date().toISOString(),
      })
    );
    return false;
  }

  console.log(
    JSON.stringify({
      level: 'info',
      event: 'startup_validation',
      component: 'webhook_secret',
      message: `ALERTMANAGER_WEBHOOK_SECRET is valid (${secret.length} chars)`,
      timestamp: new Date().toISOString(),
    })
  );
  return true;
}

/**
 * Pre-flight DB probe: Check that normalize_stage() function exists
 *
 * Fails fast if the database migration hasn't been run
 *
 * @returns true if function exists, false with error if missing
 */
export async function validateDatabaseFunction(): Promise<boolean> {
  try {
    // Test that normalize_stage() function exists by calling it with a known input
    const result = await sql`SELECT normalize_stage('seed') AS test_stage`;

    const firstRow = result?.[0];
    if (!firstRow) {
      throw new Error('normalize_stage() returned no results');
    }

    const testStage = firstRow['test_stage'];
    if (testStage !== 'seed') {
      console.warn(
        JSON.stringify({
          level: 'warn',
          event: 'startup_validation',
          component: 'database_function',
          message: 'normalize_stage() returned unexpected value',
          input: 'seed',
          output: testStage,
          timestamp: new Date().toISOString(),
        })
      );
    }

    console.log(
      JSON.stringify({
        level: 'info',
        event: 'startup_validation',
        component: 'database_function',
        message: 'normalize_stage() function exists and is working',
        test_result: testStage,
        timestamp: new Date().toISOString(),
      })
    );
    return true;
  } catch (err) {
    console.error(
      JSON.stringify({
        level: 'error',
        event: 'startup_validation_failed',
        component: 'database_function',
        message: 'normalize_stage() function not found in database',
        error: (err as Error)?.message,
        hint: 'Run database migration to create normalize_stage() function',
        timestamp: new Date().toISOString(),
      })
    );
    return false;
  }
}

/**
 * Validate Redis connectivity for mode store
 *
 * Tests connection but doesn't fail startup if Redis is unavailable
 * (mode store has fallback behavior)
 *
 * @returns true if connected, false with warning if unavailable
 */
export async function validateRedisConnection(): Promise<boolean> {
  const redisUrl = process.env.REDIS_URL || 'redis://localhost:6379';

  try {
    const client = createClient({ url: redisUrl });
    await client.connect();
    await client.ping();
    await client.disconnect();

    console.log(
      JSON.stringify({
        level: 'info',
        event: 'startup_validation',
        component: 'redis_connection',
        message: 'Redis connection successful',
        url: redisUrl.replace(/:[^:@]+@/, ':****@'), // Mask password
        timestamp: new Date().toISOString(),
      })
    );
    return true;
  } catch (err) {
    console.warn(
      JSON.stringify({
        level: 'warn',
        event: 'startup_validation',
        component: 'redis_connection',
        message: 'Redis connection failed - mode store will use fallback',
        error: (err as Error)?.message,
        url: redisUrl.replace(/:[^:@]+@/, ':****@'),
        impact: 'Mode store will use cache/default fallback',
        timestamp: new Date().toISOString(),
      })
    );
    return false; // Not a fatal error - mode store has fallback
  }
}

/**
 * Run all startup validations
 *
 * @throws Error if any critical validation fails
 */
export async function runStartupValidations(): Promise<void> {
  console.log(
    JSON.stringify({
      level: 'info',
      event: 'startup_validation_begin',
      message: 'Running Stage Normalization v3.4 startup validations',
      timestamp: new Date().toISOString(),
    })
  );

  const results = {
    stage_validation_mode: validateStageValidationMode(),
    webhook_secret: validateWebhookSecret(),
    database_function: await validateDatabaseFunction(),
    redis_connection: await validateRedisConnection(),
  };

  // Critical failures (must pass)
  const critical = ['webhook_secret', 'database_function'];
  const criticalFailures = critical.filter((key) => !results[key as keyof typeof results]);

  if (criticalFailures.length > 0) {
    const errorMsg = `Startup validation failed: ${criticalFailures.join(', ')}`;
    console.error(
      JSON.stringify({
        level: 'error',
        event: 'startup_validation_failed',
        message: errorMsg,
        failed_components: criticalFailures,
        all_results: results,
        timestamp: new Date().toISOString(),
      })
    );
    throw new Error(errorMsg);
  }

  // Warnings (can proceed)
  const warnings = Object.keys(results).filter(
    (key) => !results[key as keyof typeof results] && !critical.includes(key)
  );
  if (warnings.length > 0) {
    console.warn(
      JSON.stringify({
        level: 'warn',
        event: 'startup_validation_warnings',
        message: 'Some validations failed but server can proceed',
        warning_components: warnings,
        timestamp: new Date().toISOString(),
      })
    );
  }

  console.log(
    JSON.stringify({
      level: 'info',
      event: 'startup_validation_complete',
      message: 'All critical startup validations passed',
      results,
      timestamp: new Date().toISOString(),
    })
  );
}

