/**
 * Distributed tracing utilities for deployment and operational monitoring
 */

export interface TraceSpan {
  id: string;
  parentId?: string;
  operationName: string;
  startTime: number;
  endTime?: number;
  duration?: number;
  tags: Record<string, string | number | boolean>;
  logs: Array<{
    timestamp: number;
    message: string;
    level: 'info' | 'warn' | 'error' | 'debug';
    fields?: Record<string, any>;
  }>;
  status: 'active' | 'completed' | 'failed';
}

class TracingService {
  private spans = new Map<string, TraceSpan>();
  private activeSpans = new Set<string>();

  generateSpanId(): string {
    return crypto.randomUUID();
  }

  startSpan(operationName: string, parentId?: string, tags: Record<string, any> = {}): TraceSpan {
    const span: TraceSpan = {
      id: this.generateSpanId(),
      ...(parentId && { parentId }),
      operationName,
      startTime: Date.now(),
      tags: this.sanitizeTags(tags),
      logs: [],
      status: 'active'
    };

    this.spans['set'](span.id, span);
    this.activeSpans.add(span.id);

    this.log(span.id, 'info', `Started ${operationName}`, { spanId: span.id, parentId });

    return span;
  }

  finishSpan(spanId: string, status: 'completed' | 'failed' = 'completed', finalTags: Record<string, any> = {}) {
    const span = this.spans['get'](spanId);
    if (!span) {
      console.warn(`Attempted to finish unknown span: ${spanId}`);
      return;
    }

    span.endTime = Date.now();
    span.duration = span.endTime - span.startTime;
    span.status = status;

    // Add final tags
    Object.assign(span.tags, this.sanitizeTags(finalTags));

    this.activeSpans.delete(spanId);
    this.log(spanId, 'info', `Finished ${span.operationName}`, { 
      duration: span.duration,
      status 
    });

    return span;
  }

  log(spanId: string, level: TraceSpan['logs'][0]['level'], message: string, fields?: Record<string, any>) {
    const span = this.spans['get'](spanId);
    if (!span) return;

    span.logs.push({
      timestamp: Date.now(),
      message,
      level,
      ...(fields && { fields })
    });

    // Also log to console for immediate visibility
    const logMethod = level === 'error' ? console.error : level === 'warn' ? console.warn : console.log;
    logMethod(`[${span.operationName}:${spanId.slice(0, 8)}] ${message}`, fields || '');
  }

  addTags(spanId: string, tags: Record<string, any>) {
    const span = this.spans['get'](spanId);
    if (!span) return;

    Object.assign(span.tags, this.sanitizeTags(tags));
  }

  getSpan(spanId: string): TraceSpan | undefined {
    return this.spans['get'](spanId);
  }

  getActiveSpans(): TraceSpan[] {
    return Array.from(this.activeSpans).map(id => this.spans['get'](id)!).filter(Boolean);
  }

  getAllSpans(): TraceSpan[] {
    return Array.from(this.spans.values());
  }

  // Get trace tree for a root span
  getTrace(rootSpanId: string): TraceSpan[] {
    const trace: TraceSpan[] = [];
    const visited = new Set<string>();

    const collectSpans = (spanId: string) => {
      if (visited.has(spanId)) return;
      visited.add(spanId);

      const span = this.spans['get'](spanId);
      if (!span) return;

      trace.push(span);

      // Find children
      for (const [id, childSpan] of this.spans) {
        if (childSpan.parentId === spanId) {
          collectSpans(id);
        }
      }
    };

    collectSpans(rootSpanId);
    return trace.sort((a: any, b: any) => a.startTime - b.startTime);
  }

  // Export trace data in OpenTelemetry format
  exportTrace(rootSpanId: string) {
    const trace = this.getTrace(rootSpanId);
    const rootSpan = trace.find(s => s.id === rootSpanId);

    return {
      traceId: rootSpanId,
      spans: trace.map(span => ({
        spanId: span.id,
        parentSpanId: span.parentId,
        operationName: span.operationName,
        startTime: span.startTime,
        endTime: span.endTime,
        duration: span.duration,
        tags: span.tags,
        logs: span.logs,
        status: span.status
      })),
      duration: rootSpan ? (rootSpan.endTime || Date.now()) - rootSpan.startTime : 0,
      startTime: rootSpan?.startTime || Date.now()
    };
  }

  // Clean up completed spans older than retention period
  cleanup(retentionMs: number = 24 * 60 * 60 * 1000) { // 24 hours default
    const cutoff = Date.now() - retentionMs;
    let cleaned = 0;

    for (const [id, span] of this.spans) {
      if (span.status !== 'active' && span.startTime < cutoff) {
        this.spans.delete(id);
        cleaned++;
      }
    }

    if (cleaned > 0) {
      console.log(`Cleaned up ${cleaned} old trace spans`);
    }
  }

  private sanitizeTags(tags: Record<string, any>): Record<string, string | number | boolean> {
    const sanitized: Record<string, string | number | boolean> = {};

    for (const [key, value] of Object.entries(tags)) {
      if (typeof value === 'string' || typeof value === 'number' || typeof value === 'boolean') {
        sanitized[key] = value;
      } else if (value !== null && value !== undefined) {
        sanitized[key] = String(value);
      }
    }

    return sanitized;
  }
}

// Global tracing instance
export const tracer = new TracingService();

// Deployment-specific tracing helpers
export class DeploymentTracer {
  private rootSpanId: string;

  constructor(deploymentId: string, version: string) {
    this.rootSpanId = tracer.startSpan('deployment', undefined, {
      deploymentId,
      version,
      component: 'deployment-orchestrator'
    }).id;
  }

  startStage(stageName: string, percentage: number, duration: number) {
    return tracer.startSpan(`deployment.stage.${stageName}`, this.rootSpanId, {
      stage: stageName,
      percentage,
      plannedDuration: duration,
      phase: 'deployment'
    });
  }

  startPreflight() {
    return tracer.startSpan('deployment.preflight', this.rootSpanId, {
      phase: 'preflight'
    });
  }

  startHealthCheck(target: string, checkType: string) {
    return tracer.startSpan('deployment.health_check', this.rootSpanId, {
      target,
      checkType,
      phase: 'monitoring'
    });
  }

  startRollback(reason: string) {
    return tracer.startSpan('deployment.rollback', this.rootSpanId, {
      reason,
      phase: 'rollback'
    });
  }

  finishDeployment(status: 'success' | 'failed', metadata: Record<string, any> = {}) {
    tracer.finishSpan(this.rootSpanId, status === 'success' ? 'completed' : 'failed', {
      deploymentStatus: status,
      ...metadata
    });
  }

  exportTrace() {
    return tracer.exportTrace(this.rootSpanId);
  }

  getRootSpanId() {
    return this.rootSpanId;
  }
}

// Auto-cleanup every hour
setInterval(() => {
  tracer.cleanup();
}, 60 * 60 * 1000);

export interface KV {
  get<T>(_k: string): Promise<T | undefined>;
  set<T>(_k: string, _v: T, ttlMs?: number): Promise<void>;
  delete(_k: string): Promise<boolean>;
}

type Wrapped<T> = { v: T; x: number }; // value + expiresAtMs

export class TTLCache<T> {
  constructor(private kv: KV) {}

  private wrap(value: T, ttlMs?: number): Wrapped<T> {
    const now = Date.now();
    const expiresAt = typeof ttlMs === 'number' ? now + ttlMs : Number.POSITIVE_INFINITY;
    return { v: value, x: expiresAt };
  }

  async set(key: string, value: T, ttlMs?: number) {
    await this.kv.set<Wrapped<T>>(key, this.wrap(value, ttlMs), ttlMs);
  }

  async get(key: string): Promise<T | undefined> {
    const w = await this.kv.get<Wrapped<T>>(key);
    if (!w) return undefined;
    const now = Date.now();
    if (now >= w.x) {
      await this.kv.delete(key); // expire eagerly
      return undefined;
    }
    return w.v;
  }

  async ttlMs(key: string): Promise<number> {
    const w = await this.kv.get<Wrapped<T>>(key);
    if (!w) return 0;
    const now = Date.now();
    return Math.max(0, w.x - now);
  }
}

// Simple in-memory KV adapter for health cache
export class MemoryKV implements KV {
  private store = new Map<string, any>();

  async get<T>(k: string): Promise<T | undefined> {
    return this.store['get'](k);
  }

  async set<T>(k: string, v: T, ttlMs?: number): Promise<void> {
    this.store['set'](k, v);
    // For memory KV, we could implement native TTL cleanup here if needed
    // But the TTLCache wrapper handles expiration logic
  }

  async delete(k: string): Promise<boolean> {
    return this.store.delete(k);
  }

  clear(): void {
    this.store.clear();
  }
}

/**
 * Worker thread for WASM execution
 * Runs in isolated context with resource monitoring
 */

const { parentPort, workerData } = require('worker_threads');
const fs = require('fs');
const { performance } = require('perf_hooks');

// Extract worker configuration
const {
  wasmPath,
  functionName,
  args,
  seed,
  engineVersion,
  maxMemoryMB,
  trapNonFinite,
  enableProfiling
} = workerData;

// Initialize random seed for determinism
let randomState = parseInt(seed.substring(0, 8), 16);

// Linear Congruential Generator (LCG) constants from Numerical Recipes
// These are standard ANSI C LCG parameters - intentionally precise 32-bit integers
const LCG_MULTIPLIER = 1103515245;  // Standard LCG multiplier
const LCG_INCREMENT = 12345;         // Standard LCG increment
const LCG_MODULUS = 0x7fffffff;      // 2^31 - 1 (max 32-bit signed int)

function deterministicRandom() {
  randomState = (randomState * LCG_MULTIPLIER + LCG_INCREMENT) & LCG_MODULUS;
  return randomState / LCG_MODULUS;
}

// Override Math.random for determinism
Math.random = deterministicRandom;

// Track non-finite values
let nonFiniteDetected = false;
const originalNumber = Number;
const proxyNumber = new Proxy(Number, {
  construct(target, args) {
    const result = new target(...args);
    checkNonFinite(result, 'Number constructor');
    return result;
  }
});

function checkNonFinite(value, location) {
  if (!isFinite(value)) {
    parentPort.postMessage({
      type: 'non-finite',
      value: value.toString(),
      location
    });
    nonFiniteDetected = true;
    if (trapNonFinite) {
      throw new Error(`Non-finite value detected: ${value} at ${location}`);
    }
  }
  return value;
}

// Wrap math operations to detect NaN/Infinity
const mathOperations = ['sqrt', 'pow', 'log', 'exp', 'sin', 'cos', 'tan'];
mathOperations.forEach(op => {
  const original = Math[op];
  Math[op] = function(...args) {
    const result = original.apply(Math, args);
    checkNonFinite(result, `Math.${op}`);
    return result;
  };
});

async function executeWasm() {
  const startTime = performance.now();
  const startMemory = process.memoryUsage();

  try {
    // Send initial memory usage
    parentPort.postMessage({
      type: 'memory-usage',
      bytes: startMemory.heapUsed
    });

    // Read WASM file
    const wasmBuffer = fs.readFileSync(wasmPath);

    // Configure memory limits
    const memory = new WebAssembly.Memory({
      initial: 16, // 1MB initial (16 * 64KB pages)
      maximum: Math.floor((maxMemoryMB * 1024 * 1024) / 65536), // Convert MB to pages
    });

    // Track gas usage (simplified - counts operations)
    let gasUsed = 0;
    const gasLimit = 1000000;

    // Import object with resource tracking
    const importObject = {
      env: {
        memory,

        // Abort function for panics
        abort: (msg, file, line, column) => {
          throw new Error(`WASM abort: ${msg} at ${file}:${line}:${column}`);
        },

        // Seed for deterministic random
        seed: () => parseInt(seed.substring(8, 16), 16),

        // Gas metering
        consumeGas: (amount) => {
          gasUsed += amount;
          if (gasUsed > gasLimit) {
            throw new Error(`Gas limit exceeded: ${gasUsed}/${gasLimit}`);
          }
        },

        // Memory tracking
        trackMemory: () => {
          const usage = process.memoryUsage();
          parentPort.postMessage({
            type: 'memory-usage',
            bytes: usage.heapUsed
          });

          if (usage.heapUsed > maxMemoryMB * 1024 * 1024) {
            throw new Error(`Memory limit exceeded: ${usage.heapUsed} bytes`);
          }
        },

        // Math functions with NaN/Inf checking
        mathSqrt: (x) => checkNonFinite(Math.sqrt(x), 'wasm.sqrt'),
        mathPow: (x, y) => checkNonFinite(Math.pow(x, y), 'wasm.pow'),
        mathLog: (x) => checkNonFinite(Math.log(x), 'wasm.log'),

        // Console for debugging (limited)
        consoleLog: (ptr) => {
          if (enableProfiling) {
            console.log(`[WASM]: ${ptr}`);
          }
        }
      },

      // WASI preview1 imports (if needed)
      wasi_snapshot_preview1: {
        proc_exit: (code) => {
          throw new Error(`WASM process exit: ${code}`);
        },
        environ_get: () => 0,
        environ_sizes_get: () => 0,
        clock_time_get: () => Date.now() * 1000000, // nanoseconds
        fd_close: () => 0,
        fd_seek: () => 0,
        fd_write: () => 0,
        fd_read: () => 0,
        path_open: () => 0,
        random_get: (ptr, len) => {
          // Fill with deterministic "random" data
          const view = new Uint8Array(memory.buffer, ptr, len);
          for (let i = 0; i < len; i++) {
            view[i] = Math.floor(deterministicRandom() * 256);
          }
          return 0;
        }
      }
    };

    // Instantiate WASM module
    const wasmModule = await WebAssembly.instantiate(wasmBuffer, importObject);
    const wasmInstance = wasmModule.instance;

    // Check if function exists
    if (!wasmInstance.exports[functionName]) {
      throw new Error(`Function '${functionName}' not found in WASM module`);
    }

    // Monitor memory periodically during execution
    const memoryMonitor = setInterval(() => {
      const usage = process.memoryUsage();
      parentPort.postMessage({
        type: 'memory-usage',
        bytes: usage.heapUsed
      });
    }, 100);

    // Execute the function
    const wasmFunction = wasmInstance.exports[functionName];
    const result = wasmFunction(...args);

    // Stop memory monitoring
    clearInterval(memoryMonitor);

    // Final memory check
    const endMemory = process.memoryUsage();
    const cpuTime = performance.now() - startTime;

    // Send result
    parentPort.postMessage({
      type: 'result',
      result,
      cpuTime,
      gasUsed,
      memoryUsed: endMemory.heapUsed - startMemory.heapUsed,
      nonFiniteCount: nonFiniteDetected ? 1 : 0
    });

  } catch (error) {
    parentPort.postMessage({
      type: 'error',
      error: {
        message: error.message,
        stack: error.stack
      }
    });
    process.exit(1);
  }
}

// Execute and handle errors
executeWasm().catch(err => {
  parentPort.postMessage({
    type: 'error',
    error: {
      message: err.message,
      stack: err.stack
    }
  });
  process.exit(1);
});

