// Job types
export interface SimulationJobData {
  fundId: number;
  runs: number;
  timeHorizonYears: number;
  baselineId?: string;
  portfolioSize?: number;
  userId?: number;
  requestId?: string;
}

export interface SimulationJobResult {
  success: boolean;
  metrics?: {
    mean: number;
    median: number;
    p10: number;
    p90: number;
    min: number;
    max: number;
  };
  error?: string;
  durationMs?: number;
}

export interface JobProgressEvent {
  jobId: string;
  progress: number;
  message?: string;
}

export interface JobCompleteEvent {
  jobId: string;
  result: SimulationJobResult;
}

export interface JobFailedEvent {
