/**
 * Example: How to wire engine guards into Express routes
 * 
 * This shows how to protect simulation endpoints from NaN/Infinity leaks
 */

import type { Request, Response } from 'express';
import { assertFiniteDeep } from '../middleware/engine-guards';
// TODO: Import your actual engine/simulation functions
// import { runMonteCarlo, runSimulation } from '../engine/simulations';

// Example simulation endpoint with guard
export async function simulationHandler(req: Request, res: Response) {
  try {
    // Run your simulation/calculation
    // const result = await runMonteCarlo(req.body);
    const result = mockSimulation(req.body); // Replace with real engine

    // Guard against non-finite values
    const guard = assertFiniteDeep(result);
    if (!guard.ok) {
      // Log for debugging (include correlation ID if available)
      const correlationId = req.headers['x-correlation-id'] || 'unknown';
      const failure = guard as { ok: false; path: string; value: unknown; reason: string };
      console.error(`[ENGINE_NONFINITE] Correlation: ${correlationId}, Path: ${failure.path}, Reason: ${failure.reason}`);

      // Return 422 with error details
      return res["status"](422)["json"]({
        error: 'ENGINE_NONFINITE',
        path: failure.path,
        reason: failure.reason,
        correlationId,
        message: 'Calculation produced invalid numeric values'
      });
    }

    // Safe to return - no NaN/Infinity will leak
    res["json"](result);
  } catch (error) {
    console.error('Simulation error:', error);
    res["status"](500)["json"]({ error: 'SIMULATION_FAILED' });
  }
}

// Mock simulation for example (replace with real engine)
function mockSimulation(params: any) {
  return {
    fundSize: params.fundSize || 50000000,
    irr: 0.15,
    moic: 1.8,
    tvpi: 1.5,
    dpi: 0.3,
    percentiles: {
      '5': 0.8,
      '25': 1.2,
      '50': 1.5,
      '75': 2.0,
      '95': 3.5
    },
    simulations: [
      { year: 1, value: 45000000 },
      { year: 2, value: 42000000 },
      { year: 3, value: 48000000 },
      { year: 4, value: 65000000 },
      { year: 5, value: 90000000 }
    ]
  };
}

// Example: Wire into Express app
export function registerGuardedRoutes(app: any) {
  // Protected simulation endpoints
  app.post('/api/v2/simulate', simulationHandler);
  app.post('/api/v2/monte-carlo', simulationHandler);
  app.post('/api/v2/calculate', simulationHandler);

  // You can also add middleware for all routes
  app.use('/api/v2/*', (req: Request, res: Response, next: any) => {
    const originalJson = res.json;
    res.json = function(data: any) {
      const guard = assertFiniteDeep(data);
      if (!guard.ok) {
        const failure = guard as { ok: false; path: string; value: unknown; reason: string };
        console.error(`[ENGINE_NONFINITE] Response guard triggered at ${failure.path}`);
        return res["status"](422)["json"]({
          error: 'ENGINE_NONFINITE',
          path: failure.path,
          reason: failure.reason
        });
      }
      return originalJson.call(this, data);
    };
    next();
  });
}

/**
 * Server-Sent Events (SSE) Routes
 *
 * Provides real-time event streaming for clients that prefer SSE over WebSocket.
 * SSE is simpler, uses standard HTTP, and automatically reconnects.
 */

import { Router } from 'express';
import type { Request, Response } from 'express';
import { logger } from '../logger';

const router = Router();

// Store active SSE connections per fund
const activeConnections = new Map<number, Set<Response>>();

// Event types that can be streamed
export type SSEEventType =
  | 'metrics:update'
  | 'simulation:progress'
  | 'simulation:complete'
  | 'allocation:changed'
  | 'scenario:updated'
  | 'forecast:ready'
  | 'heartbeat';

/**
 * GET /api/events/fund/:fundId
 *
 * Establish an SSE connection for real-time fund events
 * Client will receive events as they occur
 */
router['get']('/api/events/fund/:fundId', (req: Request, res: Response) => {
  const fundIdParam = req.params['fundId'];
  const fundId = parseInt(fundIdParam || '0', 10);

  if (isNaN(fundId) || fundId <= 0) {
    return res['status'](400)['json']({
      error: 'Invalid fund ID',
      message: 'Fund ID must be a positive integer',
    });
  }

  // Parse optional event type filter
  const eventTypesParam = req.query['eventTypes'];
  let eventTypes: string[] | undefined;
  if (typeof eventTypesParam === 'string') {
    eventTypes = eventTypesParam.split(',').map((t) => t.trim());
  }

  // Set SSE headers
  res.setHeader('Content-Type', 'text/event-stream');
  res.setHeader('Cache-Control', 'no-cache');
  res.setHeader('Connection', 'keep-alive');
  res.setHeader('X-Accel-Buffering', 'no'); // Disable nginx buffering
  res.flushHeaders();

  // Register this connection
  if (!activeConnections.has(fundId)) {
    activeConnections.set(fundId, new Set());
  }
  activeConnections.get(fundId)!.add(res);

  // Store event type filter on the response object
  (res as any).eventTypeFilter = eventTypes;
  (res as any).fundId = fundId;

  logger.info('SSE connection established', {
    fundId,
    eventTypes,
    connectionCount: activeConnections.get(fundId)!.size,
  });

  // Send initial connection event
  sendSSEEvent(res, 'connected', {
    fundId,
    timestamp: new Date().toISOString(),
    message: 'SSE connection established',
  });

  // Heartbeat to keep connection alive (every 30 seconds)
  const heartbeatInterval = setInterval(() => {
    if (!res.writableEnded) {
      sendSSEEvent(res, 'heartbeat', {
        timestamp: new Date().toISOString(),
        fundId,
      });
    }
  }, 30000);

  // Clean up on disconnect
  req.on('close', () => {
    clearInterval(heartbeatInterval);
    const fundConnections = activeConnections.get(fundId);
    if (fundConnections) {
      fundConnections.delete(res);
      if (fundConnections.size === 0) {
        activeConnections.delete(fundId);
      }
    }
    logger.info('SSE connection closed', {
      fundId,
      remainingConnections: activeConnections.get(fundId)?.size || 0,
    });
  });
});

/**
 * GET /api/events/simulation/:simulationId
 *
 * SSE stream for Monte Carlo simulation progress
 * Streams progress updates and final results
 */
router['get']('/api/events/simulation/:simulationId', (req: Request, res: Response) => {
  const simulationId = req.params['simulationId'];

  if (!simulationId) {
    return res['status'](400)['json']({
      error: 'Invalid simulation ID',
      message: 'Simulation ID is required',
    });
  }

  // Set SSE headers
  res.setHeader('Content-Type', 'text/event-stream');
  res.setHeader('Cache-Control', 'no-cache');
  res.setHeader('Connection', 'keep-alive');
  res.setHeader('X-Accel-Buffering', 'no');
  res.flushHeaders();

  logger.info('SSE connection for simulation established', { simulationId });

  // Send initial connection event
  sendSSEEvent(res, 'simulation:connected', {
    simulationId,
    timestamp: new Date().toISOString(),
    message: 'Connected to simulation progress stream',
  });

  // Register for simulation updates
  const simulationConnections = getSimulationConnections(simulationId);
  simulationConnections.add(res);

  // Heartbeat
  const heartbeatInterval = setInterval(() => {
    if (!res.writableEnded) {
      sendSSEEvent(res, 'heartbeat', {
        timestamp: new Date().toISOString(),
        simulationId,
      });
    }
  }, 15000);

  // Clean up on disconnect
  req.on('close', () => {
    clearInterval(heartbeatInterval);
    simulationConnections.delete(res);
    logger.info('Simulation SSE connection closed', { simulationId });
  });
});

// Simulation connections storage
const simulationConnections = new Map<string, Set<Response>>();

function getSimulationConnections(simulationId: string): Set<Response> {
  if (!simulationConnections.has(simulationId)) {
    simulationConnections.set(simulationId, new Set());
  }
  return simulationConnections.get(simulationId)!;
}

/**
 * Send an SSE event to a specific response stream
 */
function sendSSEEvent(res: Response, eventType: string, data: unknown): void {
  if (res.writableEnded) return;

  try {
    res.write(`event: ${eventType}\n`);
    res.write(`data: ${JSON.stringify(data)}\n\n`);
  } catch (error) {
    logger.error('Failed to send SSE event', { eventType, error });
  }
}

/**
 * Broadcast an event to all SSE connections for a fund
 */
export function broadcastFundEvent(
  fundId: number,
  eventType: SSEEventType,
  data: unknown
): void {
  const connections = activeConnections.get(fundId);
  if (!connections || connections.size === 0) return;

  const payload = {
    ...((data as object) || {}),
    fundId,
    eventType,
    timestamp: new Date().toISOString(),
  };

  connections.forEach((res) => {
    // Check event type filter if set
    const filter = (res as any).eventTypeFilter as string[] | undefined;
    if (!filter || filter.includes(eventType)) {
      sendSSEEvent(res, eventType, payload);
    }
  });

  logger.debug('SSE event broadcast', {
    fundId,
    eventType,
    recipientCount: connections.size,
  });
}

/**
 * Broadcast simulation progress to connected clients
 */
export function broadcastSimulationProgress(
  simulationId: string,
  progress: {
    completedIterations: number;
    totalIterations: number;
    percentComplete: number;
    estimatedTimeRemaining?: number;
    currentPhase?: string;
  }
): void {
  const connections = getSimulationConnections(simulationId);
  if (connections.size === 0) return;

  const payload = {
    simulationId,
    ...progress,
    timestamp: new Date().toISOString(),
  };

  connections.forEach((res) => {
    sendSSEEvent(res, 'simulation:progress', payload);
  });
}

/**
 * Broadcast simulation completion
 */
export function broadcastSimulationComplete(
  simulationId: string,
  results: {
    status: 'completed' | 'failed';
    summary?: unknown;
    error?: string;
  }
): void {
  const connections = getSimulationConnections(simulationId);
  if (connections.size === 0) return;

  const payload = {
    simulationId,
    ...results,
    timestamp: new Date().toISOString(),
  };

  connections.forEach((res) => {
    sendSSEEvent(res, 'simulation:complete', payload);
    // Close the connection after sending completion
    res.end();
  });

  // Clean up simulation connections
  simulationConnections.delete(simulationId);
}

/**
 * Get SSE connection statistics
 */
export function getSSEStats(): {
  totalFundConnections: number;
  totalSimulationConnections: number;
  fundConnectionsPerFund: Record<number, number>;
  activeSimulations: string[];
} {
  const fundConnectionsPerFund: Record<number, number> = {};
  let totalFundConnections = 0;

  activeConnections.forEach((connections, fundId) => {
    fundConnectionsPerFund[fundId] = connections.size;
    totalFundConnections += connections.size;
  });

  let totalSimulationConnections = 0;
  simulationConnections.forEach((connections) => {
    totalSimulationConnections += connections.size;
  });

  return {
    totalFundConnections,
    totalSimulationConnections,
    fundConnectionsPerFund,
    activeSimulations: Array.from(simulationConnections.keys()),
  };
}

export default router;

/**
 * Timeline API Routes
 *
 * RESTful endpoints for fund timeline and snapshot management
 * Routes are thin wrappers that delegate business logic to TimeTravelAnalyticsService
 */
import { funds } from '@shared/schema';
import { eq } from 'drizzle-orm';
import { Router } from 'express';
import type { Express } from 'express';
import { z } from 'zod';
import { db } from '../db';
import { NotFoundError } from '../errors';
import { logger } from '../logger';
import { recordBusinessMetric } from '../metrics';
import { asyncHandler } from '../middleware/async';
import { validateRequest } from '../middleware/validation';
import { TimeTravelAnalyticsService, type Cache } from '../services/time-travel-analytics';

/**
 * Create timeline router with service dependency injection
 */

/**
 * Cache adapter bridges Express app.locals.cache to service Cache interface
 */
function createCacheAdapter(appLocalsCache: unknown): Cache | undefined {
  if (!appLocalsCache) return undefined;

  return {
    async get(key: string): Promise<string | null> {
      return appLocalsCache.get(key);
    },
    async set(key: string, value: string, ttlSeconds?: number): Promise<void> {
      return appLocalsCache.set(key, value, { EX: ttlSeconds });
    },
  };
}

/**
 * Create timeline router with service dependency injection
 */
export function createTimelineRouter(service: TimeTravelAnalyticsService) {
  const router = Router();

// Timeline range schema
const timelineRangeSchema = z.object({
  fundId: z.coerce.number().int().positive(),
  startTime: z.string().datetime().optional(),
  endTime: z.string().datetime().optional(),
  limit: z.coerce.number().int().min(1).max(1000).default(100),
  offset: z.coerce.number().int().min(0).default(0),
});

// Point-in-time query schema
const pointInTimeSchema = z.object({
  fundId: z.coerce.number().int().positive(),
  timestamp: z.string().datetime(),
  includeEvents: z.coerce.boolean().default(false),
});

// Snapshot creation schema
const createSnapshotSchema = z.object({
  fundId: z.coerce.number().int().positive(),
  type: z.enum(['manual', 'scheduled', 'auto']).default('manual'),
  description: z.string().optional(),
});

  /**
   * GET /api/timeline/:fundId
   * Get timeline of events and snapshots for a fund
   */
  router.get(
    '/:fundId',
    validateRequest({
      params: z.object({ fundId: z.coerce.number() }),
      query: timelineRangeSchema.omit({ fundId: true }),
    }),
    asyncHandler(async (req, res) => {
      const startTimer = Date.now();
      const fundIdNum = parseInt(req.params.fundId, 10);
      const startTimeStr = typeof req.query.startTime === 'string' ? req.query.startTime : undefined;
      const endTimeStr = typeof req.query.endTime === 'string' ? req.query.endTime : undefined;
      const limitNum = typeof req.query.limit === 'string' ? parseInt(req.query.limit, 10) : 100;
      const offsetNum = typeof req.query.offset === 'string' ? parseInt(req.query.offset, 10) : 0;

      // Delegate to service
      const result = await service.getTimelineEvents(fundIdNum, {
        ...(startTimeStr && { startTime: new Date(startTimeStr) }),
        ...(endTimeStr && { endTime: new Date(endTimeStr) }),
        limit: limitNum,
        offset: offsetNum,
      });

      recordBusinessMetric('timeline_query', 'success', Date.now() - startTimer);
      res.json(result);
    })
  );

  /**
   * GET /api/timeline/:fundId/state
   * Get fund state at a specific point in time
   */
  router.get(
    '/:fundId/state',
    validateRequest({
      params: z.object({ fundId: z.coerce.number() }),
      query: pointInTimeSchema.omit({ fundId: true }),
    }),
    asyncHandler(async (req, res) => {
      const startTimer = Date.now();
      const fundIdNum = parseInt(req.params.fundId, 10);
      const timestampStr = typeof req.query.timestamp === 'string' ? req.query.timestamp : '';
      const includeEventsFlag = typeof req.query.includeEvents === 'string' ? req.query.includeEvents === 'true' : false;

      if (!timestampStr) {
        throw new NotFoundError('timestamp is required');
      }

      const targetTime = new Date(timestampStr);

      // Delegate to service (service handles caching)
      const response = await service.getStateAtTime(fundIdNum, targetTime, includeEventsFlag);

      // Check if result came from cache by seeing if it's very fast
      const duration = Date.now() - startTimer;
      const metricType = duration < 10 ? 'cache_hit' : 'success';

      recordBusinessMetric('state_query', metricType, duration);
      res.json(response);
    })
  );

  /**
   * POST /api/timeline/:fundId/snapshot
   * Create a new snapshot for a fund
   */
  router.post(
    '/:fundId/snapshot',
    validateRequest({
      params: z.object({ fundId: z.coerce.number() }),
      body: createSnapshotSchema.omit({ fundId: true }),
    }),
    asyncHandler(async (req, res) => {
      const startTimer = Date.now();
      const fundIdNum = parseInt(req.params.fundId, 10);
      const { type, _description } = req.body;

      // Verify fund exists
      const fund = await db.query.funds.findFirst({
        where: eq(funds.id, fundIdNum),
      });

      if (!fund) {
        throw new NotFoundError(`Fund ${fundIdNum} not found`);
      }

      // Get queue from providers
      const providers = (req as { app: { locals: { providers?: { queue?: { enabled: boolean } } } } }).app.locals.providers;

      // Only create snapshot if queues are enabled
      if (!providers.queue?.enabled) {
        throw new Error('Background queues not available in this environment');
      }

      // For development mode, just return a mock response
      logger.info('Snapshot creation requested (dev mode)', {
        fundId: fundIdNum,
        type,
      });

      recordBusinessMetric('snapshot_creation', 'queued', Date.now() - startTimer);

      res.status(202).json({
        message: 'Snapshot creation requested (dev mode - no background processing)',
        fundId: fundIdNum,
        type,
        estimatedCompletion: new Date(Date.now() + 30000).toISOString(),
      });
    })
  );

  /**
   * GET /api/timeline/:fundId/compare
   * Compare fund states at two different times
   */
  router.get(
    '/:fundId/compare',
    validateRequest({
      params: z.object({ fundId: z.coerce.number() }),
      query: z.object({
        timestamp1: z.string().datetime(),
        timestamp2: z.string().datetime(),
        includeDiff: z.coerce.boolean().default(true),
      }),
    }),
    asyncHandler(async (req, res) => {
      const startTimer = Date.now();
      const { fundId } = req.params;
      const { timestamp1, timestamp2, includeDiff } = req.query;

      const fundIdNum = parseInt(fundId, 10);
      const ts1 = typeof timestamp1 === 'string' ? timestamp1 : '';
      const ts2 = typeof timestamp2 === 'string' ? timestamp2 : '';

      if (!ts1 || !ts2) {
        throw new NotFoundError('Both timestamp1 and timestamp2 are required');
      }

      // Delegate to service
      const result = await service.compareStates(
        fundIdNum,
        new Date(ts1),
        new Date(ts2),
        includeDiff !== false
      );

      recordBusinessMetric('state_comparison', 'success', Date.now() - startTimer);
      res.json(result);
    })
  );

  /**
   * GET /api/timeline/events/latest
   * Get latest events across all funds (for admin dashboard)
   */
  router.get(
    '/events/latest',
    validateRequest({
      query: z.object({
        limit: z.coerce.number().int().min(1).max(100).default(20),
        eventTypes: z.array(z.string()).optional(),
      }),
    }),
    asyncHandler(async (req, res) => {
      const limitNum = typeof req.query.limit === 'string' ? parseInt(req.query.limit, 10) : 20;
      const eventTypes = Array.isArray(req.query.eventTypes) ? req.query.eventTypes : undefined;

      // Delegate to service
      const result = await service.getLatestEvents(limitNum, eventTypes);

      res.json(result);
    })
  );

  return router;
}

/**
 * Default export: instantiate service and create router
 *
 * Cache is lazily accessed from req.app.locals.cache at runtime.
 * This factory allows cache integration when app context is available.
 */
function createDefaultTimelineRouter(app?: Express) {
  const cache = app ? createCacheAdapter((app as { locals: { cache?: unknown } }).locals.cache) : undefined;
  const timelineService = new TimeTravelAnalyticsService(db, cache);
  return createTimelineRouter(timelineService);
}

