// HuggingFace (native fetch)
async function askHuggingFace(prompt: string, model: string) {
  const started = Date.now();
  const r = await fetch(`https://api-inference.huggingface.co/models/${model}`, {
    method: 'POST',
    headers: {
      'Authorization': `Bearer ${process.env["HF_TOKEN"] ?? ''}`,
      'Content-Type': 'application/json'
    },
    body: JSON.stringify({
      inputs: prompt,
      parameters: { max_new_tokens: 2048, temperature: 0.3, return_full_text: false }
    })
  });
  if (!r.ok) throw new Error(`HF ${model} -> ${r.status}`);
  const j = await r.json();
  const text = Array.isArray(j) ? (j[0]?.['generated_text'] ?? '') : (j?.['generated_text'] ?? '');
  return {
    text,
    usage: {
      inputTokens: Math.ceil(prompt.length / 4),
      outputTokens: Math.ceil((text?.length ?? 0) / 4),
      costUsd: 0.15
    },
    elapsed: Date.now() - started
  };
}

const __userText = (messages: ChatMessage[]) =>
  messages.find(m => m.role === 'user')?.content ?? '';

export const AIRouter = {
  async call(providerId: string, messages: ChatMessage[], _opts?: Record<string, unknown>) {
    const prompt = __userText(messages);

    if (providerId.startsWith('ollama:')) {
      const model = providerId.slice('ollama:'.length);
      return askOllama(prompt, model);
    }

    if (providerId.startsWith('hf:')) {
      const model = providerId.slice('hf:'.length);
      return askHuggingFace(prompt, model);
    }

    // Wire to your existing cloud functions (budgeting/retry already there)
    if (providerId === 'gpt' || providerId === 'gpt4') {
      const r = await askGPT(prompt);
      return { text: r.text ?? '', usage: { inputTokens: r.usage?.prompt_tokens ?? 0, outputTokens: r.usage?.completion_tokens ?? 0, costUsd: r.cost_usd ?? 0 } };
    }
    if (providerId === 'gemini') {
      const r = await askGemini(prompt);
      return { text: r.text ?? '', usage: { inputTokens: r.usage?.prompt_tokens ?? 0, outputTokens: r.usage?.completion_tokens ?? 0, costUsd: r.cost_usd ?? 0 } };
    }
    if (providerId === 'deepseek') {
      const r = await askDeepSeek(prompt);
      return { text: r.text ?? '', usage: { inputTokens: r.usage?.prompt_tokens ?? 0, outputTokens: r.usage?.completion_tokens ?? 0, costUsd: r.cost_usd ?? 0 } };
    }
    if (providerId === 'claude') {
      const r = await askClaude(prompt);
      return { text: r.text ?? '', usage: { inputTokens: r.usage?.prompt_tokens ?? 0, outputTokens: r.usage?.completion_tokens ?? 0, costUsd: r.cost_usd ?? 0 } };
    }

    throw new Error(`Unknown providerId: ${providerId}`);
  }
};

export default AIRouter;

/**
 * Construction Forecast Calculator
 *
 * Generates J-curve-based forecasts for funds with no investments yet.
 * Returns construction-phase projections using pure mathematical models.
 *
 * Source: 'construction_forecast'
 */

import Decimal from 'decimal.js';
import type { FeeProfile } from '@shared/schemas/fee-profile';
import { computeJCurvePath, type JCurveConfig, type JCurvePath } from '@shared/lib/jcurve';
import { computeFeeBasisTimeline, type FeeBasisConfig } from '@shared/lib/fund-math';
import { getFundAge, getLifecycleStage, isConstructionPhase } from '@shared/lib/lifecycle-rules';

/**
 * Construction forecast configuration
 */
export interface ConstructionForecastConfig {
  /** Fund size (committed capital) */
  fundSize: Decimal;

  /** Fund establishment date */
  establishmentDate: Date | string;

  /** Target TVPI multiple (e.g., 2.5) */
  targetTVPI: number;

  /** Investment period in years (default 5) */
  investmentPeriodYears?: number;

  /** Total fund life in years (default 10) */
  fundLifeYears?: number;

  /** Fee profile (optional) */
  feeProfile?: FeeProfile;

  /** NAV calculation mode */
  navCalculationMode?: 'standard' | 'fee-adjusted';

  /** Final distribution coefficient (default 0.7) */
  finalDistributionCoefficient?: number;
}

/**
 * Construction forecast result
 */
export interface ConstructionForecast {
  /** Forecast source identifier */
  source: 'construction_forecast';

  /** Current metrics (quarter 0) */
  current: {
    tvpi: number;
    dpi: number;
    rvpi: number;
    nav: Decimal;
    calledCapital: Decimal;
    distributions: Decimal;
  };

  /** Projected metrics (final quarter) */
  projected: {
    tvpi: number;
    dpi: number;
    rvpi: number;
    nav: Decimal;
    calledCapital: Decimal;
    distributions: Decimal;
  };

  /** Full J-curve path */
  jCurvePath: JCurvePath;

  /** Fund lifecycle metadata */
  metadata: {
    fundAge: ReturnType<typeof getFundAge>;
    lifecycleStage: ReturnType<typeof getLifecycleStage>;
    isConstruction: boolean;
  };
}

/**
 * Construction Forecast Calculator
 *
 * Generates J-curve forecasts for empty funds using mathematical models.
 */
export class ConstructionForecastCalculator {
  /**
   * Generate construction forecast
   *
   * @param config - Forecast configuration
   * @returns Construction forecast with J-curve path
   */
  static generateForecast(config: ConstructionForecastConfig): ConstructionForecast {
    const {
      fundSize,
      establishmentDate,
      targetTVPI,
      investmentPeriodYears = 5,
      fundLifeYears = 10,
      feeProfile,
      navCalculationMode = 'standard',
      finalDistributionCoefficient = 0.7
    } = config;

    // Calculate fund age
    const fundAge = getFundAge(establishmentDate);
    const lifecycleStage = getLifecycleStage(fundAge, investmentPeriodYears);
    const hasInvestments = false; // Construction phase by definition
    const isConstruction = isConstructionPhase(fundAge, hasInvestments);

    // Number of quarters in fund life
    const numQuarters = fundLifeYears * 4;

    // Compute fee basis timeline if fee profile provided
    let feeTimelinePerPeriod: Decimal[] = Array(numQuarters + 1).fill(new Decimal(0));
    if (feeProfile) {
      const feeBasisConfig: FeeBasisConfig = {
        fundSize,
        numQuarters,
        feeProfile
      };
      const feeBasisTimeline = computeFeeBasisTimeline(feeBasisConfig);
      // Extract management fees from each period
      feeTimelinePerPeriod = feeBasisTimeline.periods.map((p) => p.managementFees);
    }

    // Configure J-curve computation
    const jCurveConfig: JCurveConfig = {
      kind: 'logistic',
      horizonYears: fundLifeYears,
      investYears: investmentPeriodYears,
      targetTVPI: new Decimal(targetTVPI),
      step: 'quarter',
      navCalculationMode,
      finalDistributionCoefficient,
    };

    // Compute J-curve path
    const jCurvePath = computeJCurvePath(jCurveConfig, feeTimelinePerPeriod);

    // Extract current metrics (quarter 0) from separate arrays
    const tvpi0 = jCurvePath.tvpi[0];
    const dpi0 = jCurvePath.dpi[0];
    const nav0 = jCurvePath.nav[0];
    const calls0 = jCurvePath.calls[0];

    if (!tvpi0 || !nav0) {
      throw new Error('J-curve computation failed: no data points');
    }

    const current = {
      tvpi: tvpi0.toNumber(),
      dpi: dpi0?.toNumber() ?? 0,
      rvpi: tvpi0.minus(dpi0 ?? 0).toNumber(),
      nav: nav0,
      calledCapital: calls0 ?? new Decimal(0),
      distributions: nav0.times(dpi0 ?? 0),
    };

    // Extract projected metrics (final quarter)
    const lastIdx = jCurvePath.tvpi.length - 1;
    const tvpiFinal = jCurvePath.tvpi[lastIdx];
    const dpiFinal = jCurvePath.dpi[lastIdx];
    const navFinal = jCurvePath.nav[lastIdx];
    const callsFinal = jCurvePath.calls[lastIdx];

    if (!tvpiFinal || !navFinal) {
      throw new Error('J-curve computation failed: no final point');
    }

    const projected = {
      tvpi: tvpiFinal.toNumber(),
      dpi: dpiFinal?.toNumber() ?? 0,
      rvpi: tvpiFinal.minus(dpiFinal ?? 0).toNumber(),
      nav: navFinal,
      calledCapital: callsFinal ?? fundSize,
      distributions: navFinal.times(dpiFinal ?? 0),
    };

    return {
      source: 'construction_forecast',
      current,
      projected,
      jCurvePath,
      metadata: {
        fundAge,
        lifecycleStage,
        isConstruction
      }
    };
  }

  /**
   * Check if fund is eligible for construction forecast
   *
   * @param establishmentDate - Fund establishment date
   * @param hasInvestments - Whether fund has any investments
   * @returns True if eligible
   */
  static isEligible(
    establishmentDate: Date | string,
    hasInvestments: boolean
  ): boolean {
    const fundAge = getFundAge(establishmentDate);
    return isConstructionPhase(fundAge, hasInvestments);
  }
}

/**
 * Advanced Database Connection Pool Manager
 *
 * Production-ready connection pooling with:
 * - Automatic pool sizing based on load
 * - Connection health monitoring
 * - Graceful degradation under high load
 * - Memory pressure detection
 * - Detailed metrics and monitoring
 *
 * @author Claude Code
 * @version 1.0 - Production Ready
 */

import type { PoolClient } from '@neondatabase/serverless';
import { Pool } from '@neondatabase/serverless';
import { EventEmitter } from 'events';

// ============================================================================
// INTERFACES
// ============================================================================

export interface PoolConfig {
  connectionString: string;
  minConnections?: number;
  maxConnections?: number;
  idleTimeoutMs?: number;
  connectionTimeoutMs?: number;
  acquireTimeoutMs?: number;
  maxRetries?: number;
  healthCheckIntervalMs?: number;
  enableMetrics?: boolean;
}

export interface PoolMetrics {
  totalConnections: number;
  activeConnections: number;
  idleConnections: number;
  pendingRequests: number;
  connectionsCreated: number;
  connectionsDestroyed: number;
  connectionErrors: number;
  averageQueryTime: number;
  peakConnections: number;
  lastHealthCheck: Date;
  memoryUsageMB: number;
}

export interface ConnectionWrapper {
  client: PoolClient;
  acquired: Date;
  lastActivity: Date;
  queryCount: number;
  isHealthy: boolean;
}

// ============================================================================
// ADVANCED POOL MANAGER
// ============================================================================

export class DatabasePoolManager extends EventEmitter {
  private pools: Map<string, Pool> = new Map();
  private poolConfigs: Map<string, PoolConfig> = new Map();
  private metrics: Map<string, PoolMetrics> = new Map();
  private healthCheckIntervals: Map<string, NodeJS.Timeout> = new Map();
  private activeConnections: Map<string, Set<ConnectionWrapper>> = new Map();

  // Default configuration
  private readonly defaultConfig: Required<PoolConfig> = {
    connectionString: '',
    minConnections: 2,
    maxConnections: 10,
    idleTimeoutMs: 30000,
    connectionTimeoutMs: 5000,
    acquireTimeoutMs: 10000,
    maxRetries: 3,
    healthCheckIntervalMs: 60000,
    enableMetrics: true
  };

  /**
   * Create or get existing pool with enhanced configuration
   */
  async createPool(poolId: string, config: PoolConfig): Promise<Pool> {
    if (this.pools.has(poolId)) {
      return this.pools.get(poolId)!;
    }

    const fullConfig = { ...this.defaultConfig, ...config };
    this.poolConfigs.set(poolId, fullConfig);

    // Create pool with advanced configuration
    const pool = new Pool({
      connectionString: fullConfig.connectionString,
      max: fullConfig.maxConnections,
      min: fullConfig.minConnections,
      idleTimeoutMillis: fullConfig.idleTimeoutMs,
      connectionTimeoutMillis: fullConfig.connectionTimeoutMs,
    });

    // Initialize metrics
    this.initializeMetrics(poolId);

    // Setup connection event handlers
    this.setupPoolEventHandlers(poolId, pool);

    // Start health monitoring
    if (fullConfig.enableMetrics) {
      this.startHealthMonitoring(poolId);
    }

    this.pools.set(poolId, pool);
    this.activeConnections.set(poolId, new Set());

    this.emit('poolCreated', { poolId, config: fullConfig });

    return pool;
  }

  /**
   * Get pool with automatic scaling based on load
   */
  async getPool(poolId: string): Promise<Pool> {
    const pool = this.pools.get(poolId);
    if (!pool) {
      throw new Error(`Pool ${poolId} not found. Create it first with createPool()`);
    }

    // Check if pool needs scaling
    await this.checkPoolScaling(poolId);

    return pool;
  }

  /**
   * Acquire connection with enhanced tracking
   */
  async acquireConnection(poolId: string): Promise<ConnectionWrapper> {
    const pool = await this.getPool(poolId);
    const startTime = Date.now();

    try {
      const client = await pool.connect();
      const wrapper: ConnectionWrapper = {
        client,
        acquired: new Date(),
        lastActivity: new Date(),
        queryCount: 0,
        isHealthy: true
      };

      // Track active connection
      this.activeConnections.get(poolId)!.add(wrapper);

      // Update metrics
      this.updateAcquisitionMetrics(poolId, Date.now() - startTime);

      return wrapper;

    } catch (error) {
      this.updateErrorMetrics(poolId, error);
      throw error;
    }
  }

  /**
   * Release connection with cleanup
   */
  async releaseConnection(poolId: string, wrapper: ConnectionWrapper): Promise<void> {
    try {
      // Update activity
      wrapper.lastActivity = new Date();

      // Release the actual connection
      wrapper.client.release();

      // Remove from tracking
      this.activeConnections.get(poolId)?.delete(wrapper);

      this.emit('connectionReleased', { poolId, queryCount: wrapper.queryCount });

    } catch (error) {
      this.updateErrorMetrics(poolId, error);
      throw error;
    }
  }

  /**
   * Execute query with automatic connection management
   */
  async executeQuery<T = unknown>(poolId: string, query: string, params?: unknown[]): Promise<T> {
    const wrapper = await this.acquireConnection(poolId);
    const startTime = Date.now();

    try {
      // Update wrapper activity
      wrapper.lastActivity = new Date();
      wrapper.queryCount++;

      // Execute query
      const result = await wrapper.client.query(query, params);

      // Update metrics
      const queryTime = Date.now() - startTime;
      this.updateQueryMetrics(poolId, queryTime);

      return result as T;

    } finally {
      await this.releaseConnection(poolId, wrapper);
    }
  }

  /**
   * Execute transaction with automatic rollback on error
   */
  async executeTransaction<T = unknown>(
    poolId: string,
    transactionFn: (client: PoolClient) => Promise<T>
  ): Promise<T> {
    const wrapper = await this.acquireConnection(poolId);

    try {
      await wrapper.client.query('BEGIN');
      wrapper.queryCount++;

      const result = await transactionFn(wrapper.client);

      await wrapper.client.query('COMMIT');
      wrapper.queryCount++;

      return result;

    } catch (error) {
      try {
        await wrapper.client.query('ROLLBACK');
        wrapper.queryCount++;
      } catch (rollbackError) {
        this.emit('rollbackError', { poolId, error: rollbackError });
      }
      throw error;

    } finally {
      await this.releaseConnection(poolId, wrapper);
    }
  }

  /**
   * Get detailed pool metrics
   */
  getMetrics(poolId: string): PoolMetrics | null {
    return this.metrics.get(poolId) || null;
  }

  /**
   * Get metrics for all pools
   */
  getAllMetrics(): Record<string, PoolMetrics> {
    const result: Record<string, PoolMetrics> = {};
    for (const [poolId, metrics] of this.metrics.entries()) {
      result[poolId] = { ...metrics };
    }
    return result;
  }

  /**
   * Check pool health and perform maintenance
   */
  async checkPoolHealth(poolId: string): Promise<boolean> {
    const pool = this.pools.get(poolId);
    const metrics = this.metrics.get(poolId);

    if (!pool || !metrics) {
      return false;
    }

    try {
      // Test connection
      const testWrapper = await this.acquireConnection(poolId);
      await testWrapper.client.query('SELECT 1');
      await this.releaseConnection(poolId, testWrapper);

      // Check for stale connections
      await this.cleanupStaleConnections(poolId);

      // Update health check timestamp
      metrics.lastHealthCheck = new Date();

      this.emit('healthCheckPassed', { poolId });
      return true;

    } catch (error) {
      this.emit('healthCheckFailed', { poolId, error });
      return false;
    }
  }

  /**
   * Scale pool based on current load
   */
  private async checkPoolScaling(poolId: string): Promise<void> {
    const metrics = this.metrics.get(poolId);
    const config = this.poolConfigs.get(poolId);

    if (!metrics || !config) return;

    const utilizationRatio = metrics.activeConnections / (config.maxConnections ?? 10);

    // Scale up if utilization is high
    if (utilizationRatio > 0.8 && (config.maxConnections ?? 10) < 20) {
      config.maxConnections = Math.min((config.maxConnections ?? 10) + 2, 20);
      this.emit('poolScaledUp', { poolId, newMaxConnections: config.maxConnections });
    }

    // Scale down if utilization is low for extended period
    if (utilizationRatio < 0.3 && (config.maxConnections ?? 10) > (config.minConnections ?? 2)) {
      config.maxConnections = Math.max((config.maxConnections ?? 10) - 1, config.minConnections ?? 2);
      this.emit('poolScaledDown', { poolId, newMaxConnections: config.maxConnections });
    }
  }

  /**
   * Clean up stale connections
   */
  private async cleanupStaleConnections(poolId: string): Promise<void> {
    const activeConns = this.activeConnections.get(poolId);
    if (!activeConns) return;

    const staleThreshold = 300000; // 5 minutes
    const now = Date.now();
    const staleConnections: ConnectionWrapper[] = [];

    for (const wrapper of activeConns) {
      if (now - wrapper.lastActivity.getTime() > staleThreshold) {
        staleConnections.push(wrapper);
      }
    }

    // Clean up stale connections
    for (const wrapper of staleConnections) {
      try {
        await this.releaseConnection(poolId, wrapper);
        this.emit('staleConnectionCleaned', { poolId });
      } catch (error) {
        this.emit('cleanupError', { poolId, error });
      }
    }
  }

  /**
   * Initialize metrics for a pool
   */
  private initializeMetrics(poolId: string): void {
    this.metrics.set(poolId, {
      totalConnections: 0,
      activeConnections: 0,
      idleConnections: 0,
      pendingRequests: 0,
      connectionsCreated: 0,
      connectionsDestroyed: 0,
      connectionErrors: 0,
      averageQueryTime: 0,
      peakConnections: 0,
      lastHealthCheck: new Date(),
      memoryUsageMB: 0
    });
  }

  /**
   * Setup pool event handlers
   */
  private setupPoolEventHandlers(poolId: string, pool: Pool): void {
    pool.on('connect', () => {
      const metrics = this.metrics.get(poolId)!;
      metrics.connectionsCreated++;
      metrics.totalConnections++;
      metrics.peakConnections = Math.max(metrics.peakConnections, metrics.totalConnections);
    });

    pool.on('remove', () => {
      const metrics = this.metrics.get(poolId)!;
      metrics.connectionsDestroyed++;
      metrics.totalConnections--;
    });

    pool.on('error', (error: unknown) => {
      this.updateErrorMetrics(poolId, error);
      this.emit('poolError', { poolId, error });
    });
  }

  /**
   * Start health monitoring for a pool
   */
  private startHealthMonitoring(poolId: string): void {
    const config = this.poolConfigs.get(poolId)!;

    const interval = setInterval(async () => {
      await this.checkPoolHealth(poolId);
      this.updateMemoryMetrics(poolId);
    }, config.healthCheckIntervalMs);

    this.healthCheckIntervals.set(poolId, interval);
  }

  /**
   * Update acquisition metrics
   */
  private updateAcquisitionMetrics(poolId: string, acquisitionTime: number): void {
    const metrics = this.metrics.get(poolId)!;
    metrics.activeConnections++;
    metrics.idleConnections = Math.max(0, metrics.totalConnections - metrics.activeConnections);
  }

  /**
   * Update query metrics
   */
  private updateQueryMetrics(poolId: string, queryTime: number): void {
    const metrics = this.metrics.get(poolId)!;

    // Update rolling average
    if (metrics.averageQueryTime === 0) {
      metrics.averageQueryTime = queryTime;
    } else {
      metrics.averageQueryTime = (metrics.averageQueryTime * 0.9) + (queryTime * 0.1);
    }
  }

  /**
   * Update error metrics
   */
  private updateErrorMetrics(poolId: string, error: unknown): void {
    const metrics = this.metrics.get(poolId)!;
    metrics.connectionErrors++;
    this.emit('error', { poolId, error });
  }

  /**
   * Update memory metrics
   */
  private updateMemoryMetrics(poolId: string): void {
    const metrics = this.metrics.get(poolId)!;
    const memUsage = process.memoryUsage();
    metrics.memoryUsageMB = memUsage.heapUsed / (1024 * 1024);
  }

  /**
   * Gracefully close a specific pool
   */
  async closePool(poolId: string): Promise<void> {
    const pool = this.pools.get(poolId);
    const interval = this.healthCheckIntervals.get(poolId);

    if (interval) {
      clearInterval(interval);
      this.healthCheckIntervals.delete(poolId);
    }

    if (pool) {
      await pool.end();
      this.pools.delete(poolId);
    }

    this.poolConfigs.delete(poolId);
    this.metrics.delete(poolId);
    this.activeConnections.delete(poolId);

    this.emit('poolClosed', { poolId });
  }

  /**
   * Gracefully close all pools
   */
  async closeAll(): Promise<void> {
    const closePromises = Array.from(this.pools.keys()).map(poolId =>
      this.closePool(poolId)
    );

    await Promise.all(closePromises);
    this.emit('allPoolsClosed');
  }

  /**
   * Get summary statistics across all pools
   */
  getSummaryStats() {
    const allMetrics = Array.from(this.metrics.values());

    return {
      totalPools: this.pools.size,
      totalConnections: allMetrics.reduce((sum, m) => sum + m.totalConnections, 0),
      totalActiveConnections: allMetrics.reduce((sum, m) => sum + m.activeConnections, 0),
      totalErrors: allMetrics.reduce((sum, m) => sum + m.connectionErrors, 0),
      averageQueryTime: allMetrics.reduce((sum, m) => sum + m.averageQueryTime, 0) / allMetrics.length,
      totalMemoryUsageMB: allMetrics.reduce((sum, m) => sum + m.memoryUsageMB, 0)
    };
  }
}

