/**
 * Strict TypeScript error interfaces for better type safety
 */

export interface RolloutMetrics {
  timestamp: number;
  errorRate: number;
  p99Latency: number;
  memoryUsage: number;
  cpuUsage: number;
  requestRate: number;
  successRate?: number;
}

export interface DeploymentError extends Error {
  stage?: string;
  metrics?: RolloutMetrics;
  rollbackTriggered?: boolean;
  deploymentId?: string;
  version?: string;
  confidence?: number;
}

export interface HealthCheckError extends Error {
  target: string;
  latency?: string;
  status?: number;
  checkType: 'connectivity' | 'endpoint' | 'metrics' | 'synthetic';
}

export interface DatabaseError extends Error {
  query?: string;
  queryParams?: any[];
  connectionId?: string;
  poolStats?: {
    total: number;
    idle: number;
    waiting: number;
  };
}

export interface IdempotencyError extends Error {
  key: string;
  requestHash: string;
  storedHash?: string;
  conflictType: 'different_request' | 'timeout' | 'storage_error';
  cacheHit?: boolean;
}

export interface RateLimitError extends Error {
  identifier: string;
  limit: number;
  windowMs: number;
  retryAfter: number;
  storeType: 'memory' | 'redis';
}

export interface ValidationError extends Error {
  field: string;
  value: any;
  constraint: string;
  validationRule: string;
}

// Error factory functions for type safety
export function createDeploymentError(
  message: string,
  options: Partial<DeploymentError> = {}
): DeploymentError {
  const error = new Error(message) as DeploymentError;
  Object.assign(error, options);
  error.name = 'DeploymentError';
  return error;
}

export function createHealthCheckError(
  message: string,
  target: string,
  checkType: HealthCheckError['checkType'],
  options: Partial<HealthCheckError> = {}
): HealthCheckError {
  const error = new Error(message) as HealthCheckError;
  error.target = target;
  error.checkType = checkType;
  Object.assign(error, options);
  error.name = 'HealthCheckError';
  return error;
}

export function createDatabaseError(
  message: string,
  options: Partial<DatabaseError> = {}
): DatabaseError {
  const error = new Error(message) as DatabaseError;
  Object.assign(error, options);
  error.name = 'DatabaseError';
  return error;
}

export function createIdempotencyError(
  message: string,
  key: string,
  requestHash: string,
  conflictType: IdempotencyError['conflictType'],
  options: Partial<IdempotencyError> = {}
): IdempotencyError {
  const error = new Error(message) as IdempotencyError;
  error.key = key;
  error.requestHash = requestHash;
  error.conflictType = conflictType;
  Object.assign(error, options);
  error.name = 'IdempotencyError';
  return error;
}

export function createRateLimitError(
  message: string,
  identifier: string,
  limit: number,
  windowMs: number,
  retryAfter: number,
  storeType: RateLimitError['storeType'],
  options: Partial<RateLimitError> = {}
): RateLimitError {
  const error = new Error(message) as RateLimitError;
  error.identifier = identifier;
  error.limit = limit;
  error.windowMs = windowMs;
  error.retryAfter = retryAfter;
  error.storeType = storeType;
  Object.assign(error, options);
  error.name = 'RateLimitError';
  return error;
}

export function createValidationError(
  message: string,
  field: string,
  value: any,
  constraint: string,
  validationRule: string,
  options: Partial<ValidationError> = {}
): ValidationError {
  const error = new Error(message) as ValidationError;
  error.field = field;
  error.value = value;
  error.constraint = constraint;
  error.validationRule = validationRule;
  Object.assign(error, options);
  error.name = 'ValidationError';
  return error;
}

// Type guards for error checking
export function isDeploymentError(error: Error): error is DeploymentError {
  return error.name === 'DeploymentError';
}

export function isHealthCheckError(error: Error): error is HealthCheckError {
  return error.name === 'HealthCheckError';
}

export function isDatabaseError(error: Error): error is DatabaseError {
  return error.name === 'DatabaseError';
}

export function isIdempotencyError(error: Error): error is IdempotencyError {
  return error.name === 'IdempotencyError';
}

export function isRateLimitError(error: Error): error is RateLimitError {
  return error.name === 'RateLimitError';
}

export function isValidationError(error: Error): error is ValidationError {
  return error.name === 'ValidationError';
}

/**
 * Input Sanitization Utilities
 *
 * Comprehensive input validation and sanitization for:
 * - XSS prevention
 * - SQL injection prevention
 * - NoSQL injection prevention
 * - Path traversal prevention
 * - Data type validation
 * - Financial data sanitization
 * - File upload validation
 */

// DOMPurify not available in server environment, using built-in sanitization
import validator from 'validator';
import { logValidationError, securityLogger } from './logger.js';
import { sanitizeInput } from './sanitizer.js';

// =============================================================================
// SANITIZATION CONFIGURATION
// =============================================================================

interface SanitizationOptions {
  allowedTags?: string[];
  allowedAttributes?: string[];
  maxLength?: number;
  trimWhitespace?: boolean;
  removeEmptyStrings?: boolean;
  normalizeUnicode?: boolean;
  strictMode?: boolean;
}

const DEFAULT_SANITIZATION_OPTIONS: SanitizationOptions = {
  allowedTags: [], // No HTML tags allowed by default
  allowedAttributes: [],
  maxLength: 10000,
  trimWhitespace: true,
  removeEmptyStrings: true,
  normalizeUnicode: true,
  strictMode: true
};

// Dangerous patterns to detect and block
// Note: HTML/script sanitization is now handled by sanitize-html library
const DANGEROUS_PATTERNS = [
  // XSS patterns - simplified since sanitize-html handles complex HTML
  /javascript:/gi,
  /vbscript:/gi,
  /on\w+\s*=/gi,
  /style\s*=.*expression\s*\(/gi,

  // SQL injection patterns
  /(\b(SELECT|INSERT|UPDATE|DELETE|DROP|CREATE|ALTER|EXEC|UNION)\b)/gi,
  /(\b(OR|AND)\s+\d+\s*=\s*\d+)/gi,
  /('|\"|`|;|--|\|\/\*|\*\/)/g,

  // NoSQL injection patterns
  /(\$where|\$ne|\$in|\$nin|\$gt|\$lt|\$gte|\$lte|\$exists|\$regex)/gi,

  // Path traversal patterns
  /(\.\.[\/\\]|[\/\\]\.\.|%2e%2e%2f|%2e%2e%5c|\.\.\/|\.\.\\)/gi,

  // Command injection patterns
  /(\||&|;|`|\$\(|\${|<|>)/g,

  // LDAP injection patterns
  /(\*|\(|\)|\\|\/|null|\0)/g
];

// =============================================================================
// CORE SANITIZATION FUNCTIONS
// =============================================================================

/**
 * Sanitize a string value with comprehensive security checks
 */
export function sanitizeString(
  value: unknown,
  options: SanitizationOptions = {}
): string {
  if (typeof value !== 'string') {
    if (value === null || value === undefined) return '';
    value = String(value);
  }

  const opts = { ...DEFAULT_SANITIZATION_OPTIONS, ...options };
  let sanitized = value as string;

  try {
    // Basic cleanup
    if (opts.trimWhitespace) {
      sanitized = sanitized.trim();
    }

    if (opts.removeEmptyStrings && sanitized.length === 0) {
      return '';
    }

    // Unicode normalization
    if (opts.normalizeUnicode) {
      sanitized = sanitized.normalize('NFC');
    }

    // Length validation
    if (opts.maxLength && sanitized.length > opts.maxLength) {
      if (opts.strictMode) {
        throw new Error(`Input exceeds maximum length of ${opts.maxLength} characters`);
      }
      sanitized = sanitized.substring(0, opts.maxLength);
    }

    // Basic HTML sanitization using sanitize-html library for proper security
    sanitized = sanitizeInput(sanitized);

    // Check for dangerous patterns
    if (opts.strictMode) {
      for (const pattern of DANGEROUS_PATTERNS) {
        if (pattern.test(sanitized)) {
          throw new Error(`Input contains potentially dangerous content: ${pattern.source}`);
        }
      }
    } else {
      // Remove dangerous patterns
      for (const pattern of DANGEROUS_PATTERNS) {
        sanitized = sanitized.replace(pattern, '');
      }
    }

    // Additional encoding for special characters
    sanitized = validator.escape(sanitized);

    return sanitized;

  } catch (error) {
    securityLogger.error('String sanitization failed', {
      originalValue: typeof value === 'string' ? value.substring(0, 100) : String(value),
      error: error instanceof Error ? error.message : 'Unknown error'
    });

    if (opts.strictMode) {
      throw error;
    }

    return ''; // Return empty string if sanitization fails in non-strict mode
  }
}

/**
 * Sanitize numeric input with range validation
 */
export function sanitizeNumber(
  value: unknown,
  options: {
    min?: number;
    max?: number;
    integer?: boolean;
    finite?: boolean;
    positive?: boolean;
  } = {}
): number {
  let num: number;

  if (typeof value === 'number') {
    num = value;
  } else if (typeof value === 'string') {
    // Remove any non-numeric characters except decimal point and minus sign
    const cleaned = value.replace(/[^0-9.-]/g, '');
    num = parseFloat(cleaned);
  } else {
    throw new Error('Value cannot be converted to number');
  }

  // Validation checks
  if (isNaN(num)) {
    throw new Error('Value is not a valid number');
  }

  if (options.finite && !isFinite(num)) {
    throw new Error('Value must be finite');
  }

  if (options.integer && !Number.isInteger(num)) {
    throw new Error('Value must be an integer');
  }

  if (options.positive && num <= 0) {
    throw new Error('Value must be positive');
  }

  if (options.min !== undefined && num < options.min) {
    throw new Error(`Value must be at least ${options.min}`);
  }

  if (options.max !== undefined && num > options.max) {
    throw new Error(`Value must be at most ${options.max}`);
  }

  return num;
}

/**
 * Sanitize financial amounts with proper validation
 */
export function sanitizeFinancialAmount(value: unknown): number {
  return sanitizeNumber(value, {
    min: 0,
    max: 1e12, // $1 trillion max
    finite: true
  });
}

/**
 * Sanitize percentage values
 */
export function sanitizePercentage(value: unknown, as100Based: boolean = false): number {
  const max = as100Based ? 100 : 1;
  return sanitizeNumber(value, {
    min: 0,
    max,
    finite: true
  });
}

/**
 * Sanitize email addresses
 */
export function sanitizeEmail(value: unknown): string {
  const str = sanitizeString(value, { maxLength: 254 });

  if (!validator.isEmail(str)) {
    throw new Error('Invalid email address format');
  }

  return validator.normalizeEmail(str) || str;
}

/**
 * Sanitize URLs
 */
export function sanitizeURL(value: unknown, options: {
  protocols?: string[];
  requireTLD?: boolean;
  requireProtocol?: boolean;
} = {}): string {
  const str = sanitizeString(value, { maxLength: 2048 });

  const opts = {
    protocols: options.protocols || ['http', 'https'],
    require_tld: options.requireTLD !== false,
    require_protocol: options.requireProtocol !== false
  };

  if (!validator.isURL(str, opts)) {
    throw new Error('Invalid URL format');
  }

  return str;
}

/**
 * Sanitize file paths to prevent directory traversal
 */
export function sanitizeFilePath(value: unknown): string {
  const str = sanitizeString(value, { maxLength: 255 });

  // Use sanitizeInput to remove any HTML/script injection attempts
  let cleaned = sanitizeInput(str);

  // Remove path traversal attempts - more comprehensive pattern
  cleaned = cleaned.replace(/\.\.[\/\\]/g, '').replace(/[\/\\]/g, '_');

  // Remove potentially dangerous characters
  const safe = cleaned.replace(/[<>:"|?*\0]/g, '');

  if (safe !== str) {
    securityLogger.warn('File path sanitization applied', {
      original: str,
      sanitized: safe
    });
  }

  return safe;
}

// =============================================================================
// OBJECT SANITIZATION
// =============================================================================

/**
 * Recursively sanitize an object
 */
export function sanitizeObject(
  obj: unknown,
  options: SanitizationOptions & {
    maxDepth?: number;
    allowedKeys?: string[];
    blockedKeys?: string[];
  } = {}
): unknown {
  const opts = { ...DEFAULT_SANITIZATION_OPTIONS, ...options };
  const maxDepth = opts.maxDepth || 10;

  function sanitizeRecursive(value: unknown, depth: number = 0): unknown {
    if (depth > maxDepth) {
      throw new Error('Object nesting too deep');
    }

    if (value === null || value === undefined) {
      return value;
    }

    if (typeof value === 'string') {
      return sanitizeString(value, opts);
    }

    if (typeof value === 'number') {
      return sanitizeNumber(value, { finite: true });
    }

    if (typeof value === 'boolean') {
      return value;
    }

    if (Array.isArray(value)) {
      return value.map(item => sanitizeRecursive(item, depth + 1));
    }

    if (typeof value === 'object') {
      const sanitized: Record<string, unknown> = {};

      for (const [key, val] of Object.entries(value)) {
        const sanitizedKey = sanitizeString(key, { maxLength: 100 });

        // Check key allowlist/blocklist
        if (opts.allowedKeys && !opts.allowedKeys.includes(sanitizedKey)) {
          continue;
        }

        if (opts.blockedKeys && opts.blockedKeys.includes(sanitizedKey)) {
          continue;
        }

        sanitized[sanitizedKey] = sanitizeRecursive(val, depth + 1);
      }

      return sanitized;
    }

    // For other types, convert to string and sanitize
    return sanitizeString(String(value), opts);
  }

  return sanitizeRecursive(obj);
}

// =============================================================================
// MONTE CARLO SPECIFIC SANITIZATION
// =============================================================================

/**
 * Sanitize Monte Carlo simulation configuration
 */
export function sanitizeMonteCarloConfig(config: unknown): Record<string, unknown> {
  if (!config || typeof config !== 'object') {
    throw new Error('Monte Carlo configuration must be an object');
  }

  const cfg = config as Record<string, unknown>;
  const sanitized: Record<string, unknown> = {};

  // Fund ID validation
  if (cfg.fundId !== undefined) {
    sanitized.fundId = sanitizeNumber(cfg.fundId, {
      integer: true,
      positive: true,
      max: 999999999
    });
  }

  // Simulation runs validation
  if (cfg.runs !== undefined) {
    sanitized.runs = sanitizeNumber(cfg.runs, {
      integer: true,
      min: 100,
      max: 50000
    });
  }

  // Time horizon validation
  if (cfg.timeHorizonYears !== undefined) {
    sanitized.timeHorizonYears = sanitizeNumber(cfg.timeHorizonYears, {
      integer: true,
      min: 1,
      max: 15
    });
  }

  // Portfolio size validation
  if (cfg.portfolioSize !== undefined) {
    sanitized.portfolioSize = sanitizeNumber(cfg.portfolioSize, {
      integer: true,
      positive: true,
      max: 1000
    });
  }

  // Baseline ID validation
  if (cfg.baselineId !== undefined) {
    sanitized.baselineId = sanitizeString(cfg.baselineId, {
      maxLength: 36 // UUID length
    });

    // Validate UUID format
    if (!validator.isUUID(sanitized.baselineId as string)) {
      throw new Error('Invalid baseline ID format');
    }
  }

  return sanitized;
}

/**
 * Sanitize financial distribution parameters
 */
export function sanitizeDistributionParams(params: unknown): Record<string, unknown> {
  if (!params || typeof params !== 'object') {
    throw new Error('Distribution parameters must be an object');
  }

  const prms = params as Record<string, unknown>;
  const sanitized: Record<string, unknown> = {};

  // Sanitize IRR parameters
  if (prms.irr) {
    const irr = prms.irr as { mean: unknown; volatility: unknown };
    sanitized.irr = {
      mean: sanitizeNumber(irr.mean, { min: -1, max: 10, finite: true }),
      volatility: sanitizeNumber(irr.volatility, { min: 0.01, max: 5, finite: true })
    };
  }

  // Sanitize multiple parameters
  if (prms.multiple) {
    const multiple = prms.multiple as { mean: unknown; volatility: unknown };
    sanitized.multiple = {
      mean: sanitizeNumber(multiple.mean, { min: 0, max: 100, finite: true }),
      volatility: sanitizeNumber(multiple.volatility, { min: 0.01, max: 10, finite: true })
    };
  }

  // Sanitize DPI parameters
  if (prms.dpi) {
    const dpi = prms.dpi as { mean: unknown; volatility: unknown };
    sanitized.dpi = {
      mean: sanitizeNumber(dpi.mean, { min: 0, max: 5, finite: true }),
      volatility: sanitizeNumber(dpi.volatility, { min: 0.01, max: 2, finite: true })
    };
  }

  return sanitized;
}

// =============================================================================
// VALIDATION ERROR HANDLING
// =============================================================================

export class SanitizationError extends Error {
  constructor(
    message: string,
    public _field?: string,
    public _originalValue?: unknown,
    public _sanitizedValue?: unknown
  ) {
    super(message);
    this.name = 'SanitizationError';
  }
}

/**
 * Create a sanitization middleware that validates and sanitizes request data
 */
export function createSanitizationMiddleware(options: {
  sanitizeBody?: boolean;
  sanitizeQuery?: boolean;
  sanitizeParams?: boolean;
  strictMode?: boolean;
  customSanitizers?: Record<string, (_value: unknown) => unknown>;
} = {}) {
  return (req: Record<string, unknown>, res: Record<string, unknown>, next: (error?: unknown) => void) => {
    try {
      const opts = {
        sanitizeBody: true,
        sanitizeQuery: true,
        sanitizeParams: true,
        strictMode: true,
        ...options
      };

      // Sanitize request body
      if (opts.sanitizeBody && req.body) {
        req.body = sanitizeObject(req.body, {
          strictMode: opts.strictMode,
          maxDepth: 5
        });

        // Apply custom sanitizers
        if (opts.customSanitizers) {
          for (const [field, sanitizer] of Object.entries(opts.customSanitizers)) {
            if (req.body[field] !== undefined) {
              req.body[field] = sanitizer(req.body[field]);
            }
          }
        }
      }

      // Sanitize query parameters
      if (opts.sanitizeQuery && req.query) {
        req.query = sanitizeObject(req.query, {
          strictMode: opts.strictMode,
          maxDepth: 3
        });
      }

      // Sanitize route parameters
      if (opts.sanitizeParams && req.params) {
        req.params = sanitizeObject(req.params, {
          strictMode: opts.strictMode,
          maxDepth: 2
        });
      }

      next();

    } catch (error) {
      logValidationError(
        'request_sanitization',
        { body: req.body, query: req.query, params: req.params },
        error instanceof Error ? error.message : 'Unknown sanitization error',
        { path: req.path, method: req.method }
      );

      res["status"](400)["json"]({
        error: 'Invalid input data',
        message: error instanceof Error ? error.message : 'Request contains invalid data',
        field: error instanceof SanitizationError ? error._field : undefined
      });
    }
  };
}

// =============================================================================
// UTILITY FUNCTIONS
// =============================================================================

/**
 * Check if a value contains any dangerous patterns
 */
export function containsDangerousContent(value: string): boolean {
  return DANGEROUS_PATTERNS.some(pattern => pattern.test(value));
}

/**
 * Get sanitization statistics for monitoring
 */
export function getSanitizationStats() {
  return {
    dangerousPatterns: DANGEROUS_PATTERNS.length,
    defaultMaxLength: DEFAULT_SANITIZATION_OPTIONS.maxLength,
    strictModeEnabled: DEFAULT_SANITIZATION_OPTIONS.strictMode
  };
}

/**
 * Validate and sanitize a specific field type
 */
export const fieldSanitizers = {
  fundName: (value: unknown) => sanitizeString(value, { maxLength: 255 }),
  sector: (value: unknown) => sanitizeString(value, { maxLength: 50 }),
  amount: (value: unknown) => sanitizeFinancialAmount(value),
  percentage: (value: unknown) => sanitizePercentage(value),
  email: (value: unknown) => sanitizeEmail(value),
  url: (value: unknown) => sanitizeURL(value),
  uuid: (value: unknown) => {
    const str = sanitizeString(value, { maxLength: 36 });
    if (!validator.isUUID(str)) {
      throw new Error('Invalid UUID format');
    }
    return str;
  }
};

export default {
  sanitizeString,
  sanitizeNumber,
  sanitizeObject,
  sanitizeFinancialAmount,
  sanitizePercentage,
  sanitizeEmail,
  sanitizeURL,
  sanitizeFilePath,
  sanitizeMonteCarloConfig,
  sanitizeDistributionParams,
  createSanitizationMiddleware,
  containsDangerousContent,
  getSanitizationStats,
  fieldSanitizers,
  SanitizationError
};

// server/utils/singleflight-enhanced.ts
// Production-grade single-flight with metrics and retry

export interface SingleFlightEntry<T> {
  promise: Promise<T>;
  startedAt: number;
  abort?: AbortController;
  attempts: number;
  lastError?: Error;
}

export interface SingleFlightOptions {
  capacity?: number;
  holdForMs?: number;
  defaultTimeout?: number;
  maxRetries?: number;
  onEvict?: (_key: string, _reason: 'capacity' | 'timeout' | 'error') => void;
}

export interface SingleFlightStats {
  size: number;
  totalRequests: number;
  dedupedRequests: number;
  errors: number;
  evictions: number;
  avgDuration: number;
}

export function createEnhancedSingleFlight(opts: SingleFlightOptions = {}) {
  const {
    capacity = 200,
    holdForMs = 0,
    defaultTimeout = 30000,
    maxRetries = 0,
    onEvict,
  } = opts;

  const inflight = new Map<string, SingleFlightEntry<any>>();
  const durations: number[] = [];
  const stats: SingleFlightStats = {
    size: 0,
    totalRequests: 0,
    dedupedRequests: 0,
    errors: 0,
    evictions: 0,
    avgDuration: 0,
  };

  // Cleanup expired entries periodically
  const cleanupInterval = setInterval(() => {
    const now = Date.now();
    for (const [key, entry] of inflight.entries()) {
      if (now - entry.startedAt > defaultTimeout) {
        entry.abort?.abort();
        inflight.delete(key);
        stats.evictions++;
        onEvict?.(key, 'timeout');
      }
    }
  }, 5000);

  function size(): number { 
    return inflight.size; 
  }

  function has(key: string): boolean { 
    return inflight.has(key); 
  }

  function getStats(): SingleFlightStats { 
    return { 
      ...stats,
      avgDuration: durations.length > 0 
        ? durations.reduce((a: any, b: any) => a + b, 0) / durations.length 
        : 0
    }; 
  }

  function cancel(key: string): boolean {
    const entry = inflight['get'](key);
    if (entry) {
      entry.abort?.abort();
      inflight.delete(key);
      return true;
    }
    return false;
  }

  function execute<T>(
    key: string,
    worker: (_signal: AbortSignal) => Promise<T>,
    options: { timeout?: number; retries?: number } = {}
  ): Promise<T> {
    stats.totalRequests++;

    const existing = inflight['get'](key);
    if (existing) {
      stats.dedupedRequests++;
      return existing.promise;
    }

    // Capacity management with LRU eviction
    if (inflight.size >= capacity) {
      // Evict oldest entry
      const oldestKey = inflight.keys().next().value;
      if (oldestKey) {
        const entry = inflight['get'](oldestKey)!;
        entry.abort?.abort();
        inflight.delete(oldestKey);
        stats.evictions++;
        onEvict?.(oldestKey, 'capacity');
      }
    }

    const controller = new AbortController();
    const timeout = options.timeout ?? defaultTimeout;
    const retries = options.retries ?? maxRetries;
    const startTime = Date.now();

    // Setup timeout
    const timeoutId = setTimeout(() => {
      controller.abort();
    }, timeout);

    const executeWithRetries = async (attempts = 0): Promise<T> => {
      try {
        const result = await worker(controller.signal);

        // Record successful duration
        const duration = Date.now() - startTime;
        durations.push(duration);
        if (durations.length > 100) {
          durations.shift(); // Keep last 100 for moving average
        }

        return result;
      } catch (error) {
        if (attempts < retries && !controller.signal.aborted) {
          // Exponential backoff with jitter
          const backoffMs = Math.min(1000 * Math.pow(2, attempts), 5000);
          const jitter = Math.random() * 1000;
          await new Promise(resolve => setTimeout(resolve, backoffMs + jitter));
          return executeWithRetries(attempts + 1);
        }
        throw error;
      }
    };

    const promise = executeWithRetries()
      .finally(() => {
        clearTimeout(timeoutId);
        if (holdForMs > 0) {
          setTimeout(() => inflight.delete(key), holdForMs);
        } else {
          queueMicrotask(() => inflight.delete(key));
        }
      })
      .catch(error => {
        stats.errors++;
        const entry = inflight['get'](key);
        if (entry) {
          entry.lastError = error;
        }
        throw error;
      });

    const entry: SingleFlightEntry<T> = {
      promise,
      startedAt: Date.now(),
      abort: controller,
      attempts: 0,
    };

    inflight['set'](key, entry);
    stats.size = inflight.size;

    return promise;
  }

  function shutdown(): void {
    clearInterval(cleanupInterval);
    for (const entry of inflight.values()) {
      entry.abort?.abort();
    }
    inflight.clear();
  }

  function clear(): void {
    for (const entry of inflight.values()) {
      entry.abort?.abort();
    }
    inflight.clear();
    stats.size = 0;
  }

  return { 
    do: execute, 
    cancel, 
    has, 
    size, 
    getStats, 
    shutdown,
    clear
  };
}

