export const AdaptedLineChart: React.FC<LineChartProps> = ({
  data,
  xKey,
  yKey,
  series,
  curve = 'monotone',
  config = {},
  className,
  style
}) => {
  const mergedConfig = { ...DEFAULT_CONFIG, ...config };

  const renderLines = () => {
    if (series && series.length > 0) {
      return series.map((s: ChartSeries, index: number) => (
        <Line
          key={s.key}
          type={curve}
          dataKey={s.key}
          stroke={s.color || mergedConfig.colors[index % mergedConfig.colors.length]}
          strokeWidth={2}
          dot={{ r: 4 }}
          activeDot={{ r: 6 }}
          name={s.name}
          animationDuration={mergedConfig.animation ? 300 : 0}
        />
      ));
    }

    return (
      <Line
        type={curve}
        dataKey={yKey}
        stroke={mergedConfig.colors[0]!}
        strokeWidth={2}
        dot={{ r: 4 }}
        activeDot={{ r: 6 }}
        animationDuration={mergedConfig.animation ? 300 : 0}
      />
    );
  };

  const numericHeight = typeof mergedConfig.height === 'number' ? mergedConfig.height : 300;
  const numericWidth = typeof mergedConfig.width === 'number' ? mergedConfig.width : 600;

  const chart = (
    <LineChart
      width={numericWidth}
      height={numericHeight}
        data={data}
        margin={mergedConfig.margin}
        {...(className && { className })}
        {...(!mergedConfig.responsive && style && { style })}
      >
        {mergedConfig.grid && <CartesianGrid strokeDasharray="3 3" />}
        <XAxis 
          dataKey={xKey}
          tick={{ fontSize: 12 }}
          tickLine={{ stroke: '#e0e0e0' }}
        />
        <YAxis 
          tick={{ fontSize: 12 }}
          tickLine={{ stroke: '#e0e0e0' }}
        />
        {mergedConfig.tooltip && <Tooltip />}
        {mergedConfig.legend && series && series.length > 1 && <Legend />}
        {renderLines()}
      </LineChart>
  );

  if (mergedConfig.responsive) {
    return (
      <ResponsiveContainer width="100%" height={numericHeight}>
        {chart}
      </ResponsiveContainer>
    );
  }

  return <div style={style}>{chart}</div>;
};

