  endingCashCents: number;
  pacingTarget: PacingTarget;
  allocatedCents: number;
  violations: Violation[];
}

export interface PacingTargetOutput {
  period: string;
  target: number;
}

export interface PeriodLoopOutput extends CAEngineOutput {
  pacing_targets_by_period: PacingTargetOutput[];
}

export function executePeriodLoop(input: NormalizedInput): PeriodLoopOutput {
  const periods = generatePeriods(
    input.startDate,
    input.endDate,
    input.rebalanceFrequency
  );

  if (periods.length === 0) {
    return createEmptyPeriodLoopOutput(input);
  }

  const flowsByPeriod = bucketFlowsIntoPeriods(
    input.contributionsCents,
    input.distributionsCents,
    periods
  );

  const pacingConfig: PacingConfig = {
    commitmentCents: input.commitmentCents,
    pacingWindowMonths: input.original.fund.pacing_window_months ?? 24,
    frequency: input.rebalanceFrequency,
  };

  let state: PeriodState = {
    cashCents: 0,
    deployedCents: 0,
    pacingCarryoverCents: 0,
    cohorts: input.cohorts.map((c) => ({ ...c, allocationCents: 0 })),
  };

  const periodResults: PeriodResult[] = [];
  const allViolations: Violation[] = [];

  for (const period of periods) {
    const result = processPeriod(
      period,
      state,
      flowsByPeriod.get(period.id) ?? { contributions: [], distributions: [] },
      input,
      pacingConfig
    );

    periodResults.push(result);
    allViolations.push(...result.violations);

    state = {
      cashCents: result.endingCashCents,
      deployedCents: state.deployedCents + result.allocatedCents,
      pacingCarryoverCents: Math.max(
        0,
        result.pacingTarget.effectiveTargetCents - result.allocatedCents
      ),
      cohorts: state.cohorts.map((c) => {
        const allocated = result.allocatedCents > 0
          ? (c.allocationCents + (result.allocatedCents * c.weightBps / 10_000_000))
          : c.allocationCents;
        return { ...c, allocationCents: Math.floor(allocated) };
      }),
    };
  }

  return buildOutput(input, state, periodResults, allViolations, pacingConfig);
}

function bucketFlowsIntoPeriods(
  contributions: CashFlow[],
  distributions: CashFlow[],
  periods: Period[]
): Map<string, { contributions: CashFlow[]; distributions: CashFlow[] }> {
  const buckets = new Map<string, { contributions: CashFlow[]; distributions: CashFlow[] }>();

  for (const period of periods) {
    buckets.set(period.id, { contributions: [], distributions: [] });
  }

  for (const flow of contributions) {
    const period = findPeriodForDate(flow.date, periods);
    if (period) {
      buckets.get(period.id)?.contributions.push(flow);
    }
  }

  for (const flow of distributions) {
    const period = findPeriodForDate(flow.date, periods);
    if (period) {
      buckets.get(period.id)?.distributions.push(flow);
    }
  }

  return buckets;
}

function processPeriod(
  period: Period,
  state: PeriodState,
  flows: { contributions: CashFlow[]; distributions: CashFlow[] },
  input: NormalizedInput,
  pacingConfig: PacingConfig
): PeriodResult {
  const violations: Violation[] = [];

  const contributionsCents = flows.contributions.reduce(
    (sum, f) => sum + (f.amountCents ?? 0),
    0
  );
  const distributionsCents = flows.distributions.reduce(
    (sum, f) => sum + Math.abs(f.amountCents ?? 0),
    0
  );

  const endingCashCents =
    state.cashCents + contributionsCents - distributionsCents;

  const reserveRequiredCents = calculateReserveForPeriod(input, endingCashCents);
  const reserveBalanceCents = Math.min(endingCashCents, reserveRequiredCents);

  if (endingCashCents < reserveRequiredCents) {
    const isMinBufferViolation =
      input.minCashBufferCents > 0 && reserveBalanceCents < input.minCashBufferCents;

    violations.push(
      createViolation(
        isMinBufferViolation ? 'reserve_below_minimum' : 'buffer_breach',
        `Reserve balance (${reserveBalanceCents}) below required (${reserveRequiredCents}) in ${period.id}`,
        {
          severity: 'warning',
          period: period.id,
          expected: reserveRequiredCents,
          actual: reserveBalanceCents,
        }
      )
    );
  }

  const baseTarget = calculateBasePacingTarget(pacingConfig);
  const pacingTarget: PacingTarget = {
    periodId: period.id,
    targetCents: baseTarget,
    carryoverCents: state.pacingCarryoverCents,
    effectiveTargetCents: baseTarget + state.pacingCarryoverCents,
  };

  const availableForDeployment = Math.max(0, endingCashCents - reserveRequiredCents);
  const deployableFromPacing = pacingTarget.effectiveTargetCents;
  const deployableCents = Math.min(availableForDeployment, deployableFromPacing);

  const { allocations, unallocatedCents } = allocateToCohorts(
    state.cohorts,
    period,
    deployableCents,
    input.original.constraints?.max_allocation_per_cohort ?? null,
    input.commitmentCents
  );

  const allocatedCents = deployableCents - unallocatedCents;

  state.cohorts = accumulateAllocations(state.cohorts, allocations);

  const finalEndingCashCents = endingCashCents - allocatedCents;

  return {
    period,
    reserveBalanceCents: Math.min(finalEndingCashCents, reserveRequiredCents),
    endingCashCents: finalEndingCashCents,
    pacingTarget,
    allocatedCents,
    violations,
  };
}

function calculateReserveForPeriod(
  input: NormalizedInput,
  endingCashCents: number
): number {
  const targetReserveCents = roundPercentDerivedToCents(
    input.commitmentCents * input.targetReservePct
  );
  return Math.max(input.minCashBufferCents, targetReserveCents);
}

function buildOutput(
  input: NormalizedInput,
  finalState: PeriodState,
  periodResults: PeriodResult[],
  violations: Violation[],
  pacingConfig: PacingConfig
): PeriodLoopOutput {
  const reserveBalanceOverTime: ReserveBalancePoint[] = periodResults.map((r) => ({
    date: r.period.endDate,
    reserve_balance: centsToOutputUnits(r.reserveBalanceCents, input.unitScale),
    reserveBalanceCents: r.reserveBalanceCents,
    ending_cash: centsToOutputUnits(r.endingCashCents, input.unitScale),
    endingCashCents: r.endingCashCents,
  }));

  const pacingTargetsByPeriod: PacingTargetOutput[] = periodResults.map((r) => ({
    period: r.period.id,
    target: centsToOutputUnits(r.pacingTarget.targetCents, input.unitScale),
  }));

  const lastResult = periodResults[periodResults.length - 1];
  const finalReserveBalanceCents = lastResult?.reserveBalanceCents ?? 0;
  const finalEndingCashCents = lastResult?.endingCashCents ?? 0;

  const totalAllocatedCents = finalState.cohorts.reduce(
    (sum, c) => sum + c.allocationCents,
    0
  );
  const remainingCapacityCents = input.commitmentCents - totalAllocatedCents;

  return {
    reserve_balance: centsToOutputUnits(finalReserveBalanceCents, input.unitScale),
    reserveBalanceCents: finalReserveBalanceCents,

    allocations_by_cohort: finalState.cohorts.map((c) =>
      formatCohortOutput(c, input.unitScale)
    ),

    reserve_balance_over_time: reserveBalanceOverTime,

    pacing_targets_by_period: pacingTargetsByPeriod,

    remaining_capacity: centsToOutputUnits(remainingCapacityCents, input.unitScale),
    remainingCapacityCents,

    cumulative_deployed: centsToOutputUnits(finalState.deployedCents, input.unitScale),
    cumulativeDeployedCents: finalState.deployedCents,

    violations,

    ending_cash: centsToOutputUnits(finalEndingCashCents, input.unitScale),
    endingCashCents: finalEndingCashCents,

    effective_buffer: centsToOutputUnits(input.effectiveBufferCents, input.unitScale),
    effectiveBufferCents: input.effectiveBufferCents,
  };
}

function createEmptyPeriodLoopOutput(input: NormalizedInput): PeriodLoopOutput {
  return {
    reserve_balance: 0,
    reserveBalanceCents: 0,
    allocations_by_cohort: [],
    reserve_balance_over_time: [],
    pacing_targets_by_period: [],
    remaining_capacity: centsToOutputUnits(input.commitmentCents, input.unitScale),
    remainingCapacityCents: input.commitmentCents,
    cumulative_deployed: 0,
    cumulativeDeployedCents: 0,
    violations: [],
    ending_cash: 0,
    endingCashCents: 0,
    effective_buffer: centsToOutputUnits(input.effectiveBufferCents, input.unitScale),
    effectiveBufferCents: input.effectiveBufferCents,
  };
}

export function requiresPeriodLoop(input: NormalizedInput): boolean {
  if (input.cohorts.length > 1) {
    return true;
  }

  const startYear = parseInt(input.startDate.substring(0, 4), 10);
  const endYear = parseInt(input.endDate.substring(0, 4), 10);
  const startMonth = parseInt(input.startDate.substring(5, 7), 10);
  const endMonth = parseInt(input.endDate.substring(5, 7), 10);

  const monthSpan = (endYear - startYear) * 12 + (endMonth - startMonth);

  if (monthSpan > 3) {
    return true;
  }

  return false;
}

/**
 * GraduationRateEngine
 *
 * Implements stage transition modeling for VC portfolio companies.
 * Supports two modes:
 * - Expectation Mode (deterministic): Uses expected values only, testable
 * - Stochastic Mode (seeded): Monte Carlo sampling with reproducible results
 *
 * Phase 2 Phoenix: Wraps Phase 1 deterministic core, never modifies it.
 */

import { PRNG } from '../../utils/prng';

// Stage definitions
export type Stage = 'seed' | 'series_a' | 'series_b' | 'series_c' | 'exit' | 'failed';

export interface TransitionProbabilities {
  graduate: number; // 0-100, probability of advancing to next stage
  fail: number;     // 0-100, probability of failure
  remain: number;   // 0-100, probability of staying at current stage
}

export interface GraduationConfig {
  /** If true, uses expected values only (deterministic). If false, samples. */
  expectationMode: boolean;
  /** Seed for reproducible stochastic runs. Required when expectationMode=false */
  seed?: number;
  /** Graduation probabilities per stage transition */
  transitions: {
    seedToA: TransitionProbabilities;
    aToB: TransitionProbabilities;
    bToC: TransitionProbabilities;
    cToExit: TransitionProbabilities;
  };
}

export interface TransitionResult {
  fromStage: Stage;
  toStage: Stage;
  probability: number;
  isExpectedPath: boolean;
}

export interface CohortProjection {
  quarter: number;
  stageDistribution: Record<Stage, number>;
  expectedGraduates: number;
  expectedFailures: number;
}

export interface GraduationSummary {
  mode: 'expectation' | 'stochastic';
  seed?: number;
  totalCompanies: number;
  expectedGraduationRate: number;
  expectedFailureRate: number;
  stageDistribution: Record<Stage, number>;
  quarterlyProjections: CohortProjection[];
}

// Type for legacy FundDataForReserves graduation rates
export interface LegacyGraduationRates {
  seedToA: TransitionProbabilities;
  aToB: TransitionProbabilities;
  bToC: TransitionProbabilities;
}

/**
 * GraduationRateEngine
 *
 * Core engine for modeling company stage transitions through the VC pipeline.
 */
export class GraduationRateEngine {
  private config: GraduationConfig;
  private prng: PRNG | null = null;

  constructor(config: GraduationConfig) {
    this.config = config;

    // Validate configuration
    this.validateConfig();

    // Initialize PRNG for stochastic mode
    if (!config.expectationMode) {
      if (config.seed === undefined) {
        throw new Error('Seed is required for stochastic mode');
      }
      this.prng = new PRNG(config.seed);
    }
  }

  private validateConfig(): void {
    const transitions = ['seedToA', 'aToB', 'bToC', 'cToExit'] as const;

    for (const key of transitions) {
      const t = this.config.transitions[key];
      const sum = t.graduate + t.fail + t.remain;
      if (Math.abs(sum - 100) > 0.01) {
        throw new Error(`${key} probabilities must sum to 100% (got ${sum}%)`);
      }
    }
  }

  /**
   * Calculate expected transition for a company at a given stage.
   * In expectation mode, returns weighted average outcome.
   * In stochastic mode, samples from the distribution.
   */
  calculateTransition(currentStage: Stage): TransitionResult {
    if (currentStage === 'exit' || currentStage === 'failed') {
      // Terminal states - no transition
      return {
        fromStage: currentStage,
        toStage: currentStage,
        probability: 1.0,
        isExpectedPath: true,
      };
    }

    const transitionKey = this.getTransitionKey(currentStage);
    if (!transitionKey) {
      throw new Error(`Unknown stage: ${currentStage}`);
    }

    const probs = this.config.transitions[transitionKey];

    if (this.config.expectationMode) {
      return this.calculateExpectedTransition(currentStage, probs);
    } else {
      return this.sampleTransition(currentStage, probs);
    }
  }

  /**
   * Expectation Mode: Returns the most likely outcome with its probability.
   * This is deterministic and testable.
   */
  private calculateExpectedTransition(
    currentStage: Stage,
    probs: TransitionProbabilities
  ): TransitionResult {
    const nextStage = this.getNextStage(currentStage);

    // In expectation mode, we report the graduation probability
    // The "expected" path is graduation if probability > 50%
    const graduateProb = probs.graduate / 100;
    const failProb = probs.fail / 100;

    if (graduateProb >= failProb && graduateProb >= probs.remain / 100) {
      return {
        fromStage: currentStage,
        toStage: nextStage,
        probability: graduateProb,
        isExpectedPath: true,
      };
    } else if (failProb > graduateProb && failProb > probs.remain / 100) {
      return {
        fromStage: currentStage,
        toStage: 'failed',
        probability: failProb,
        isExpectedPath: false,
      };
    } else {
      return {
        fromStage: currentStage,
        toStage: currentStage, // remain
        probability: probs.remain / 100,
        isExpectedPath: false,
      };
    }
  }

  /**
   * Stochastic Mode: Samples from the transition distribution using seeded PRNG.
   * Reproducible given the same seed.
   */
  private sampleTransition(
    currentStage: Stage,
    probs: TransitionProbabilities
  ): TransitionResult {
    if (!this.prng) {
      throw new Error('PRNG not initialized - stochastic mode requires seed');
    }

    const roll = this.prng.next() * 100; // 0-100
    const nextStage = this.getNextStage(currentStage);

    if (roll < probs.graduate) {
      return {
        fromStage: currentStage,
        toStage: nextStage,
        probability: probs.graduate / 100,
        isExpectedPath: true,
      };
    } else if (roll < probs.graduate + probs.fail) {
      return {
        fromStage: currentStage,
        toStage: 'failed',
        probability: probs.fail / 100,
        isExpectedPath: false,
      };
    } else {
      return {
        fromStage: currentStage,
        toStage: currentStage, // remain
        probability: probs.remain / 100,
        isExpectedPath: false,
      };
    }
  }

  /**
   * Project a cohort of companies through the graduation pipeline.
   * In expectation mode, uses expected values for fractional companies.
   * In stochastic mode, simulates individual companies.
   */
  projectCohort(
    initialCompanies: number,
    horizonQuarters: number
  ): CohortProjection[] {
    if (this.config.expectationMode) {
      return this.projectCohortExpectation(initialCompanies, horizonQuarters);
    } else {
      return this.projectCohortStochastic(initialCompanies, horizonQuarters);
    }
  }

  /**
   * Expectation Mode projection: Uses fractional companies based on probabilities.
   */
  private projectCohortExpectation(
    initialCompanies: number,
    horizonQuarters: number
  ): CohortProjection[] {
    const projections: CohortProjection[] = [];

    // Track fractional companies at each stage
    const distribution: Record<Stage, number> = {
      seed: initialCompanies,
      series_a: 0,
      series_b: 0,
      series_c: 0,
      exit: 0,
      failed: 0,
    };

    for (let q = 0; q < horizonQuarters; q++) {
      // Calculate transitions for each stage
      const newDistribution = { ...distribution };

      // Seed -> Series A
      const seedGrads = distribution.seed * (this.config.transitions.seedToA.graduate / 100);
      const seedFails = distribution.seed * (this.config.transitions.seedToA.fail / 100);
      newDistribution.seed -= seedGrads + seedFails;
      newDistribution.series_a += seedGrads;
      newDistribution.failed += seedFails;

      // Series A -> Series B
      const aGrads = distribution.series_a * (this.config.transitions.aToB.graduate / 100);
      const aFails = distribution.series_a * (this.config.transitions.aToB.fail / 100);
      newDistribution.series_a -= aGrads + aFails;
      newDistribution.series_b += aGrads;
      newDistribution.failed += aFails;

      // Series B -> Series C
      const bGrads = distribution.series_b * (this.config.transitions.bToC.graduate / 100);
      const bFails = distribution.series_b * (this.config.transitions.bToC.fail / 100);
      newDistribution.series_b -= bGrads + bFails;
      newDistribution.series_c += bGrads;
      newDistribution.failed += bFails;

      // Series C -> Exit
      const cGrads = distribution.series_c * (this.config.transitions.cToExit.graduate / 100);
      const cFails = distribution.series_c * (this.config.transitions.cToExit.fail / 100);
      newDistribution.series_c -= cGrads + cFails;
      newDistribution.exit += cGrads;
      newDistribution.failed += cFails;

      // Update distribution
      Object.assign(distribution, newDistribution);

      projections.push({
        quarter: q + 1,
        stageDistribution: { ...distribution },
        expectedGraduates: seedGrads + aGrads + bGrads + cGrads,
        expectedFailures: seedFails + aFails + bFails + cFails,
      });
    }

    return projections;
  }

  /**
   * Stochastic Mode projection: Simulates individual company paths.
   */
  private projectCohortStochastic(
    initialCompanies: number,
    horizonQuarters: number
  ): CohortProjection[] {
    const projections: CohortProjection[] = [];

    // Track each company's stage
    const companyStages: Stage[] = Array(initialCompanies).fill('seed');

    for (let q = 0; q < horizonQuarters; q++) {
      let graduates = 0;
      let failures = 0;

      for (let i = 0; i < companyStages.length; i++) {
        const currentStage = companyStages[i];
        if (!currentStage || currentStage === 'exit' || currentStage === 'failed') {
          continue; // Terminal state or undefined
        }

        const transition = this.calculateTransition(currentStage);
        companyStages[i] = transition.toStage;

        if (transition.toStage !== currentStage) {
          if (transition.toStage === 'failed') {
            failures++;
          } else if (transition.toStage !== currentStage) {
            graduates++;
          }
        }
      }

      // Count distribution
      const distribution: Record<Stage, number> = {
        seed: 0,
        series_a: 0,
        series_b: 0,
        series_c: 0,
        exit: 0,
        failed: 0,
      };

      for (const stage of companyStages) {
        distribution[stage]++;
      }

      projections.push({
        quarter: q + 1,
        stageDistribution: distribution,
        expectedGraduates: graduates,
        expectedFailures: failures,
      });
    }

    return projections;
  }

  /**
   * Generate summary statistics for the graduation engine.
   */
  getSummary(initialCompanies: number, horizonQuarters: number): GraduationSummary {
    const projections = this.projectCohort(initialCompanies, horizonQuarters);
    const finalProjection = projections[projections.length - 1];

    const total = initialCompanies;
    const exits = finalProjection?.stageDistribution.exit ?? 0;
    const failures = finalProjection?.stageDistribution.failed ?? 0;

    const summary: GraduationSummary = {
      mode: this.config.expectationMode ? 'expectation' : 'stochastic',
      totalCompanies: initialCompanies,
      expectedGraduationRate: total > 0 ? exits / total : 0,
      expectedFailureRate: total > 0 ? failures / total : 0,
      stageDistribution: finalProjection?.stageDistribution ?? {
        seed: 0,
        series_a: 0,
        series_b: 0,
        series_c: 0,
        exit: 0,
        failed: 0,
      },
      quarterlyProjections: projections,
    };

    // Only add seed for stochastic mode
    if (this.config.seed !== undefined) {
      summary.seed = this.config.seed;
    }

    return summary;
  }

  /**
   * Reset PRNG for reproducible runs (stochastic mode only).
   */
  resetSeed(seed: number): void {
    if (this.config.expectationMode) {
      throw new Error('Cannot reset seed in expectation mode');
    }
    this.prng = new PRNG(seed);
    this.config.seed = seed;
  }

  // Helper methods

  private getTransitionKey(
    stage: Stage
  ): 'seedToA' | 'aToB' | 'bToC' | 'cToExit' | null {
    switch (stage) {
      case 'seed':
        return 'seedToA';
      case 'series_a':
        return 'aToB';
      case 'series_b':
        return 'bToC';
      case 'series_c':
        return 'cToExit';
      default:
        return null;
    }
  }

  private getNextStage(stage: Stage): Stage {
    switch (stage) {
      case 'seed':
        return 'series_a';
      case 'series_a':
        return 'series_b';
      case 'series_b':
        return 'series_c';
      case 'series_c':
        return 'exit';
      default:
        return stage;
    }
  }
}

/**
 * Create a default graduation config based on industry averages.
 */
export function createDefaultGraduationConfig(
  expectationMode: boolean = true,
  seed: number = 42
): GraduationConfig {
  const config: GraduationConfig = {
    expectationMode,
    transitions: {
      seedToA: { graduate: 35, fail: 45, remain: 20 },
      aToB: { graduate: 45, fail: 35, remain: 20 },
      bToC: { graduate: 55, fail: 25, remain: 20 },
      cToExit: { graduate: 65, fail: 15, remain: 20 },
    },
  };

  // Only add seed for stochastic mode
  if (!expectationMode) {
    config.seed = seed;
  }

  return config;
}

/**
 * Convert legacy graduation rates to GraduationConfig.
 * Bridges existing Phase 1 data structures to Phase 2 engine.
 */
export function fromLegacyGraduationRates(
  graduationRates: LegacyGraduationRates,
  expectationMode: boolean = true,
  seed: number = 42
): GraduationConfig {
  const config: GraduationConfig = {
    expectationMode,
    transitions: {
      seedToA: {
        graduate: graduationRates.seedToA.graduate,
        fail: graduationRates.seedToA.fail,
        remain: graduationRates.seedToA.remain,
      },
      aToB: {
        graduate: graduationRates.aToB.graduate,
        fail: graduationRates.aToB.fail,
        remain: graduationRates.aToB.remain,
      },
      bToC: {
        graduate: graduationRates.bToC.graduate,
        fail: graduationRates.bToC.fail,
        remain: graduationRates.bToC.remain,
      },
      // Default C to Exit - not in original legacy format
      cToExit: { graduate: 65, fail: 15, remain: 20 },
    },
  };

  // Only add seed for stochastic mode
  if (!expectationMode) {
    config.seed = seed;
  }

  return config;
}

/**
 * Matrix Compression for MOIC Scenario Storage
 *
 * Compresses large MOIC scenario matrices using Float32Array + zlib for efficient storage and transmission.
 * Critical for performance: 10,000 scenarios × 5 buckets = 50,000 floats = 200KB uncompressed, ~20KB compressed.
 *
 * Design rationale:
 * - Float32 instead of Float64: MOIC precision to 6 decimals sufficient, saves 50% memory
 * - Row-major layout: [s0b0, s0b1, ..., s1b0, s1b1, ...] for cache locality
 * - zlib deflate: ~90% compression ratio for typical MOIC distributions
 * - Browser/Node compatible: works in both environments
 *
 * Performance targets:
 * - Compression: <50ms for 10K scenarios × 5 buckets
 * - Decompression: <30ms for same
 * - Size reduction: >85% compression ratio
 *
 * References:
 * - Float32Array: MDN Web Docs
 * - zlib: Node.js built-in, pako for browser
 */

/**
 * Compressed matrix format with metadata
 */
export interface CompressedMatrix {
  /** Compressed binary data (zlib deflate) */
  data: Uint8Array;

  /** Number of scenarios (rows) */
  numScenarios: number;

  /** Number of buckets (columns) */
  numBuckets: number;

  /** Compression algorithm version */
  version: 1;

  /** Uncompressed size in bytes */
  uncompressedSize: number;

  /** Compressed size in bytes */
  compressedSize: number;
}

/**
 * Validate matrix dimensions
 */
export function validateMatrixDimensions(numScenarios: number, numBuckets: number): void {
  if (!Number.isInteger(numScenarios) || numScenarios <= 0) {
    throw new Error(`Invalid numScenarios: ${numScenarios} (must be positive integer)`);
  }

  if (!Number.isInteger(numBuckets) || numBuckets <= 0) {
    throw new Error(`Invalid numBuckets: ${numBuckets} (must be positive integer)`);
  }

  // Sanity check: prevent absurdly large matrices
  const maxElements = 100_000_000; // 100M floats = 400MB
  const totalElements = numScenarios * numBuckets;

  if (totalElements > maxElements) {
    throw new Error(
      `Matrix too large: ${numScenarios} × ${numBuckets} = ${totalElements} elements (max ${maxElements})`
    );
  }
}

/**
 * Validate MOIC values are finite and non-negative
 */
export function validateMOICValues(matrix: number[][]): void {
  for (let s = 0; s < matrix.length; s++) {
    const scenario = matrix[s];
    if (!Array.isArray(scenario)) {
      throw new Error(`Scenario ${s} is not an array`);
    }

    for (let b = 0; b < scenario.length; b++) {
      const moic = scenario[b];

      if (moic === undefined) {
        throw new Error(`Missing MOIC at scenario ${s}, bucket ${b}`);
      }

      if (!Number.isFinite(moic)) {
        throw new Error(`Invalid MOIC at scenario ${s}, bucket ${b}: ${moic} (must be finite)`);
      }

      if (moic < 0) {
        throw new Error(
          `Negative MOIC at scenario ${s}, bucket ${b}: ${moic} (must be non-negative)`
        );
      }
    }
  }
}

/**
 * Convert 2D MOIC matrix to Float32Array (row-major layout)
 *
 * @param matrix - 2D array of MOIC values [scenario][bucket]
 * @returns Float32Array in row-major order
 */
export function matrixToFloat32(matrix: number[][]): Float32Array {
  if (!Array.isArray(matrix) || matrix.length === 0) {
    throw new Error('Matrix must be non-empty 2D array');
  }

  const numScenarios = matrix.length;
  const firstRow = matrix[0];
  if (!firstRow) {
    throw new Error('Matrix first row is undefined');
  }
  const numBuckets = firstRow.length;

  validateMatrixDimensions(numScenarios, numBuckets);
  validateMOICValues(matrix);

  // Check all rows have same length
  for (let s = 0; s < numScenarios; s++) {
    const row = matrix[s];
    if (!row) {
      throw new Error(`Matrix row ${s} is undefined`);
    }
    if (row.length !== numBuckets) {
      throw new Error(
        `Inconsistent row length at scenario ${s}: expected ${numBuckets}, got ${row.length}`
      );
    }
  }

  // Flatten to row-major Float32Array
  const flat = new Float32Array(numScenarios * numBuckets);
  let idx = 0;

  for (let s = 0; s < numScenarios; s++) {
    const row = matrix[s];
    if (!row) continue; // Already validated above
    for (let b = 0; b < numBuckets; b++) {
      const value = row[b];
      if (value === undefined) continue; // Already validated above
      flat[idx++] = value;
    }
  }

  return flat;
}

/**
 * Convert Float32Array back to 2D MOIC matrix
 *
 * @param flat - Float32Array in row-major order
 * @param numScenarios - Number of scenarios (rows)
 * @param numBuckets - Number of buckets (columns)
 * @returns 2D array [scenario][bucket]
 */
export function float32ToMatrix(
  flat: Float32Array,
  numScenarios: number,
  numBuckets: number
): number[][] {
  validateMatrixDimensions(numScenarios, numBuckets);

  const expectedLength = numScenarios * numBuckets;
  if (flat.length !== expectedLength) {
    throw new Error(`Float32Array length mismatch: expected ${expectedLength}, got ${flat.length}`);
  }

  const matrix: number[][] = [];
  let idx = 0;

  for (let s = 0; s < numScenarios; s++) {
    const scenario: number[] = [];
    for (let b = 0; b < numBuckets; b++) {
      scenario.push(flat[idx++]);
    }
    matrix.push(scenario);
  }

  return matrix;
}

/**
 * Compress MOIC matrix using Float32Array + zlib
 *
 * @param matrix - 2D array of MOIC values [scenario][bucket]
 * @returns Compressed matrix with metadata
 */
export async function compressMatrix(matrix: number[][]): Promise<CompressedMatrix> {
  if (!Array.isArray(matrix) || matrix.length === 0) {
    throw new Error('Matrix must be non-empty 2D array');
  }

  const numScenarios = matrix.length;
  const numBuckets = matrix[0].length;

  // Convert to Float32Array
  const flat = matrixToFloat32(matrix);
  const uncompressedSize = flat.byteLength;

  // Compress using zlib (Node.js) or pako (browser)
  let compressed: Uint8Array;

  if (typeof process !== 'undefined' && process.versions?.node) {
    // Node.js environment

    const zlib = await import('zlib');

    const { promisify } = await import('util');

    const deflate = promisify(zlib.deflate);

    const buffer = Buffer.from(flat.buffer, flat.byteOffset, flat.byteLength);

    const compressedBuffer = await deflate(buffer);
    compressed = new Uint8Array(compressedBuffer);
  } else {
    // Browser environment - use pako
    // @ts-expect-error - pako types not available
    // eslint-disable-next-line @typescript-eslint/no-unsafe-assignment
    const pako = await import('pako');
    // @ts-expect-error - pako types not available
    // eslint-disable-next-line @typescript-eslint/no-unsafe-assignment, @typescript-eslint/no-unsafe-member-access, @typescript-eslint/no-unsafe-call
    compressed = pako.deflate(new Uint8Array(flat.buffer, flat.byteOffset, flat.byteLength));
  }

  return {
    data: compressed,
    numScenarios,
    numBuckets,
    version: 1,
    uncompressedSize,
    compressedSize: compressed.byteLength,
  };
}

/**
 * Decompress MOIC matrix from compressed format
 *
 * @param compressed - Compressed matrix with metadata
 * @returns 2D array of MOIC values [scenario][bucket]
 */
export async function decompressMatrix(compressed: CompressedMatrix): Promise<number[][]> {
  if (compressed.version !== 1) {
    throw new Error(`Unsupported compression version: ${compressed.version}`);
  }

  validateMatrixDimensions(compressed.numScenarios, compressed.numBuckets);

  // Decompress using zlib (Node.js) or pako (browser)
  let decompressed: Uint8Array;

  if (typeof process !== 'undefined' && process.versions?.node) {
    // Node.js environment

    const zlib = await import('zlib');

    const { promisify } = await import('util');

    const inflate = promisify(zlib.inflate);

    const compressedBuffer = Buffer.from(compressed.data);

    const decompressedBuffer = await inflate(compressedBuffer);
    decompressed = new Uint8Array(decompressedBuffer);
  } else {
    // Browser environment - use pako
    // @ts-expect-error - pako types not available
    // eslint-disable-next-line @typescript-eslint/no-unsafe-assignment
    const pako = await import('pako');
    // @ts-expect-error - pako types not available
    // eslint-disable-next-line @typescript-eslint/no-unsafe-assignment, @typescript-eslint/no-unsafe-member-access, @typescript-eslint/no-unsafe-call
    decompressed = pako.inflate(compressed.data);
  }

  // Verify decompressed size
  if (decompressed.byteLength !== compressed.uncompressedSize) {
    throw new Error(
      `Decompression size mismatch: expected ${compressed.uncompressedSize}, got ${decompressed.byteLength}`
    );
  }

  // Convert back to Float32Array
  const flat = new Float32Array(
    decompressed.buffer,
    decompressed.byteOffset,
    decompressed.byteLength / 4
  );

  // Convert to 2D matrix
  return float32ToMatrix(flat, compressed.numScenarios, compressed.numBuckets);
}

/**
 * Calculate compression ratio (percentage)
 *
 * @param compressed - Compressed matrix with metadata
 * @returns Compression ratio as percentage (e.g., 0.12 = 88% reduction)
 */
export function compressionRatio(compressed: CompressedMatrix): number {
  if (compressed.uncompressedSize === 0) return 0;
  return compressed.compressedSize / compressed.uncompressedSize;
}

/**
 * Format compression statistics for logging
 *
 * @param compressed - Compressed matrix with metadata
 * @returns Human-readable compression stats
 */
export function formatCompressionStats(compressed: CompressedMatrix): string {
  const ratio = compressionRatio(compressed);
  const reduction = (1 - ratio) * 100;

  return (
    `Compressed ${compressed.numScenarios}×${compressed.numBuckets} matrix: ` +
    `${(compressed.uncompressedSize / 1024).toFixed(1)}KB → ${(compressed.compressedSize / 1024).toFixed(1)}KB ` +
    `(${reduction.toFixed(1)}% reduction, ratio ${ratio.toFixed(3)})`
  );
}

/**
 * Serialize compressed matrix to JSON-safe format
 *
 * @param compressed - Compressed matrix
 * @returns JSON-serializable object
 */
export function serializeCompressedMatrix(compressed: CompressedMatrix): {
  data: number[];
  numScenarios: number;
  numBuckets: number;
  version: number;
  uncompressedSize: number;
  compressedSize: number;
} {
  return {
    data: Array.from(compressed.data),
    numScenarios: compressed.numScenarios,
    numBuckets: compressed.numBuckets,
    version: compressed.version,
    uncompressedSize: compressed.uncompressedSize,
    compressedSize: compressed.compressedSize,
  };
}

/**
 * Deserialize compressed matrix from JSON format
 *
 * @param serialized - JSON-serialized compressed matrix
 * @returns CompressedMatrix
 */
export function deserializeCompressedMatrix(serialized: {
  data: number[];
  numScenarios: number;
  numBuckets: number;
  version: number;
  uncompressedSize: number;
  compressedSize: number;
}): CompressedMatrix {
  return {
    data: new Uint8Array(serialized.data),
    numScenarios: serialized.numScenarios,
    numBuckets: serialized.numBuckets,
    version: serialized.version as 1,
    uncompressedSize: serialized.uncompressedSize,
    compressedSize: serialized.compressedSize,
  };
}

/**
 * DeterministicReserveEngine
 * 
 * Implements industry-standard "Exit MOIC on Planned Reserves" allocation algorithm
 * Provides deterministic, repeatable calculations for follow-on investment decisions
 */

import Decimal from 'decimal.js';
import {
  type PortfolioCompany,
  type GraduationMatrix,
  type StageStrategy,
  type ReserveAllocationInput,
  type ReserveAllocationOutput,
  type ReserveCalculationResult,
  type FeatureFlags,
  ReserveCalculationError,
  DEFAULT_STAGE_STRATEGIES,
} from '@shared/schemas/reserves-schemas';
import { getLogger, getPerf } from '@shared/instrumentation';
import { validateReserveAllocationConservation } from '@shared/validation/conservation';

// Get instrumentation instances
const logger = getLogger();
const performanceMonitor = getPerf();

// Configuration and constants
const CALCULATION_VERSION = '1.0.0';
const _MAX_ITERATIONS = 1000;
const _CONVERGENCE_THRESHOLD = 0.001;
const _DEFAULT_RISK_FREE_RATE = 0.02; // 2%

interface CalculationContext {
  startTime: number;
  deterministicSeed: string;
  featureFlags: FeatureFlags;
  debugMode: boolean;
}

interface MOICCalculation {
  companyId: string;
  currentMOIC: Decimal;
  projectedMOIC: Decimal;
  graduationProbability: Decimal;
  expectedValue: Decimal;
  riskAdjustedReturn: Decimal;
  allocationScore: Decimal;
}

export class DeterministicReserveEngine {
  private context: CalculationContext | null = null;
  private calculationCache = new Map<string, ReserveCalculationResult>();

  constructor(
    private featureFlags: FeatureFlags = {
      enableNewReserveEngine: true,
      enableParityTesting: true,
      enableRiskAdjustments: true,
      enableScenarioAnalysis: true,
      enableAdvancedDiversification: false,
      enableLiquidationPreferences: true,
      enablePerformanceLogging: true,
      maxCalculationTimeMs: 5000,
    }
  ) {
    // Set high precision for financial calculations
    Decimal['set']({ precision: 28, rounding: Decimal.ROUND_HALF_UP });
  }

  /**
   * Main entry point for reserve allocation calculation
   * Implements Exit MOIC on Planned Reserves ranking algorithm
   */
  async calculateOptimalReserveAllocation(
    input: ReserveAllocationInput
  ): Promise<ReserveCalculationResult> {
    const startTime = Date.now();

    // Initialize calculation context
    this.context = {
      startTime,
      deterministicSeed: this.generateDeterministicHash(input),
      featureFlags: this.featureFlags,
      debugMode: process.env['NODE_ENV'] === 'development',
    };

    try {
      // Check cache first (for deterministic results)
      const cacheKey = this.context.deterministicSeed;
      if (this.calculationCache.has(cacheKey)) {
        const cached = this.calculationCache['get'](cacheKey)!;
        logger.debug('Returning cached reserve calculation', { cacheKey });
        return cached;
      }

      // Validate inputs
      this.validateInputs(input);

      // Track performance
      if (this.featureFlags.enablePerformanceLogging) {
        performanceMonitor.recordMetric(
          'reserve_calculation_start',
          input.portfolio.length,
          'companies'
        );
      }

      // Core calculation steps
      const moicCalculations = await this.calculateMOICForAllCompanies(input);
      const rankedAllocations = await this.rankByExitMOICOnPlannedReserves(
        moicCalculations,
        input
      );
      const optimizedAllocations = await this.optimizePortfolioAllocation(
        rankedAllocations,
        input
      );
      const riskAdjustedAllocations = await this.applyRiskAdjustments(
        optimizedAllocations,
        input
      );
      const finalAllocations = await this.applyConstraints(
        riskAdjustedAllocations,
        input
      );

      // Generate result
      const result = await this.generateCalculationResult(
        finalAllocations,
        input,
        moicCalculations
      );

      // Cache result for consistency
      this.calculationCache['set'](cacheKey, result);

      // Performance tracking
      const duration = Date.now() - startTime;
      if (this.featureFlags.enablePerformanceLogging) {
        performanceMonitor.recordCalculationPerformance(
          'reserve-calculation',
          duration,
          {
            portfolioSize: input.portfolio.length,
            success: true
          }
        );
      }

      logger.info('Reserve calculation completed', {
        duration,
        companiesAnalyzed: input.portfolio.length,
        allocationsGenerated: finalAllocations.length,
        totalAllocated: result.inputSummary.totalAllocated,
      });

      return result;
    } catch (error) {
      const duration = Date.now() - startTime;

      if (this.featureFlags.enablePerformanceLogging) {
        performanceMonitor.recordCalculationPerformance(
          'reserve-calculation',
          duration,
          {
            portfolioSize: input.portfolio.length,
            success: false
          }
        );
      }

      const errorDetails = {
        errorMessage: error instanceof Error ? error.message : String(error),
        duration,
        input: this.sanitizeForLogging(input),
      };
      logger.error('Reserve calculation failed', new Error(errorDetails.errorMessage));

      throw new ReserveCalculationError(
        `Reserve calculation failed: ${error instanceof Error ? error.message : String(error)}`,
        'CALCULATION_ERROR',
        { originalError: error, duration }
      );
    } finally {
      this.context = null;
    }
  }

  /**
   * Calculate MOIC (Multiple of Invested Capital) for all portfolio companies
   * This is the foundation for the Exit MOIC on Planned Reserves algorithm
   */
  private async calculateMOICForAllCompanies(
    input: ReserveAllocationInput
  ): Promise<MOICCalculation[]> {
    const calculations: MOICCalculation[] = [];

    for (const company of input.portfolio) {
      if (!company.isActive) continue;

      const currentMOIC = this.calculateCurrentMOIC(company);
      const projectedMOIC = await this.calculateProjectedMOIC(
        company,
        input.graduationMatrix,
        input.stageStrategies
      );
      const graduationProbability = this.calculateGraduationProbability(
        company,
        input.graduationMatrix
      );
      const expectedValue = this.calculateExpectedValue(
        company,
        projectedMOIC,
        graduationProbability
      );
      const riskAdjustedReturn = this.calculateRiskAdjustedReturn(
        expectedValue,
        company,
        input.stageStrategies
      );
      const allocationScore = this.calculateAllocationScore(
        projectedMOIC,
        graduationProbability,
        riskAdjustedReturn,
        company
      );

      calculations.push({
        companyId: company.id,
        currentMOIC,
        projectedMOIC,
        graduationProbability,
        expectedValue,
        riskAdjustedReturn,
        allocationScore,
      });

      if (this.context?.debugMode) {
        logger.debug('MOIC calculation for company', {
          companyId: company.id,
          companyName: company.name,
          currentMOIC: currentMOIC.toNumber(),
          projectedMOIC: projectedMOIC.toNumber(),
          allocationScore: allocationScore.toNumber(),
        });
      }
    }

    return calculations;
  }

  /**
   * Rank companies by Exit MOIC on Planned Reserves
   * This is the core industry-standard algorithm for follow-on decisions
   */
  private async rankByExitMOICOnPlannedReserves(
    calculations: MOICCalculation[],
    input: ReserveAllocationInput
  ): Promise<ReserveAllocationOutput[]> {
    // Sort by allocation score (highest first)
    const sorted = [...calculations].sort((a: MOICCalculation, b: MOICCalculation) =>
      b.allocationScore.comparedTo(a.allocationScore)
    );

    const allocations: ReserveAllocationOutput[] = [];
    let remainingReserves = new Decimal(input.availableReserves);

    for (let i = 0; i < sorted.length; i++) {
      const calc = sorted[i];
      if (!calc) continue;
      const company = input.portfolio.find(c => c.id === calc.companyId);
      if (!company) {
        logger.warn(`Company ${calc.companyId} not found in portfolio`);
        continue;
      }
      const stageStrategy = this.findStageStrategy(company.currentStage, input.stageStrategies);

      if (remainingReserves.lte(input.minAllocationThreshold)) {
        break; // Not enough reserves left
      }

      // Calculate recommended allocation
      const maxAllocation = this.calculateMaxAllocation(
        company,
        stageStrategy,
        input
      );
      const optimalAllocation = this.calculateOptimalAllocation(
        calc,
        maxAllocation,
        remainingReserves,
        input
      );

      if (optimalAllocation.gt(input.minAllocationThreshold)) {
        const allocation = this.createAllocationOutput(
          company,
          calc,
          optimalAllocation,
          i + 1, // priority
          stageStrategy,
          input
        );

        allocations.push(allocation);
        remainingReserves = remainingReserves.minus(optimalAllocation);
      }
    }

    return allocations;
  }

  /**
   * Optimize portfolio allocation for diversification and risk management
   */
  private async optimizePortfolioAllocation(
    allocations: ReserveAllocationOutput[],
    input: ReserveAllocationInput
  ): Promise<ReserveAllocationOutput[]> {
    if (!input.enableDiversification) {
      return allocations;
    }

    // Calculate current portfolio concentrations
    const totalFundSize = new Decimal(input.totalFundSize);
    const optimized = [...allocations];

    // Apply concentration limits
    for (const allocation of optimized) {
      const company = input.portfolio.find(c => c.id === allocation.companyId);
      if (!company) {
        logger.warn(`Company ${allocation.companyId} not found in portfolio`);
        continue;
      }
      const totalInvestment = new Decimal(company.totalInvested).plus(allocation.recommendedAllocation);
      const concentrationRatio = totalInvestment.div(totalFundSize);

      if (concentrationRatio.gt(input.maxPortfolioConcentration)) {
        // Reduce allocation to meet concentration limit
        const maxAdditional = totalFundSize
          .mul(input.maxPortfolioConcentration)
          .minus(company.totalInvested);

        allocation.recommendedAllocation = Math.max(
          maxAdditional.toNumber(),
          0
        );
        allocation.concentrationRisk = 'high';
        allocation.riskFactors.push('Portfolio concentration limit applied');
      }
    }

    // Apply diversification bonuses
    if (this.featureFlags.enableAdvancedDiversification) {
      this.applyDiversificationBonuses(optimized, input);
    }

    return optimized;
  }

  /**
   * Apply risk adjustments based on company and portfolio characteristics
   */
  private async applyRiskAdjustments(
    allocations: ReserveAllocationOutput[],
    input: ReserveAllocationInput
  ): Promise<ReserveAllocationOutput[]> {
    if (!input.enableRiskAdjustment) {
      return allocations;
    }

    const adjusted = [...allocations];

    for (const allocation of adjusted) {
      const company = input.portfolio.find(c => c.id === allocation.companyId);
      if (!company) {
        logger.warn(`Company ${allocation.companyId} not found in portfolio`);
        continue;
      }

      // Apply risk adjustments
      const riskMultiplier = this.calculateRiskMultiplier(company, input);
      const adjustedAllocation = new Decimal(allocation.recommendedAllocation)
        .mul(riskMultiplier);

      allocation.recommendedAllocation = adjustedAllocation.toNumber();
      allocation.riskAdjustedReturn = allocation.riskAdjustedReturn * riskMultiplier.toNumber();

      // Update risk factors
      if (riskMultiplier.lt(1)) {
        allocation.riskFactors.push('Risk adjustment applied due to company factors');
      }

      // Recalculate portfolio impact
      allocation.portfolioWeight = adjustedAllocation
        .div(input.totalFundSize)
        .toNumber();
    }

    return adjusted;
  }

  /**
   * Apply final constraints and validation with conservation check
   */
  private async applyConstraints(
    allocations: ReserveAllocationOutput[],
    input: ReserveAllocationInput
  ): Promise<ReserveAllocationOutput[]> {
    const constrained = [...allocations];

    // Remove allocations below minimum threshold
    const filtered = constrained.filter(
      a => a.recommendedAllocation >= input.minAllocationThreshold
    );

    // Apply maximum single allocation constraint
    if (input.maxSingleAllocation) {
      for (const allocation of filtered) {
        if (allocation.recommendedAllocation > input.maxSingleAllocation) {
          allocation.recommendedAllocation = input.maxSingleAllocation;
          allocation.riskFactors.push('Maximum single allocation limit applied');
        }
      }
    }

    // Ensure total doesn't exceed available reserves
    const totalAllocated = filtered.reduce(
      (sum: number, a: ReserveAllocationOutput) => sum + a.recommendedAllocation,
      0
    );

    if (totalAllocated > input.availableReserves) {
      // Proportionally reduce allocations
      const reductionFactor = input.availableReserves / totalAllocated;
      for (const allocation of filtered) {
        allocation.recommendedAllocation *= reductionFactor;
        allocation.riskFactors.push('Proportional reduction applied to fit available reserves');
      }
    }

    // Conservation of capital validation
    const finalTotal = filtered.reduce(
      (sum: number, a: ReserveAllocationOutput) => sum + a.recommendedAllocation,
      0
    );
    const unallocated = input.availableReserves - finalTotal;

    const conservationCheck = validateReserveAllocationConservation(
      input.availableReserves,
      filtered.map(a => a.recommendedAllocation),
      unallocated,
      0.001 // 0.1% tolerance
    );

    if (!conservationCheck.isValid) {
      logger.error('Conservation of capital validation failed', {
        ...conservationCheck,
        context: 'DeterministicReserveEngine.applyConstraints'
      });
      throw new ReserveCalculationError(
        `Conservation of capital validation failed: ${conservationCheck.message}`,
        'CONSERVATION_ERROR',
        conservationCheck
      );
    }

    logger.debug('Conservation check passed', conservationCheck);

    return filtered;
  }

  /**
   * Generate final calculation result with comprehensive metrics
   */
  private async generateCalculationResult(
    allocations: ReserveAllocationOutput[],
    input: ReserveAllocationInput,
    moicCalculations: MOICCalculation[]
  ): Promise<ReserveCalculationResult> {
    const totalAllocated = allocations.reduce(
      (sum: number, a: ReserveAllocationOutput) => sum + a.recommendedAllocation,
      0
    );
    const unallocatedReserves = input.availableReserves - totalAllocated;

    // Calculate portfolio metrics
    const expectedPortfolioValue = allocations.reduce(
      (sum: number, a: ReserveAllocationOutput) => sum + a.expectedValue,
      0
    );
    const expectedPortfolioMOIC = expectedPortfolioValue / totalAllocated || 0;

    // Calculate risk metrics
    const riskAnalysis = this.calculateRiskAnalysis(allocations, input);
    const scenarioResults = await this.calculateScenarioAnalysis(allocations, input);

    const result: ReserveCalculationResult = {
      inputSummary: {
        totalPortfolioCompanies: input.portfolio.length,
        availableReserves: input.availableReserves,
        totalAllocated,
        allocationEfficiency: totalAllocated / input.availableReserves,
      },
      allocations,
      unallocatedReserves,
      portfolioMetrics: {
        expectedPortfolioMOIC,
        expectedPortfolioValue,
        portfolioDiversification: this.calculateDiversificationIndex(allocations),
        concentrationRisk: this.assessConcentrationRisk(allocations, input),
        averageTimeToExit: this.calculateAverageTimeToExit(allocations),
      },
      riskAnalysis,
      scenarioResults,
      metadata: {
        calculationDate: new Date(),
        calculationDuration: Date.now() - this.context!.startTime,
        modelVersion: CALCULATION_VERSION,
        deterministicHash: this.context!.deterministicSeed,
        assumptions: this.getCalculationAssumptions(),
        limitations: this.getCalculationLimitations(),
      },
    };

    return result;
  }

  // Helper methods for calculations
  private calculateCurrentMOIC(company: PortfolioCompany): Decimal {
    return new Decimal(company.currentValuation).div(company.totalInvested);
  }

  private async calculateProjectedMOIC(
    company: PortfolioCompany,
    graduationMatrix: GraduationMatrix,
    stageStrategies: StageStrategy[]
  ): Promise<Decimal> {
    const stageStrategy = this.findStageStrategy(company.currentStage, stageStrategies);
    if (!stageStrategy) {
      return new Decimal(company.currentMOIC || 1);
    }

    // Find graduation path
    const graduationRate = graduationMatrix.rates.find(
      rate => rate.fromStage === company.currentStage
    );

    if (!graduationRate) {
      return new Decimal(stageStrategy.expectedMOIC);
    }

    // Calculate projected MOIC based on graduation probability and valuation multiple
    const currentMOIC = this.calculateCurrentMOIC(company);
    const projectedMultiple = new Decimal(graduationRate.valuationMultiple);
    const graduationBonus = new Decimal(graduationRate.probability);

    return currentMOIC
      .mul(projectedMultiple)
      .mul(graduationBonus.plus(1));
  }

  /**
   * Calculate graduation probability with improved defaults
   * Fix: Use stage-specific defaults instead of blanket 0.5 (line 505 improvement)
   */
  private calculateGraduationProbability(
    company: PortfolioCompany,
    graduationMatrix: GraduationMatrix
  ): Decimal {
    const graduationRate = graduationMatrix.rates.find(
      rate => rate.fromStage === company.currentStage
    );

    if (graduationRate) {
      return new Decimal(graduationRate.probability);
    }

    // Improved stage-specific defaults based on industry data
    const stageDefaults: Record<string, number> = {
      'seed': 0.30,        // 30% seed to Series A
      'series-a': 0.50,    // 50% Series A to Series B
      'series-b': 0.60,    // 60% Series B to Series C
      'series-c': 0.70,    // 70% Series C to later stages
      'growth': 0.75,      // 75% growth to exit
      'late-stage': 0.80,  // 80% late-stage to exit
    };

    return new Decimal(stageDefaults[company.currentStage.toLowerCase()] || 0.40);
  }

  /**
   * Calculate expected value with validation to prevent division by zero
   * @throws {ReserveCalculationError} if company.totalInvested is invalid
   */
  private calculateExpectedValue(
    company: PortfolioCompany,
    projectedMOIC: Decimal,
    graduationProbability: Decimal
  ): Decimal {
    // Validate totalInvested to prevent downstream division by zero
    if (!company.totalInvested || company.totalInvested <= 0) {
      throw new ReserveCalculationError(
        `Invalid totalInvested (${company.totalInvested}) for company ${company.id}. Must be positive.`,
        'INVALID_COMPANY_DATA',
        { companyId: company.id, totalInvested: company.totalInvested }
      );
    }

    return new Decimal(company.totalInvested)
      .mul(projectedMOIC)
      .mul(graduationProbability);
  }

  private calculateRiskAdjustedReturn(
    expectedValue: Decimal,
    company: PortfolioCompany,
    stageStrategies: StageStrategy[]
  ): Decimal {
    const stageStrategy = this.findStageStrategy(company.currentStage, stageStrategies);
    if (!stageStrategy) {
      return expectedValue;
    }

    const riskAdjustment = new Decimal(1).minus(stageStrategy.failureRate);
    return expectedValue.mul(riskAdjustment);
  }

  /**
   * Calculate allocation score with validation to prevent division by zero
   * Exit MOIC on Planned Reserves calculation
   * Score = (Projected MOIC * Graduation Probability * Risk Adjustment) / Current Valuation
   * @throws {ReserveCalculationError} if currentValuation is zero or negative
   */
  private calculateAllocationScore(
    projectedMOIC: Decimal,
    graduationProbability: Decimal,
    riskAdjustedReturn: Decimal,
    company: PortfolioCompany
  ): Decimal {
    // Validate currentValuation to prevent division by zero (line 548 fix)
    if (!company.currentValuation || company.currentValuation <= 0) {
      throw new ReserveCalculationError(
        `Invalid currentValuation (${company.currentValuation}) for company ${company.id}. Must be positive for allocation score calculation.`,
        'INVALID_COMPANY_DATA',
        {
          companyId: company.id,
          companyName: company.name,
          currentValuation: company.currentValuation,
          totalInvested: company.totalInvested
        }
      );
    }

    return projectedMOIC
      .mul(graduationProbability)
      .mul(riskAdjustedReturn)
      .div(company.currentValuation);
  }

  private findStageStrategy(
    stage: string,
    stageStrategies: StageStrategy[]
  ): StageStrategy | undefined {
    return stageStrategies.find(s => s.stage === stage) || 
           DEFAULT_STAGE_STRATEGIES.find(s => s.stage === stage);
  }

  private calculateMaxAllocation(
    company: PortfolioCompany,
    stageStrategy: StageStrategy | undefined,
    input: ReserveAllocationInput
  ): Decimal {
    if (!stageStrategy) {
      return new Decimal(input.availableReserves * 0.1); // Default 10% max
    }

    const maxByStrategy = new Decimal(stageStrategy.maxInvestment);
    const maxByReserves = new Decimal(input.availableReserves * 0.3); // Max 30% of reserves
    const maxByConcentration = new Decimal(input.totalFundSize)
      .mul(input.maxPortfolioConcentration)
      .minus(company.totalInvested);

    return Decimal.min(maxByStrategy, maxByReserves, maxByConcentration);
  }

  private calculateOptimalAllocation(
    calc: MOICCalculation,
    maxAllocation: Decimal,
    remainingReserves: Decimal,
    input: ReserveAllocationInput
  ): Decimal {
    // Use allocation score to determine optimal amount within constraints
    const scoreBasedAllocation = calc.allocationScore
      .mul(remainingReserves)
      .div(100); // Normalize score

    return Decimal.min(
      scoreBasedAllocation,
      maxAllocation,
      remainingReserves,
      new Decimal(input.maxSingleAllocation || Infinity)
    );
  }

  private createAllocationOutput(
    company: PortfolioCompany,
    calc: MOICCalculation,
    allocation: Decimal,
    priority: number,
    stageStrategy: StageStrategy | undefined,
    input: ReserveAllocationInput
  ): ReserveAllocationOutput {
    const newOwnership = new Decimal(company.ownershipPercentage)
      .plus(allocation.div(company.currentValuation));

    return {
      companyId: company.id,
      companyName: company.name,
      recommendedAllocation: allocation.toNumber(),
      allocationRationale: this.generateAllocationRationale(calc, stageStrategy),
      priority,
      expectedMOIC: calc.projectedMOIC.toNumber(),
      expectedValue: calc.expectedValue.toNumber(),
      riskAdjustedReturn: calc.riskAdjustedReturn.toNumber(),
      newOwnership: Math.min(newOwnership.toNumber(), 1),
      portfolioWeight: allocation.div(input.totalFundSize).toNumber(),
      concentrationRisk: this.assessConcentrationRisk([{ 
        recommendedAllocation: allocation.toNumber(),
        companyId: company.id 
      } as ReserveAllocationOutput], input),
      recommendedStage: company.currentStage,
      timeToDeployment: 6, // Default 6 months
      followOnPotential: stageStrategy?.followOnProbability || 0.5,
      riskFactors: [],
      mitigationStrategies: [],
      calculationMetadata: {
        graduationProbability: calc.graduationProbability.toNumber(),
        expectedExitMultiple: calc.projectedMOIC.toNumber(),
        timeToExit: stageStrategy?.expectedTimeToExit || 84,
        diversificationBonus: 0,
        liquidationPrefImpact: 0,
      },
    };
  }

  // Utility methods
  private validateInputs(input: ReserveAllocationInput): void {
    if (input.portfolio.length === 0) {
      throw new ReserveCalculationError(
        'Portfolio cannot be empty',
        'INVALID_INPUT'
      );
    }

    if (input.availableReserves <= 0) {
      throw new ReserveCalculationError(
        'Available reserves must be positive',
        'INVALID_INPUT'
      );
    }

    if (input.totalFundSize <= 0) {
      throw new ReserveCalculationError(
        'Total fund size must be positive',
        'INVALID_INPUT'
      );
    }
  }

  private generateDeterministicHash(input: ReserveAllocationInput): string {
    // Create deterministic hash for caching and verification
    const hashInput = {
      portfolioCount: input.portfolio.length,
      availableReserves: input.availableReserves,
      totalFundSize: input.totalFundSize,
      scenarioType: input.scenarioType,
      timeHorizon: input.timeHorizon,
    };

    return Buffer.from(JSON.stringify(hashInput)).toString('base64');
  }

  private sanitizeForLogging(input: ReserveAllocationInput): Record<string, unknown> {
    return {
      portfolioCompanies: input.portfolio.length,
      availableReserves: input.availableReserves,
      totalFundSize: input.totalFundSize,
      scenarioType: input.scenarioType,
    };
  }

  private generateAllocationRationale(
    calc: MOICCalculation,
    stageStrategy: StageStrategy | undefined
  ): string {
    return `High allocation score (${calc.allocationScore.toFixed(2)}) based on projected MOIC of ${calc.projectedMOIC.toFixed(1)}x with ${(calc.graduationProbability.toNumber() * 100).toFixed(0)}% graduation probability.`;
  }

  private calculateRiskMultiplier(
    company: PortfolioCompany,
    input: ReserveAllocationInput
  ): Decimal {
    let multiplier = new Decimal(1);

    // Adjust for company age
    const ageMonths = (Date.now() - company.investmentDate.getTime()) / (1000 * 60 * 60 * 24 * 30);
    if (ageMonths > 60) { // Over 5 years
      multiplier = multiplier.mul(0.9);
    }

    // Adjust for performance
    if (company.currentMOIC && company.currentMOIC < 1) {
      multiplier = multiplier.mul(0.8);
    }

    return multiplier;
  }

  private applyDiversificationBonuses(
    allocations: ReserveAllocationOutput[],
    input: ReserveAllocationInput
  ): void {
    // Apply bonuses for sector diversification
    const sectorCounts = new Map<string, number>();
    for (const allocation of allocations) {
      const company = input.portfolio.find(c => c.id === allocation.companyId);
      if (!company) {
        logger.warn(`Company ${allocation.companyId} not found in portfolio`);
        continue;
      }
      sectorCounts['set'](company.sector, (sectorCounts['get'](company.sector) || 0) + 1);
    }

    for (const allocation of allocations) {
      const company = input.portfolio.find(c => c.id === allocation.companyId);
      if (!company) {
        logger.warn(`Company ${allocation.companyId} not found in portfolio`);
        continue;
      }
      const sectorCount = sectorCounts['get'](company.sector) || 1;

      if (sectorCount === 1) {
        // Bonus for unique sector
        allocation.recommendedAllocation *= 1.1;
        allocation.calculationMetadata.diversificationBonus = 0.1;
      }
    }
  }

  private calculateDiversificationIndex(allocations: ReserveAllocationOutput[]): number {
    // Calculate Herfindahl-Hirschman Index (HHI) for diversification
    const total = allocations.reduce((sum: number, a: ReserveAllocationOutput) => sum + a.recommendedAllocation, 0);
    if (total === 0) return 1;

    const hhi = allocations.reduce((sum: number, a: ReserveAllocationOutput) => {
      const share = a.recommendedAllocation / total;
      return sum + (share * share);
    }, 0);

    // Return diversification index (1 - HHI)
    return Math.max(0, 1 - hhi);
  }

  private assessConcentrationRisk(
    allocations: ReserveAllocationOutput[],
    input: ReserveAllocationInput
  ): 'low' | 'medium' | 'high' {
    const maxConcentration = Math.max(
      ...allocations.map(a => a.portfolioWeight || 0)
    );

    if (maxConcentration > input.maxPortfolioConcentration * 0.8) {
      return 'high';
    } else if (maxConcentration > input.maxPortfolioConcentration * 0.5) {
      return 'medium';
    }
    return 'low';
  }

  private calculateAverageTimeToExit(allocations: ReserveAllocationOutput[]): number {
    if (allocations.length === 0) return 84; // Default 7 years

    const totalWeighted = allocations.reduce(
      (sum: number, a: ReserveAllocationOutput) => sum + (a.calculationMetadata.timeToExit * a.recommendedAllocation),
      0
    );
    const totalAllocation = allocations.reduce(
      (sum: number, a: ReserveAllocationOutput) => sum + a.recommendedAllocation,
      0
    );

    return totalAllocation > 0 ? totalWeighted / totalAllocation : 84;
  }

  private calculateRiskAnalysis(
    allocations: ReserveAllocationOutput[],
    input: ReserveAllocationInput
  ): ReserveCalculationResult['riskAnalysis'] {
    // Simplified risk analysis
    const avgRiskAdjustedReturn = allocations.reduce(
      (sum: number, a: ReserveAllocationOutput) => sum + a.riskAdjustedReturn,
      0
    ) / allocations.length;

    return {
      portfolioRisk: avgRiskAdjustedReturn > 10000000 ? 'high' : 'medium',
      keyRiskFactors: ['Market concentration', 'Stage concentration', 'Sector concentration'],
      riskMitigationActions: ['Diversification', 'Staged deployment', 'Risk monitoring'],
      stressTestResults: {
        downside10: avgRiskAdjustedReturn * 0.3,
        upside90: avgRiskAdjustedReturn * 2.5,
        expectedValue: avgRiskAdjustedReturn,
      },
    };
  }

  private async calculateScenarioAnalysis(
    allocations: ReserveAllocationOutput[],
    input: ReserveAllocationInput
  ): Promise<ReserveCalculationResult['scenarioResults']> {
    const baseValue = allocations.reduce((sum: number, a: ReserveAllocationOutput) => sum + a.expectedValue, 0);

    return {
      conservative: {
        totalValue: baseValue * 0.7,
        portfolioMOIC: 2.5,
        probability: 0.2,
      },
      base: {
        totalValue: baseValue,
        portfolioMOIC: 5.0,
        probability: 0.6,
      },
      optimistic: {
        totalValue: baseValue * 1.8,
        portfolioMOIC: 12.0,
        probability: 0.2,
      },
    };
  }

  private getCalculationAssumptions(): string[] {
    return [
      'Industry-standard graduation rates applied',
      'Market conditions remain stable',
      'Company performance projections based on historical data',
      'No major economic disruptions assumed',
    ];
  }

  private getCalculationLimitations(): string[] {
    return [
      'Projections based on historical patterns',
      'Market timing not considered',
      'Individual company risk factors simplified',
      'Regulatory changes not factored',
    ];
  }
}

