import { z } from 'zod';
import { percent100, bounded01 } from './schema-helpers';

// Enhanced follow-on rule schema for capital-first modeling
export const FollowOnRuleSchema = z.object({
  from: z.enum(['preseed', 'seed', 'series_a', 'series_b', 'series_c', 'series_dplus']),
  to: z.enum(['preseed', 'seed', 'series_a', 'series_b', 'series_c', 'series_dplus']),
  mode: z.enum(['fixed_check', 'maintain_ownership']),
  participationPct: percent100(), // 0-100%
  fixedAmount: z.number().positive().optional(), // if fixed_check mode
  targetOwnershipPct: percent100().optional(), // if maintain_ownership mode
  nextRoundSize: z.number().positive().optional(), // for ownership calculations
});

// Stage allocation schema
export const StageAllocationSchema = z.object({
  id: z.string(),
  category: z.string().min(1),
  percentage: percent100(),
});

// Stage progression schema with validation constraints
export const StageSchema = z.object({
  id: z.string(),
  name: z.string().min(1),
  graduationRate: percent100(), // percentage
  exitRate: percent100(), // percentage
});

// Core fund wire schema with optimistic locking
export const fundModelWireSchema = z.object({
  id: z.string().uuid(),
  version: z.number().int().nonnegative(), // Optimistic locking version
  name: z.string().min(1),
  currency: z.literal('USD'),
  waterfall: z.literal('american'),
  model_version: z.number().int().default(1),
  state: z.object({
    foundation: z.object({
      startDate: z.string(),
      termMonths: z.number().nullable(),
    }),
    capital: z.object({
      totalCommitment: z.number().positive(),
    }),
    fees: z.object({
      managementFee: bounded01(), // decimal (e.g., 0.02 = 2%)
      carryPercentage: bounded01(), // decimal (e.g., 0.20 = 20%)
    }),
    investmentStrategy: z.object({
      allocations: z.array(StageAllocationSchema),
      stages: z.array(StageSchema),
    }),
    followOnRules: z.array(FollowOnRuleSchema).optional(),
  }),
})
.refine(
  (data: z.infer<typeof fundModelWireSchema>) => {
    // Validation: Allocation sum ≤ 100%
    const totalAllocation = data.state.investmentStrategy.allocations
      .reduce((sum: number, alloc: z.infer<typeof StageAllocationSchema>) => sum + alloc.percentage, 0);
    return totalAllocation <= 100.01; // Allow tiny floating point tolerance
  },
  {
    message: "Total allocation percentages cannot exceed 100%",
    path: ["state", "investmentStrategy", "allocations"],
  }
)
.refine(
  (data) => {
    // Validation: Each stage graduation + exit ≤ 100%
    return data.state.investmentStrategy.stages.every((stage: {
      graduationRate: number;
      exitRate: number;
    }) =>
      (stage.graduationRate + stage.exitRate) <= 100.01 // Floating point tolerance
    );
  },
  {
    message: "For each stage, graduation rate + exit rate cannot exceed 100%",
    path: ["state", "investmentStrategy", "stages"],
  }
)
.refine(
  (data: any) => {
    // Validation: Last stage graduation rate must be 0
    const stages = data.state.investmentStrategy.stages;
    if (stages.length > 0) {
      const lastStage = stages[stages.length - 1];
      return lastStage?.graduationRate === 0;
    }
    return true;
  },
  {
    message: "Last stage must have graduation rate of 0% (final stage)",
    path: ["state", "investmentStrategy", "stages"],
  }
);

export type FundModelWire = z.infer<typeof fundModelWireSchema>;
export type FollowOnRule = z.infer<typeof FollowOnRuleSchema>;
export type StageAllocation = z.infer<typeof StageAllocationSchema>;
export type Stage = z.infer<typeof StageSchema>;

// Helper function for capital-first follow-on calculations
export function initialCountBalanced(
  budgetStage: number,
  initialCheck: number,
  gradPct: number,
  partPct: number,
  followOnPerDeal: number
): number {
  const g = (gradPct / 100) * (partPct / 100);
  const denom = initialCheck + g * followOnPerDeal;
  return denom > 0 ? budgetStage / denom : 0; // fractional is OK, guards division by zero
}

// Validation helper for demo safety
export function validateFundModelSafe(data: unknown): { success: boolean; data?: FundModelWire; error?: string } {
  try {
    const result = fundModelWireSchema.safeParse(data);
    if (!result.success) {
      return {
        success: false,
        error: `Validation failed: ${result.error.message}`
      };
    }
    return {
      success: true,
      data: result.data
    };
  } catch (error) {
    return {
      success: false,
      error: `Validation error: ${error instanceof Error ? error.message : 'Unknown error'}`
    };
  }
}

/**
 * Fund Mathematics Library
 *
 * Core financial calculations for venture capital fund modeling:
 * - Fee basis timeline computation (integrates with FeeProfile schema)
 * - Capital call/distribution projections
 * - NAV calculations with fee adjustments
 *
 * Used by J-curve engine and construction forecasting.
 */

import Decimal from 'decimal.js';
import type { FeeProfile, FeeBasisType, FeeCalculationContext } from '@shared/schemas/fee-profile';
import { calculateManagementFees, calculateRecyclableFees } from '@shared/schemas/fee-profile';

/**
 * Fee basis data for a single period (quarter)
 */
export interface FeeBasisPeriod {
  /** Quarter number (0-based) */
  quarter: number;

  /** Committed capital (fund size) */
  committedCapital: Decimal;

  /** Called capital cumulative */
  calledCapitalCumulative: Decimal;

  /** Called capital net of distributions */
  calledCapitalNetOfReturns: Decimal;

  /** Invested capital (deployed) */
  investedCapital: Decimal;

  /** Fair market value (portfolio valuation) */
  fairMarketValue: Decimal;

  /** Unrealized cost basis */
  unrealizedCost: Decimal;

  /** Management fees for this period */
  managementFees: Decimal;

  /** Recyclable fees available */
  recyclableFees: Decimal;
}

/**
 * Complete fee basis timeline
 */
export interface FeeBasisTimeline {
  /** Period data by quarter */
  periods: FeeBasisPeriod[];

  /** Total fees over timeline */
  totalFees: Decimal;

  /** Total recyclable fees */
  totalRecyclable: Decimal;
}

/**
 * Configuration for fee basis computation
 */
export interface FeeBasisConfig {
  /** Fund size (committed capital) */
  fundSize: Decimal;

  /** Number of quarters to compute */
  numQuarters: number;

  /** Fee profile (optional - for fee-adjusted NAV) */
  feeProfile?: FeeProfile;

  /** Called capital schedule (cumulative by quarter) */
  calledCapitalSchedule?: Decimal[];

  /** Distribution schedule (cumulative by quarter) */
  distributionSchedule?: Decimal[];

  /** Invested capital schedule (cumulative by quarter) */
  investedCapitalSchedule?: Decimal[];

  /** FMV schedule (by quarter) */
  fmvSchedule?: Decimal[];

  /** Unrealized cost schedule (by quarter) */
  unrealizedCostSchedule?: Decimal[];
}

/**
 * Compute fee basis timeline for J-curve calculations
 *
 * Integrates with FeeProfile schema to handle:
 * - Multiple fee tiers with basis changes
 * - Step-downs by fund year
 * - Fee holidays
 * - Caps (percentage and fixed)
 * - Recycling policies
 *
 * @param config - Fee basis configuration
 * @returns Fee basis timeline with all periods
 */
export function computeFeeBasisTimeline(config: FeeBasisConfig): FeeBasisTimeline {
  const { fundSize, numQuarters, feeProfile } = config;

  const periods: FeeBasisPeriod[] = [];
  let totalFees = new Decimal(0);
  let totalRecyclable = new Decimal(0);
  let cumulativeCalledCapital = new Decimal(0);
  let cumulativeDistributions = new Decimal(0);
  let cumulativeFeesPaid = new Decimal(0);

  for (let q = 0; q < numQuarters; q++) {
    // Get scheduled values or use defaults
    const calledCapital = config.calledCapitalSchedule?.[q] ?? new Decimal(0);
    const distributions = config.distributionSchedule?.[q] ?? new Decimal(0);
    const investedCapital = config.investedCapitalSchedule?.[q] ?? new Decimal(0);
    const fmv = config.fmvSchedule?.[q] ?? new Decimal(0);
    const unrealizedCost = config.unrealizedCostSchedule?.[q] ?? new Decimal(0);

    // Update cumulatives
    cumulativeCalledCapital = calledCapital;
    cumulativeDistributions = distributions;

    // Calculate capital net of returns
    const calledNetOfReturns = cumulativeCalledCapital.minus(cumulativeDistributions);

    // Calculate fees if profile provided
    let managementFees = new Decimal(0);
    let recyclableFees = new Decimal(0);

    if (feeProfile) {
      const context: FeeCalculationContext = {
        committedCapital: fundSize,
        calledCapitalCumulative: cumulativeCalledCapital,
        calledCapitalNetOfReturns: calledNetOfReturns,
        investedCapital,
        fairMarketValue: fmv,
        unrealizedCost,
        currentMonth: q * 3 // Convert quarters to months
      };

      // Calculate management fees for the quarter (3 months)
      const monthlyFees = calculateManagementFees(feeProfile, context);
      managementFees = monthlyFees.times(3);

      cumulativeFeesPaid = cumulativeFeesPaid.plus(managementFees);

      // Calculate recyclable fees
      recyclableFees = calculateRecyclableFees(feeProfile, cumulativeFeesPaid, context);

      totalFees = totalFees.plus(managementFees);
      totalRecyclable = totalRecyclable.plus(recyclableFees);
    }

    periods.push({
      quarter: q,
      committedCapital: fundSize,
      calledCapitalCumulative: cumulativeCalledCapital,
      calledCapitalNetOfReturns: calledNetOfReturns,
      investedCapital,
      fairMarketValue: fmv,
      unrealizedCost,
      managementFees,
      recyclableFees
    });
  }

  return {
    periods,
    totalFees,
    totalRecyclable
  };
}

/**
 * Resolve fee basis amount for a specific basis type and period
 *
 * @param basisType - Type of fee basis
 * @param period - Fee basis period data
 * @returns Basis amount as Decimal
 */
export function resolveFeeBasis(
  basisType: FeeBasisType,
  period: FeeBasisPeriod
): Decimal {
  switch (basisType) {
    case 'committed_capital':
      return period.committedCapital;
    case 'called_capital_cumulative':
      return period.calledCapitalCumulative;
    case 'called_capital_net_of_returns':
      return period.calledCapitalNetOfReturns;
    case 'invested_capital':
      return period.investedCapital;
    case 'fair_market_value':
      return period.fairMarketValue;
    case 'unrealized_cost':
      return period.unrealizedCost;
  }
}

/**
 * Calculate fee-adjusted NAV for a period
 *
 * NAV = FMV - Accrued Fees + Recyclable Fees
 *
 * @param period - Fee basis period
 * @returns Fee-adjusted NAV
 */
export function calculateFeeAdjustedNAV(period: FeeBasisPeriod): Decimal {
  return period.fairMarketValue
    .minus(period.managementFees)
    .plus(period.recyclableFees);
}

/**
 * Calculate standard NAV (no fee adjustment)
 *
 * NAV = FMV
 *
 * @param period - Fee basis period
 * @returns Standard NAV
 */
export function calculateStandardNAV(period: FeeBasisPeriod): Decimal {
  return period.fairMarketValue;
}

/**
 * Project capital call schedule (pacing model)
 *
 * Simple S-curve projection for capital calls over investment period.
 * Used when no actual capital call data exists.
 *
 * @param fundSize - Total committed capital
 * @param investmentPeriodQuarters - Length of investment period
 * @param numQuarters - Total quarters to project
 * @returns Cumulative capital calls by quarter
 */
export function projectCapitalCalls(
  fundSize: Decimal,
  investmentPeriodQuarters: number,
  numQuarters: number
): Decimal[] {
  const schedule: Decimal[] = [];

  for (let q = 0; q < numQuarters; q++) {
    if (q >= investmentPeriodQuarters) {
      // After investment period, no new calls
      schedule.push(fundSize);
    } else {
      // S-curve ramp during investment period
      const progress = q / investmentPeriodQuarters;
      const sCurve = 1 / (1 + Math.exp(-10 * (progress - 0.5)));
      schedule.push(fundSize.times(sCurve));
    }
  }

  return schedule;
}

/**
 * Project distribution schedule (J-curve model)
 *
 * Distributions follow J-curve path with early DPI near zero,
 * then rapid growth during harvest phase.
 *
 * @param fundSize - Total committed capital
 * @param targetTVPI - Target multiple (e.g., 2.5x)
 * @param fundLifeQuarters - Total fund life in quarters
 * @param numQuarters - Quarters to project
 * @returns Cumulative distributions by quarter
 */
export function projectDistributions(
  fundSize: Decimal,
  targetTVPI: number,
  fundLifeQuarters: number,
  numQuarters: number
): Decimal[] {
  const schedule: Decimal[] = [];
  const targetDistributions = fundSize.times(targetTVPI);

  for (let q = 0; q < numQuarters; q++) {
    if (q >= fundLifeQuarters) {
      // After fund life, all distributions complete
      schedule.push(targetDistributions);
    } else {
      // J-curve: slow start, rapid growth in harvest phase
      const progress = q / fundLifeQuarters;

      // Gompertz curve (asymmetric S-curve)
      const a = 1.0; // Upper asymptote
      const b = 0.95; // Displacement
      const c = 0.15; // Growth rate

      const dpiRatio = a * Math.exp(-b * Math.exp(-c * q));
      schedule.push(targetDistributions.times(Math.max(0, dpiRatio)));
    }
  }

  return schedule;
}

/**
 * Calculate TVPI from DPI and NAV
 *
 * TVPI = (Distributions + NAV) / Called Capital
 *
 * @param dpi - Distributions to Paid-In
 * @param nav - Net Asset Value
 * @param calledCapital - Total called capital
 * @returns TVPI multiple
 */
export function calculateTVPI(
  dpi: Decimal,
  nav: Decimal,
  calledCapital: Decimal
): Decimal {
  if (calledCapital.isZero()) {
    return new Decimal(0);
  }

  const totalValue = dpi.plus(nav);
  return totalValue.div(calledCapital);
}

/**
 * Calculate DPI from cumulative distributions
 *
 * DPI = Distributions / Called Capital
 *
 * @param distributions - Cumulative distributions
 * @param calledCapital - Total called capital
 * @returns DPI multiple
 */
export function calculateDPI(
  distributions: Decimal,
  calledCapital: Decimal
): Decimal {
  if (calledCapital.isZero()) {
    return new Decimal(0);
  }

  return distributions.div(calledCapital);
}

/**
 * Calculate RVPI (Residual Value to Paid-In)
 *
 * RVPI = NAV / Called Capital
 *
 * @param nav - Net Asset Value
 * @param calledCapital - Total called capital
 * @returns RVPI multiple
 */
export function calculateRVPI(
  nav: Decimal,
  calledCapital: Decimal
): Decimal {
  if (calledCapital.isZero()) {
    return new Decimal(0);
  }

  return nav.div(calledCapital);
}

// shared/lib/jcurve-fit.ts
/**
 * Nonlinear least squares curve fitting using Levenberg-Marquardt algorithm
 *
 * Wraps ml-levenberg-marquardt library to fit Gompertz/logistic curves
 * to target TVPI with robust error handling and fallback strategies.
 */

import * as LMModule from 'ml-levenberg-marquardt';
import { gompertz, logistic } from './jcurve-shapes';

// ml-levenberg-marquardt default export
const LM = (LMModule as any).default || LMModule;

export type CurveKind = 'gompertz' | 'logistic';

export interface FitOptions {
  maxIterations?: number;
}

export interface FitResult {
  params: number[];
  rmse: number;
}

/**
 * Fit TVPI curve to target value using nonlinear least squares
 *
 * @param kind - 'gompertz' or 'logistic'
 * @param xs - Time points (in years)
 * @param ys - Seed TVPI values (piecewise or historical)
 * @param K - Target TVPI at horizon
 * @param opts - Fitting options
 * @returns Fitted parameters and root-mean-square error
 *
 * @example
 * const { params, rmse } = fitTVPI('gompertz', [0, 5, 10], [0.95, 1.5, 2.5], 2.5);
 * // params = [b, c] for gompertz
 * // rmse indicates fit quality (lower is better)
 */
export function fitTVPI(
  kind: CurveKind,
  xs: number[],
  ys: number[],
  K: number,
  opts?: FitOptions
): FitResult {
  const modelFactory = (initial: number[]) =>
    (p: number[]) => (t: number) =>
      kind === 'gompertz'
        ? gompertz(t, K, p[0] ?? initial[0] ?? 1, p[1] ?? initial[1] ?? 0.5)
        : logistic(t, K, p[0] ?? initial[0] ?? 0.8, p[1] ?? initial[1] ?? 1);

  // Initial parameter guesses
  const initial = kind === 'gompertz'
    ? [1.0, 0.5]  // [b, c] - reasonable defaults for 10yr fund
    : [0.8, xs[Math.floor(xs.length / 2)] || 1];  // [r, t0]

  try {
    const result = LM(
      { x: xs, y: ys },
      modelFactory(initial),
      {
        initialValues: initial,
        maxIterations: opts?.maxIterations ?? 100,
      }
    );

    const params = Array.isArray(result.parameterValues)
      ? (result.parameterValues as number[])
      : initial;

    const rmse = Math.sqrt(
      result.residuals.reduce((s: number, v: number) => s + v * v, 0) / xs.length
    );

    return { params, rmse };
  } catch (error) {
    // Fit failed - return initial guess with NaN RMSE
    // Caller should fall back to piecewise path
    return { params: initial, rmse: Number.NaN };
  }
}

// shared/lib/jcurve.ts
/**
 * J-Curve Engine (REVISED with all fixes applied)
 *
 * IMPORTANT ASSUMPTIONS & LIMITATIONS:
 *
 * 1. **Distribution Coefficient**: Configurable via `finalDistributionCoefficient`
 *    (default 0.7 = 70%). This is a heuristic; actual distribution % varies by fund strategy.
 *
 * 2. **NAV Calculation**: Two modes available:
 *    - 'standard' (default): NAV = Total Value - DPI
 *    - 'fee-adjusted': NAV = Total Value - DPI - Fees (non-standard)
 *
 * 3. **Curve Fitting**: Gompertz/logistic curves fitted to target TVPI. Check `fitRMSE`
 *    for fit quality; use piecewise fallback for low-confidence scenarios.
 *
 * 4. **Sensitivity Bands**: Parameter perturbation analysis, NOT statistical confidence intervals.
 *
 * VALIDATION REQUIRED:
 * - Compare against Excel/Python golden datasets
 * - Validate with domain experts for your fund strategy
 * - Consider Monte Carlo for true probabilistic forecasting
 */

import Decimal from 'decimal.js';
import { fitTVPI } from './jcurve-fit';
import { gompertz, logistic } from './jcurve-shapes';

export type CurveKind = 'gompertz' | 'logistic' | 'piecewise';
export type PacingStrategy = 'front-loaded' | 'flat' | 'back-loaded';
export type Step = 'quarter' | 'year';
export type NavCalculationMode = 'standard' | 'fee-adjusted';

export interface JCurveConfig {
  kind: CurveKind;
  horizonYears: number;
  investYears: number;
  targetTVPI: Decimal;
  startTVPI?: Decimal;
  step: Step;
  pacingStrategy?: PacingStrategy;
  distributionLag?: number;
  confidenceEpsilon?: number;
  /** Fraction of total value eventually distributed (default 0.7 = 70%) */
  finalDistributionCoefficient?: number;
  /** NAV calculation mode: 'standard' (default) or 'fee-adjusted' */
  navCalculationMode?: NavCalculationMode;
}

export interface JCurvePath {
  tvpi: Decimal[];
  nav: Decimal[];
  dpi: Decimal[];
  calls: Decimal[];
  fees: Decimal[];
  params: Record<string, number | Decimal>;
  fitRMSE?: number;
  /** Sensitivity bands - NOT probabilistic confidence intervals */
  sensitivityBands?: { low: Decimal[]; high: Decimal[] };
}

/**
 * Compute J-curve path with TVPI, NAV, DPI projections
 *
 * @param cfg - Configuration with all assumptions explicit
 * @param feeTimelinePerPeriod - Per-period management fees (length N)
 * @param calledSoFar - Optional: actual capital calls to-date (Current mode)
 * @param dpiSoFar - Optional: actual distributions to-date (Current mode)
 * @returns Complete J-curve path with sensitivity bands
 */

export function computeJCurvePath(
  cfg: JCurveConfig,
  feeTimelinePerPeriod: Decimal[],
  calledSoFar?: Decimal[],
  dpiSoFar?: Decimal[]
): JCurvePath {
  const periodsPerYear = cfg.step === 'quarter' ? 4 : 1;
  const N = Math.ceil(cfg.horizonYears * periodsPerYear);
  const xs = Array.from({ length: N + 1 }, (_, i) => i / periodsPerYear);
  const K = cfg.targetTVPI.toNumber();
  const startTVPI = cfg.startTVPI?.toNumber() ?? 0.95;

  // Step 1: Generate/fit TVPI curve
  let tvpiDecimals: Decimal[];
  let paramsRecord: Record<string, number | Decimal> = {};
  let rmse: number | undefined;

  if (cfg.kind === 'piecewise') {
    const seed = generatePiecewiseSeed(xs, K, cfg);
    tvpiDecimals = seed.map(v => new Decimal(v));
    rmse = undefined;
  } else {
    const ysSeed = generatePiecewiseSeed(xs, K, cfg);

    // Calibrate to actuals if provided (Current mode)
    if (calledSoFar && calledSoFar.length > 0) {
      const calledCum = cumulativeFromPeriods(calledSoFar);
      const dpiCum = dpiSoFar
        ? cumulativeFromPeriods(dpiSoFar)
        : Array(calledCum.length).fill(new Decimal(0));

      for (let i = 0; i < Math.min(calledSoFar.length, ysSeed.length); i++) {
        const called = calledCum[i + 1];
        if (called && called.gt(0)) {
          // Crude observed TVPI approximation
          const dpiVal = dpiCum[i + 1];
          if (dpiVal) {
            const approxTvpi = 1 + dpiVal.div(called).toNumber();
            ysSeed[i] = approxTvpi || ysSeed[i];
          }
        }
      }
    }

    const fit = fitTVPI(
      cfg.kind === 'gompertz' ? 'gompertz' : 'logistic',
      xs,
      ysSeed,
      K,
      { maxIterations: 200 }
    );
    rmse = fit.rmse;

    const tvpiArr = xs.map(t =>
      new Decimal(
        cfg.kind === 'gompertz'
          ? gompertz(t, K, fit.params[0] ?? 1, fit.params[1] ?? 0.5)
          : logistic(t, K, fit.params[0] ?? 0.8, fit.params[1] ?? 1)
      )
    );

    // Sanitize: monotonic + endpoints
    const firstElem = tvpiArr[0];
    if (firstElem) {
      tvpiArr[0] = Decimal.max(firstElem, new Decimal(startTVPI));
    }
    tvpiArr[tvpiArr.length - 1] = new Decimal(K);
    for (let i = 1; i < tvpiArr.length; i++) {
      const current = tvpiArr[i];
      const previous = tvpiArr[i - 1];
      if (current && previous && current.lt(previous)) {
        tvpiArr[i] = previous;
      }
    }

    tvpiDecimals = tvpiArr;
    paramsRecord =
      cfg.kind === 'gompertz'
        ? { b: fit.params[0] ?? 1, c: fit.params[1] ?? 0.5 }
        : { r: fit.params[0] ?? 0.8, t0: fit.params[1] ?? 1 };
  }

  // Step 2: Generate capital calls (normalized)
  const calls = generateCapitalCalls(cfg, N, calledSoFar);

  // Step 3: Materialize NAV & DPI
  const calledCumFull = cumulativeFromPeriods(calls);
  const feesCum = cumulativeFromPeriods(feeTimelinePerPeriod);
  const { nav, dpi } = materializeNAVandDPI(
    tvpiDecimals,
    calledCumFull,
    feesCum,
    cfg,
    dpiSoFar
  );

  // Step 4: Sensitivity bands
  const sensitivityBands = computeSensitivityBands(cfg, paramsRecord, rmse, N, xs);

  const feesOut = padOrTrimDecimals(feeTimelinePerPeriod, N);

  return {
    tvpi: tvpiDecimals,
    nav,
    dpi,
    calls,
    fees: feesOut,
    params: paramsRecord,
    ...(rmse !== undefined ? { fitRMSE: rmse } : {}),
    ...(sensitivityBands !== undefined ? { sensitivityBands } : {}),
  };
}

/* ---------------------- Internal Helpers ---------------------- */

function generatePiecewiseSeed(
  xs: number[],
  targetTVPI: number,
  cfg: JCurveConfig
): number[] {
  const out: number[] = [];
  const investFrac = Math.max(0, Math.min(1, cfg.investYears / cfg.horizonYears));
  const holdingFrac = 0.5;
  const harvestStart = Math.min(1, investFrac + holdingFrac);
  const start = cfg.startTVPI?.toNumber() ?? 1.0;

  for (const t of xs) {
    const tNorm = t / cfg.horizonYears;
    if (tNorm <= investFrac) {
      const v = start - (start - 0.9) * (tNorm / Math.max(1e-9, investFrac));
      out.push(v);
    } else if (tNorm <= harvestStart) {
      const frac = (tNorm - investFrac) / Math.max(1e-9, harvestStart - investFrac);
      out.push(0.9 + (targetTVPI - 0.9) * frac);
    } else {
      out.push(targetTVPI);
    }
  }
  return out;
}

function generateCapitalCalls(
  cfg: JCurveConfig,
  N: number,
  calledSoFar?: Decimal[]
): Decimal[] {
  const periodsPerYear = cfg.step === 'quarter' ? 4 : 1;
  const investPeriods = Math.max(1, Math.ceil(cfg.investYears * periodsPerYear));
  const prefix = (calledSoFar ?? []).slice(0, investPeriods);
  const calls: Decimal[] = [];

  for (let i = 0; i < investPeriods; i++) {
    if (i < prefix.length) {
      const prefixVal = prefix[i];
      calls.push(new Decimal(prefixVal ?? 0));
      continue;
    }
    let w = 1;
    if (cfg.pacingStrategy === 'front-loaded')
      w = 1.5 - i / Math.max(1, investPeriods - 1);
    if (cfg.pacingStrategy === 'back-loaded')
      w = 0.5 + i / Math.max(1, investPeriods - 1);
    calls.push(new Decimal(w));
  }

  for (let i = investPeriods; i < N; i++) calls.push(new Decimal(0));

  // Normalize sum to 1
  const prefixSum = calls
    .slice(0, investPeriods)
    .reduce((s, v) => s.plus(v), new Decimal(0));
  if (prefixSum.gt(0)) {
    for (let i = 0; i < investPeriods; i++) {
      const callVal = calls[i];
      if (callVal) calls[i] = callVal.div(prefixSum);
    }
  } else {
    for (let i = 0; i < investPeriods; i++)
      calls[i] = new Decimal(1 / investPeriods);
  }

  while (calls.length < N) calls.push(new Decimal(0));
  return calls.slice(0, N);
}

function materializeNAVandDPI(
  tvpi: Decimal[],
  calledCum: Decimal[],
  feesCum: Decimal[],
  cfg: JCurveConfig,
  dpiSoFar?: Decimal[]
): { nav: Decimal[]; dpi: Decimal[] } {
  const N = tvpi.length - 1;
  const periodsPerYear = cfg.step === 'quarter' ? 4 : 1;
  const distLagPeriods = Math.round(
    (cfg.distributionLag ?? cfg.investYears + 2) * periodsPerYear
  );
  const finalDistCoef = cfg.finalDistributionCoefficient ?? 0.7;
  const navMode: NavCalculationMode = cfg.navCalculationMode ?? 'standard';

  const nav: Decimal[] = [];
  const dpi: Decimal[] = [];

  for (let i = 0; i < N; i++) {
    const called = calledCum[i + 1] ?? new Decimal(0);
    const tvpiVal = tvpi[i + 1] ?? new Decimal(0);
    const totalValue = tvpiVal.mul(called);
    const feesToDate = feesCum[i + 1] ?? new Decimal(0);

    // DPI ramp logic
    let dpiVal = new Decimal(0);
    if (i + 1 < distLagPeriods) {
      const dpiSoFarVal = dpiSoFar?.[i];
      dpiVal = dpiSoFarVal ? new Decimal(dpiSoFarVal) : new Decimal(0);
    } else {
      const rampFrac = Math.min(
        1,
        (i + 1 - distLagPeriods + 1) / Math.max(1, N - distLagPeriods + 1)
      );
      const targetDPI = totalValue.mul(finalDistCoef).mul(rampFrac);
      dpiVal = targetDPI;
    }

    // Ensure monotonic
    const lastDpi = dpi[dpi.length - 1];
    if (lastDpi && dpiVal.lt(lastDpi))
      dpiVal = lastDpi;
    dpi.push(dpiVal);

    // NAV calculation modes
    let navVal: Decimal;
    if (navMode === 'fee-adjusted') {
      // Non-standard: subtract fees explicitly
      navVal = Decimal.max(new Decimal(0), totalValue.minus(dpiVal).minus(feesToDate));
    } else {
      // Standard: NAV = Total Value - DPI
      navVal = Decimal.max(new Decimal(0), totalValue.minus(dpiVal));
    }
    nav.push(navVal);
  }

  return { nav, dpi };
}

/**
 * Compute sensitivity bands via parameter perturbation
 * NOTE: These are NOT statistical confidence intervals
 */
function computeSensitivityBands(
  cfg: JCurveConfig,
  params: Record<string, number | Decimal>,
  rmse: number | undefined,
  N: number,
  xs: number[]
): { low: Decimal[]; high: Decimal[] } | undefined {
  if (!rmse || isNaN(rmse)) return undefined;
  const eps = cfg.confidenceEpsilon ?? Math.min(0.1, rmse * 2);
  const K = cfg.targetTVPI.toNumber();
  const low: Decimal[] = [];
  const high: Decimal[] = [];

  if (cfg.kind === 'gompertz') {
    const b = Number(params['b'] ?? 1);
    const c = Number(params['c'] ?? 0.5);
    for (const t of xs) {
      low.push(new Decimal(gompertz(t, K, b * (1 + eps), c * (1 - eps))));
      high.push(new Decimal(gompertz(t, K, b * (1 - eps), c * (1 + eps))));
    }
  } else if (cfg.kind === 'logistic') {
    // FIXED: Use correct logistic parameter names
    const r = Number(params['r'] ?? 0.8);
    const t0 = Number(params['t0'] ?? xs.length / 2);
    for (const t of xs) {
      low.push(new Decimal(logistic(t, K, r * (1 - eps), t0 * (1 + eps))));
      high.push(new Decimal(logistic(t, K, r * (1 + eps), t0 * (1 - eps))));
    }
  } else {
    return undefined;
  }

  // Sanitize: monotonic + clamp endpoints
  for (let i = 1; i < low.length; i++) {
    const lowCurrent = low[i];
    const lowPrevious = low[i - 1];
    const highCurrent = high[i];
    const highPrevious = high[i - 1];

    if (lowCurrent && lowPrevious && lowCurrent.lt(lowPrevious)) {
      low[i] = lowPrevious;
    }
    if (highCurrent && highPrevious && highCurrent.lt(highPrevious)) {
      high[i] = highPrevious;
    }
  }
  const lowFirst = low[0];
  if (lowFirst) {
    low[0] = Decimal.max(lowFirst, new Decimal(cfg.startTVPI?.toNumber() ?? 0.9));
  }
  high[high.length - 1] = new Decimal(K);
  return { low, high };
}

export function cumulativeFromPeriods(periods: Decimal[]): Decimal[] {
  const out: Decimal[] = [new Decimal(0)];
  for (const v of periods) {
    const last = out[out.length - 1];
    if (last) {
      out.push(last.plus(v));
    }
  }
  return out;
}

function padOrTrimDecimals(arr: Decimal[], n: number): Decimal[] {
  const out = (arr ?? []).slice(0, n);
  while (out.length < n) out.push(new Decimal(0));
  return out;
}

/**
 * Reserves v1.1 Calculation Engine
 * - Configurable reserve percentage
 * - Optional "remain" pass for additional allocation
 * - Integer cents for precision
 * - Exit MOIC-based ranking
 * - Comprehensive audit trail
 */

import type {
  Company,
  ReservesConfig,
  ReservesInput,
  ReservesOutput,
  ReservesResult,
  AllocationDecision
} from '@shared/types/reserves-v11';

// Helper function to calculate cap for a company
function calculateCap(company: Company, config: ReservesConfig): number {
  const { cap_policy } = config;

  switch (cap_policy.kind) {
    case 'fixed_percent': {
      const percent = cap_policy.default_percent || 0.5; // Default 50%
      return Math.floor((company.invested_cents || 0) * percent);
    }

    case 'stage_based': {
      const stage = company.stage || 'unknown';
      const caps = cap_policy.stage_caps || {};
      const percent = caps[stage] || cap_policy.default_percent || 0.5;
      return Math.floor((company.invested_cents || 0) * percent);
    }

    case 'custom': {
      if (cap_policy.custom_fn) {
        return cap_policy.custom_fn(company);
      }
      return Math.floor((company.invested_cents || 0) * 0.5);
    }

    default:
      return Math.floor((company.invested_cents || 0) * 0.5);
  }
}

// Main calculation function with safety and invariants
export function calculateReservesSafe(
  input: ReservesInput,
  config: ReservesConfig
): ReservesResult {
  const startTime = performance.now();
  const warnings: string[] = [];

  try {
    // Input validation
    if (!input.companies || input.companies.length === 0) {
      return {
        ok: true,
        data: {
          allocations: [],
          remaining_cents: 0,
          metadata: {
            total_available_cents: 0,
            total_allocated_cents: 0,
            companies_funded: 0,
            max_iterations: 0,
            conservation_check: true,
            exit_moic_ranking: []
          }
        },
        warnings: ['No companies provided'],
        metrics: {
          duration_ms: performance.now() - startTime,
          company_count: 0,
          policy_type: config.cap_policy.kind
        }
      };
    }

    // Calculate total available reserves
    const totalInitial = input.companies.reduce((sum: any, c: any) => sum + (c.invested_cents || 0), 0);
    const available = Math.floor((totalInitial * config.reserve_bps) / 10_000);
    let remaining = available;

    // Rank companies by Exit MOIC (descending)
    const ranked = [...input.companies].sort((a: any, b: any) => {
      const moicA = a.exit_moic_bps || 0;
      const moicB = b.exit_moic_bps || 0;
      if (moicB !== moicA) return moicB - moicA;
      // Secondary sort by invested amount for stability
      return (b.invested_cents || 0) - (a.invested_cents || 0);
    });

    const exitMoicRanking = ranked.map(c => c.id);
    const allocations: AllocationDecision[] = [];
    const companyAllocations = new Map<string, number>();

    // Single allocation pass
    const performAllocationPass = (iteration: number) => {
      for (const company of ranked) {
        if (remaining <= 0) break;

        const cap = calculateCap(company, config);
        const already = companyAllocations['get'](company.id) || 0;
        const room = Math.max(0, cap - already);

        if (room <= 0) continue;

        const allot = Math.min(remaining, room);

        if (allot > 0) {
          const newTotal = already + allot;
          companyAllocations['set'](company.id, newTotal);

          // Find and update existing allocation or create new
          const existingIndex = allocations.findIndex(a => a.company_id === company.id);

          if (existingIndex >= 0) {
            allocations[existingIndex] = {
              company_id: company.id,
              planned_cents: newTotal,
              reason: `Ranked #${exitMoicRanking.indexOf(company.id) + 1} by Exit MOIC (${(company.exit_moic_bps || 0) / 100}%), iteration ${iteration}`,
              cap_cents: cap,
              iteration
            };
          } else {
            allocations.push({
              company_id: company.id,
              planned_cents: allot,
              reason: `Ranked #${exitMoicRanking.indexOf(company.id) + 1} by Exit MOIC (${(company.exit_moic_bps || 0) / 100}%), iteration ${iteration}`,
              cap_cents: cap,
              iteration
            });
          }

          remaining -= allot;
        }
      }
    };

    // First pass
    performAllocationPass(1);

    // Optional "remain" pass
    if (config.remain_passes === 1 && remaining > 0) {
      performAllocationPass(2);
    }

    // Calculate totals for invariant checking
    const totalAllocated = allocations.reduce((sum: any, a: any) => sum + a.planned_cents, 0);

    // Conservation invariant check
    const conservationCheck = Math.abs((totalAllocated + remaining) - available) <= 1; // Allow 1 cent rounding

    if (!conservationCheck) {
      warnings.push(`Conservation check failed: allocated=${totalAllocated}, remaining=${remaining}, available=${available}`);
      // Normalize to maintain invariant
      remaining = Math.max(0, available - totalAllocated);
    }

    const output: ReservesOutput = {
      allocations,
      remaining_cents: remaining,
      metadata: {
        total_available_cents: available,
        total_allocated_cents: totalAllocated,
        companies_funded: allocations.length,
        max_iterations: config.remain_passes === 1 ? 2 : 1,
        conservation_check: conservationCheck,
        exit_moic_ranking: exitMoicRanking
      }
    };

    return {
      ok: true,
      data: output,
      ...(warnings.length > 0 ? { warnings } : {}),
      metrics: {
        duration_ms: performance.now() - startTime,
        company_count: input.companies.length,
        policy_type: config.cap_policy.kind
      }
    };

  } catch (error) {
    return {
      ok: false,
      error: error instanceof Error ? error.message : 'Unknown error',
      metrics: {
        duration_ms: performance.now() - startTime,
        company_count: input.companies.length,
        policy_type: config.cap_policy.kind
      }
    };
  }
}

// Export a simpler interface for common use cases
export function calculateReserves(
  companies: Company[],
  reservePercent: number,
  enableRemainPass: boolean = false
): ReservesResult {
  const config: ReservesConfig = {
    reserve_bps: Math.round(reservePercent * 10000),
    remain_passes: enableRemainPass ? 1 : 0,
    cap_policy: {
      kind: 'fixed_percent',
      default_percent: 0.5
    },
    audit_level: 'basic'
  };

  const input: ReservesInput = {
    companies,
    fund_size_cents: companies.reduce((sum: any, c: any) => sum + (c.invested_cents || 0), 0),
    quarter_index: new Date().getFullYear() * 4 + Math.floor(new Date().getMonth() / 3)
  };

  return calculateReservesSafe(input, config);
}

/**
 * CapitalCallPolicy Schema
 * Flexible capital call timing and scheduling
 */

import { z } from 'zod';
import Decimal from 'decimal.js';
import { ZodPercentage } from './decimal-zod';

/**
 * Capital call modes
 */
export const CapitalCallMode = z.enum([
  'upfront',      // All capital called at fund inception
  'quarterly',    // Regular quarterly calls
  'semi_annual',  // Every 6 months
  'annual',       // Yearly calls
  'as_needed',    // Called when investment opportunities arise
  'custom'        // User-defined schedule
]);

export type CapitalCallMode = z.infer<typeof CapitalCallMode>;

/**
 * Custom capital call schedule entry
 */
export const CustomCallScheduleSchema = z.object({
  /** Month from fund inception */
  month: z.number().int().min(0),

  /** Amount to call (as % of committed capital) */
  percentage: ZodPercentage,

  /** Optional description */
  description: z.string().optional()
});

export type CustomCallSchedule = z.infer<typeof CustomCallScheduleSchema>;

/**
 * Base capital call policy
 */
const BaseCapitalCallPolicySchema = z.object({
  /** Policy identifier */
  id: z.string(),

  /** Human-readable name */
  name: z.string(),

  /** Notice period for capital calls (days) */
  noticePeriodDays: z.number().int().min(0).default(30),

  /** Funding period (days from notice to payment due) */
  fundingPeriodDays: z.number().int().min(0).default(60)
});

/**
 * Upfront capital call policy
 */
const UpfrontPolicySchema = BaseCapitalCallPolicySchema.extend({
  mode: z.literal('upfront'),

  /** Percentage of committed capital to call upfront */
  percentage: ZodPercentage.default(new Decimal(1))
});

/**
 * Periodic capital call policy (quarterly, semi-annual, annual)
 */
const PeriodicPolicySchema = BaseCapitalCallPolicySchema.extend({
  mode: z.enum(['quarterly', 'semi_annual', 'annual']),

  /** Percentage to call each period */
  percentagePerPeriod: ZodPercentage,

  /** Start year */
  startYear: z.number().int().positive().default(1),

  /** End year */
  endYear: z.number().int().positive()
}).refine(
  (data) => data.endYear >= data.startYear,
  {
    message: 'endYear must be >= startYear',
    path: ['endYear']
  }
);

/**
 * As-needed capital call policy
 */
const AsNeededPolicySchema = BaseCapitalCallPolicySchema.extend({
  mode: z.literal('as_needed'),

  /** Minimum notice period (days) */
  minimumNoticeDays: z.number().int().min(0).default(15),

  /** Maximum call size as % of committed capital */
  maxCallSizePercent: ZodPercentage.default(new Decimal(0.25))
});

/**
 * Custom schedule capital call policy
 */
const CustomPolicySchema = BaseCapitalCallPolicySchema.extend({
  mode: z.literal('custom'),

  /** Custom call schedule */
  schedule: z.array(CustomCallScheduleSchema).min(1)
}).refine(
  (data) => {
    // Validate total percentage <= 100%
    const totalPercent = data.schedule.reduce(
      (sum, entry) => sum.plus(entry.percentage),
      new Decimal(0)
    );
    return totalPercent.lte(1);
  },
  {
    message: 'Total custom schedule calls cannot exceed 100%',
    path: ['schedule']
  }
).refine(
  (data) => {
    // Validate schedule is sorted by month
    for (let i = 1; i < data.schedule.length; i++) {
      const current = data.schedule[i];
      const previous = data.schedule[i - 1];
      if (!current || !previous || current.month <= previous.month) {
        return false;
      }
    }
    return true;
  },
  {
    message: 'Custom schedule must be sorted by month',
    path: ['schedule']
  }
);

/**
 * Discriminated union of all capital call policies
 */
export const CapitalCallPolicySchema = z.union([
  UpfrontPolicySchema,
  PeriodicPolicySchema,
  AsNeededPolicySchema,
  CustomPolicySchema
]);

export type CapitalCallPolicy = z.infer<typeof CapitalCallPolicySchema>;

/**
 * Calculate capital calls for a given month
 */
export function calculateCapitalCall(
  policy: CapitalCallPolicy,
  committedCapital: Decimal,
  currentMonth: number,
  uncalledCapital: Decimal
): Decimal {
  switch (policy.mode) {
    case 'upfront':
      return currentMonth === 0 ? committedCapital.times(policy['percentage']) : new Decimal(0);

    case 'quarterly': {
      if (currentMonth % 3 !== 0) return new Decimal(0);
      const currentYear = Math.floor(currentMonth / 12) + 1;
      if (currentYear < policy['startYear'] || currentYear > policy['endYear']) {
        return new Decimal(0);
      }
      return committedCapital.times(policy['percentagePerPeriod']);
    }

    case 'semi_annual': {
      if (currentMonth % 6 !== 0) return new Decimal(0);
      const currentYear = Math.floor(currentMonth / 12) + 1;
      if (currentYear < policy['startYear'] || currentYear > policy['endYear']) {
        return new Decimal(0);
      }
      return committedCapital.times(policy['percentagePerPeriod']);
    }

    case 'annual': {
      if (currentMonth % 12 !== 0) return new Decimal(0);
      const currentYear = Math.floor(currentMonth / 12) + 1;
      if (currentYear < policy['startYear'] || currentYear > policy['endYear']) {
        return new Decimal(0);
      }
      return committedCapital.times(policy['percentagePerPeriod']);
    }

    case 'as_needed':
      // As-needed calls are triggered by investment opportunities
      // This function doesn't have access to that context
      return new Decimal(0);

    case 'custom': {
      const entry = policy['schedule'].find((s: { month: number }) => s.month === currentMonth);
      return entry ? committedCapital.times(entry.percentage) : new Decimal(0);
    }

    default:
      return new Decimal(0);
  }
}

/**
 * FeeProfile Schema
 * Parameterized fee structure with multiple bases, step-downs, and recycling
 */

import { z } from 'zod';
import Decimal from 'decimal.js';
import { ZodPercentage, ZodPositiveDecimal } from './decimal-zod';

/**
 * Fee calculation bases (what the fee percentage applies to)
 */
export const FeeBasisType = z.enum([
  'committed_capital',           // Total fund commitment
  'called_capital_cumulative',   // All capital called to date
  'called_capital_net_of_returns', // Called capital minus distributions
  'invested_capital',            // Capital deployed in investments
  'fair_market_value',          // Current portfolio FMV
  'unrealized_cost'             // Cost basis of unrealized investments
]);

export type FeeBasisType = z.infer<typeof FeeBasisType>;

/**
 * Single fee tier with basis, rate, and timing
 */
export const FeeTierSchema = z.object({
  /** Fee calculation basis */
  basis: FeeBasisType,

  /** Annual fee rate as percentage (e.g., 0.02 = 2%) */
  annualRatePercent: ZodPercentage,

  /** Fund year when tier becomes active */
  startYear: z.number().int().positive(),

  /** Fund year when tier ends (optional, defaults to fund end) */
  endYear: z.number().int().positive().optional(),

  /** Optional fee cap as percentage of basis */
  capPercent: ZodPercentage.optional(),

  /** Optional fixed fee cap amount */
  capAmount: ZodPositiveDecimal.optional()
});

export type FeeTier = z.infer<typeof FeeTierSchema>;

/**
 * Fee recycling policy
 */
export const FeeRecyclingPolicySchema = z.object({
  /** Enable fee recycling */
  enabled: z.boolean(),

  /** Maximum recyclable amount as % of committed capital */
  recyclingCapPercent: ZodPercentage,

  /** Term during which fees can be recycled (months) */
  recyclingTermMonths: z.number().int().positive(),

  /** Basis for fee recycling cap */
  basis: FeeBasisType.default('committed_capital'),

  /** Proactively assume recycling up to cap (for forecasting) */
  anticipatedRecycling: z.boolean().default(false)
}).refine(
  (data) => !data.enabled || (data.recyclingCapPercent.gt(0) && data.recyclingTermMonths > 0),
  {
    message: 'Recycling cap and term must be positive when enabled',
    path: ['enabled']
  }
);

export type FeeRecyclingPolicy = z.infer<typeof FeeRecyclingPolicySchema>;

/**
 * Fee holiday (period with suspended fees)
 */
export const FeeHolidaySchema = z.object({
  /** Start month (from fund inception) */
  startMonth: z.number().int().min(0),

  /** Duration of holiday in months */
  durationMonths: z.number().int().positive(),

  /** Reason for holiday (optional documentation) */
  reason: z.string().optional()
});

export type FeeHoliday = z.infer<typeof FeeHolidaySchema>;

/**
 * Complete fee profile
 */
export const FeeProfileSchema = z.object({
  /** Profile identifier */
  id: z.string(),

  /** Human-readable name */
  name: z.string(),

  /** Fee tiers (must be ordered by startYear) */
  tiers: z.array(FeeTierSchema).min(1),

  /** Months when fees step down (for reference) */
  stepDownMonths: z.array(z.number().int().positive()).optional(),

  /** Fee recycling policy */
  recyclingPolicy: FeeRecyclingPolicySchema.optional(),

  /** Fee holidays */
  feeHolidays: z.array(FeeHolidaySchema).optional()
}).refine(
  (data) => {
    // Validate tiers are sorted by startYear
    for (let i = 1; i < data.tiers.length; i++) {
      const current = data.tiers[i];
      const previous = data.tiers[i - 1];
      if (!current || !previous || current.startYear <= previous.startYear) {
        return false;
      }
      // Validate endYear > startYear if present
      const tier = data.tiers[i];
      if (tier && tier.endYear && tier.endYear <= tier.startYear) {
        return false;
      }
    }
    return true;
  },
  {
    message: 'Fee tiers must be sorted by startYear and endYear must be after startYear',
    path: ['tiers']
  }
);

export type FeeProfile = z.infer<typeof FeeProfileSchema>;

/**
 * Fee calculation context (amounts for each basis type)
 */
export interface FeeCalculationContext {
  committedCapital: Decimal;
  calledCapitalCumulative: Decimal;
  calledCapitalNetOfReturns: Decimal;
  investedCapital: Decimal;
  fairMarketValue: Decimal;
  unrealizedCost: Decimal;
  currentMonth: number;
}

/**
 * Calculate management fees for a given period
 */
export function calculateManagementFees(
  profile: FeeProfile,
  context: FeeCalculationContext
): Decimal {
  let totalFees = new Decimal(0);
  const currentYear = Math.floor(context.currentMonth / 12) + 1;

  // Check if in fee holiday
  if (profile.feeHolidays) {
    const inHoliday = profile.feeHolidays.some(holiday => {
      const holidayEnd = holiday.startMonth + holiday.durationMonths;
      return context.currentMonth >= holiday.startMonth && context.currentMonth < holidayEnd;
    });
    if (inHoliday) return new Decimal(0);
  }

  // Calculate fees from active tiers
  for (const tier of profile.tiers) {
    const tierActive = currentYear >= tier.startYear &&
                      (!tier.endYear || currentYear <= tier.endYear);

    if (!tierActive) continue;

    // Get basis amount
    const basisAmount = getBasisAmount(tier.basis, context);

    // Calculate tier fees (annualized, so divide by 12 for monthly)
    let tierFees = basisAmount.times(tier.annualRatePercent).div(12);

    // Apply caps if present
    if (tier.capPercent) {
      const cap = basisAmount.times(tier.capPercent);
      tierFees = Decimal.min(tierFees, cap);
    }
    if (tier.capAmount) {
      tierFees = Decimal.min(tierFees, tier.capAmount);
    }

    totalFees = totalFees.plus(tierFees);
  }

  return totalFees;
}

/**
 * Get basis amount from context
 */
function getBasisAmount(basis: FeeBasisType, context: FeeCalculationContext): Decimal {
  switch (basis) {
    case 'committed_capital':
      return context.committedCapital;
    case 'called_capital_cumulative':
      return context.calledCapitalCumulative;
    case 'called_capital_net_of_returns':
      return context.calledCapitalNetOfReturns;
    case 'invested_capital':
      return context.investedCapital;
    case 'fair_market_value':
      return context.fairMarketValue;
    case 'unrealized_cost':
      return context.unrealizedCost;
  }
}

/**
 * Calculate recyclable fees for a period
 */
export function calculateRecyclableFees(
  profile: FeeProfile,
  feesPaid: Decimal,
  context: FeeCalculationContext
): Decimal {
  if (!profile.recyclingPolicy || !profile.recyclingPolicy.enabled) {
    return new Decimal(0);
  }

  const policy = profile.recyclingPolicy;

  // Check if within recycling term
  if (context.currentMonth > policy.recyclingTermMonths) {
    return new Decimal(0);
  }

  // Calculate recycling cap
  const basisAmount = getBasisAmount(policy.basis, context);
  const cap = basisAmount.times(policy.recyclingCapPercent);

  // Return min of fees paid and cap
  return Decimal.min(feesPaid, cap);
}

import { z } from 'zod';

/**
 * Fund Model Schemas (FROZEN for Iteration A)
 *
 * This file defines the complete input/output contract for the deterministic
 * fund calculation engine. These schemas are FROZEN and should not be modified
 * without a corresponding engine version bump and migration strategy.
 *
 * Version: 1.0.0
 * Last Modified: 2025-10-03
 */

// =====================
// STAGE DEFINITIONS
// =====================

export const StageSchema = z.enum([
  'seed',
  'series_a',
  'series_b',
  'series_c',
  'growth',
]);
export type Stage = z.infer<typeof StageSchema>;

export const StageAllocationSchema = z.object({
  stage: StageSchema,
  allocationPct: z.number().min(0).max(1)
    .describe('Allocation percentage (0.0 to 1.0)'),
});

export type StageAllocation = z.infer<typeof StageAllocationSchema>;

// =====================
// INPUTS (FROZEN API)
// =====================

export const FundModelInputsSchema = z.object({
  // Fund basics
  fundSize: z.number().positive()
    .describe('Total committed capital in dollars'),

  periodLengthMonths: z.number().int().positive()
    .describe('Length of each period in months (e.g., 3 for quarterly)'),

  // Capital call (LOCKED to upfront in Iteration A)
  capitalCallMode: z.literal('upfront')
    .describe('Capital call mode - LOCKED to "upfront" (100% at period 0)'),

  // Fees (management only, with duration limit)
  managementFeeRate: z.number().min(0).max(0.05)
    .describe('Annual management fee as % of committed capital (e.g., 0.02 = 2%)'),

  managementFeeYears: z.number().int().positive().default(10)
    .describe('Number of years to charge management fees (typically 10)'),

  // Stage allocations
  stageAllocations: z.array(StageAllocationSchema)
    .min(1)
    .describe('Allocation of fund across stages - must sum to 100%'),

  // Reserve pool
  reservePoolPct: z.number().min(0).max(0.5)
    .describe('Reserve pool as % of fund size (carved from stage allocations)'),

  // Investment parameters
  averageCheckSizes: z.record(StageSchema, z.number().positive())
    .describe('Average initial check size per stage in dollars'),

  graduationRates: z.record(StageSchema, z.number().min(0).max(1))
    .describe('Per-period graduation rate to next stage (0.0 to 1.0)'),

  exitRates: z.record(StageSchema, z.number().min(0).max(1))
    .describe('Per-period exit rate (0.0 to 1.0)'),

  monthsToGraduate: z.record(StageSchema, z.number().int().positive())
    .describe('Average months to graduate to next stage'),

  monthsToExit: z.record(StageSchema, z.number().int().positive())
    .describe('Average months to exit from stage'),
}).superRefine((inputs, ctx) => {

  // =====================
  // FEASIBILITY CONSTRAINT 1: Stage allocations sum to 100%
  // =====================
  const allocSum = inputs.stageAllocations.reduce((s, a) => s + a.allocationPct, 0);
  if (Math.abs(allocSum - 1.0) > 1e-6) {
    ctx.addIssue({
      code: z.ZodIssueCode.custom,
      message: `Stage allocations must sum to 100%. Current sum: ${(allocSum * 100).toFixed(2)}%. Reserve pool is carved from these allocations.`,
      path: ['stageAllocations'],
    });
  }

  // =====================
  // FEASIBILITY CONSTRAINT 2: Check sizes ≤ stage allocations
  // =====================
  inputs.stageAllocations.forEach((stage, idx) => {
    const stageCapital = inputs.fundSize * stage.allocationPct;
    const avgCheck = inputs.averageCheckSizes[stage.stage];

    if (!avgCheck) return; // Skip if check size not defined

    if (avgCheck > stageCapital) {
      ctx.addIssue({
        code: z.ZodIssueCode.custom,
        message: `Average check size for ${stage.stage} ($${(avgCheck / 1e6).toFixed(2)}M) exceeds stage allocation ($${(stageCapital / 1e6).toFixed(2)}M). At least one investment must be possible.`,
        path: ['averageCheckSizes', stage.stage],
      });
    }
  });

  // =====================
  // FEASIBILITY CONSTRAINT 3: Minimum companies per stage
  // =====================
  inputs.stageAllocations.forEach((stage, idx) => {
    const stageCapital = inputs.fundSize * stage.allocationPct * (1 - inputs.reservePoolPct);
    const avgCheck = inputs.averageCheckSizes[stage.stage];

    if (!avgCheck) return;

    const numCompanies = Math.floor(stageCapital / avgCheck);

    if (numCompanies < 1) {
      ctx.addIssue({
        code: z.ZodIssueCode.custom,
        message: `Stage allocation for ${stage.stage} ($${(stageCapital / 1e6).toFixed(2)}M after reserves) is too small for average check size ($${(avgCheck / 1e6).toFixed(2)}M). Increase stage allocation or reduce check size.`,
        path: ['stageAllocations', idx],
      });
    }
  });

  // =====================
  // FEASIBILITY CONSTRAINT 4: Total initial investments ≤ deployable capital
  // =====================
  const maxManagementFees = inputs.fundSize * inputs.managementFeeRate * inputs.managementFeeYears;
  const deployableCapital = inputs.fundSize - maxManagementFees;

  const totalInitialInvestments = inputs.stageAllocations.reduce((sum, stage) => {
    const stageCapital = inputs.fundSize * stage.allocationPct * (1 - inputs.reservePoolPct);
    const avgCheck = inputs.averageCheckSizes[stage.stage];
    if (!avgCheck) return sum;
    const numCompanies = Math.floor(stageCapital / avgCheck);
    return sum + (numCompanies * avgCheck);
  }, 0);

  if (totalInitialInvestments > deployableCapital) {
    ctx.addIssue({
      code: z.ZodIssueCode.custom,
      message: `Total initial investments ($${(totalInitialInvestments / 1e6).toFixed(2)}M) exceed deployable capital ($${(deployableCapital / 1e6).toFixed(2)}M after ${inputs.managementFeeYears} years of fees). Reduce check sizes or adjust allocations.`,
      path: ['averageCheckSizes'],
    });
  }

  // =====================
  // FEASIBILITY CONSTRAINT 5: Graduation time < Exit time
  // =====================
  const stages = inputs.stageAllocations.map(s => s.stage);
  stages.forEach(stage => {
    const gradTime = inputs.monthsToGraduate[stage];
    const exitTime = inputs.monthsToExit[stage];

    if (gradTime && exitTime && gradTime >= exitTime) {
      ctx.addIssue({
        code: z.ZodIssueCode.custom,
        message: `Graduation time for ${stage} (${gradTime} months) must be less than exit time (${exitTime} months).`,
        path: ['monthsToGraduate', stage],
      });
    }
  });

  // =====================
  // WARNING: Reserve pool sanity check
  // =====================
  if (inputs.reservePoolPct > 0.5) {
    ctx.addIssue({
      code: z.ZodIssueCode.custom,
      message: `Reserve pool (${(inputs.reservePoolPct * 100).toFixed(0)}%) is unusually high. Typical range: 20-40%.`,
      path: ['reservePoolPct'],
      fatal: false, // Warning only
    });
  }

  // =====================
  // WARNING: Preliminary reserve capacity check
  // =====================
  const estimatedReserveNeed = inputs.stageAllocations.reduce((sum, stage) => {
    const stageCapital = inputs.fundSize * stage.allocationPct * (1 - inputs.reservePoolPct);
    const avgCheck = inputs.averageCheckSizes[stage.stage];
    if (!avgCheck) return sum;
    const numCompanies = Math.floor(stageCapital / avgCheck);
    const estimatedFollowOn = avgCheck * 2; // Heuristic: 2x initial check
    return sum + (numCompanies * estimatedFollowOn);
  }, 0);

  const reservePool = inputs.fundSize * inputs.reservePoolPct;

  if (estimatedReserveNeed > reservePool * 1.2) { // 20% buffer
    ctx.addIssue({
      code: z.ZodIssueCode.custom,
      message: `Estimated reserve need ($${(estimatedReserveNeed / 1e6).toFixed(2)}M at 2x initial checks) may exceed reserve pool ($${(reservePool / 1e6).toFixed(2)}M). Consider increasing reservePoolPct.`,
      path: ['reservePoolPct'],
      fatal: false, // Warning only
    });
  }
});

