/**
 * StageProfile Schema
 * Replaces hard-coded exit buckets with stage-driven valuations
 * Supports deterministic cohort math with fractional company counts
 */

import { z } from 'zod';
import Decimal from 'decimal.js';
import { ZodPercentage, ZodPositiveDecimal } from './decimal-zod';

/**
 * Investment stage types
 */
export const StageType = z.enum([
  'pre_seed',
  'seed',
  'series_a',
  'series_b',
  'series_c',
  'growth',
  'late_stage'
]);

export type StageType = z.infer<typeof StageType>;

/**
 * Stage-specific financial and operational assumptions
 */
export const StageDefinitionSchema = z.object({
  /** Stage identifier */
  stage: StageType,

  /** Average funding round size at this stage */
  roundSize: ZodPositiveDecimal,

  /** Average post-money valuation at this stage */
  postMoneyValuation: ZodPositiveDecimal,

  /** ESOP pool percentage allocated in this round */
  esopPercent: ZodPercentage,

  /** Probability of graduating to next stage (0-1) */
  graduationRate: ZodPercentage,

  /** Probability of exiting at this stage (0-1) */
  exitRate: ZodPercentage,

  /** Average months until graduation to next stage */
  monthsToGraduate: z.number().int().positive(),

  /** Average months until exit at this stage */
  monthsToExit: z.number().int().positive(),

  /** Derived failure rate (computed automatically) */
  failureRate: ZodPercentage.optional(),

  /** Exit multiple for successful exits at this stage */
  exitMultiple: ZodPositiveDecimal.default(new Decimal(3)),

  /** Dilution per subsequent round */
  dilutionPerRound: ZodPercentage.default(new Decimal(0.2))
}).refine(
  (data) => {
    // Ensure graduation + exit + failure = 100%
    const sum = data.graduationRate.plus(data.exitRate);
    return sum.lte(1);
  },
  {
    message: 'graduationRate + exitRate cannot exceed 100%',
    path: ['graduationRate']
  }
);

export type StageDefinition = z.infer<typeof StageDefinitionSchema>;

/**
 * Complete stage profile defining company lifecycle
 */
export const StageProfileSchema = z.object({
  /** Profile identifier */
  id: z.string(),

  /** Human-readable profile name */
  name: z.string(),

  /** Ordered array of stages (earliest to latest) */
  stages: z.array(StageDefinitionSchema).min(1),

  /** Initial portfolio size (supports fractional counts for determinism) */
  initialPortfolioSize: ZodPositiveDecimal,

  /** Enable exit proceeds recycling */
  recyclingEnabled: z.boolean().default(false),

  /** Global assumptions */
  assumptions: z.object({
    /** Average dilution per financing round */
    dilutionPerRound: ZodPercentage.default(new Decimal(0.2)),

    /** Follow-on investment multiplier (e.g., 2x initial check) */
    followOnMultiplier: ZodPositiveDecimal.default(new Decimal(2)),

    /** Reserve allocation strategy */
    reserveStrategy: z.enum(['pro_rata', 'winner_picking', 'hybrid']).default('pro_rata')
  }).optional()
}).refine(
  (data) => {
    // Ensure stages are ordered from early to late
    const stageOrder: StageType[] = ['pre_seed', 'seed', 'series_a', 'series_b', 'series_c', 'growth', 'late_stage'];
    for (let i = 1; i < data.stages.length; i++) {
      const current = data.stages[i];
      const previous = data.stages[i - 1];
      if (!current || !previous) {
        return false;
      }
      const prevIdx = stageOrder.indexOf(previous.stage);
      const currIdx = stageOrder.indexOf(current.stage);
      if (currIdx <= prevIdx) {
        return false;
      }
    }
    return true;
  },
  {
    message: 'Stages must be ordered from earliest to latest',
    path: ['stages']
  }
);

export type StageProfile = z.infer<typeof StageProfileSchema>;

/**
 * Helper: Calculate derived failure rate for a stage
 */
export function calculateFailureRate(stage: StageDefinition): Decimal {
  return new Decimal(1)
    .minus(stage.graduationRate)
    .minus(stage.exitRate);
}

/**
 * Helper: Add failure rates to all stages
 */
export function enrichStageProfile(profile: StageProfile): StageProfile & {
  stages: (StageDefinition & { failureRate: Decimal })[];
} {
  return {
    ...profile,
    stages: profile.stages.map(stage => ({
      ...stage,
      failureRate: calculateFailureRate(stage)
    }))
  };
}

/**
 * Cohort progression result
 */
export interface CohortProgression {
  stage: StageType;
  startingCount: Decimal;
  graduatedCount: Decimal;
  exitedCount: Decimal;
  failedCount: Decimal;
  remainingCount: Decimal;
}

/**
 * Calculate deterministic cohort progression through stages
 * Uses fractional counts to avoid rounding errors
 */
export function calculateCohortProgression(
  profile: StageProfile,
  initialCount: Decimal,
  monthsElapsed: number
): CohortProgression[] {
  const enriched = enrichStageProfile(profile);
  const results: CohortProgression[] = [];
  let currentCount = initialCount;

  for (const stage of enriched.stages) {
    const graduated = currentCount.times(stage.graduationRate);
    const exited = currentCount.times(stage.exitRate);
    const failed = currentCount.times(stage.failureRate);
    const remaining = currentCount.minus(graduated).minus(exited).minus(failed);

    results.push({
      stage: stage.stage,
      startingCount: currentCount,
      graduatedCount: graduated,
      exitedCount: exited,
      failedCount: failed,
      remainingCount: remaining
    });

    // Graduated companies flow to next stage
    currentCount = graduated;
  }

  return results;
}

/**
 * CANONICAL STAGE SCHEMA (Single Source of Truth)
 *
 * This file defines the authoritative stage enumeration for the entire codebase.
 * All other stage definitions should either:
 * 1. Import from this file directly, OR
 * 2. Use the normalization utilities to convert to/from legacy formats
 *
 * Canonical format: snake_case (e.g., 'pre_seed', 'series_a')
 *
 * Migration Notes:
 * - Some schemas are FROZEN (fund-model.ts, reserve-engine.contract.ts)
 *   and cannot be modified without version bumps
 * - Use normalizeStage() to convert legacy formats to canonical
 * - Use toHyphenatedStage() for reserve-engine.contract.ts compatibility
 * - Use toCamelCaseStage() for wizard-types.ts compatibility
 */

import { z } from 'zod';

// ============================================================================
// CANONICAL STAGE ENUM (Comprehensive)
// ============================================================================

/**
 * All possible investment stages in canonical snake_case format.
 * This is the superset of all stages used across the codebase.
 */
export const CanonicalStageSchema = z.enum([
  'pre_seed',
  'seed',
  'series_a',
  'series_b',
  'series_c',
  'series_d',
  'growth',
  'late_stage',
]);

export type CanonicalStage = z.infer<typeof CanonicalStageSchema>;

/**
 * All canonical stage values as a readonly array
 */
export const CANONICAL_STAGES: readonly CanonicalStage[] = CanonicalStageSchema.options;

// ============================================================================
// STAGE LABELS (Human-readable)
// ============================================================================

export const STAGE_LABELS: Record<CanonicalStage, string> = {
  pre_seed: 'Pre-Seed',
  seed: 'Seed',
  series_a: 'Series A',
  series_b: 'Series B',
  series_c: 'Series C',
  series_d: 'Series D+',
  growth: 'Growth',
  late_stage: 'Late Stage',
};

// ============================================================================
// LEGACY FORMAT TYPES
// ============================================================================

/** Legacy format: no separator (preseed) - used in shared/schemas.ts */
type NoSeparatorStage = 'preseed' | 'seed' | 'series_a' | 'series_b' | 'series_c' | 'series_dplus';

/** Legacy format: hyphenated (pre-seed) - used in reserve-engine.contract.ts */
type HyphenatedStage = 'pre-seed' | 'seed' | 'series-a' | 'series-b' | 'series-c' | 'series-d-plus' | 'late-stage';

/** Legacy format: camelCase (preSeed) - used in wizard-types.ts */
type CamelCaseStage = 'preSeed' | 'seed' | 'seriesA' | 'seriesB' | 'seriesC' | 'seriesD';

/** Union of all legacy stage formats */
type LegacyStage = NoSeparatorStage | HyphenatedStage | CamelCaseStage | CanonicalStage;

// ============================================================================
// NORMALIZATION UTILITIES
// ============================================================================

/**
 * Mapping from all legacy formats to canonical format
 */
const STAGE_NORMALIZATION_MAP: Record<string, CanonicalStage> = {
  // Canonical (already normalized)
  pre_seed: 'pre_seed',
  seed: 'seed',
  series_a: 'series_a',
  series_b: 'series_b',
  series_c: 'series_c',
  series_d: 'series_d',
  growth: 'growth',
  late_stage: 'late_stage',

  // No-separator format (shared/schemas.ts)
  preseed: 'pre_seed',
  series_dplus: 'series_d',

  // Hyphenated format (reserve-engine.contract.ts)
  'pre-seed': 'pre_seed',
  'series-a': 'series_a',
  'series-b': 'series_b',
  'series-c': 'series_c',
  'series-d-plus': 'series_d',
  'late-stage': 'late_stage',

  // CamelCase format (wizard-types.ts)
  preSeed: 'pre_seed',
  seriesA: 'series_a',
  seriesB: 'series_b',
  seriesC: 'series_c',
  seriesD: 'series_d',
};

/**
 * Normalize any stage format to canonical snake_case format.
 *
 * @param stage - Stage in any format (legacy or canonical)
 * @returns Canonical stage in snake_case format
 * @throws Error if stage is not recognized
 *
 * @example
 * normalizeStage('preseed')     // => 'pre_seed'
 * normalizeStage('pre-seed')    // => 'pre_seed'
 * normalizeStage('preSeed')     // => 'pre_seed'
 * normalizeStage('series_dplus') // => 'series_d'
 */
export function normalizeStage(stage: string): CanonicalStage {
  const normalized = STAGE_NORMALIZATION_MAP[stage];
  if (!normalized) {
    throw new Error(`Unknown stage format: "${stage}". Valid stages: ${Object.keys(STAGE_NORMALIZATION_MAP).join(', ')}`);
  }
  return normalized;
}

/**
 * Safely normalize a stage, returning undefined for invalid stages.
 *
 * @param stage - Stage in any format
 * @returns Canonical stage or undefined if not recognized
 */
export function normalizeStageOrUndefined(stage: string): CanonicalStage | undefined {
  return STAGE_NORMALIZATION_MAP[stage];
}

/**
 * Check if a string is a valid stage in any format.
 */
export function isValidStage(stage: string): boolean {
  return stage in STAGE_NORMALIZATION_MAP;
}

// ============================================================================
// FORMAT CONVERSION UTILITIES
// ============================================================================

/**
 * Mapping from canonical to hyphenated format (for reserve-engine.contract.ts)
 */
const CANONICAL_TO_HYPHENATED: Record<CanonicalStage, HyphenatedStage> = {
  pre_seed: 'pre-seed',
  seed: 'seed',
  series_a: 'series-a',
  series_b: 'series-b',
  series_c: 'series-c',
  series_d: 'series-d-plus',
  growth: 'late-stage', // growth maps to late-stage in hyphenated format
  late_stage: 'late-stage',
};

/**
 * Mapping from canonical to camelCase format (for wizard-types.ts)
 */
const CANONICAL_TO_CAMELCASE: Record<CanonicalStage, CamelCaseStage> = {
  pre_seed: 'preSeed',
  seed: 'seed',
  series_a: 'seriesA',
  series_b: 'seriesB',
  series_c: 'seriesC',
  series_d: 'seriesD',
  growth: 'seriesD', // growth maps to seriesD in camelCase format
  late_stage: 'seriesD', // late_stage maps to seriesD in camelCase format
};

/**
 * Mapping from canonical to no-separator format (for shared/schemas.ts)
 */
const CANONICAL_TO_NO_SEPARATOR: Record<CanonicalStage, NoSeparatorStage> = {
  pre_seed: 'preseed',
  seed: 'seed',
  series_a: 'series_a',
  series_b: 'series_b',
  series_c: 'series_c',
  series_d: 'series_dplus',
  growth: 'series_dplus', // growth maps to series_dplus in no-separator format
  late_stage: 'series_dplus', // late_stage maps to series_dplus in no-separator format
};

/**
 * Convert canonical stage to hyphenated format (reserve-engine.contract.ts compatibility)
 */
export function toHyphenatedStage(stage: CanonicalStage): HyphenatedStage {
  return CANONICAL_TO_HYPHENATED[stage];
}

/**
 * Convert canonical stage to camelCase format (wizard-types.ts compatibility)
 */
export function toCamelCaseStage(stage: CanonicalStage): CamelCaseStage {
  return CANONICAL_TO_CAMELCASE[stage];
}

/**
 * Convert canonical stage to no-separator format (shared/schemas.ts compatibility)
