/**
 * Concurrency Stress Tests
 * Run separately: npm test -- tests/chaos/rls-chaos-suite.test.ts -t "Concurrency"
 */
describe('Concurrency Stress Tests', () => {
  let pool: Pool;

  beforeAll(async () => {
    pool = new Pool({
      connectionString: CHAOS_CONFIG.connectionString,
      max: 50, // Allow more concurrent connections
    });
  });

  afterAll(async () => {
    await pool.end();
  });

  it('should handle 50 concurrent queries without context leakage', async () => {
    const orgs = Array.from({ length: 5 }, (_, i) => `org-${i}`);
    const queries = Array.from({ length: 50 }, (_, i) => ({
      orgId: orgs[i % orgs.length],
      queryId: i,
    }));

    const results = await Promise.all(
      queries.map(async ({ orgId, queryId }) => {
        const client = await pool.connect();

        try {
          await client.query('BEGIN');
          await client.query("SELECT set_config('app.current_org', $1, true)", [orgId]);

          const result = await client.query('SELECT current_org_id() as org');
          const returnedOrg = result.rows[0]?.org;

          await client.query('ROLLBACK');

          return { queryId, expectedOrg: orgId, returnedOrg };
        } finally {
          client.release();
        }
      })
    );

    // Verify no context leakage
    for (const { queryId, expectedOrg, returnedOrg } of results) {
      expect(returnedOrg, `Query ${queryId} context mismatch`).toBe(expectedOrg);
    }
  });

  it('should handle connection pool saturation gracefully', async () => {
    const maxConnections = 50;

    // Saturate pool
    const clients: PoolClient[] = [];
    for (let i = 0; i < maxConnections; i++) {
      clients.push(await pool.connect());
    }

    // Try to get one more (should timeout or queue)
    const startTime = Date.now();
    let timedOut = false;

    try {
      await Promise.race([
        pool.connect(),
        new Promise((_, reject) =>
          setTimeout(() => {
            timedOut = true;
            reject(new Error('Connection timeout'));
          }, 2000)
        ),
      ]);
    } catch (err) {
      expect(timedOut).toBe(true);
    }

    // Release all connections
    clients.forEach((client) => client.release());

    // Should be able to connect now
    const client = await pool.connect();
    expect(client).toBeDefined();
    client.release();
  });
});

/**
 * Vitest integration that proves:
 *  1) withFaults can introduce non-finite values
 *  2) assertFiniteDeep blocks them (returns ok=false with path)
 *
 * Replace the engine stub with your real engine if you want end-to-end coverage.
 *   TODO: import { runMonteCarlo } from '../../server/engine/runMonteCarlo';
 */

import { describe, it, expect } from 'vitest';
import { withFaults } from '../../server/engine/fault-injector';
import { assertFiniteDeep } from '../../server/middleware/engine-guards';

// --- Engine stub (replace with real engine import to test actual pipeline)
type Params = { fundSize: number; horizonQuarters: number; reserves: number };
function engineStub(p: Params) {
  // A deterministic-looking but finite output
  const base = (p.fundSize / 1e6) * 0.01 + p.horizonQuarters * 0.001 - p.reserves * 0.1;
  return {
    moic: Math.max(0.01, 1.2 + base * 0.01),
    irr: Math.min(0.6, Math.max(-0.9, 0.15 + base * 0.005)),
    median: 1.1 + base * 0.002,
    percentiles: { '5': 0.6, '50': 1.1, '95': 2.1 },
  };
}

describe('WASM/Engine fault injection + non-finite guard', () => {
  it('rejects non-finite outputs when faults are present', async () => {
    const faulty = withFaults(engineStub, { rate: 0.7, seed: 42, targetKeys: ['irr', 'moic', 'percentiles'] });
    let foundNonFinite = false;

    // Try a handful of runs to surface a fault
    for (let i = 0; i < 10; i++) {
      const result = await faulty({ fundSize: 50e6, horizonQuarters: 16, reserves: 0.2 });
      const g = assertFiniteDeep(result);
      if (!g.ok && g.reason === 'non-finite-number') {
        foundNonFinite = true;
        expect(g.path).toMatch(/\$\.((irr|moic|median|percentiles)(\.|\[|$))/);
        break;
      }
    }

    expect(foundNonFinite).toBe(true);
  });

  it('passes when faults are disabled (rate=0)', async () => {
    const safe = withFaults(engineStub, { rate: 0, seed: 7 });
    for (let i = 0; i < 5; i++) {
      const result = await safe({ fundSize: 75e6, horizonQuarters: 20, reserves: 0.25 });
      const g = assertFiniteDeep(result);
      expect(g.ok).toBe(true);
    }
  });

  it('guards detect NaN at any depth', () => {
    const data = {
      topLevel: 42,
      nested: {
        deep: {
          value: NaN,
        },
      },
    };

    const g = assertFiniteDeep(data);
    expect(g.ok).toBe(false);
    expect(g.path).toBe('$.nested.deep.value');
    expect(g.reason).toBe('non-finite-number');
  });

  it('guards detect Infinity in arrays', () => {
    const data = {
      values: [1, 2, Infinity, 4],
    };

    const g = assertFiniteDeep(data);
    expect(g.ok).toBe(false);
    expect(g.path).toBe('$.values[2]');
    expect(g.reason).toBe('non-finite-number');
  });

  it('guards handle complex nested structures', () => {
    const data = {
      results: {
        simulations: [
          { irr: 0.12, moic: 1.5 },
          { irr: -Infinity, moic: 1.2 },
          { irr: 0.18, moic: 1.8 },
        ],
        summary: {
          mean: 0.15,
          percentiles: {
            '25': 0.1,
            '50': NaN,
            '75': 0.2,
          },
        },
      },
    };

    const g = assertFiniteDeep(data);
    expect(g.ok).toBe(false);
    // Should find the first non-finite value
    expect(g.reason).toBe('non-finite-number');
  });

  it('guards respect depth limits', () => {
    let deeply = { value: 1 };
    for (let i = 0; i < 60; i++) {
      deeply = { nested: deeply };
    }

    const g = assertFiniteDeep(deeply, { maxDepth: 50 });
    expect(g.ok).toBe(false);
    expect(g.reason).toBe('too-deep');
  });

  it('guards respect breadth limits', () => {
    const wide = {
      items: Array(300).fill(0).map((_, i) => ({ index: i, value: Math.random() })),
    };

    const g = assertFiniteDeep(wide, { maxBreadth: 200 });
    expect(g.ok).toBe(false);
    expect(g.reason).toBe('too-broad');
  });

  it('withFaults preserves original when disabled in production', async () => {
    const originalEnv = process.env.NODE_ENV;
    process.env.NODE_ENV = 'production';
    process.env.ENGINE_FAULT_ENABLE = '0';

    const wrapped = withFaults(engineStub, { rate: 1.0 }); // 100% fault rate
    const result = await wrapped({ fundSize: 100e6, horizonQuarters: 12, reserves: 0.15 });

    const g = assertFiniteDeep(result);
    expect(g.ok).toBe(true); // Should not inject faults in production

    process.env.NODE_ENV = originalEnv;
    delete process.env.ENGINE_FAULT_ENABLE;
  });
});

#!/usr/bin/env node
/**
 * wasm-simulator/index.js
 * CLI that reads JSON on stdin, randomly corrupts numeric leaves, and prints JSON to stdout.
 *
 * Env:
 *   FAULT_RATE=0.3    (0..1)
 *   FAULT_SEED=42
 *   FAULT_TARGETS=irr,moic,median,percentiles
 *
 * Usage:
 *   echo '{"moic":1.2,"irr":0.14,"percentiles":{"50":1.1}}' | FAULT_RATE=0.5 node index.js
 */

const rate = clamp01(Number(process.env.FAULT_RATE ?? 0));
const seed = Number(process.env.FAULT_SEED ?? 1337);
const targets =
  (process.env.FAULT_TARGETS || 'irr,moic,median,percentiles')
    .split(',')
    .map((s) => s.trim().toLowerCase())
    .filter(Boolean);

const rnd = xorshift32(seed);

function main() {
  let input = '';
  process.stdin.setEncoding('utf8');
  process.stdin.on('data', (chunk) => (input += chunk));
  process.stdin.on('end', () => {
    try {
      const obj = JSON.parse(input || '{}');
      const out = mutate(obj, rate, rnd, targets);
      process.stdout.write(JSON.stringify(out));
    } catch (e) {
      console.error('parse error:', e && e.message);
      process.exit(2);
    }
  });
}

function mutate(v, rate, rnd, targets) {
  const seen = new WeakSet();
  const visit = (node, path) => {
    if (node == null) return node;
    if (typeof node === 'number') {
      const isTarget = targets.some((t) => path.toLowerCase().endsWith('.' + t));
      if (rnd() < (isTarget ? Math.min(1, rate * 1.5) : rate)) return mutateNum(node, rnd);
      return node;
    }
    if (Array.isArray(node)) return node.map((x, i) => visit(x, `${path}[${i}]`));
    if (typeof node === 'object') {
      if (seen.has(node)) return node;
      seen.add(node);
      const out = {};
      for (const [k, val] of Object.entries(node)) out[k] = visit(val, `${path}.${k}`);
      return out;
    }
    return node;
  };
  return visit(v, '$');
}

function mutateNum(n, rnd) {
  const r = rnd();
  if (r < 0.34) return NaN;
  if (r < 0.67) return rnd() < 0.5 ? Infinity : -Infinity;
  const factor = rnd() < 0.5 ? 1e12 : -1e12;
  return n * factor;
}

function xorshift32(seed) {
  let x = (seed | 0) || 123456789;
  return function rand() {
    x ^= x << 13;
    x ^= x >>> 17;
    x ^= x << 5;
    return (x >>> 0) / 0xffffffff;
  };
}

function clamp01(n) {
  if (!Number.isFinite(n)) return 0;
  return Math.max(0, Math.min(1, n));
}

main();

