    it('should produce reproducible results with same seed', async () => {
      const params: SimulationParameters = {
        fundId: 1,
        scenarios: 2000,
        timeHorizonYears: 5,
        confidenceIntervals: [25, 50, 75],
        randomSeed: TEST_SEED
      };

      const forecast1 = await monteCarloService.generateForecast(params);
      const forecast2 = await monteCarloService.generateForecast(params);

      // Results should be identical with same seed
      expect(forecast1.multiple.statistics.mean).toBe(forecast2.multiple.statistics.mean);
      expect(forecast1.multiple.statistics.median).toBe(forecast2.multiple.statistics.median);
      expect(forecast1.irr.statistics.mean).toBe(forecast2.irr.statistics.mean);
    });

    it('should maintain statistical consistency across multiple runs', async () => {
      const runs = 5;
      const scenarios = 3000;

      const results = [];

      for (let i = 0; i < runs; i++) {
        const params: SimulationParameters = {
          fundId: 1,
          scenarios,
          timeHorizonYears: 6,
          confidenceIntervals: [50],
          randomSeed: TEST_SEED + i // Different seeds
        };

        const forecast = await monteCarloService.generateForecast(params);
        results.push(forecast.multiple.statistics.mean);
      }

      // Results should be statistically consistent (not wildly different)
      const meanOfMeans = results.reduce((a, b) => a + b, 0) / results.length;
      const variance = results.reduce((sum, x) => sum + Math.pow(x - meanOfMeans, 2), 0) / results.length;
      const stdDev = Math.sqrt(variance);

      // Standard deviation of means should be reasonable (<20% of mean)
      expect(stdDev / meanOfMeans).toBeLessThan(0.2);
    });
  });
});

/**
 * Integration test setup - runs before each integration test file
 * Handles server startup, database connections, and external dependencies
 */

import { beforeAll, afterAll } from 'vitest';
import type { ChildProcess } from 'child_process';
import { spawn } from 'child_process';
import { setTimeout } from 'timers/promises';

// Force UTC timezone for consistent date handling
process.env.TZ = 'UTC';

// Integration test environment
process.env.NODE_ENV = 'test';
process.env.PORT = '3333'; // Different from dev to avoid conflicts
process.env.DATABASE_URL = process.env.DATABASE_URL || 'postgresql://postgres:postgres@localhost:5432/povc_test';
process.env.REDIS_URL = 'memory://';
process.env.ENABLE_QUEUES = '0';

let serverProcess: ChildProcess | null = null;

async function waitForServer(url: string, timeout: number = 30000): Promise<boolean> {
  const start = Date.now();

  while (Date.now() - start < timeout) {
    try {
      const response = await fetch(url);
      if (response.ok) {
        return true;
      }
    } catch (error) {
      // Server not ready yet
    }
    await setTimeout(1000);
  }

  return false;
}

beforeAll(async () => {
  // Check if we need to start the server
  const baseUrl = process.env.BASE_URL || `http://localhost:${process.env.PORT}`;
  const healthUrl = `${baseUrl}/healthz`;

  try {
    const response = await fetch(healthUrl);
    if (response.ok) {
      console.log('Server already running, using existing instance');
      return;
    }
  } catch {
    // Server not running, need to start it
  }

  console.log('Starting test server...');

  serverProcess = spawn('npm', ['run', 'dev:quick'], {
    env: { ...process.env },
    stdio: ['ignore', 'pipe', 'pipe'],
    shell: true
  });

  serverProcess.stdout?.on('data', (data) => {
    const output = data.toString();
    if (output.includes('api on http://')) {
      console.log('Server startup detected');
    }
  });

  serverProcess.stderr?.on('data', (data) => {
    const error = data.toString();
    if (!error.includes('ECONNREFUSED') && !error.includes('DATABASE_URL not set')) {
      console.error('Server error:', error);
    }
  });

  // Wait for server to be ready
  const isReady = await waitForServer(healthUrl, 30000);
  if (!isReady) {
    throw new Error(`Server failed to start within 30 seconds. Check ${healthUrl}`);
  }

  console.log('Test server ready');
}, 60000); // Increase timeout for server startup

afterAll(async () => {
  if (serverProcess) {
    console.log('Shutting down test server...');
    serverProcess.kill('SIGTERM');

    // Wait for graceful shutdown
    await new Promise((resolve) => {
      if (serverProcess) {
        serverProcess.on('exit', resolve);
        setTimeout(() => {
          if (serverProcess && !serverProcess.killed) {
            serverProcess.kill('SIGKILL');
          }
          resolve(null);
        }, 5000);
      } else {
        resolve(null);
      }
    });
  }
});

